#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

static int spi_handle = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value;

    buffer[0] = 1; // Start bit
    buffer[1] = (8 + channel) << 4; // Single-ended bit + channel
    buffer[2] = 0; // Don't care

    if (gpioSPIDataRW(SPI_CHANNEL, buffer, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = ((buffer[1] & 3) << 8) | buffer[2];
    return adc_value;
}

void log_moisture_level(int adc_value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("[%s] Moisture level: %d\n", time_str, adc_value);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    spi_handle = gpioSPISetup(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            log_moisture_level(adc_value);
        } else {
            fprintf(stderr, "Error reading from MCP3008\n");
        }
        sleep(1);
    }

    if (spi_handle >= 0) {
        gpioSPIClose(spi_handle);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

