#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_POINTER_CONVERT 0x00
#define ADS1115_REG_POINTER_CONFIG 0x01
#define ADS1115_REG_CONFIG_OS_SINGLE 0x8000
#define ADS1115_REG_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_REG_CONFIG_PGA_4_096V 0x0000
#define ADS1115_REG_CONFIG_DR_128SPS 0x0080
#define ADS1115_REG_CONFIG_CMODE_TRAD 0x0000
#define ADS1115_REG_CONFIG_CPOL_ACTVLOW 0x0000
#define ADS1115_REG_CONFIG_CLAT_NONLAT 0x0000
#define ADS1115_REG_CONFIG_CQUE_1CONV 0x0000

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(1, ADS1115_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    uint16_t config = ADS1115_REG_CONFIG_OS_SINGLE |
                      ADS1115_REG_CONFIG_MUX_SINGLE_0 |
                      ADS1115_REG_CONFIG_PGA_4_096V |
                      ADS1115_REG_CONFIG_DR_128SPS |
                      ADS1115_REG_CONFIG_CMODE_TRAD |
                      ADS1115_REG_CONFIG_CPOL_ACTVLOW |
                      ADS1115_REG_CONFIG_CLAT_NONLAT |
                      ADS1115_REG_CONFIG_CQUE_1CONV;

    if (i2cWriteI2CBlockData(i2c_handle, ADS1115_REG_POINTER_CONFIG, (uint8_t *)&config, 2) < 0) {
        fprintf(stderr, "Failed to write configuration to ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        uint16_t data = 0;
        if (i2cReadI2CBlockData(i2c_handle, ADS1115_REG_POINTER_CONVERT, (uint8_t *)&data, 2) < 0) {
            fprintf(stderr, "Failed to read data from ADS1115\n");
            break;
        }

        // Convert the 16-bit data to a signed 16-bit integer
        int16_t raw_value = (data >> 4) & 0x0FFF;
        if (raw_value > 0x07FF) {
            raw_value |= 0xF000; // Sign extend negative values
        }

        // Convert raw value to voltage
        float voltage = raw_value * 4.096 / 32767.0;

        // Convert voltage to current (40mV/A sensitivity, zero-centered at mid-supply)
        float current = (voltage - 2.048) / 0.04;

        printf("Current: %.3f A\n", current);

        usleep(500000); // Sleep for 500ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

