#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_FLAME_SENSOR_D0 4
#define SPI_CHANNEL 0
#define SPI_SPEED_HZ 1000000
#define SPI_CS 8
#define MCP3008_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define TEMP_MIN 10
#define TEMP_MAX 40

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_adc(int pi, int channel) {
    unsigned char buffer[3];
    buffer[0] = 1; // Start bit
    buffer[1] = (8 + channel) << 4; // Single-ended bit and channel
    buffer[2] = 0; // Don't care

    if (gpioSPIRead(pi, SPI_CHANNEL, SPI_SPEED_HZ, SPI_CS, buffer, 3, buffer, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((buffer[1] & 3) << 8) | buffer[2];
    return adc_value;
}

double map_adc_to_temperature(int adc_value) {
    return TEMP_MIN + (adc_value * (TEMP_MAX - TEMP_MIN) / ADC_MAX_VALUE);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    if (gpioSetMode(GPIO_FLAME_SENSOR_D0, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for flame sensor D0\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("flame_data.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,FlameDetected,Temperature\n");

    while (keep_running) {
        int flame_detected = gpioRead(GPIO_FLAME_SENSOR_D0);
        int adc_value = read_adc(gpioConnectionInfo().pi, MCP3008_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Skipping log entry due to SPI failure\n");
        } else {
            double temperature = map_adc_to_temperature(adc_value);
            fprintf(file, "%ld,%d,%.2f\n", time(NULL), flame_detected, temperature);
        }

        fflush(file);
        sleep(1);
    }

    fclose(file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

