#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define AIN0 0
#define ADC_GAIN 0x0003 // ±4.096V
#define ADC_MODE 0x0100 // Single-shot mode
#define ADC_CONFIG (ADC_GAIN | ADC_MODE)
#define ADC_CONVERSION_TIME 8500 // 8.5ms in microseconds
#define DEBOUNCE_TIME 50 // 50ms debounce time
#define TEMP_THRESHOLD 60.0 // Temperature threshold in °C
#define LOG_FILE "fire_log.txt"

volatile int running = 1;
volatile unsigned long last_flame_event = 0;
int i2c_handle;
int log_file;

void handle_sigint(int sig) {
    running = 0;
}

void flame_callback(int gpio, unsigned level, uint32_t tick) {
    unsigned long now = pigpio_get_current_tick();
    if (now - last_flame_event >= DEBOUNCE_TIME) {
        last_flame_event = now;
    }
}

double read_temperature() {
    unsigned int result;
    if (i2c_write_i2c_block_data(i2c_handle, 0x01, 1, &AIN0) < 0 ||
        i2c_write_i2c_block_data(i2c_handle, 0x01, 1, &ADC_CONFIG) < 0 ||
        i2c_write_byte(i2c_handle, 0x01) < 0 ||
        i2c_read_i2c_block_data(i2c_handle, 0x00, 2, (unsigned char *)&result) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1.0;
    }

    int16_t raw = (result >> 4) & 0x0FFF;
    if (raw & 0x800) {
        raw |= 0x1000;
    }
    double voltage = (raw * 4.096) / 32768.0;
    double temperature = (voltage / 3.3) * 60.0 + 20.0;
    return temperature;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0 ||
        gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioCallback(FLAME_SENSOR_PIN, PI_FALLING_EDGE, flame_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO callback\n");
        gpioTerminate();
        return 1;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        int flame_detected = gpioRead(FLAME_SENSOR_PIN) == 0;
        double temperature = read_temperature();

        if (flame_detected && temperature > TEMP_THRESHOLD) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            dprintf(log_file, "%s Fire detected! Temperature: %.2f°C\n", timestamp, temperature);
            gpioWrite(BUZZER_PIN, 1);
            usleep(2000000);
            gpioWrite(BUZZER_PIN, 0);
        } else if (flame_detected) {
            dprintf(log_file, "Flame detected!\n");
        } else if (temperature > TEMP_THRESHOLD) {
            dprintf(log_file, "High temperature: %.2f°C\n", temperature);
        }

        usleep(100000);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioCancelCallback(FLAME_SENSOR_PIN);
    i2cClose(i2c_handle);
    close(log_file);
    gpioTerminate();

    return 0;
}

