#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_CHIP_FALLBACK 0
#define GPIO_FAN_PIN 18
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define ADC_COMMAND_0 0x01
#define ADC_COMMAND_1 0x80
#define ADC_COMMAND_2 0x00
#define DEFAULT_SENSITIVITY 100.0
#define DEFAULT_THRESHOLD 5.0

static int spi_fd = -1;
static struct gpiod_line *fan_line = NULL;
static double sensitivity = DEFAULT_SENSITIVITY;
static double threshold = DEFAULT_THRESHOLD;

void cleanup_and_exit(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (fan_line) {
        gpiod_line_release(fan_line);
    }
    if (fan_line && gpiod_line_request(fan_line, "fan_control", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) == 0) {
        gpiod_line_set_value(fan_line, 0);
    }
    exit(0);
}

int open_spi_device() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int open_gpio_chip(struct gpiod_chip **chip, const char *chip_name) {
    *chip = gpiod_chip_open_by_name(chip_name);
    if (!*chip) {
        fprintf(stderr, "Failed to open GPIO chip %s, trying fallback\n", chip_name);
        *chip = gpiod_chip_open(GPIO_CHIP_FALLBACK);
        if (!*chip) {
            perror("Failed to open GPIO chip");
            return -1;
        }
    }
    return 0;
}

int setup_gpio_fan(struct gpiod_chip *chip) {
    fan_line = gpiod_chip_get_line(chip, GPIO_FAN_PIN);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request(fan_line, "fan_control", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        perror("Failed to request GPIO line");
        return -1;
    }

    gpiod_line_set_value(fan_line, 0);
    return 0;
}

int read_adc(uint16_t *adc_value) {
    uint8_t tx[] = {ADC_COMMAND_0, ADC_COMMAND_1, ADC_COMMAND_2};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

void log_reading(double current) {
    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    struct gpiod_chip *chip = NULL;
    if (open_gpio_chip(&chip, GPIO_CHIP_NAME) < 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio_fan(chip) < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (open_spi_device() < 0) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            sensitivity = atof(argv[++i]);
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[++i]);
        }
    }

    while (1) {
        uint16_t adc_value = 0;
        if (read_adc(&adc_value) < 0) {
            continue;
        }

        if (adc_value == 0 || adc_value == 0x3FF) {
            fprintf(stderr, "Sensor absent or error reading ADC\n");
            continue;
        }

        double voltage = (adc_value / 1023.0) * 3.3;
        double current = voltage / (sensitivity / 1000.0);

        log_reading(current);

        if (current > threshold) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }

        sleep(1);
    }

    cleanup_and_exit(0);
    return EXIT_SUCCESS;
}

