#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define ADS1115_ADDRESS 0x48
#define MICS4514_ADDRESS 0x28
#define ADS1115_REG_POINTER_CONVERT 0x00
#define ADS1115_REG_POINTER_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_AIN0_AIN1 0x0000
#define ADS1115_CONFIG_PGA_6_144V 0x0080
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_860SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int setup_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    return 0;
}

int setup_i2c() {
    int i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return -1;
    }
    return i2c_handle;
}

int read_adc(int i2c_handle) {
    unsigned char config[2];
    unsigned char data[2];
    int adc_value = 0;

    config[0] = ADS1115_REG_POINTER_CONFIG;
    config[1] = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0_AIN1 | ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_860SPS | ADS1115_CONFIG_CQUE_NONE;

    if (i2cWrite(i2c_handle, config, 2, true) < 0) {
        fprintf(stderr, "Failed to write to ADS1115\n");
        return -1;
    }

    if (i2cRead(i2c_handle, ADS1115_REG_POINTER_CONVERT, data, 2) < 0) {
        fprintf(stderr, "Failed to read from ADS1115\n");
        return -1;
    }

    adc_value = (data[0] << 8) | data[1];
    if (adc_value > 0x7FFF) {
        adc_value -= 0x10000;
    }

    return adc_value;
}

double convert_to_ppm(int adc_value) {
    // Placeholder for actual conversion logic using a calibrated logarithmic curve
    // This is a dummy conversion for demonstration purposes
    return (adc_value / 32768.0) * 1000.0;
}

void log_ppm(double ppm) {
    FILE *log_file = fopen("co_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s: %f PPM\n", timestamp, ppm);
    fclose(log_file);
}

int main() {
    if (setup_pigpio() != 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = setup_i2c();
    if (i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int adc_value = read_adc(i2c_handle);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
        } else {
            double ppm = convert_to_ppm(adc_value);
            log_ppm(ppm);
        }
        sleep(5);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

