#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define KY026_DIGITAL_PIN 4
#define MCP3008_SPI_CHANNEL 0
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define CSV_FILENAME "flame_data.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_adc(int spi_handle, int channel) {
    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3] = {0};

    if (pi_spi_xfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

float adc_to_temperature(int adc_value) {
    if (adc_value < 0) return -1.0;
    return 10.0 + (adc_value * 30.0 / 1023.0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    int spi_handle = pi_spi_open(MCP3008_SPI_CHANNEL, MCP3008_SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen(CSV_FILENAME, "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        pi_spi_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,flame_detected,temperature\n");

    while (keep_running) {
        int flame_detected = gpioRead(KY026_DIGITAL_PIN);
        int adc_value = read_adc(spi_handle, MCP3008_CHANNEL);
        float temperature = adc_to_temperature(adc_value);

        if (flame_detected < 0 || adc_value < 0) {
            fprintf(stderr, "Sensor error or SPI bus error\n");
        } else {
            time_t now = time(NULL);
            fprintf(csv_file, "%ld,%d,%.2f\n", now, flame_detected, temperature);
            fflush(csv_file);
        }

        sleep(1);
    }

    fclose(csv_file);
    pi_spi_close(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

