#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define ADDR1 0x48
#define ADDR2 0x49
#define REG 0x00
#define SAMPLE_INTERVAL_MS 100
#define MICROPHONE_SENSITIVITY_DBV_PA -38.0
#define REFERENCE_PRESSURE_PA 20e-6
#define ERROR_VALUE_DB -999.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double raw_to_db(int16_t raw) {
    double voltage = raw * (3.3 / 32768.0); // Assuming 3.3V reference
    double pressure = voltage / (10.0 / (1 << 15)); // Convert voltage to pressure in Pa
    double db = 20.0 * log10(pressure / REFERENCE_PRESSURE_PA) + MICROPHONE_SENSITIVITY_DBV_PA;
    return db;
}

int read_i2c_sensor(int i2c_handle, uint8_t address) {
    uint8_t buffer[2];
    if (i2c_read(i2c_handle, address, REG, buffer, 2) < 0) {
        return -1;
    }
    int16_t raw = (buffer[0] << 8) | buffer[1];
    if (buffer[0] & 0x80) { // Check if the MSB is set (negative number)
        raw |= 0xFF00; // Sign extend
    }
    return raw;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle1 = i2cOpen(I2C_BUS, ADDR1);
    int i2c_handle2 = i2cOpen(I2C_BUS, ADDR2);

    if (i2c_handle1 < 0 || i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C handles\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int16_t raw1 = read_i2c_sensor(i2c_handle1, ADDR1);
        int16_t raw2 = read_i2c_sensor(i2c_handle2, ADDR2);

        double db1 = (raw1 < 0) ? ERROR_VALUE_DB : raw_to_db(raw1);
        double db2 = (raw2 < 0) ? ERROR_VALUE_DB : raw_to_db(raw2);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s, %f, %f\n", timestamp, db1, db2);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return EXIT_SUCCESS;
}

