#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL_MIC1 0
#define ADC_CHANNEL_MIC2 1
#define LED_PIN 27
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_MS 100
#define RMS_THRESHOLD 0.7
#define LED_ON_DURATION_MS 500

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_adc(int channel) {
    unsigned char buffer[3] = {0x01, (8 + channel) << 4, 0x00};
    unsigned char response[3];
    if (gpioSPIRead(SPI_CHANNEL, buffer, 3, response, 3) < 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }
    int value = ((response[1] & 0x03) << 8) | response[2];
    return value;
}

double calculate_rms(int *samples, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / count);
}

void log_event(FILE *file, int timestamp, double rms1, double rms2) {
    fprintf(file, "%d,%f,%f\n", timestamp, rms1, rms2);
    fflush(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(8, PI_OUTPUT) < 0 || gpioSetMode(9, PI_OUTPUT) < 0 ||
        gpioSetMode(10, PI_OUTPUT) < 0 || gpioSetMode(11, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI pin modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "SPI setup failed\n");
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen("audio_events.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int samples1[WINDOW_DURATION_MS];
        int samples2[WINDOW_DURATION_MS];
        int timestamp = (int)time(NULL);

        for (int i = 0; i < WINDOW_DURATION_MS; i++) {
            if (!keep_running) break;

            samples1[i] = read_adc(ADC_CHANNEL_MIC1);
            samples2[i] = read_adc(ADC_CHANNEL_MIC2);

            if (samples1[i] < 0 || samples2[i] < 0) {
                fprintf(stderr, "ADC read error\n");
                break;
            }

            usleep(SAMPLE_INTERVAL_MS * 1000);
        }

        double rms1 = calculate_rms(samples1, WINDOW_DURATION_MS);
        double rms2 = calculate_rms(samples2, WINDOW_DURATION_MS);

        log_event(file, timestamp, rms1, rms2);

        if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            usleep(LED_ON_DURATION_MS * 1000);
            gpioWrite(LED_PIN, 0);
        }
    }

    fclose(file);
    gpioTerminate();
    return 0;
}

