#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ADS1115_REG_POINTER_CONVERT 0x00
#define ADS1115_REG_POINTER_CONFIG 0x01
#define ADS1115_REG_CONFIG_OS_SINGLE 0x8000
#define ADS1115_REG_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_REG_CONFIG_PGA_4_096V 0x0200
#define ADS1115_REG_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_REG_CONFIG_DR_1600SPS 0x0080
#define ADS1115_REG_CONFIG_CQUE_NONE 0x0003
#define ADS1115_REG_CONFIG_GAIN 0x0200
#define ADS1115_REG_CONFIG_MODE 0x0100
#define ADS1115_REG_CONFIG_DR 0x0080
#define ADS1115_REG_CONFIG_CQUE 0x0003
#define LED_GPIO 17
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0

volatile sig_atomic_t keep_running = 1;
int led_state = 0;
int pi = -1;
int i2c_handle = -1;
int current_buffer[BUFFER_SIZE];
int buffer_index = 0;
int sample_count = 0;

void handle_sigint(int sig) {
    keep_running = 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    if (gpioSetMode(pi, LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        gpioTerminate(pi);
        return -1;
    }
    gpioWrite(pi, LED_GPIO, 0);
    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(pi, I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate(pi);
        return -1;
    }
    return 0;
}

int read_adc() {
    unsigned char config[2];
    unsigned char data[2];
    int raw_adc;

    config[0] = ADS1115_REG_POINTER_CONFIG;
    config[1] = ADS1115_REG_CONFIG_OS_SINGLE | ADS1115_REG_CONFIG_MUX_SINGLE_0 |
                ADS1115_REG_CONFIG_PGA_4_096V | ADS1115_REG_CONFIG_MODE_SINGLE |
                ADS1115_REG_CONFIG_DR_1600SPS | ADS1115_REG_CONFIG_CQUE_NONE;

    if (i2cWriteDevice(i2c_handle, 2, config) < 0) {
        fprintf(stderr, "Failed to write to ADC config register\n");
        return -1;
    }

    usleep(1000); // Wait for conversion

    if (i2cReadDevice(i2c_handle, 2, data) < 0) {
        fprintf(stderr, "Failed to read from ADC data register\n");
        return -1;
    }

    raw_adc = (data[0] << 8) | data[1];
    if (raw_adc > 0x7FFF) {
        raw_adc -= 0x10000; // Convert to signed 16-bit
    }

    return raw_adc;
}

double convert_to_current(int raw_adc) {
    double voltage = (raw_adc * 4.096) / 32768.0;
    double current = ((voltage - 0.5) / 4.0) * 100.0;
    return current;
}

void update_led(double average_current) {
    if (average_current > CURRENT_THRESHOLD && !led_state) {
        gpioWrite(pi, LED_GPIO, 1);
        led_state = 1;
    } else if (average_current <= CURRENT_THRESHOLD && led_state) {
        gpioWrite(pi, LED_GPIO, 0);
        led_state = 0;
    }
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0 || init_i2c() < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int raw_adc = read_adc();
        if (raw_adc < 0) {
            fprintf(stderr, "Error reading ADC\n");
            break;
        }

        double current = convert_to_current(raw_adc);
        current_buffer[buffer_index] = (int)(current * 100); // Store as integer with 2 decimal places
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        sample_count = (sample_count < BUFFER_SIZE) ? sample_count + 1 : BUFFER_SIZE;

        int sum = 0;
        for (int i = 0; i < sample_count; i++) {
            sum += current_buffer[i];
        }
        double average_current = sum / (double)(sample_count * 100);

        update_led(average_current);

        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    gpioWrite(pi, LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (pi >= 0) {
        gpioTerminate(pi);
    }

    return EXIT_SUCCESS;
}

