#define CONTROL_VALUE 0x01
#define ENABLE_VALUE 0x03

#define MAX_FAILURES 3

static int i2c_handle;
static FILE *log_file = NULL;
static int consecutive_failures = 0;
static volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signal) {
    exit_flag = 1;
}

int i2c_write_byte_data(int handle, uint8_t reg, uint8_t value) {
    int result = i2c_write_byte_data(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", pi_i2c_error(result));
        consecutive_failures++;
        if (consecutive_failures >= MAX_FAILURES) {
            fprintf(stderr, "Too many consecutive I2C write failures, exiting.\n");
            exit(1);
        }
    } else {
        consecutive_failures = 0;
    }
    return result;
}

int i2c_read_word_data(int handle, uint8_t reg) {
    int result = i2c_read_word_data(handle, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", pi_i2c_error(result));
        consecutive_failures++;
        if (consecutive_failures >= MAX_FAILURES) {
            fprintf(stderr, "Too many consecutive I2C read failures, exiting.\n");
            exit(1);
        }
    } else {
        consecutive_failures = 0;
    }
    return result;
}

void write_log_header() {
    if (log_file == NULL) {
        log_file = fopen("color_log.csv", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(1);
        }
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
}

