        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t id = i2c_read_word_data(i2c_handle, ID_REG) & ID_MASK;
    if (id != ID_VALUE) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X\n", id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    i2c_write_byte_data(i2c_handle, ATIME_REG, ATIME_VALUE);
    i2c_write_byte_data(i2c_handle, CONTROL_REG, CONTROL_VALUE);
    i2c_write_byte_data(i2c_handle, ENABLE_REG, ENABLE_VALUE);

