        uint16_t clear = i2c_read_word_data(i2c_handle, CLEAR_REG);
        uint16_t red = i2c_read_word_data(i2c_handle, RED_REG);
        uint16_t green = i2c_read_word_data(i2c_handle, GREEN_REG);
        uint16_t blue = i2c_read_word_data(i2c_handle, BLUE_REG);

        write_log_entry(clear, red, green, blue);

        struct timespec ts = {1, 0};
        nanosleep(&ts, NULL);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

