#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL_MASK 0x07
#define MCP3008_SINGLE_ENDED 0x01
#define MCP3008_DUMMY_BYTE 0x00
#define MCP3008_START_BIT 0x08
#define MCP3008_SINGLE_ENDED_BIT 0x04

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[] = {MCP3008_START_BIT | (MCP3008_SINGLE_ENDED | channel) << 4, MCP3008_DUMMY_BYTE};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to perform SPI transaction");
        return -1;
    }

    uint16_t result = (rx[1] & 0x03) << 8 | rx[2];
    return result;
}

double map_value(int raw_value) {
    return (raw_value / 1023.0) * 100.0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = open_spi_device(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008_cs", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("moisture_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");

    while (keep_running) {
        gpiod_line_set_value(cs_line, 0);

        int raw_value1 = read_adc(spi_fd, 0);
        int raw_value2 = read_adc(spi_fd, 1);

        gpiod_line_set_value(cs_line, 1);

        if (raw_value1 < 0 || raw_value2 < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue;
        }

        double moisture1 = map_value(raw_value1);
        double moisture2 = map_value(raw_value2);

        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

