    }

    uint8_t mode_bits = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_bits) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[] = {0b11000000 | (channel << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; ++attempt) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("SPI transfer failed");
            if (attempt == MAX_SPI_RETRIES - 1) {
                return -1;
            }
            continue;
        }

        uint16_t adc_value = (rx[1] & 0x0F) << 8 | rx[2];
        return adc_value;
    }

