#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define PRESSURE_REGISTER 0x00
#define LOG_FILE "pressure_log.csv"
#define MAX_READ_FAILURES 5

static int i2c_handle;
static FILE *log_file;
static int read_failures = 0;

void handle_signal(int signal) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_log_file() {
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    fprintf(log_file, "timestamp,pressure_kPa\n");
    return 0;
}

int open_i2c() {
    i2c_handle = i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int read_pressure(int16_t *pressure) {
    uint8_t buffer[2];
    int result = i2c_read_i2c_block_data(i2c_handle, PRESSURE_REGISTER, 2, buffer);
    if (result < 0) {
        fprintf(stderr, "I2C read error from register 0x%02X: %d\n", PRESSURE_REGISTER, result);
        read_failures++;
        return -1;
    }
    *pressure = (buffer[0] << 8) | buffer[1];
    read_failures = 0;
    return 0;
}

void log_pressure(int16_t raw_value) {
    double pressure_kPa = (raw_value / 65535.0) * 500.0;
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);
    fprintf(log_file, "%s,%.6f\n", timestamp, pressure_kPa);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    setup_signal_handler();

    if (open_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    if (open_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (1) {
        int16_t raw_value;
        if (read_pressure(&raw_value) == 0) {
            log_pressure(raw_value);
        } else if (read_failures >= MAX_READ_FAILURES) {
            fprintf(stderr, "Repeated I2C read failures, exiting\n");
            break;
        }
        sleep(1);
    }

    handle_signal(0);
    return 0;
}

