#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_MUX_SINGLE_1 0x5000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_MODE_SINGLE 0x0100

#define GPIO_LED 17
#define MAX_RETRIES 3
#define PRESSURE_THRESHOLD 105.0

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_adc(int pi, uint8_t channel) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | (channel == 0 ? ADS1115_CONFIG_MUX_SINGLE_0 : ADS1115_CONFIG_MUX_SINGLE_1) |
                      ADS1115_CONFIG_PGA_6_144V | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_MODE_SINGLE;
    uint16_t conversion = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (gpio_i2c_write_byte_data(pi, ADS1115_ADDRESS, ADS1115_REG_CONFIG, config) == 0) {
            if (gpio_i2c_read_word_data(pi, ADS1115_ADDRESS, ADS1115_REG_CONVERSION, &conversion) == 0) {
                return conversion;
            }
        }
        retries++;
        usleep(100000); // 100 ms
    }
    fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
    return -1;
}

double convert_voltage_to_pressure(double voltage) {
    return (voltage / 5.0) * 400.0;
}

double convert_voltage_to_temperature(double voltage) {
    return (voltage - 1.0) * 100.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int pi = 0; // Use default I2C bus
    if (gpio_i2c_open(pi, ADS1115_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        uint16_t pressure_raw = read_adc(pi, 0);
        uint16_t temp_raw = read_adc(pi, 1);

        if (pressure_raw < 0 || temp_raw < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue;
        }

        double pressure_voltage = (pressure_raw * 6.144) / 32767.0;
        double temp_voltage = (temp_raw * 6.144) / 32767.0;

        double pressure = convert_voltage_to_pressure(pressure_voltage);
        double temperature = convert_voltage_to_temperature(temp_voltage);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        sleep(1);
    }

    gpio_i2c_close(pi);
    gpioTerminate();
    return 0;
}

