#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define GPIO_SHUTDOWN 27
#define LOG_FILE "current_log.txt"
#define MAX_CURRENT 10.0
#define VCC 3.3
#define ADC_MAX 1023.0
#define ADC_RESOLUTION 1024.0
#define SENSITIVITY 0.066

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void log_message(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fprintf(file, "%s\n", message);
    fflush(file);
    fclose(file);
}

double read_adc(int pi, int channel) {
    unsigned char tx[3] = {0x01, (0x08 + (channel << 4)), 0x00};
    unsigned char rx[3] = {0};
    if (gpioSPIRead(pi, SPI_CHANNEL, SPI_SPEED, SPI_MODE, 3, tx, rx) < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

double adc_to_voltage(int adc_value) {
    return (adc_value / ADC_RESOLUTION) * VCC;
}

double voltage_to_current(double voltage) {
    double zero_current_voltage = VCC / 2.0;
    return (voltage - zero_current_voltage) / SENSITIVITY;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int pi = gpioInitialise();
        if (pi < 0) {
            fprintf(stderr, "Failed to initialize pigpio\n");
            gpioTerminate();
            return 1;
        }

        double adc_value = read_adc(pi, ADC_CHANNEL);
        if (adc_value < 0) {
            gpioTerminate();
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double current = voltage_to_current(voltage);

        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "%ld, %fV, %fA", time(NULL), voltage, current);
        log_message(log_buffer);

        if (current > MAX_CURRENT) {
            gpioWrite(GPIO_SHUTDOWN, 1);
            log_message("OVERCURRENT event");
            gpioTerminate();
            return 1;
        }

        gpioTerminate();
        usleep(100000); // 100ms
    }

    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
    return 0;
}

