void log_methane_level(FILE *log_file, time_t timestamp, int ppm) {
    struct tm tm;
    localtime_r(&timestamp, &tm);
    char buffer[64];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(log_file, "%s - Methane Level: %d PPM\n", buffer, ppm);
    if (ppm > 1000) {
        fprintf(stderr, "ALARM: Methane concentration exceeds 1000 PPM!\n");
    }
}

int read_adc(int spi_handle) {
    unsigned char tx[3] = {MCP3008_START_BYTE, MCP3008_CONFIG_BYTE, MCP3008_DUMMY_BYTE};
    unsigned char rx[3] = {0};
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        log_error("SPI transfer failed");
        return -1;
    }
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_error("Failed to open SPI handle");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("methane_log.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        int adc_value = read_adc(spi_handle);
        if (adc_value < 0) {
            continue;
        }

        int ppm = (adc_value * 5000) / 1023;
        time_t now = time(NULL);
        log_methane_level(log_file, now, ppm);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

