#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_POINTER_CONVERT 0x00
#define ADS1115_REG_POINTER_CONFIG 0x01
#define ADS1115_REG_CONFIG_OS_SINGLE 0x8000
#define ADS1115_REG_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_REG_CONFIG_PGA_4_096V 0x0200
#define ADS1115_REG_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_REG_CONFIG_DR_128SPS 0x0080
#define ADS1115_REG_CONFIG_CQUE_NONE 0x0003

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_adc(int pi, uint16_t *value) {
    uint8_t config[2];
    uint8_t data[2];
    int res;

    config[0] = ADS1115_REG_POINTER_CONFIG;
    config[1] = ADS1115_REG_CONFIG_OS_SINGLE | ADS1115_REG_CONFIG_MUX_SINGLE_0 |
                ADS1115_REG_CONFIG_PGA_4_096V | ADS1115_REG_CONFIG_MODE_SINGLE |
                ADS1115_REG_CONFIG_DR_128SPS | ADS1115_REG_CONFIG_CQUE_NONE;

    res = pi_i2c_write_i2c_block_data(pi, I2C_BUS, ADS1115_ADDRESS, config, 2);
    if (res < 0) {
        fprintf(stderr, "Error writing to ADS1115: %s\n", pi_error(res));
        return res;
    }

    res = pi_i2c_read_i2c_block_data(pi, I2C_BUS, ADS1115_ADDRESS, ADS1115_REG_POINTER_CONVERT, data, 2);
    if (res < 0) {
        fprintf(stderr, "Error reading from ADS1115: %s\n", pi_error(res));
        return res;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

double convert_to_voltage(uint16_t raw_value) {
    return (raw_value * 4.096) / 32767.0;
}

double convert_to_pressure(double voltage) {
    return (voltage - 0.5) / 0.1;
}

void log_pressure(double pressure) {
    FILE *file = fopen("pressure_log.txt", "a");
    if (!file) {
        perror("Error opening log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(file, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    int pi = 0;
    uint16_t raw_value;
    double voltage, pressure;

    while (keep_running) {
        if (read_adc(pi, &raw_value) < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        voltage = convert_to_voltage(raw_value);
        pressure = convert_to_pressure(voltage);

        if (pressure >= 0 && pressure <= 100) {
            log_pressure(pressure);
        }

        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

