#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define MCP3208_CS 8
#define MCP3208_SPI_CHANNEL 0
#define MCP3208_SPI_SPEED 1000000
#define MCP3208_COMMAND 0x06
#define MCP3208_BITS 12
#define V_SUPPLY 5.0
#define RH_THRESHOLD 80.0
#define BETA 3950.0
#define R0 10000.0
#define T0 298.15

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double read_adc(int channel) {
    unsigned char command = MCP3208_COMMAND | (channel << 4);
    unsigned char data[3];
    if (gpioSPIDataRW(MCP3208_SPI_CHANNEL, &command, 1, data, 3) < 0) {
        fprintf(stderr, "SPI read error\n");
        return -1.0;
    }
    int result = ((data[1] & 15) << 8) | data[2];
    return (result / 4095.0) * V_SUPPLY;
}

double calculate_humidity(double voltage) {
    return (voltage - 0.824) / 0.0315;
}

double calculate_temperature(double resistance) {
    return 1.0 / (1.0 / T0 + (1.0 / BETA) * log(resistance / R0)) - 273.15;
}

double calculate_thermistor_resistance(double voltage) {
    double r1 = 10000.0; // Assume a 10kΩ series resistor
    return (V_SUPPLY - voltage) * r1 / voltage;
}

void send_email_alert(double humidity) {
    FILE *fp = popen("echo 'Humidity Alert: " RH_THRESHOLD "% exceeded' | ssmtp your_email@example.com", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to send email alert\n");
    } else {
        pclose(fp);
    }
}

void log_reading(double humidity, double temperature) {
    FILE *fp = fopen("humidity_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(MCP3208_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPISetup(MCP3208_SPI_CHANNEL, MCP3208_SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        double humidity_voltage = read_adc(0);
        double thermistor_voltage = read_adc(1);

        if (humidity_voltage < 0 || thermistor_voltage < 0) {
            fprintf(stderr, "Error reading ADC\n");
            continue;
        }

        double humidity = calculate_humidity(humidity_voltage);
        double thermistor_resistance = calculate_thermistor_resistance(thermistor_voltage);
        double temperature = calculate_temperature(thermistor_resistance);

        log_reading(humidity, temperature);

        if (humidity > RH_THRESHOLD) {
            send_email_alert(humidity);
        }

        sleep(60); // Log every minute
    }

    gpioTerminate();
    return 0;
}

