#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define MCP3208_CS_PIN 8
#define MCP3208_CS_LINE 0
#define TMP36_MIN_VOLTAGE 0.0
#define TMP36_MAX_VOLTAGE 3.3
#define TMP36_MIN_TEMP -40.0
#define TMP36_MAX_TEMP 125.0
#define VREF 3.3
#define TMP36_OFFSET 0.5
#define TMP36_SCALE 0.01

static int spi_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;
static FILE *log_file = NULL;
static int log_file_created = 0;

void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int open_spi_device() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, MCP3208_CS_PIN);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "MCP3208_CS", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int read_adc() {
    uint8_t tx[] = {0b11000000, 0x00, 0x00}; // Start bit, single-ended, channel 0
    uint8_t rx[3] = {0};

    gpiod_line_set_value(cs_line, 0); // Assert CS
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1); // Deassert CS
        return -1;
    }

    gpiod_line_set_value(cs_line, 1); // Deassert CS

    uint16_t adc_value = (rx[1] & 0x0F) << 8 | rx[2];
    return adc_value;
}

double convert_to_voltage(uint16_t adc_value) {
    return (adc_value / 4095.0) * VREF;
}

double convert_to_celsius(double voltage) {
    if (voltage < TMP36_MIN_VOLTAGE || voltage > TMP36_MAX_VOLTAGE) {
        fprintf(stderr, "Voltage out of range: %f\n", voltage);
        return NAN;
    }
    double temp = (voltage - TMP36_OFFSET) / TMP36_SCALE;
    if (temp < TMP36_MIN_TEMP || temp > TMP36_MAX_TEMP) {
        fprintf(stderr, "Temperature out of range: %f\n", temp);
        return NAN;
    }
    return temp;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() != 0 || open_spi_device() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
        log_file_created = 1;
    }

    while (1) {
        uint16_t adc_value = read_adc();
        if (adc_value == -1) {
            continue;
        }

        double voltage = convert_to_voltage(adc_value);
        double temperature = convert_to_celsius(voltage);

        if (!isnan(temperature)) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f\n", time_str, temperature);
            fflush(log_file);
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

