#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define CS_PIN 8
#define LOG_FILE "impact_log.txt"
#define ADC_MAX_VALUE 1023
#define V_SUPPLY 3.3
#define ZERO_G_VOLTAGE 1.65
#define SENSITIVITY 0.300
#define IMPACT_THRESHOLD 2.0

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

double adc_to_voltage(int adc_value) {
    return (adc_value / (double)ADC_MAX_VALUE) * V_SUPPLY;
}

double voltage_to_g(double voltage) {
    return (voltage - ZERO_G_VOLTAGE) / SENSITIVITY;
}

double compute_acceleration_magnitude(double x_g, double y_g, double z_g) {
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED_HZ, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(CS_PIN, 1);

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        unsigned char tx_buffer[3] = {1, 0x00, 0x00};
        unsigned char rx_buffer[3] = {0, 0, 0};

        for (int channel = 0; channel < 3; ++channel) {
            tx_buffer[1] = (channel << 4) | 0x07;
            gpioWrite(CS_PIN, 0);
            if (gpioSPIDataRW(SPI_CHANNEL, tx_buffer, 3, rx_buffer) < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                fclose(log_file);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            gpioWrite(CS_PIN, 1);

            int adc_value = (rx_buffer[1] & 0x03) << 8 | rx_buffer[2];
            if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
                fprintf(stderr, "ADC value out of range: %d\n", adc_value);
                fclose(log_file);
                gpioTerminate();
                return EXIT_FAILURE;
            }

            double voltage = adc_to_voltage(adc_value);
            double g = voltage_to_g(voltage);

            if (channel == 0) x_g = g;
            if (channel == 1) y_g = g;
            if (channel == 2) z_g = g;
        }

        double magnitude = compute_acceleration_magnitude(x_g, y_g, z_g);
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%f\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                adc_x, adc_y, adc_z, magnitude);

        if (magnitude > IMPACT_THRESHOLD) {
            fprintf(log_file, "IMPACT DETECTED\n");
        }

        fflush(log_file);
        usleep(10000); // 100 Hz
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

