volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("biometric_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%),Error\n");

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        unsigned char cmd = CMD_REG;
        if (i2cWriteByteData(i2c_handle, CMD_REG, cmd) < 0) {
            fprintf(log_file, "%lu,0,0,1\n", (unsigned long)time(NULL));
            fflush(log_file);
            continue;
        }

        unsigned short ir_value = 0, red_value = 0;
        int error_flag = 0;

        for (int i = 0; i < SAMPLES_TO_READ; i++) {
            unsigned char data[2];
            if (i2cReadBytes(i2c_handle, FIFO_REG + i, 2, data) < 0) {
                error_flag = 1;
                break;
            }
            unsigned short value = (data[0] << 8) | data[1];
            if (i % 2 == 0) {
                ir_value = value;
            } else {
                red_value = value;
            }
        }

        if (error_flag) {
            fprintf(log_file, "%lu,0,0,1\n", (unsigned long)time(NULL));
        } else {
            fprintf(log_file, "%lu,%hu,%hu,0\n", (unsigned long)time(NULL), ir_value, red_value);
        }

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

