#define SPI_CHANNEL 0
#define SPI_CE_PIN 8
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define ADC_CHANNEL 0
#define ADC_FULL_SCALE 1023
#define VREF 3.3
#define MAX_FLOW_RATE 5.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double read_adc(int pi, int channel) {
    unsigned char buf[3];
    int adc_value = 0;

    buf[0] = 1; // Start bit
    buf[1] = (8 + channel) << 4; // Single-ended bit + channel
    buf[2] = 0; // Don't care

    if (gpioSPIRead(pi, SPI_CHANNEL, buf, 3, buf, 3) < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    adc_value = ((buf[1] & 3) << 8) | buf[2];
    return adc_value;
}

double convert_to_flow_rate(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_FULL_SCALE) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }
    double voltage = (adc_value / (double)ADC_FULL_SCALE) * VREF;
    double flow_rate = (voltage / VREF) * MAX_FLOW_RATE;
    return flow_rate;
}

void log_flow_rate(FILE *file, double flow_rate) {
    time_t now = time(NULL);
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&now);

    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d.%06ld,%f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            ts.tv_nsec / 1000, flow_rate);
    fflush(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED_HZ, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("flow_log.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int adc_value = (int)read_adc(gpioConnectionInfo().pi, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC\n");
            continue;
        }

        double flow_rate = convert_to_flow_rate(adc_value);
        if (flow_rate < 0 || flow_rate > MAX_FLOW_RATE) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
            continue;
        }

        log_flow_rate(file, flow_rate);
        usleep(1000000); // Sleep for 1 second
    }

    fclose(file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

