int open_i2c_device(const char *device, int address) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return file;
}

int write_i2c(int file, uint8_t command) {
    uint8_t buffer[1] = {command};
    if (write(file, buffer, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }
    return 0;
}

int read_i2c(int file, uint8_t *buffer, size_t length) {
    if (read(file, buffer, length) != length) {
        perror("Failed to read from the i2c bus");
        return -1;
    }
    return 0;
}

void log_data(FILE *log_file, double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f,%.2f\n", time_str, temperature, pressure);
    fflush(log_file);
}

void convert_raw_to_physical(uint8_t *data, double *temperature, double *pressure) {
    // Extract raw values
    uint16_t pressure_raw = (data[0] << 8) | data[1];
    uint16_t temperature_raw = (data[2] << 8) | data[3];

    // Apply calibration formulas (example values, replace with actual calibration)
    *pressure = (pressure_raw * 0.1) + 100000; // Example conversion
    *temperature = (temperature_raw * 0.01) - 40; // Example conversion
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("environmental_data.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Temperature (°C),Pressure (Pa)\n");
    fclose(log_file);

    while (keep_running) {
        int file = open_i2c_device(I2C_DEVICE, I2C_ADDRESS);
        if (file < 0) {
            fprintf(stderr, "Error opening I2C device, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        if (write_i2c(file, MEASUREMENT_COMMAND) < 0) {
            close(file);
            fprintf(stderr, "Error writing measurement command, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Wait for conversion to finish (example delay, adjust as needed)
        usleep(100000); // 100 ms

        uint8_t buffer[6];
        if (read_i2c(file, buffer, sizeof(buffer)) < 0) {
            close(file);
            fprintf(stderr, "Error reading sensor data, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        double temperature, pressure;
        convert_raw_to_physical(buffer, &temperature, &pressure);

        printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);

        log_file = fopen("environmental_data.csv", "a");
        if (!log_file) {
            perror("Failed to open log file");
            close(file);
            continue;
        }
        log_data(log_file, temperature, pressure);
        fclose(log_file);

        close(file);
        sleep(SAMPLE_INTERVAL);
    }

    log_file = fopen("environmental_data.csv", "a");
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

