#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CS_PIN 8
#define MCP3008_DOUT_PIN 7
#define MCP3008_DIN_PIN 11
#define MCP3008_CLK_PIN 10

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    int adc_value = 0;
    if (gpioSPIRead(SPI_CHANNEL, MCP3008_CS_PIN, 3, &adc_value, 3) < 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    adc_value = (adc_value >> 6) & 0x03FF;
    return adc_value;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gain>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double gain = atof(argv[1]);
    if (gain <= 0) {
        fprintf(stderr, "Gain must be a positive number\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_DOUT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(MCP3008_DIN_PIN, PI_OUTPUT) < 0 ||
