#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define BUZZER_PIN 18
#define LOG_FILE "flame_log.txt"
#define TEMP_FILE "ambient_temp.txt"
#define SAMPLE_INTERVAL 500000 // 500 ms in microseconds
#define MAX_ADC_VALUE 1023
#define DEFAULT_TEMPERATURE 25.0
#define VREF 3.3
#define ADC_BITS 10
#define SPI_MODE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_BITS_PER_WORD 8

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_temperature() {
    FILE *file = fopen(TEMP_FILE, "r");
    if (!file) {
        return DEFAULT_TEMPERATURE;
    }

    double temperature;
    if (fscanf(file, "%lf", &temperature) != 1) {
        fclose(file);
        return DEFAULT_TEMPERATURE;
    }

    fclose(file);
    return temperature;
}

int read_adc(int fd, uint16_t *adc_value) {
    uint8_t tx[] = {0x01, 0x80, 0x00}; // Start bit, single-ended CH0, dummy byte
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

void log_reading(const char *timestamp, uint16_t raw_adc, double voltage, double compensated_voltage, double temperature, int flame_detected) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log, "%s,%u,%.4f,%.4f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fclose(log);
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    int buzzer_chip = gpiod_chip_open("/dev/gpiochip0");
    if (buzzer_chip < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *buzzer_line = gpiod_chip_get_line(buzzer_chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_chip_close(buzzer_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(buzzer_chip);
        return EXIT_FAILURE;
    }

    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(buzzer_chip);
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(fd, SPI_IOC_RD_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(buzzer_chip);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 || ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(buzzer_chip);
        return EXIT_FAILURE;
    }

    double temperature = read_temperature();

    while (keep_running) {
        uint16_t adc_value = 0;
        int retries = 3;
        int success = 0;

        while (retries-- > 0 && !success) {
            if (read_adc(fd, &adc_value) == 0 && adc_value <= MAX_ADC_VALUE) {
                success = 1;
            } else {
                log_error("ADC read error or out of range value");
                gpiod_line_set_value(buzzer_line, 0);
                usleep(SAMPLE_INTERVAL);
                continue;
            }
        }

        if (!success) {
            log_error("Failed to read valid ADC value after retries");
            gpiod_line_set_value(buzzer_line, 0);
            usleep(SAMPLE_INTERVAL);
            continue;
        }

        double voltage = (adc_value * VREF) / (1 << ADC_BITS);
        double compensated_voltage = voltage + (temperature - DEFAULT_TEMPERATURE) * 0.001;
        int flame_detected = compensated_voltage > 1.0;

        if (flame_detected) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        log_reading(timestamp, adc_value, voltage, compensated_voltage, temperature, flame_detected);

        usleep(SAMPLE_INTERVAL);
    }

    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(buzzer_chip);
    close(fd);

    return EXIT_SUCCESS;
}

