#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0
#define LED_PIN 17
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define ADC_CHANNEL 0
#define SPI_TRANSFER_SIZE 3
#define JSON_FILE "water_levels.json"

static int pi = -1;
static int spi_handle = -1;
static int led_state = 0;
static FILE *json_file = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate(pi);
        exit(EXIT_FAILURE);
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set LED pin low\n");
        gpioTerminate(pi);
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    spi_handle = spiOpen(pi, SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", pigpio_error(spi_handle));
        gpioTerminate(pi);
        exit(EXIT_FAILURE);
    }
}

void close_resources() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (json_file != NULL) {
        fprintf(json_file, "]");
        fclose(json_file);
    }
    if (pi >= 0) {
        gpioTerminate(pi);
    }
}

void log_water_level(double percentage) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "\"%Y-%m-%dT%H:%M:%S.", tm_info);
    char ms[4];
    snprintf(ms, sizeof(ms), "%03ld\"", (long) (1000.0 * (now - (time_t)tm_info)));

    if (json_file == NULL) {
        json_file = fopen(JSON_FILE, "w");
        if (json_file == NULL) {
            fprintf(stderr, "Failed to open JSON file\n");
            return;
        }
        fprintf(json_file, "[");
    } else {
        fprintf(json_file, ",");
    }

    fprintf(json_file, "{\"timestamp\": %s%s, \"water_level\": %.2f}", timestamp, ms, percentage);
    fflush(json_file);
}

void update_led(double percentage) {
    if (percentage > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
        if (gpioWrite(LED_PIN, 1) < 0) {
            fprintf(stderr, "Failed to turn LED on\n");
        } else {
            led_state = 1;
        }
    } else if (percentage < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
        if (gpioWrite(LED_PIN, 0) < 0) {
            fprintf(stderr, "Failed to turn LED off\n");
        } else {
            led_state = 0;
        }
    }
}

int main() {
    setup_gpio();
    setup_spi();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

