void handle_signal(int signal) {
    keep_running = 0;
}

int read_adc(int pi, int spi_channel, int adc_channel) {
    unsigned char tx[3] = {1, (8 + adc_channel) << 4, 0};
    unsigned char rx[3] = {0};
    int adc_value = 0;

    if (gpioSPIDataRW(pi, spi_channel, tx, 3, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

double calculate_moisture(int raw_value, int min_raw, int max_raw) {
    if (raw_value < min_raw) return 0.0;
    if (raw_value > max_raw) return 100.0;
    return (double)(raw_value - min_raw) / (max_raw - min_raw) * 100.0;
}

