        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        pigpio_stop();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int raw_value = read_adc(pi, spi_channel, adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            sleep(log_frequency);
            continue;
