#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define LOG_FILE "soil_moisture.log"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_adc(int pi, int channel) {
    unsigned char buffer[3];
    int adc_value;

    buffer[0] = 1; // Start bit
    buffer[1] = (8 + channel) << 4; // Single-ended mode, channel
    buffer[2] = 0; // Don't care

    if (pi_spi_writeread(pi, 8, SPI_CHANNEL, SPI_SPEED, SPI_MODE, buffer, 3, buffer, 3) < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    adc_value = ((buffer[1] & 3) << 8) | buffer[2];
    return adc_value;
}

void log_moisture(int pi, int adc_value, int sample_interval) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    int moisture_percentage = (adc_value * 100) / 1023;
    if (moisture_percentage < 0) moisture_percentage = 0;
    if (moisture_percentage > 100) moisture_percentage = 100;

    fprintf(log_file, "%s, %d, %d%%\n", timestamp, adc_value, moisture_percentage);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sample_interval>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int sample_interval = atoi(argv[1]);
    if (sample_interval <= 0) {
        fprintf(stderr, "Invalid sample interval: %d\n", sample_interval);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio daemon\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int adc_value = read_adc(pi, ADC_CHANNEL);
        if (adc_value >= 0) {
            log_moisture(pi, adc_value, sample_interval);
        } else {
            fprintf(stderr, "Warning: Sensor absent or bus error\n");
        }
        sleep(sample_interval);
    }

    pigpio_stop(pi);
    gpioTerminate();
    return EXIT_SUCCESS;
}
