    float moisture = 100.0f * (float)(DRY_CALIBRATION - adc_value) / (DRY_CALIBRATION - WET_CALIBRATION);
    if (moisture < 0.0f) moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;
    return moisture;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = open_spi_device(SPI_DEVICE);
    configure_spi(spi_fd);

