#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_MAX_VALUE 1023
#define VREF 3.3
#define ADC_BITS 10
#define ADC_RESOLUTION (VREF / (1 << ADC_BITS))
#define MIN_VOLTAGE 0.5
#define MAX_VOLTAGE 4.5
#define MIN_PRESSURE 10.0
#define MAX_PRESSURE 150.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double adc_to_voltage(int adc_value) {
    return adc_value * ADC_RESOLUTION;
}

double voltage_to_pressure(double voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        return -1.0; // Out of range
    }
    return MIN_PRESSURE + ((voltage - MIN_VOLTAGE) / (MAX_VOLTAGE - MIN_VOLTAGE)) * (MAX_PRESSURE - MIN_PRESSURE);
}

void log_reading(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    printf("%s - Pressure: %.2f kPa\n", timestamp, pressure);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        unsigned char tx_buffer[3] = {1, 0x00, 0x00};
        unsigned char rx_buffer[3] = {0, 0, 0};

        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        int adc_value = (rx_buffer[1] & 0x03) << 8 | rx_buffer[2];
        double voltage = adc_to_voltage(adc_value);
        double pressure = voltage_to_pressure(voltage);

        if (pressure < 0) {
            fprintf(stderr, "Voltage out of range: %.2fV\n", voltage);
        } else if (voltage == 0.0 || voltage == VREF) {
            fprintf(stderr, "Sensor absent condition detected\n");
        } else {
            log_reading(pressure);
        }

        sleep(1);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

