volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

