#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 5
#define VREF 3.3
#define CSV_FILENAME "environmental_data.csv"

static volatile int keep_running = 1;
static int spi_fd;
static struct gpiod_line *cs_line;
static FILE *csv_file;

void handle_signal(int sig) {
    keep_running = 0;
}

uint8_t spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return 0;
    }
    return 1;
}

float read_adc_channel(uint8_t channel) {
    uint8_t tx[5] = {1, (8 + channel) << 4, 0, 0, 0};
    uint8_t rx[3] = {0};

    if (!gpiod_line_set_value(cs_line, 0)) {
        fprintf(stderr, "Failed to set CS low\n");
        return -1.0;
    }

    if (!spi_transfer(tx, rx, sizeof(tx))) {
        gpiod_line_set_value(cs_line, 1);
        return -1.0;
    }

    if (!gpiod_line_set_value(cs_line, 1)) {
        fprintf(stderr, "Failed to set CS high\n");
        return -1.0;
    }

    uint16_t result = (rx[1] & 3) << 8 | rx[2];
    return (result * VREF) / 1023.0;
}

void cleanup() {
    if (csv_file) {
        fclose(csv_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    csv_file = fopen(CSV_FILENAME, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return EXIT_FAILURE;
    }
    fprintf(csv_file, "Timestamp,Channel 0,Channel 1,Channel 2,Channel 3\n");

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(spi_fd, SPI_IOC_RD_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 || ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_open_by_name("gpiochip0");
    if (!cs_line) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(cs_line, 8);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(cs_line);
        cleanup();
        return EXIT_FAILURE;
    }

    if (!gpiod_line_request_output(cs_line, "spi_cs", GPIOD_LINE_REQUEST_DIRECTIONS)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(cs_line);
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        float voltages[4];
        for (int i = 0; i < 4; ++i) {
            voltages[i] = read_adc_channel(i);
            if (voltages[i] < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                voltages[i] = 0.0;
            }
        }

        fprintf(csv_file, "%s,%f,%f,%f,%f\n", timestamp, voltages[0], voltages[1], voltages[2], voltages[3]);
        fflush(csv_file);

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

