#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define MCP3008_CS 0
#define MCP3008_CHANNEL 0
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL 5000 // 5 seconds
#define BUFFER_SIZE 20

typedef struct {
    unsigned long timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;
int pump_state = 0;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int read_moisture_level() {
    unsigned char tx[] = {1, (8 + MCP3008_CHANNEL) << 4, 0};
    unsigned char rx[3] = {0};
    int fd = spiOpen(MCP3008_CS, 1000000, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", piStrerror(-fd));
        return -1;
    }

    if (spiXfer(fd, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", piStrerror(spiXfer(fd, tx, rx, 3)));
        spiClose(fd);
        return -1;
    }

    spiClose(fd);

    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

void update_pump_state(int moisture_level) {
    if (moisture_level < LOW_THRESHOLD && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) < 0) {
            fprintf(stderr, "Failed to activate pump: %s\n", piStrerror(gpioWrite(PUMP_GPIO, 1)));
        } else {
            pump_state = 1;
        }
    } else if (moisture_level > HIGH_THRESHOLD && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) < 0) {
            fprintf(stderr, "Failed to deactivate pump: %s\n", piStrerror(gpioWrite(PUMP_GPIO, 0)));
        } else {
            pump_state = 0;
        }
    }
}

void log_entry(unsigned long timestamp, int moisture_level, int pump_state) {
    log_buffer[log_index].timestamp = timestamp;
    log_buffer[log_index].moisture_level = moisture_level;
    log_buffer[log_index].pump_state = pump_state;
    log_index = (log_index + 1) % BUFFER_SIZE;
}

void print_log() {
    printf("Log Buffer:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %lu, Moisture: %d, Pump: %d\n",
               log_buffer[i].timestamp,
               log_buffer[i].moisture_level,
               log_buffer[i].pump_state);
    }
}

void sample_callback(int timer) {
    unsigned long timestamp = piHiPriTimerRead();
    int moisture_level = read_moisture_level();
    if (moisture_level < 0) {
        return;
    }

    update_pump_state(moisture_level);
    log_entry(timestamp, moisture_level, pump_state);
    print_log();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", piStrerror(gpioInitialise()));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", piStrerror(gpioSetMode(PUMP_GPIO, PI_OUTPUT)));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int timer = piHiPriTimerCreate(SAMPLE_INTERVAL, 0, sample_callback, NULL);
    if (timer < 0) {
        fprintf(stderr, "Failed to create timer: %s\n", piStrerror(timer));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        piHiPriTimerSleep();
    }

    piHiPriTimerDelete(timer);
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

