#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define VREF 3.3
#define CSV_FILENAME "analog_log.csv"
#define RETRY_LIMIT 3

static int spi_handle;
static FILE *csv_file;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_adc_channel(int channel) {
    unsigned char tx_buf[3] = {0x01, (0x08 + (channel << 4)), 0x00};
    unsigned char rx_buf[3] = {0};
    int retries = 0;
    int result = -1;

    while (retries < RETRY_LIMIT) {
        result = pi_spi_xfer(spi_handle, tx_buf, rx_buf, 3);
        if (result >= 0) {
            int adc_value = ((rx_buf[1] & 3) << 8) | rx_buf[2];
            return adc_value;
        }
        retries++;
    }
    fprintf(stderr, "SPI communication error on channel %d\n", channel);
    return -1;
}

double calculate_voltage(int adc_value) {
    return (adc_value / 1023.0) * VREF;
}

void log_to_csv(int channel, double voltage) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    fprintf(csv_file, "%s,%d,%.4f\n", timestamp, channel, voltage);
    fflush(csv_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    spi_handle = pi_spi_open(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return 1;
    }

    if (pi_spi_set_mode(spi_handle, 0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        pi_spi_close(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (pi_spi_set_bit_order(spi_handle, 1) < 0) {
        fprintf(stderr, "Failed to set SPI bit order\n");
        pi_spi_close(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (pi_spi_set_lsb_first(spi_handle, 0) < 0) {
        fprintf(stderr, "Failed to set SPI LSB first\n");
        pi_spi_close(spi_handle);
        gpioTerminate();
        return 1;
    }

    csv_file = fopen(CSV_FILENAME, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        pi_spi_close(spi_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(csv_file, "Timestamp,Channel,Voltage\n");
    fclose(csv_file);

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        for (int channel = 0; channel < 3; channel++) {
            int adc_value = read_adc_channel(channel);
            if (adc_value >= 0) {
                double voltage = calculate_voltage(adc_value);
                csv_file = fopen(CSV_FILENAME, "a");
                if (csv_file) {
                    log_to_csv(channel, voltage);
                    fclose(csv_file);
                } else {
                    fprintf(stderr, "Failed to open CSV file for writing\n");
                }
            }
        }
        sleep(0.5);
    }

    pi_spi_close(spi_handle);
    gpioTerminate();
    if (csv_file) {
        fclose(csv_file);
    }

    return 0;
}

