#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE_PIN 8
#define ADC_CHANNEL 0
#define BUZZER_PIN 24
#define GAS_THRESHOLD 500
#define SAMPLE_INTERVAL 500 // in milliseconds

static int spi_handle = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

int setup_spi() {
    spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        return -1;
    }
    if (gpioSetMode(SPI_CE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI CE pin mode\n");
        spiClose(spi_handle);
        return -1;
    }
    return 0;
}

int read_adc_value() {
    unsigned char tx_buffer[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
    unsigned char rx_buffer[3] = {0};

    if (spiWriteRead(spi_handle, tx_buffer, 3, rx_buffer, 3) < 0) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 3) << 8) | rx_buffer[2];
    return adc_value;
}

void control_buzzer(int adc_value) {
    if (adc_value < GAS_THRESHOLD) {
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            fprintf(stderr, "Failed to turn buzzer off\n");
        }
    } else {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            fprintf(stderr, "Failed to turn buzzer on\n");
        }
    }
}

int main() {
    if (setup_gpio() < 0 || setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int adc_value = read_adc_value();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        printf("ADC Value: %d\n", adc_value);
        control_buzzer(adc_value);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

