#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_POINTER_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_POINTER_CONFIG 0x01
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000
#define ADS1115_CONFIG_PGA_6_144V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_1600SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define GPIO_RELAY 17
#define GPIO_REED_SENSOR 27
#define GPIO_RELAY_ACTIVE_HIGH 1
#define GPIO_REED_SENSOR_ACTIVE_LOW 0

#define SAMPLE_COUNT 10
#define SAMPLE_INTERVAL_MS 50
#define POLL_INTERVAL_MS 200
#define RELAY_ON_DURATION_MS 3000

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_device(const char *device, uint8_t address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }
    return fd;
}

int read_adc(int fd) {
    uint8_t buffer[2];
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];

    buffer[0] = ADS1115_REG_POINTER_CONVERSION;
    messages[0].addr = ADS1115_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = buffer;

    buffer[0] = ADS1115_REG_POINTER_CONVERSION;
    messages[1].addr = ADS1115_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 2;
    messages[1].buf = buffer;

    packets.msgs = messages;
    packets.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to read from ADC");
        return -1;
    }

    int16_t value = (buffer[0] << 8) | buffer[1];
    return value;
}

void log_event(const char *event) {
    FILE *log_file = fopen("/var/log/door_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld: %s\n", ts.tv_sec, ts.tv_nsec / 1000, event);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open_i2c_device(I2C_DEVICE, ADS1115_ADDRESS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", GPIO_RELAY_ACTIVE_HIGH) < 0) {
        perror("Failed to request relay line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

