    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, cs_gpio);
    if (!cs_line) {
        gpiod_chip_close(chip);
        perror("Failed to get GPIO line");
        return -1;
    }

    ret = gpiod_line_request_output(cs_line, "adc_cs", 1);
    if (ret < 0) {
        gpiod_chip_close(chip);
        perror("Failed to request GPIO line");
        return -1;
    }

    // Activate CS
    gpiod_line_set_value(cs_line, 0);

    // Perform SPI transfer
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)(&MCP3008_CMD_BYTE1),
        .rx_buf = (unsigned long)(&MCP3008_CMD_BYTE1),
        .len = 3,
        .delay_usecs = SPI_DELAY_USEC,
