        perror("SPI transfer failed");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Deactivate CS
    gpiod_line_set_value(cs_line, 1);

    // Extract 10-bit ADC value
    int adc_value = ((MCP3008_CMD_BYTE1 & 0x03) << 8) | MCP3008_CMD_BYTE2;

    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);

    return adc_value;
}

