        if (sensor1 < 0) sensor1 = -1;
        if (sensor2 < 0) sensor2 = -1;
        if (sensor3 < 0) sensor3 = -1;

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

