        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    }
}

void handle_signal(int sig) {
    if (relay_gpio != -1) {
        gpioWrite(relay_gpio, 0);
    }
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }
    if (pi != -1) {
        pigpioStop(pi);
    }
    exit(0);
}

int read_adc(int channel) {
    unsigned char buf[3] = {0x06, (8 + channel) << 4, 0x00};
    unsigned char response[3];
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, buf, response, 3) == 3) {
            result = ((response[1] & 0x03) << 8) | response[2];
            break;
        }
        retries++;
        log_message("SPI transfer failed, retrying...");
    }

    if (result == -1) {
        log_message("SPI transfer failed after retries, skipping cycle.");
    }

    return result;
}

int map_moisture(int adc_value) {
    if (adc_value <= ADC_DRY) return 0;
    if (adc_value >= ADC_WET) return 100;
    return (adc_value - ADC_DRY) * 100 / (ADC_WET - ADC_DRY);
}

void parse_arguments(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            duration_seconds = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            sleep_interval = atoi(argv[++i]);
        }
    }
}

int main(int argc, char *argv[]) {
    parse_arguments(argc, argv);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    pi = pigpioStart(NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio daemon\n");
        return 1;
    }

    relay_gpio = gpioInitialise();
    if (relay_gpio < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        pigpioStop(pi);
        return 1;
    }

    gpioSetMode(relay_gpio, PI_OUTPUT);
    gpioWrite(relay_gpio, 0);

    ce0_gpio = gpioInitialise();
    if (ce0_gpio < 0) {
        fprintf(stderr, "Failed to initialise CE0 GPIO\n");
        gpioTerminate(relay_gpio);
        pigpioStop(pi);
        return 1;
    }

    gpioSetMode(ce0_gpio, PI_OUTPUT);
    gpioWrite(ce0_gpio, 0);

    spi_handle = spiOpen(pi, SPI_CHANNEL, SPI_SPEED_HZ, SPI_MODE, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate(ce0_gpio);
        gpioTerminate(relay_gpio);
        pigpioStop(pi);
        return 1;
    }

    while (1) {
        int adc_value = read_adc(0);
        if (adc_value != -1) {
            int moisture = map_moisture(adc_value);
            char log_buf[128];
            snprintf(log_buf, sizeof(log_buf), "Moisture: %d%%", moisture);
            log_message(log_buf);

            if (moisture < threshold) {
                gpioWrite(relay_gpio, 1);
                log_message("Pump activated");
                sleep(duration_seconds);
                gpioWrite(relay_gpio, 0);
                log_message("Pump deactivated");
            }
        }

        sleep(sleep_interval);
    }

    if (relay_gpio != -1) {
        gpioWrite(relay_gpio, 0);
    }
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }
    if (pi != -1) {
        pigpioStop(pi);
    }
    if (relay_gpio != -1) {
        gpioTerminate(relay_gpio);
    }
    if (ce0_gpio != -1) {
        gpioTerminate(ce0_gpio);
    }

    return 0;
}
