#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 10
#define EMA_ALPHA 0.1
#define THRESHOLD_MARGIN 0.2

static int pi;
static int spi_handle;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;
static double ema = 0.0;

void handle_signal(int sig) {
    keep_running = 0;
}

int init_pigpio() {
    pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        syslog(LOG_ERR, "Failed to start pigpio daemon: %s", strerror(-pi));
        return -1;
    }
    return 0;
}

int init_spi() {
    spi_handle = spi_open(pi, SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "Failed to open SPI channel: %s", strerror(-spi_handle));
        return -1;
    }
    return 0;
}

int read_adc(int channel) {
    unsigned char tx[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3] = {0};

    if (spi_xfer(spi_handle, tx, rx, 3) < 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

void log_peak(int value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (fprintf(log_file, "[%s] Peak detected: %d\n", timestamp, value) < 0) {
        syslog(LOG_ERR, "Failed to write to log file: %s", strerror(errno));
    }
}

void cleanup() {
    if (spi_handle >= 0) {
        spi_close(spi_handle);
    }
    if (pi >= 0) {
        pigpio_stop(pi);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    if (init_pigpio() < 0 || init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    openlog("sound_sampler", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen("/var/log/sound_events.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int raw_value = read_adc(ADC_CHANNEL);
        if (raw_value < 0) {
            continue;
