        ema = EMA_ALPHA * raw_value + (1 - EMA_ALPHA) * ema;
        if (raw_value > ema * (1 + THRESHOLD_MARGIN)) {
            log_peak(raw_value);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    closelog();
    return EXIT_SUCCESS;
}

