#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define CONTROL_BYTE 0x40 // Single-ended mode on channel 0 (AIN0), analog output disabled

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    unsigned char buffer[2];
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    int ret;

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Perform a dummy read to discard the previous conversion result
    buffer[0] = 0x00; // Dummy read from the data register
    messages[0].addr = I2C_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = buffer;

    packets.msgs = messages;
    packets.nmsgs = 1;

    ret = ioctl(i2c_fd, I2C_RDWR, &packets);
    if (ret < 0) {
        perror("Failed to perform dummy read");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Write control byte to start conversion
        buffer[0] = CONTROL_BYTE;
        messages[0].addr = I2C_ADDRESS;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = buffer;

        buffer[0] = 0x00; // Read from the data register
        messages[1].addr = I2C_ADDRESS;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 1;
        messages[1].buf = buffer;

        packets.msgs = messages;
        packets.nmsgs = 2;

        ret = ioctl(i2c_fd, I2C_RDWR, &packets);
        if (ret < 0) {
            perror("Failed to read from ADC");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        printf("Sample value: %d\n", buffer[0]);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close I2C device
    close(i2c_fd);
    return EXIT_SUCCESS;
}

