#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <errno.h>
#include <math.h>
#include <inttypes.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define AIN0 0
#define GPIO_PIN 27
#define SAMPLE_RATE_HZ 1
#define BUFFER_SIZE 10
#define VCC 3.3
#define ZERO_FIELD_VOLTAGE 2.5
#define SENSITIVITY 0.0014 // 1.4 mV/Gauss
#define THRESHOLD_GAUSS 500

static int adc_handle;
static int gpio_pin = GPIO_PIN;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int read_adc_voltage() {
    int16_t raw;
    if (i2c_read_i2c_block_data(adc_handle, AIN0, 2, (uint8_t *)&raw) < 0) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }
    int16_t msb = raw >> 4;
    int16_t lsb = (raw & 0x0F) << 4;
    int16_t result = msb | lsb;
    if (result > 2047) {
        result -= 4096;
    }
    double voltage = (result / 32768.0) * VCC;
    if (voltage < 0 || voltage > VCC) {
        syslog(LOG_WARNING, "Invalid voltage reading: %f V", voltage);
        return -1;
    }
    return voltage;
}

double voltage_to_gauss(double voltage) {
    return (voltage - ZERO_FIELD_VOLTAGE) / SENSITIVITY;
}

void update_buffer(double gauss) {
    buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

double calculate_rolling_average() {
    double sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    return sum / BUFFER_SIZE;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting Hall-effect sensor monitor");

    adc_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (adc_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C handle: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, PI_LOW);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        double voltage = read_adc_voltage();
        if (voltage < 0) {
            continue;
        }

        double gauss = voltage_to_gauss(voltage);
        update_buffer(gauss);

        double avg_gauss = calculate_rolling_average();
        char log_buffer[256];
        snprintf(log_buffer, sizeof(log_buffer), "Voltage: %f V, Gauss: %f, Avg Gauss: %f", voltage, gauss, avg_gauss);
        log_message(log_buffer);

        if (avg_gauss > THRESHOLD_GAUSS) {
            gpioWrite(gpio_pin, PI_HIGH);
            log_message("Threshold exceeded, motor shutdown signal activated");
        }

        sleep(1);
    }

    gpioWrite(gpio_pin, PI_LOW);
    i2cClose(adc_handle);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

