#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define MCP3008_CS_PIN 8
#define MCP3008_DOUT_PIN 7
#define MCP3008_SCLK_PIN 11

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char buffer[3];
    buffer[0] = 1; // Start bit
    buffer[0] |= (channel & 0x07) << 4; // Single-ended mode, channel selection
    buffer[1] = 0x0; // Don't care
    buffer[2] = 0x0; // Don't care

    int result = piSPIXfer(SPI_CHANNEL, buffer, 3, buffer, 3, SPI_SPEED_HZ, SPI_MODE);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", piStrerror(result));
        return -1;
    }

    int adc_value = ((buffer[1] & 0x03) << 8) | buffer[2];
    return adc_value;
}

int map_adc_to_intensity(int adc_value) {
    if (adc_value < 0) return -1;
    return (adc_value * 10) / 1023;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (piSPISetup(SPI_CHANNEL, SPI_SPEED_HZ, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to setup SPI: %s\n", piStrerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            sleep(1);
            continue;
        }

        int intensity = map_adc_to_intensity(adc_value);
        if (intensity < 0) {
            fprintf(stderr, "Failed to map ADC value to intensity\n");
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("%s - Raw ADC: %d, Rainfall Intensity: %d\n", time_str, adc_value, intensity);

        sleep(1);
    }

    piSPIClose(SPI_CHANNEL);
    gpioTerminate();
    return 0;
}

