#define PWM_RANGE 1023
#define ADC_CHANNEL 0
#define ADC_SPI_CS_PIN 8
#define READ_INTERVAL_MS 100

static int gpiod_handle = -1;
static int pwm_handle = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    return 0;
}

int setup_pwm() {
    pwm_handle = gpioServo(PWM_PIN);
    if (pwm_handle < 0) {
        fprintf(stderr, "Failed to initialize PWM on GPIO %d\n", PWM_PIN);
        return -1;
    }
    return 0;
}

int setup_spi() {
    gpiod_handle = gpioSPISetup(ADC_SPI_CS_PIN, SPI_CHANNEL, SPI_SPEED_HZ, SPI_MODE);
    if (gpiod_handle < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return -1;
    }
    return 0;
}

int read_adc() {
    unsigned char buffer[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
    int result = gpioSPIDataRW(gpiod_handle, buffer, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    int adc_value = ((buffer[1] & 3) << 8) | buffer[2];
    return adc_value;
}

void cleanup() {
    if (pwm_handle >= 0) {
        gpioPWMStop(pwm_handle);
    }
    if (gpiod_handle >= 0) {
        gpioSPIDestroy(gpiod_handle);
    }
    gpioTerminate();
}

int main() {
    if (setup_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (setup_pwm() < 0 || setup_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int adc_value = read_adc();
        if (adc_value >= 0) {
            gpioPWMSetRange(PWM_RANGE + 1);
            gpioPWMSetFreq(pwm_handle, PWM_FREQUENCY);
            gpioPWMSetRangeDuty(pwm_handle, adc_value);
            printf("ADC Value: %d, PWM Duty: %d\n", adc_value, adc_value);
        }
        usleep(READ_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

