#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>
#include <getopt.h>
#include <math.h>
#include <inttypes.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define AIN0 0
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define BLINK_INTERVAL 50000  // 50 ms in microseconds
#define BLINK_DURATION 1000   // 1 second in milliseconds

volatile sig_atomic_t keep_running = 1;
double threshold = DEFAULT_THRESHOLD;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_adc(int fd, int channel, int gain) {
    uint16_t result;
    int res = i2c_read_word_data(fd, ADS1015_REG_POINTER_CONVERT, &result);
    if (res < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)result;
    double voltage = (raw * gain) / 32768.0;
    double gauss = (voltage - 1.65) / 0.001;
    return gauss;
}

void blink_led(int gpio, int interval, int duration) {
    gpioSetMode(gpio, PI_OUTPUT);
    for (int i = 0; i < (duration * 2); i++) {
        gpioWrite(gpio, i % 2);
        usleep(interval);
    }
    gpioWrite(gpio, 0);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int gain = 4.096; // PGA gain

    while (keep_running) {
        double gauss = read_adc(i2c_fd, AIN0, gain);
        if (gauss < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break;
        }
        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            blink_led(LED_GPIO, BLINK_INTERVAL, BLINK_DURATION);
        }

        usleep(SAMPLE_INTERVAL);
    }

    i2cClose(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

