#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <paho/mqtt3as.h>

#define RELAY_PIN 17
#define ADC_CS_PIN 8
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MQTT_TOPIC_CONTROL "pump_control"
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define READ_INTERVAL 60

static int relay_state = 0;
static int moisture_level = 0;
static int spi_handle = -1;
static int mqtt_client = NULL;

void handle_signal(int sig) {
    syslog(LOG_INFO, "Signal %d received, cleaning up...", sig);
    if (relay_state) {
        gpioWrite(RELAY_PIN, 0);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (mqtt_client) {
        MQTTClient_disconnect(mqtt_client, NULL);
        MQTTClient_destroy(&mqtt_client);
    }
    pigpioTerminate();
    exit(0);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

