#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    int fd;
    uint8_t tx[] = {0x01, 0x80, 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    // Register signal handler
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("Failed to set SPI mode");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) == -1) {
        perror("Failed to set bits per word");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Failed to set max speed");
        close(fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Perform SPI transfer
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) == -1) {
            perror("Failed to perform SPI transfer");
            close(fd);
            return EXIT_FAILURE;
        }

        // Extract 10-bit result
        uint16_t raw_value = ((rx[1] & 0x03) << 8) | rx[2];
        double voltage = raw_value * VREF / 1024.0;

        // Print raw value and voltage
        printf("Raw Value: %u, Voltage: %.4f V\n", raw_value, voltage);

        // Wait for 500 ms
        usleep(500000);
    }

    // Close SPI device
    close(fd);
    return EXIT_SUCCESS;
}

