#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define CE_PIN 0
#define VREF 3.3
#define RESOLUTION 1024
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_adc_channel(int spi_handle, int channel) {
    unsigned char tx_buffer[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buffer[3] = {0};

    if (pi_spi_xfer(spi_handle, tx_buffer, rx_buffer, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 3) << 8) | rx_buffer[2];
    return adc_value;
}

void log_data(FILE *file, int channel, int adc_value) {
    double voltage = (adc_value / (double)RESOLUTION) * VREF;
    fprintf(file, "%ld,%d,%.4f\n", (long)time(NULL), channel, voltage);
    fflush(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int spi_handle = pi_spi_open(SPI_CHANNEL, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pi_spi_set_mode(spi_handle, PI_SPI_MODE0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        pi_spi_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pi_spi_set_bit_order(spi_handle, PI_SPI_BIT_ORDER_MSBFIRST) < 0) {
        fprintf(stderr, "Failed to set SPI bit order\n");
        pi_spi_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pi_spi_set_cs_high(spi_handle) < 0) {
        fprintf(stderr, "Failed to set CS high\n");
        pi_spi_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("sensor_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        pi_spi_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(file, "timestamp,channel,voltage\n");
    fflush(file);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        for (int channel = 0; channel < 3; ++channel) {
            int adc_value = read_adc_channel(spi_handle, channel);
            if (adc_value >= 0) {
                log_data(file, channel, adc_value);
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    fclose(file);
    pi_spi_close(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

