#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX 1023
#define PWM_FREQUENCY 100
#define PWM_DUTY_MAX 255
#define NOISE_THRESHOLD 500
#define GPIO_MOTOR1 17
#define GPIO_MOTOR2 27
#define SAMPLE_INTERVAL 10 // in milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_spi(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &ADC_BITS) < 0 ||
        ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI parameters");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_adc(int fd, uint8_t channel, uint16_t *value) {
    uint8_t tx[] = {0b00000001 | (channel << 4), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = ADC_BITS,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transaction failed");
        return -1;
    }

    *value = (rx[1] << 8) | rx[2];
    return 0;
}

void log_event(const char *message) {
    FILE *log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    int spi_fd;
    if (setup_spi(&spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        close(spi_fd);
        return EXIT_FAILURE;
