int open_i2c_device() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int read_bh1750(int fd) {
    uint8_t cmd = 0x11;
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to BH1750: %s", strerror(errno));
        return -1;
    }
    usleep(180000); // Wait 180 ms

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from BH1750: %s", strerror(errno));
        return -1;
    }

    uint16_t lux = (data[0] << 8) | data[1];
    return lux;
}

int open_spi_device() {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        syslog(LOG_ERR, "Failed to set SPI bits per word: %s", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        syslog(LOG_ERR, "Failed to set SPI max speed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

