        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        syslog(LOG_ERR, "Failed to read from ADC: %s", strerror(errno));
        return -1;
    }

    uint16_t adc_value = (rx[1] & 0x0F) << 8 | rx[2];
    return adc_value;
}

