        closelog();
        return EXIT_FAILURE;
    }

    int i2c_fd = open_i2c_device();
    if (i2c_fd < 0) {
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    int spi_fd = open_spi_device();
    if (spi_fd < 0) {
        close(i2c_fd);
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");

    while (keep_running) {
        int error_code = 0;

        int adc_value = read_adc(spi_fd);
        if (adc_value < 0) {
            error_code = 1;
            adc_value = 0;
        }

        int lux = read_bh1750(i2c_fd);
        if (lux < 0) {
            error_code = 2;
            lux = 0;
        }

        log_data(log_file, adc_value, lux, error_code);
        sleep(LOG_INTERVAL);
    }

    close(i2c_fd);
    close(spi_fd);
    fclose(log_file);
    closelog();

    return EXIT_SUCCESS;
}

