#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CS 8
#define MCP3008_DOUT 7
#define MCP3008_CLK 11
#define PUMP_GPIO 17
#define MAX_RETRIES 3
#define MOISTURE_THRESHOLD 30

static int gpiod = -1;
static int pump_gpio = PUMP_GPIO;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char buffer[3];
    buffer[0] = 1; // Start bit
    buffer[0] |= (channel & 0x07) << 4; // Single-ended bit and channel
    buffer[1] = 0x0; // Don't care
    buffer[2] = 0x0; // Don't care

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpioWrite(MCP3008_CS, 0) < 0) {
            fprintf(stderr, "Failed to pull CS low\n");
            retries++;
            continue;
        }

        if (gpioWrite(MCP3008_CLK, 0) < 0) {
            fprintf(stderr, "Failed to pull CLK low\n");
            retries++;
            continue;
        }

        for (int i = 0; i < 3; i++) {
            if (gpioWrite(MCP3008_DOUT, (buffer[i] & 0x80) ? 1 : 0) < 0) {
                fprintf(stderr, "Failed to write DOUT\n");
                retries++;
                break;
            }

            for (int j = 0; j < 8; j++) {
                if (gpioDelay(1) < 0) {
                    fprintf(stderr, "Failed to delay\n");
                    retries++;
                    break;
                }

                if (gpioWrite(MCP3008_CLK, 1) < 0) {
                    fprintf(stderr, "Failed to pull CLK high\n");
                    retries++;
                    break;
                }

                if (gpioDelay(1) < 0) {
                    fprintf(stderr, "Failed to delay\n");
                    retries++;
                    break;
                }

                if (gpioWrite(MCP3008_CLK, 0) < 0) {
                    fprintf(stderr, "Failed to pull CLK low\n");
                    retries++;
                    break;
                }

                buffer[i] <<= 1;
                if (gpioRead(MCP3008_DOUT) == 1) {
                    buffer[i] |= 1;
                }
            }
        }

        if (gpioWrite(MCP3008_CS, 1) < 0) {
            fprintf(stderr, "Failed to pull CS high\n");
            retries++;
            continue;
        }

        int result = ((buffer[1] & 0x03) << 8) | buffer[2];
        return result;
    }

    fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpiod = gpioInitialise();
    if (gpiod < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MCP3008_CS, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_DOUT, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_CLK, PI_OUTPUT) < 0 ||
        gpioSetMode(pump_gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(MCP3008_CS, 1) < 0 ||
        gpioWrite(MCP3008_DOUT, 0) < 0 ||
        gpioWrite(MCP3008_CLK, 0) < 0 ||
        gpioWrite(pump_gpio, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int adc_value = read_adc_channel(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC\n");
            continue;
        }

        float voltage = (adc_value / 1023.0) * 3.3;
        float moisture_percentage = (voltage / 3.0) * 100.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("[%s] ADC Value: %d, Voltage: %.2fV, Moisture: %.2f%%\n", time_str, adc_value, voltage, moisture_percentage);

        if (moisture_percentage < MOISTURE_THRESHOLD) {
            if (gpioWrite(pump_gpio, 1) < 0) {
                fprintf(stderr, "Failed to turn on pump\n");
            }
        } else {
            if (gpioWrite(pump_gpio, 0) < 0) {
                fprintf(stderr, "Failed to turn off pump\n");
            }
        }

        sleep(60);
    }

    if (gpioWrite(pump_gpio, 0) < 0) {
        fprintf(stderr, "Failed to turn off pump on exit\n");
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

