#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define DEBOUNCE_DELAY 1000000 // 1 second in microseconds
#define POLL_INTERVAL 100000 // 100 ms in microseconds
#define PROXIMITY_THRESHOLD 20 // 20 cm

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *event) {
    FILE *log_file = fopen("door_events.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fclose(log_file);
}

int read_adc() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    int adc_value = 0;
    if (gpioSPIDataRW(0, (unsigned char *)&adc_value, 2) < 0) {
        fprintf(stderr, "Failed to read from ADC\n");
        gpioTerminate();
        return -1;
    }

    gpioTerminate();
    return adc_value;
}

int calculate_distance(int adc_value) {
    // Assuming a linear relationship for simplicity
    // This should be calibrated with actual sensor data
    int voltage = (adc_value * 3300) / 1023; // 3.3V reference
    int distance = (int)(27.86 * pow(voltage, -1.15)); // Example conversion formula
    return distance;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    int line = gpiod_chip_open("/dev/gpiochip0");
    if (line < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(line, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(line);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(line);
        return EXIT_FAILURE;
    }

    int last_trigger_time = 0;
    while (keep_running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            log_event("ADC read error");
            continue;
        }

        int distance = calculate_distance(adc_value);
        if (distance < 0) {
            log_event("Distance calculation error");
            continue;
        }

        if (distance < PROXIMITY_THRESHOLD) {
            if (last_trigger_time == 0 || (gettimeofday(NULL, NULL)->tv_sec * 1000000 + gettimeofday(NULL, NULL)->tv_usec) - last_trigger_time > DEBOUNCE_DELAY) {
                gpiod_line_set_value(relay_line, 1);
                log_event("Door opened");
                last_trigger_time = gettimeofday(NULL, NULL)->tv_sec * 1000000 + gettimeofday(NULL, NULL)->tv_usec;
            }
        } else {
            gpiod_line_set_value(relay_line, 0);
        }

        usleep(POLL_INTERVAL);
    }

    gpiod_line_release(relay_line);
    gpiod_chip_close(line);
    return EXIT_SUCCESS;
}

