#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PWM 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNELS 3
#define LOG_INTERVAL 5
#define PWM_FREQUENCY 100
#define PWM_RANGE 100

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_adc(int channel) {
    unsigned char cmd[3];
    unsigned char response[3];
    int adc_value = -1;

    cmd[0] = 1; // Start bit
    cmd[1] = (8 + channel) << 4; // Single-ended bit + channel
    cmd[2] = 0; // Don't care

    if (spiXfer(SPI_CHANNEL, cmd, 3, response, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = ((response[1] & 3) << 8) | response[2];
    return adc_value;
}

void log_data(int raw_values[], int average, int valve_position) {
    FILE *log_file = fopen("irrigation.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s: ADC0=%d, ADC1=%d, ADC2=%d, Average=%d, Valve=%d%%\n",
            ctime(&now), raw_values[0], raw_values[1], raw_values[2], average, valve_position);

    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int raw_values[ADC_CHANNELS] = {0};
        int valid_readings = 0;
        int sum = 0;

        for (int i = 0; i < ADC_CHANNELS; i++) {
            int value = read_adc(i);
            if (value >= 0) {
                raw_values[i] = value;
                sum += value;
                valid_readings++;
            }
        }

        int average = valid_readings > 0 ? sum / valid_readings : 0;
        int valve_position = average > 0 ? 100 - (average * 100 / 1023) : 100;

        gpioPWM(GPIO_PWM, PWM_FREQUENCY, PWM_RANGE * valve_position / 100);

        log_data(raw_values, average, valve_position);

        sleep(LOG_INTERVAL);
    }

    gpioPWM(GPIO_PWM, 0, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

