#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CS_PIN 8
#define MCP3008_CHANNEL 0
#define MAX_RETRIES 5
#define RETRY_DELAY 100 // Initial delay in milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_soil_moisture() {
    unsigned char command[3] = {0x01, 0x80 | (MCP3008_CHANNEL << 4), 0x00};
    unsigned char response[3];
    int retries = 0;
    int delay = RETRY_DELAY;
    int adc_value = -1;

    while (retries < MAX_RETRIES) {
        if (gpioSPIDataRW(SPI_CHANNEL, command, 3, response, 3) == 0) {
            adc_value = ((response[1] & 3) << 8) | response[2];
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            }
        }
        retries++;
        usleep(delay * 1000);
        delay *= 2; // Exponential backoff
    }
    return -1; // Indicate failure
}

void log_reading(int adc_value) {
    FILE *file = fopen("soil_data.txt", "a");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    if (adc_value != -1) {
        float moisture_percentage = (float)(1023 - adc_value) / 10.23 * 100;
        fprintf(file, "%s: ADC Value: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture_percentage);
    } else {
