int read_soil_moisture() {
    unsigned char command[3] = {0x01, 0x80 | (MCP3008_CHANNEL << 4), 0x00};
    unsigned char response[3];
    int retries = 0;
    int delay = RETRY_DELAY;
    int adc_value = -1;

    while (retries < MAX_RETRIES) {
        if (gpioSPIDataRW(SPI_CHANNEL, command, 3, response, 3) == 0) {
            adc_value = ((response[1] & 3) << 8) | response[2];
            if (adc_value >= 0 && adc_value <= 1023) {
