#define CONFIG_FILE "theremin_config.txt"
#define MAX_DISTANCE_CM 400
#define MIN_FREQ 220
#define MAX_FREQ 880
#define PWM_PERIOD_NS 20000000 // 20ms period for audio PWM

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
