uint16_t read_adc(uint8_t channel) {
    uint8_t tx[] = {1 << channel, 0x00};
    uint8_t rx[3] = {0};
    uint16_t adc_value = 0;

    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return 0;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return 0;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return 0;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return 0;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to perform SPI transfer");
        close(fd);
        return 0;
    }

    close(fd);

    adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

double measure_distance() {
    struct gpiod_line *trig_line, *echo_line;
    struct gpiod_chip *chip;
    struct gpiod_line_request req = {
        .consumer = "theremin",
        .type = GPIOD_LINE_REQ_DIR_OUT,
        .flags = GPIOD_LINE_REQUEST_DIRECTIONS,
    };
    struct gpiod_line_request req_echo = {
        .consumer = "theremin",
        .type = GPIOD_LINE_REQ_DIR_IN,
        .flags = GPIOD_LINE_REQUEST_DIRECTIONS,
    };
    uint64_t start, end;
    uint64_t pulse_duration;
    double distance_cm;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(trig_line, &req) < 0) {
        perror("Failed to request TRIG line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(echo_line, &req_echo) < 0) {
        perror("Failed to request ECHO line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, 1000000) < 0) {
        perror("Timeout waiting for ECHO rising edge");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    start = gpiod_line_event_get_time(echo_line);

    if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, 1000000) < 0) {
        perror("Timeout waiting for ECHO falling edge");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    end = gpiod_line_event_get_time(echo_line);

    pulse_duration = end - start;
    distance_cm = pulse_duration / 58.0;

    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return distance_cm;
}

void save_calibration(double min_distance, double max_distance) {
    FILE *file = fopen(CONFIG_FILE, "w");
    if (!file) {
        perror("Failed to open config file for writing");
        return;
    }
    fprintf(file, "%lf %lf\n", min_distance, max_distance);
    fclose(file);
}

int load_calibration(double *min_distance, double *max_distance) {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) {
        perror("Failed to open config file for reading");
        return -1;
    }
    if (fscanf(file, "%lf %lf", min_distance, max_distance) != 2) {
        perror("Failed to read calibration data");
        fclose(file);
        return -1;
    }
    fclose(file);
    return 0;
}

