    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/period", PWM_PIN);
    FILE *file = fopen(path, "w");
    if (!file) {
        perror("Failed to open PWM period file");
        return;
    }
    fprintf(file, "%lu\n", PWM_PERIOD_NS);
    fclose(file);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_PIN);
    file = fopen(path, "w");
    if (!file) {
        perror("Failed to open PWM duty cycle file");
        return;
    }
    uint64_t period_ns = 20000000; // 20ms period
    uint64_t duty_ns = (uint64_t)((double)period_ns * (double)frequency / 20000.0);
    fprintf(file, "%lu\n", duty_ns);
    fclose(file);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/enable", PWM_PIN);
    file = fopen(path, "w");
    if (!file) {
        perror("Failed to open PWM enable file");
        return;
    }
    fprintf(file, "1\n");
    fclose(file);
}

void set_pwm_duty_cycle(uint8_t duty_cycle) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_PIN);
    FILE *file = fopen(path, "w");
    if (!file) {
        perror("Failed to open PWM duty cycle file");
        return;
    }
    uint64_t period_ns = 20000000; // 20ms period
    uint64_t duty_ns = (uint64_t)((double)period_ns * (double)duty_cycle / 255.0);
    fprintf(file, "%lu\n", duty_ns);
    fclose(file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    double min_distance = 10.0, max_distance = 100.0;
    if (load_calibration(&min_distance, &max_distance) < 0) {
        printf("Using default calibration: min_distance = %.1f cm, max_distance = %.1f cm\n", min_distance, max_distance);
    } else {
        printf("Loaded calibration: min_distance = %.1f cm, max_distance = %.1f cm\n", min_distance, max_distance);
    }

    double last_valid_distance = -1;
    uint8_t last_valid_duty_cycle = 128;

    while (keep_running) {
        double distance = measure_distance();
        if (distance >= 0 && distance <= MAX_DISTANCE_CM) {
            last_valid_distance = distance;
        } else {
            distance = last_valid_distance;
        }

        double frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (distance - min_distance) / (max_distance - min_distance);
        frequency = fmax(MIN_FREQ, fmin(MAX_FREQ, frequency));
        set_pwm_frequency((uint32_t)frequency);

        uint16_t adc_value = read_adc(0);
        uint8_t duty_cycle = (uint8_t)(adc_value * 255 / 1023);
        set_pwm_duty_cycle(duty_cycle);
        last_valid_duty_cycle = duty_cycle;

        usleep(10000); // 10ms delay
    }

    save_calibration(min_distance, max_distance);

    return 0;
}

