#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MCP3008_CS 0
#define MCP3008_CHANNEL 0
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_SPI_MODE 0
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY 1

static int spi_handle;
static int fan_gpio;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    fan_gpio = gpioInitialise();
    if (fan_gpio < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    gpioSetMode(fan_gpio, PI_OUTPUT);
    gpioWrite(fan_gpio, 0);
    return 0;
}

int init_spi() {
    spi_handle = spiOpen(MCP3008_CS, MCP3008_SPI_SPEED, MCP3008_SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        return -1;
    }
    return 0;
}

int read_adc(int channel) {
    unsigned char tx[5] = {0x01, 0x08 | (channel & 0x07), 0x00, 0x00, 0x00};
    unsigned char rx[5] = {0};
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx, rx, 5) == 0) {
            result = ((rx[1] & 0x03) << 8) | rx[2];
            break;
        }
        retries++;
        fprintf(stderr, "SPI read failed, retrying %d/%d...\n", retries, MAX_RETRIES);
        sleep(RETRY_DELAY);
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "SPI read failed after %d retries, reinitializing SPI...\n", MAX_RETRIES);
        spiClose(spi_handle);
        if (init_spi() < 0) {
            fprintf(stderr, "Failed to reinitialize SPI\n");
            return -1;
        }
        return read_adc(channel);
    }

    return result;
}

int calculate_aqi(int adc_value) {
    return (adc_value * 500) / 1023;
}

void log_aqi(int aqi) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    time_t now = time(NULL);
    fprintf(log_file, "%s AQI: %d\n", ctime(&now), aqi);
    fclose(log_file);
}

void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(fan_gpio, 1);
    } else {
        gpioWrite(fan_gpio, 0);
    }
}

void cleanup() {
