    uint8_t tx[] = {0x01, (MCP3008_CHANNEL << 4) | 0x80, 0x00};
    uint8_t rx[3] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        gpiod_line_set_value(ce_line, 0);
        usleep(1); // Ensure CE is low before starting SPI transaction

        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = sizeof(tx),
            .delay_usecs = 0,
            .speed_hz = SPI_MAX_SPEED_HZ,
            .bits_per_word = SPI_BITS_PER_WORD,
        };

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        gpiod_line_set_value(ce_line, 1);
        usleep(1); // Ensure CE is high after SPI transaction

        *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        if (*adc_value != 0 && *adc_value != 1023) {
            return 0; // Successful read
        }

        usleep(RETRY_DELAY_MS * 1000);
    }

    return -1; // Failed to read ADC after retries
}

void log_reading(double ppm, const char *status) {
    FILE *log_file = fopen("alcohol_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));

    fprintf(log_file, "%s - ADC Value: %u, PPM: %.2f, Status: %s\n", timestamp, *adc_value, ppm, status);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() < 0 || setup_spi() < 0) {
        cleanup_gpio();
        cleanup_spi();
        return EXIT_FAILURE;
    }

    uint16_t adc_value;
    while (keep_running) {
        if (read_adc(&adc_value) < 0) {
            fprintf(stderr, "Failed to read from ADC after retries\n");
        } else {
            double ppm = (adc_value * 0.5) - 10.0;
            const char *status;
            if (ppm > 50.0) {
                status = "Alcohol detected! Limit exceeded.";
            } else if (ppm < 20.0) {
                status = "Sobriety confirmed.";
            } else {
                status = "Alcohol level within acceptable range.";
            }
            log_reading(ppm, status);
        }
        sleep(1);
    }

    cleanup_gpio();
    cleanup_spi();
    return EXIT_SUCCESS;
}

