#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MCP3008_CHANNEL 0
#define PUMP_GPIO 18
#define THRESHOLD 300
#define LOG_FILE "irrigation.log"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

static int gpiod = -1;
static int spi_handle = -1;
static int pump_state = 0;

void handle_signal(int sig) {
    if (pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        pump_state = 0;
    }
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }
    if (gpiod != -1) {
        gpioTerminate(gpiod);
    }
    exit(0);
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    }
}

int read_mcp3008(int channel) {
    unsigned char buffer[3];
    buffer[0] = 1; // Start bit
    buffer[1] = (8 + channel) << 4; // Single-ended bit + channel
    buffer[2] = 0; // Don't care

    if (spiXfer(spi_handle, buffer, buffer, 3) < 0) {
        log_message("SPI transfer failed");
        return -1;
    }

    int result = ((buffer[1] & 3) << 8) | buffer[2];
    return result;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod = pigpio_start(NULL, NULL);
    if (gpiod < 0) {
        fprintf(stderr, "Failed to start pigpio daemon\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        pigpio_stop(gpiod);
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        pigpio_stop(gpiod);
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        pigpio_stop(gpiod);
        return 1;
    }

    while (1) {
        int moisture_level = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_level < 0) {
            continue; // Skip this iteration on failure
        }

        char log_buffer[128];
        snprintf(log_buffer, sizeof(log_buffer), "Moisture level: %d", moisture_level);

        if (moisture_level < THRESHOLD) {
            if (!pump_state) {
                gpioWrite(PUMP_GPIO, 1);
                pump_state = 1;
                strcat(log_buffer, " - Pump ON");
            }
        } else {
            if (pump_state) {
                gpioWrite(PUMP_GPIO, 0);
                pump_state = 0;
                strcat(log_buffer, " - Pump OFF");
            }
        }

        log_message(log_buffer);
        sleep(60);
    }

