    if (pump_state) {
        gpioWrite(PUMP_GPIO, 0);
    }
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }
    if (gpiod != -1) {
        gpioTerminate();
        pigpio_stop(gpiod);
    }

    return 0;
}

