#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_CS_GPIO 8
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9
#define SPI_SCLK_GPIO 11
#define LED_GPIO 17
#define SAMPLES_FOR_CALIBRATION 100
#define DEBOUNCE_TIME_MS 10

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_adc(int spi_handle) {
    unsigned char tx[] = {1, 0x80, 0x00};
    unsigned char rx[3] = {0};
    int adc_value = 0;

    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(SPI_CS_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(SPI_MOSI_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(SPI_MISO_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(SPI_SCLK_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetChipSelect(spi_handle, SPI_CS_GPIO) < 0) {
        fprintf(stderr, "Failed to set SPI chip select\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Calibrate ambient noise level
    int total = 0;
    for (int i = 0; i < SAMPLES_FOR_CALIBRATION; i++) {
        int value = read_adc(spi_handle);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            spiClose(spi_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        total += value;
        usleep(10000); // 10 ms delay between samples
    }
    int ambient_level = total / SAMPLES_FOR_CALIBRATION;
    int noise_threshold = ambient_level * 1.1;

    int led_state = 0;
    int last_activation_time = 0;

    while (keep_running) {
        int value = read_adc(spi_handle);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            break;
        }

        if (value > noise_threshold) {
            int current_time = gpioTick();
            if (current_time - last_activation_time > DEBOUNCE_TIME_MS) {
                led_state = !led_state;
                gpioWrite(LED_GPIO, led_state);
                last_activation_time = current_time;
            }
        }

        usleep(10000); // 10 ms delay between samples
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

