#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "ERROR: Unable to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int read_adc(int pi, int channel) {
    unsigned int adc_value;
    if (gpioSPIDataRW(pi, SPI_CHANNEL, &channel, 1, &adc_value, 3) < 0) {
        return -1;
    }
    return (adc_value >> 6) & 0x03FF; // 10-bit ADC value
}

float voltage_to_slpm(float voltage) {
    return (voltage - 0.5) / (4.5 - 0.5) * 200;
}

void sample_airflow(int pi) {
    unsigned int adc_value = read_adc(pi, (1 << 7) | (ADC_CHANNEL << 4));
    if (adc_value < 0) {
        log_message("ERROR: ADC read failed");
        return;
    }

    float voltage = adc_value * (5.0 / 1023.0);
    float slpm = voltage_to_slpm(voltage);

    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "Airflow: %.2f SLPM", slpm);
    log_message(log_entry);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: Unable to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int pi = pigpioStart();
    if (pi < 0) {
        fprintf(stderr, "ERROR: Unable to start pigpio daemon\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPISetup(pi, SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "ERROR: Unable to setup SPI\n");
        pigpioStop(pi);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        sample_airflow(pi);
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    pigpioStop(pi);
    gpioTerminate();
    return 0;
}

