#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define SAMPLE_RATE_HZ 1000
#define CS_PIN 8
#define LOG_FILE "audio_log.txt"

static volatile sig_atomic_t keep_running = 1;
static int spi_fd;
static int log_fd;
static struct gpiod_line *cs_line;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(cs_line, "CS", 1);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(cs_line, 1);
    gpiod_chip_close(chip);
    return 0;
}

int setup_spi() {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0
    };

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int setup_log_file() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

void cleanup() {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
}

int main() {
    struct timespec ts, ts_next, ts_elapsed;
    uint8_t tx_buf[3] = {0x01, 0x08, 0x00};
    uint8_t rx_buf[3] = {0};
    uint32_t raw_adc_value;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() < 0 || setup_spi() < 0 || setup_log_file() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    ts.tv_sec = 0;
    ts.tv_nsec = 0;
    ts_next.tv_sec = ts.tv_sec;
    ts_next.tv_nsec = 1000000; // 1 ms

    while (keep_running) {
        gpiod_line_set_value(cs_line, 0);

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 0) {
            perror("SPI transfer failed");
            cleanup();
            return EXIT_FAILURE;
        }

        gpiod_line_set_value(cs_line, 1);

        raw_adc_value = ((uint32_t)rx_buf[1] << 8) | rx_buf[2];
        raw_adc_value &= 0x03FF; // Mask to 10 bits

