volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int setup_spi() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

int read_adc() {
    unsigned char cmd[3];
    unsigned char adc_value[2];
    int adc_raw;

    cmd[0] = MCP3008_CMD_SINGLE_ENDED | (MCP3008_CHANNEL << 4);
    cmd[1] = 0x0;
    cmd[2] = 0x0;

    if (gpioSPIDataRW(SPI_CHANNEL, cmd, 3, adc_value) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_raw = ((adc_value[1] & 0x03) << 8) | adc_value[2];
    return adc_raw;
}

void log_data(double voltage, double ppm) {
    FILE *file = fopen("gas_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s - Voltage: %.4f V, PPM: %.2f\n", time_str, voltage, ppm);
    fclose(file);
}

int main() {
    if (setup_spi() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    while (keep_running) {
        int adc_raw = read_adc();
        if (adc_raw < 0) {
            usleep(100000); // 100 ms delay
            continue;
        }

        double voltage = (adc_raw / (double)ADC_MAX_VALUE) * VREF;
        double ppm = voltage * 1000.0;

        printf("Voltage: %.4f V, PPM: %.2f\n", voltage, ppm);
        log_data(voltage, ppm);

        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

