#define MCP3008_CS 8
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MCP3008_SCLK 11
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_BITS 10
#define ADC_MAX 1023
#define REF_VOLTAGE 3.3
#define SENSITIVITY 0.003
#define ZERO_G_BIAS 1.5
#define SAMPLE_RATE 100 // 10 Hz sampling rate

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1.0;
    }

    int adc_value = pi_spi_writeread(MCP3008_CS, SPI_CHANNEL, SPI_SPEED, 3, 0b11000000 | (channel << 3), NULL, 0);
    if (adc_value < 0) {
        fprintf(stderr, "SPI transaction failed: %s\n", pi_strerror(-adc_value));
        return -1.0;
    }

    adc_value = (adc_value >> 6) & 0x03FF;
    double voltage = (adc_value / ADC_MAX) * REF_VOLTAGE;
    return voltage;
}

double kalman_filter(double measurement, double *estimate, double *error_estimate, double *error_measurement) {
    double kalman_gain = *error_estimate / (*error_estimate + *error_measurement);
    *estimate = *estimate + kalman_gain * (measurement - *estimate);
    *error_estimate = (1.0 - kalman_gain) * *error_estimate;
    return *estimate;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MCP3008_CS, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_MOSI, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_MISO, PI_INPUT) < 0 ||
        gpioSetMode(MCP3008_SCLK, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(MCP3008_CS, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(MCP3008_MOSI, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(MCP3008_MISO, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(MCP3008_SCLK, PI_PUD_UP) < 0) {
        fprintf(stderr, "GPIO pull-up/down setting failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(MCP3008_CS, 1) < 0) {
        fprintf(stderr, "GPIO write failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    double x_estimate = 0.0, y_estimate = 0.0, z_estimate = 0.0;
    double x_error_estimate = 1.0, y_error_estimate = 1.0, z_error_estimate = 1.0;
    double x_error_measurement = 0.1, y_error_measurement = 0.1, z_error_measurement = 0.1;

    while (keep_running) {
        double x_voltage = read_adc_channel(0);
        double y_voltage = read_adc_channel(1);
        double z_voltage = read_adc_channel(2);

        if (x_voltage < 0 || y_voltage < 0 || z_voltage < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            break;
        }

        double x_accel = (x_voltage - ZERO_G_BIAS) / SENSITIVITY;
        double y_accel = (y_voltage - ZERO_G_BIAS) / SENSITIVITY;
        double z_accel = (z_voltage - ZERO_G_BIAS) / SENSITIVITY;

        x_accel = kalman_filter(x_accel, &x_estimate, &x_error_estimate, &x_error_measurement);
        y_accel = kalman_filter(y_accel, &y_estimate, &y_error_estimate, &y_error_measurement);
        z_accel = kalman_filter(z_accel, &z_estimate, &z_error_estimate, &z_error_measurement);

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_accel, y_accel, z_accel);

        usleep(100000); // Sleep for 100 ms to achieve 10 Hz sampling rate
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

