#include <gpiod.h>

#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define SAMPLE_INTERVAL 100000000 // 100 milliseconds in nanoseconds

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

double calculate_magnetic_field(int value) {
    double voltage = value ? VCC : 0.0;
    double magnetic_field = (voltage - V_QUIESCENT) / SENSITIVITY;
    return magnetic_field;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2, *line3;
    int ret;
    FILE *log_file;
    int value1, value2, value3;
    double magnetic_field1, magnetic_field2, magnetic_field3;

    // Open log file
    log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    line1 = gpiod_chip_get_line(chip, 4);
    line2 = gpiod_chip_get_line(chip, 17);
    line3 = gpiod_chip_get_line(chip, 27);

    if (!line1 || !line2 || !line3) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line1, "hall_sensor_1", 0);
    if (ret) {
        fprintf(stderr, "Failed to request line 1: %s\n", gpiod_strerror(ret));
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line2, "hall_sensor_2", 0);
    if (ret) {
        fprintf(stderr, "Failed to request line 2: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line3, "hall_sensor_3", 0);
    if (ret) {
        fprintf(stderr, "Failed to request line 3: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read GPIO values
        value1 = gpiod_line_get_value(line1);
        value2 = gpiod_line_get_value(line2);
        value3 = gpiod_line_get_value(line3);

        if (value1 == -1 || value2 == -1 || value3 == -1) {
