#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOG_FILE "watering.log"
#define PUMP_GPIO 17
#define ADC_CHANNEL 0
#define SPI_BUS 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define MOISTURE_THRESHOLD 30
#define READ_INTERVAL 60

static int pi;
static int pump_state = 0;

void log_event(const char *event) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log, "[%s] %s\n", timestamp, event);
        fclose(log);
    }
}

void handle_signal(int signal) {
    if (pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        pump_state = 0;
        log_event("Pump turned off on exit");
    }
    if (pi >= 0) {
        pigpio_stop(pi);
    }
    log_event("Program terminated");
    exit(0);
}

int read_moisture_level() {
    unsigned int adc_value;
    if (gpioSPIDataRW(pi, SPI_BUS, &adc_value, 3) < 0) {
        log_event("SPI read error");
        return -1;
    }
    // Extract the 10-bit ADC value from the 3-byte response
    adc_value = (adc_value >> 6) & 0x03FF;
    return adc_value;
}

void check_moisture_and_control_pump() {
    int moisture_level = read_moisture_level();
    if (moisture_level < 0) {
        return; // Error already logged
    }

    int moisture_percentage = (moisture_level * 100) / 1023;
    char event[100];
    snprintf(event, sizeof(event), "Moisture level: %d%%", moisture_percentage);

    if (moisture_percentage < MOISTURE_THRESHOLD && !pump_state) {
        gpioWrite(PUMP_GPIO, 1);
        pump_state = 1;
        log_event("Pump turned on");
    } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_state) {
        gpioWrite(PUMP_GPIO, 0);
        pump_state = 0;
        log_event("Pump turned off");
    }
    log_event(event);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }
    log_event("Program started");

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        pigpio_stop(pi);
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        pigpio_stop(pi);
        return 1;
    }

    if (gpioSPISetup(SPI_BUS, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        pigpio_stop(pi);
        return 1;
    }

    while (1) {
        check_moisture_and_control_pump();
        sleep(READ_INTERVAL);
    }

    // Cleanup should be handled by signal handler
    return 0;
}

