#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define DUMMY_BYTE 0x00

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    return fd;
}

int configure_spi(int fd) {
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    return 0;
}

int read_adc(int fd, uint8_t channel, uint16_t *value) {
    uint8_t tx[] = {0x01, 0x80 | (channel << 4), DUMMY_BYTE};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    int spi_fd = open_spi_device(SPI_DEVICE);
    configure_spi(spi_fd);

    FILE *csv_file = fopen("sensor_data.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    fprintf(csv_file, "Timestamp,Channel 0,Channel 1,Channel 2\n");

    while (keep_running) {
        uint16_t adc_values[3];
        for (int i = 0; i < 3; ++i) {
            if (read_adc(spi_fd, i, &adc_values[i]) < 0) {
                fclose(csv_file);
                close(spi_fd);
                exit(EXIT_FAILURE);
            }
        }

        time_t now = time(NULL);
        fprintf(csv_file, "%ld,%u,%u,%u\n", now, adc_values[0], adc_values[1], adc_values[2]);
        fflush(csv_file);

        sleep(1);
    }

    fclose(csv_file);
    close(spi_fd);
    return 0;
}

