#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <cJSON.h>

#define LED_GPIO 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MAX_RECONNECT_DELAY 60

static int running = 1;
static int reconnect_delay = 1;
static mosquitto *mosq = NULL;
static int led_gpio = -1;

void log_error(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

void handle_signal(int sig) {
    running = 0;
}

void on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc == 0) {
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("Failed to connect to MQTT broker");
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        cJSON *json = cJSON_Parse((const char *)message->payload);
        if (json) {
            cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
            if (cJSON_IsBool(led_state) && cJSON_GetArraySize(json) == 1) {
                gpioWrite(led_gpio, cJSON_IsTrue(led_state) ? 1 : 0);
            } else {
                log_error("Invalid JSON payload");
            }
            cJSON_Delete(json);
        } else {
            log_error("Failed to parse JSON payload");
        }
    }
}

void on_disconnect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc != 0) {
        log_error("Unexpected disconnection from MQTT broker");
    }
    reconnect_delay = reconnect_delay < MAX_RECONNECT_DELAY ? reconnect_delay * 2 : MAX_RECONNECT_DELAY;
    sleep(reconnect_delay);
}

void setup_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60)) {
        log_error("Failed to initiate MQTT connection");
        exit(EXIT_FAILURE);
    }

    if (mosquitto_loop_start(mosq)) {
        log_error("Failed to start MQTT loop");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    if (led_gpio != -1) {
        gpioWrite(led_gpio, 0);
        gpioTerminate();
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    led_gpio = gpioInitialise();
    if (led_gpio < 0) {
        log_error("Failed to initialize GPIO");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(led_gpio, PI_OUTPUT);
    gpioWrite(led_gpio, 0);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_mqtt();

    while (running) {
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

