}

void setup_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60)) {
        log_error("Failed to initiate MQTT connection");
        exit(EXIT_FAILURE);
    }

    if (mosquitto_loop_start(mosq)) {
        log_error("Failed to start MQTT loop");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    if (led_gpio != -1) {
        gpioWrite(led_gpio, 0);
        gpioTerminate();
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    led_gpio = gpioInitialise();
    if (led_gpio < 0) {
        log_error("Failed to initialize GPIO");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(led_gpio, PI_OUTPUT);
    gpioWrite(led_gpio, 0);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_mqtt();

    while (running) {
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}
