#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int ret;
    FILE *log_file;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Get line 17
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line for falling edge detection
    ret = gpiod_line_request_rising_edge_events(line, "vibration-monitor");
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("/var/log/vibration_shutdown.log", "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        ret = gpiod_line_event_wait(line, -1);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_event_wait: %s\n", gpiod_strerror(ret));
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_event_read: %s\n", gpiod_strerror(ret));
            break;
        }

        // Get current time
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

        // Log and print the event
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "[%s] Vibration detected, shutting down.\n", timestamp);
        if (fprintf(log_file, "%s", log_message) < 0) {
            perror("fprintf");
            break;
        }
        if (fflush(log_file) != 0) {
            perror("fflush");
            break;
        }
        printf("%s", log_message);

        // Shutdown the system
        if (system("sudo shutdown -h now") != 0) {
            perror("system");
        }

        // Exit after shutdown command
        break;
    }

    // Clean up
    if (log_file) {
        if (fclose(log_file) != 0) {
            perror("fclose");
        }
    }
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

