#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIB_START_REG 0x88
#define BMP280_CALIB_END_REG 0xA1
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_PRESSURE_MSB_REG 0xF7
#define BMP280_PRESSURE_LSB_REG 0xF8
#define BMP280_PRESSURE_XLSB_REG 0xF9
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_TEMP_LSB_REG 0xFB
#define BMP280_TEMP_XLSB_REG 0xFC
#define SEA_LEVEL_PRESSURE 101325.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_i2c_block_data(int pi, uint8_t addr, uint8_t reg, uint8_t *buf, uint8_t len) {
    if (i2c_read_block_data(pi, addr, reg, buf, len) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    return 0;
}

int write_i2c_byte_data(int pi, uint8_t addr, uint8_t reg, uint8_t data) {
    if (i2c_write_byte_data(pi, addr, reg, data) < 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }
    return 0;
}

int read_chip_id(int pi) {
    uint8_t chip_id;
    if (i2c_read_byte_data(pi, BMP280_I2C_ADDR, BMP280_CHIP_ID_REG, &chip_id) < 0) {
        fprintf(stderr, "Failed to read chip ID\n");
        return -1;
    }
    return chip_id;
}

int read_calibration_data(int pi, int16_t *calib_data) {
    uint8_t buf[26];
    if (read_i2c_block_data(pi, BMP280_I2C_ADDR, BMP280_CALIB_START_REG, buf, 26) < 0) {
        return -1;
    }

    for (int i = 0; i < 24; i += 2) {
        calib_data[i / 2] = (int16_t)(buf[i] | (buf[i + 1] << 8));
    }

    return 0;
}

void configure_sensor(int pi) {
    if (write_i2c_byte_data(pi, BMP280_I2C_ADDR, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        exit(EXIT_FAILURE);
    }
}

int read_raw_temperature(int pi, int32_t *temp) {
    uint8_t buf[3];
    if (read_i2c_block_data(pi, BMP280_I2C_ADDR, BMP280_TEMP_MSB_REG, buf, 3) < 0) {
        return -1;
    }
    *temp = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    return 0;
}

int read_raw_pressure(int pi, int32_t *pressure) {
    uint8_t buf[3];
    if (read_i2c_block_data(pi, BMP280_I2C_ADDR, BMP280_PRESSURE_MSB_REG, buf, 3) < 0) {
        return -1;
    }
    *pressure = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    return 0;
}

double compensate_temperature(int32_t adc_T, int16_t dig_T1, int16_t dig_T2, int16_t dig_T3) {
    int32_t var1, var2, T;
    var1 = ((((adc_T >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)dig_T1)) * ((adc_T >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    T = (t_fine * 5 + 128) >> 8;
    return (double)T / 100.0;
}

double compensate_pressure(int32_t adc_P, int16_t dig_P1, int16_t dig_P2, int16_t dig_P3, int16_t dig_P4, int16_t dig_P5, int16_t dig_P6, int16_t dig_P7, int16_t dig_P8, int16_t dig_P9) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)dig_P6;
    var2 = var2 + ((var1 * (int64_t)dig_P5) << 17);
    var2 = var2 + (((int64_t)dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)dig_P3) >> 8) + ((var1 * (int64_t)dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dig_P1) >> 33;
    if (var1 == 0) {
        return 0; // Avoid division by zero
    }
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)dig_P7) << 4);
    return (double)p / 256.0;
}

double calculate_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / SEA_LEVEL_PRESSURE, 0.1903));
}

void log_altitude(double altitude) {
    FILE *log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s, Altitude: %.2f meters\n", timestamp, altitude);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int pi = 1; // I2C bus 1
    if (read_chip_id(pi) != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 not found\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t calib_data[16];
    if (read_calibration_data(pi, calib_data) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    configure_sensor(pi);

    while (keep_running) {
        int32_t raw_temp, raw_pressure;
        if (read_raw_temperature(pi, &raw_temp) < 0 || read_raw_pressure(pi, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        double temperature = compensate_temperature(raw_temp, calib_data[1], calib_data[2], calib_data[3]);
        double pressure = compensate_pressure(raw_pressure, calib_data[4], calib_data[5], calib_data[6], calib_data[7], calib_data[8], calib_data[9], calib_data[10], calib_data[11]);
        double altitude = calculate_altitude(pressure);

        log_altitude(altitude);
        sleep(5);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

