#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BUFFER_SIZE 120
#define VREF 3.3
#define LM35_SCALE 0.01

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

float read_temperature(int pi, int spi_channel) {
    unsigned char tx[] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};

    if (gpioSPIDataRW(pi, spi_channel, tx, sizeof(tx), rx, sizeof(rx)) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1.0;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    float voltage = (adc_value / 1023.0) * VREF;
    return voltage / LM35_SCALE;
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        pigpio_stop(pi);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_channel = SPI_CHANNEL;
    if (gpioSPISetup(pi, spi_channel, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        pigpio_stop(pi);
        return 1;
    }

    FILE *file = fopen("temp_log.dat", "wb+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
    }

    float buffer[BUFFER_SIZE];
    int buffer_index = 0;

    while (keep_running) {
        float temperature = read_temperature(pi, spi_channel);
        if (temperature >= 0) {
            printf("Temperature: %.2f °C\n", temperature);
            buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            if (file != NULL) {
                fseek(file, 0, SEEK_SET);
                fwrite(buffer, sizeof(float), BUFFER_SIZE, file);
            }
        }

        sleep(5);
    }

    if (file != NULL) {
        fclose(file);
    }

    gpioSPIClose(pi, spi_channel);
    pigpio_stop(pi);
    return 0;
}

