#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <errno.h>
#include <syslog.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_CMD_CONT_HIGH_RES_MODE 0x10
#define MCP3008_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_bh1750(int fd) {
    uint8_t cmd = BH1750_CMD_CONT_HIGH_RES_MODE;
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to write to BH1750");
        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux / 1.2; // Convert to lux
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int read_mcp3008(int fd, int channel) {
    uint8_t tx[] = {0b11000000 | (channel << 3), 0};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from MCP3008");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

void log_environment(int light_fd, int sound_fd, FILE *log_file) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    int light = read_bh1750(light_fd);
    if (light < 0) {
        syslog(LOG_ERR, "Error reading BH1750");
        light = -1;
    }

    int sound = read_mcp3008(sound_fd, MCP3008_CHANNEL);
    if (sound < 0) {
        syslog(LOG_ERR, "Error reading MCP3008");
        sound = -1;
    }

    fprintf(log_file, "%s, Light: %d, Sound: %d\n", time_str, light, sound);
    fflush(log_file);
}

int main() {
    openlog("environment_logger", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int light_fd = open_i2c_device("/dev/i2c-1", BH1750_I2C_ADDR);
    if (light_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize BH1750");
        closelog();
        return EXIT_FAILURE;
    }

    int sound_fd = open_spi_device("/dev/spidev0.0");
    if (sound_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize MCP3008");
        close(light_fd);
        closelog();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("environmental_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(light_fd);
        close(sound_fd);
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        log_environment(light_fd, sound_fd, log_file);
        sleep(1);
    }

    fclose(log_file);
    close(light_fd);
    close(sound_fd);
    closelog();

    return EXIT_SUCCESS;
}

