        return EXIT_FAILURE;
    }

    // Get line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line
    ret = gpiod_line_request_input(line, "flame_sensor", GPIOD_LINE_REQUEST_FLAG_NONE);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", gpiod_strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set pull-down
    ret = gpiod_line_set_pull(line, GPIOD_LINE_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pull-down: %s\n", gpiod_strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *log = fopen(LOG_FILE, "w");
    if (!log) {
        fprintf(stderr, "Error opening log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    fprintf(log, "timestamp,pin,state\n");
    fclose(log);

    // Main loop
    while (keep_running) {
        ret = gpiod_line_get_value(line, &ts.tv_sec);
        if (ret < 0) {
            fprintf(stderr, "Failed to read line value: %s\n", gpiod_strerror(-ret));
            break;
        }

        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gmtime(&ts.tv_sec));

        log_event(timestamp, GPIO_PIN, ts.tv_sec);

        if (ts.tv_sec) {
            printf("ALARM: Flame detected!\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
