        printf("%s, ADC: %d, Temp: %.2f C, DAC Voltage: %.2f V\n", timestamp, adc_value, temperature, mapped_voltage);

        fflush(log_file);
        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(MCP4725_I2C_BUS);
    gpioTerminate();
    return EXIT_SUCCESS;
}

