#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CE_PIN 8
#define NUM_SENSORS 3
#define ADC_MAX_VALUE 1023

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_adc(int channel) {
    unsigned char tx[] = {1, (8 + channel) << 4, 0};
    unsigned char rx[3] = {0};

    if (spiXfer(SPI_CHANNEL, tx, sizeof(tx), rx, sizeof(rx)) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

double convert_to_moisture(int adc_value) {
    return (1.0 - (adc_value / (double)ADC_MAX_VALUE)) * 100.0;
}

void log_moisture(int sensor_id, double moisture) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *file = fopen("soil_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(file, "Sensor %d: %s Moisture: %.2f%%\n", sensor_id, timestamp, moisture);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_adc(i);
            if (adc_value < 0) {
                fprintf(stderr, "Invalid ADC value for sensor %d\n", i);
                continue;
            }

            double moisture = convert_to_moisture(adc_value);
            log_moisture(i, moisture);
        }

        gpioDelay(60000); // Sleep for 60 seconds
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    printf("Goodbye!\n");

    return 0;
}

