#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {17, 22, 23, 24}
#define RELAY_ACTIVE_HIGH 1

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];
static int relay_pins[NUM_RELAYS] = RELAY_PINS;

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void deactivate_all_relays() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to deactivate relay %d\n", i);
        }
    }
}

int main() {
    struct gpiod_line_request req = {
        .consumer = "relay_sequencer",
        .flags = GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT,
    };

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", relay_pins[i]);
            deactivate_all_relays();
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_output(lines[i], &req) < 0) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", relay_pins[i]);
            deactivate_all_relays();
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Initially set all relays to inactive (LOW)
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set initial value for GPIO %d\n", relay_pins[i]);
            deactivate_all_relays();
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            // Activate relay
            if (gpiod_line_set_value(lines[i], RELAY_ACTIVE_HIGH) < 0) {
                fprintf(stderr, "Failed to activate relay %d\n", i);
            }
            sleep(1);

            // Deactivate relay
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to deactivate relay %d\n", i);
            }
            sleep(1);
        }
    }

    // Cleanup
    deactivate_all_relays();
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

