#define MCP3008_MODE 0
#define IN1 17
#define IN2 18
#define ENA 27
#define PWM_RANGE 255
#define PWM_DUTY 150
#define RAIN_THRESHOLD 5
#define MOTOR_DURATION 3

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

int read_rain_sensor(int pi, int cs, int channel, int frequency, int mode) {
    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0};
    int adc_value = 0;

    if (gpioSPIRead(pi, cs, frequency, mode, tx, 3, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = ((rx[1] & 3) << 8) | rx[2];
    return adc_value;
}

int convert_adc_to_rain_level(int adc_value) {
    return 10 - (adc_value * 10 / 1023);
}

void log_rain_level(FILE *log_file, int rain_level) {
    if (fprintf(log_file, "%ld: Rain level: %d\n", time(NULL), rain_level) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
    }
    fflush(log_file);
}

void setup_motor(int pi, int in1, int in2, int ena, int pwm_range, int pwm_duty) {
    gpioSetMode(pi, in1, PI_OUTPUT);
    gpioSetMode(pi, in2, PI_OUTPUT);
    gpioSetMode(pi, ena, PI_OUTPUT);
    gpioPWM(pi, ena, pwm_range, pwm_duty);
}

void drive_motor(int pi, int in1, int in2, int direction) {
    gpioWrite(pi, in1, direction);
    gpioWrite(pi, in2, !direction);
}

void cleanup(int pi, int cs, FILE *log_file) {
    if (log_file) {
        fclose(log_file);
    }
    if (cs >= 0) {
        gpioClose(pi, cs);
    }
    gpioTerminate(pi);
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int cs = gpioOpen(pi, MCP3008_CS, 1);
    if (cs < 0) {
        fprintf(stderr, "Failed to open SPI CS pin\n");
        cleanup(pi, cs, NULL);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("rain_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(pi, cs, NULL);
        return EXIT_FAILURE;
    }

    setup_motor(pi, IN1, IN2, ENA, PWM_RANGE, PWM_DUTY);
    int window_open = 1;

    while (!stop_flag) {
        int adc_value = read_rain_sensor(pi, cs, MCP3008_CHANNEL, MCP3008_FREQUENCY, MCP3008_MODE);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read rain sensor\n");
            break;
        }

        int rain_level = convert_adc_to_rain_level(adc_value);
        log_rain_level(log_file, rain_level);

        if (rain_level >= RAIN_THRESHOLD && window_open) {
            drive_motor(pi, IN1, IN2, 1);
            sleep(MOTOR_DURATION);
            drive_motor(pi, IN1, IN2, 0);
            window_open = 0;
        } else if (rain_level < RAIN_THRESHOLD && !window_open) {
            drive_motor(pi, IN1, IN2, 0);
            sleep(MOTOR_DURATION);
            drive_motor(pi, IN1, IN2, 1);
            window_open = 1;
        }

        sleep(1);
    }

    drive_motor(pi, IN1, IN2, 0);
    cleanup(pi, cs, log_file);
    return EXIT_SUCCESS;
}

