#include <pigpio.h>

#define LED_PIN 16
#define ADC_PIN 26
#define THRESHOLD 700
#define DEBOUNCE_MS 50
#define LED_ON_MS 500

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    keep_running = 0;
}

void print_timestamped_message() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] Clap detected!\n", buffer);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ADC_PIN, PI_INPUT) < 0 || gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(ADC_PIN, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    int last_detection_time = 0;
    while (keep_running) {
        int adc_value = gpioAnalogRead(ADC_PIN);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        if (adc_value > THRESHOLD) {
            int current_time = gpioTick();
            if (current_time - last_detection_time > DEBOUNCE_MS) {
                gpioWrite(LED_PIN, 1);
                print_timestamped_message();
                last_detection_time = current_time;

                gpioDelay(LED_ON_MS);
                gpioWrite(LED_PIN, 0);
            }
        }
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

