#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_PIN 17
#define SYSFS_GPIO_DIR "/sys/class/gpio"
#define SYSFS_GPIO_EXPORT SYSFS_GPIO_DIR "/export"
#define SYSFS_GPIO_UNEXPORT SYSFS_GPIO_DIR "/unexport"
#define SYSFS_GPIO_VALUE SYSFS_GPIO_DIR "/gpio%d/value"
#define A 26.0
#define B -6.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double voltage_to_distance(double voltage) {
    return A / voltage + B;
}

void log_distance(double distance) {
    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: Distance = %.2f mm\n", timestamp, distance);
    fclose(log_file);
}

void activate_feeder(double distance) {
    if (distance < 200.0) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    int fd;
    char value_str[3];
    double voltage, distance;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Export GPIO
    fd = open(SYSFS_GPIO_EXPORT, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open export");
        return EXIT_FAILURE;
    }

    if (write(fd, "17", 2) < 0) {
        perror("Failed to export GPIO");
        close(fd);
        return EXIT_FAILURE;
    }
    close(fd);

    char gpio_value_path[40];
    snprintf(gpio_value_path, sizeof(gpio_value_path), SYSFS_GPIO_VALUE, GPIO_PIN);

    while (keep_running) {
        fd = open(gpio_value_path, O_RDONLY);
        if (fd < 0) {
            perror("Failed to open GPIO value");
            sleep(1);
            continue;
        }

        if (read(fd, value_str, sizeof(value_str)) < 0) {
            perror("Failed to read GPIO value");
            close(fd);
            sleep(1);
            continue;
        }
        close(fd);

        value_str[1] = '\0'; // Null-terminate the string

        voltage = (value_str[0] == '0') ? 0.0 : 3.3;
        distance = voltage_to_distance(voltage);

        log_distance(distance);
        activate_feeder(distance);

        sleep(1); // Read every second
    }

    // Unexport GPIO
    fd = open(SYSFS_GPIO_UNEXPORT, O_WRONLY);
    if (fd >= 0) {
        if (write(fd, "17", 2) < 0) {
            perror("Failed to unexport GPIO");
        }
        close(fd);
    }

    return EXIT_SUCCESS;
}

