#define PUMP_OFF 0
#define PUMP_ON 1
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX_VALUE (1 << ADC_BITS)
#define SAMPLE_INTERVAL 60

static int pump_fd = -1;
static int spi_fd = -1;
static FILE *log_fd = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, PUMP_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "pump_control", PUMP_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    pump_fd = gpiod_line_get_fd(line);
    if (pump_fd < 0) {
        perror("Failed to get GPIO file descriptor");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

int init_spi() {
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &mode) < 0) {
        perror("Failed to get SPI mode");
        close(spi_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to get SPI bits per word");
        close(spi_fd);
        return -1;
    }

    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to get SPI max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(uint8_t channel) {
    uint8_t tx[] = {1 << 7 | (channel & 0x07), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

void log_data(int adc_value, int pump_status) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    int moisture_percentage = 100 - (int)((adc_value - WET_ADC_VALUE) * 100.0 / (DRY_ADC_VALUE - WET_ADC_VALUE));
    if (moisture_percentage < 0) moisture_percentage = 0;
    if (moisture_percentage > 100) moisture_percentage = 100;

    fprintf(log_fd, "%s - ADC: %d, Moisture: %d%%, Pump: %s\n",
            time_str, adc_value, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_fd);
}

void cleanup() {
    if (pump_fd >= 0) {
        gpiod_line_set_value_fd(pump_fd, PUMP_OFF);
        close(pump_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd) {
        fclose(log_fd);
    }
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if ((log_fd = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue;
        }

        int pump_status = PUMP_OFF;
        int moisture_percentage = 100 - (int)((adc_value - WET_ADC_VALUE) * 100.0 / (DRY_ADC_VALUE - WET_ADC_VALUE));
        if (moisture_percentage < 0) moisture_percentage = 0;
        if (moisture_percentage > 100) moisture_percentage = 100;

        if (moisture_percentage < 30) {
            pump_status = PUMP_ON;
            gpiod_line_set_value_fd(pump_fd, PUMP_ON);
        } else {
            gpiod_line_set_value_fd(pump_fd, PUMP_OFF);
        }

        log_data(adc_value, pump_status);
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

