        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t adc_value;
        if (read_adc(0, &adc_value) < 0) {
            fprintf(stderr, "ADC read failed\n");
            continue;
        }

        int32_t vout_mV = (adc_value * 3300) / 1023;
        int32_t b_mT = (vout_mV - 1650) / 100;

        time_t now = time(NULL);
        fprintf(log_file, "%ld,%.2f\n", now, (double)b_mT / 100.0);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

