#define SENSITIVITY_MV_PER_MT 1.65
#define THRESHOLD_MT 10.0
#define DELAY_MS 100

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SPI_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI CS GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SPI_CS, 1) < 0) {
        fprintf(stderr, "Failed to set SPI CS high\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    FILE *log_file = fopen("magnetic_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        unsigned char buffer[3] = {1, (8 + MCP3008_CHANNEL) << 4, 0};
        if (gpioSPIDataRW(SPI_CHANNEL, buffer, 3) < 0) {
            fprintf(stderr, "Failed to read from MCP3008\n");
            break;
        }

        int adc_value = ((buffer[1] & 3) << 8) | buffer[2];
        double voltage = adc_value * VCC / 1023.0;
        double field_mT = (voltage - VCC / 2) * 1000 / SENSITIVITY_MV_PER_MT;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s: %f mT\n", time_str, field_mT);
        fflush(log_file);

        if (field_mT > THRESHOLD_MT) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(DELAY_MS);
    }

    if (log_file) {
        fclose(log_file);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return 0;
}

