    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (adc_value == -1) {
        fprintf(file, "%s ERROR: ADC read failure\n", timestamp);
    } else {
        fprintf(file, "%s ADC Value: %d\n", timestamp, adc_value);
    }

    fclose(file);
}

