#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "current_log.txt"
#define GPIO_CHIP 0
#define GPIO_LINE 17
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX_VALUE (1 << ADC_BITS)
#define VREF 5.0
#define SENSITIVITY 0.1

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[] = {1 << 7 | (channel & 0x07), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return adc_value;
}

double adc_value_to_current(uint16_t adc_value) {
    double voltage = (adc_value / (double)ADC_MAX_VALUE) * VREF;
    return voltage / SENSITIVITY;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = open_spi_device(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_line_request_by_name(gpiod_chip_open_by_index(GPIO_CHIP), "gpio17", GPIOD_LINE_REQUEST_DIRECTIONS_NONE);
    if (!line) {
        perror("Failed to request GPIO line");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,current_A\n");

    while (keep_running) {
        uint16_t adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        double current = adc_value_to_current(adc_value);
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

        fprintf(log_file, "%s,%f\n", timestamp, current);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_release(line);
    close(spi_fd);

    return EXIT_SUCCESS;
}

