#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <string.h>

#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define LOG_INTERVAL 1

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int debounce_read(struct gpiod_line *line) {
    int count = 0;
    int value = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int level = gpiod_line_get_value(line);
        if (level < 0) {
            fprintf(stderr, "Error reading GPIO line value\n");
            exit(EXIT_FAILURE);
        }
        value += level;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (value > (DEBOUNCE_SAMPLES / 2)) ? 1 : 0;
}

void cleanup() {
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

