#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t terminate_flag = 0;

typedef struct {
    int channel;
    int baud;
} spi_config_t;

void signal_handler(int signal) {
    terminate_flag = 1;
}

int spi_setup(spi_config_t config) {
    int spi_handle = spi_open(config.channel, config.baud, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n", config.channel, pi_strerror(spi_handle));
        return -1;
    }
    return spi_handle;
}

int read_mcp3008(int channel) {
    unsigned char tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx_buf[3] = {0};
    int spi_handle = spi_setup((spi_config_t){SPI_CHANNEL, SPI_BAUD});
    if (spi_handle < 0) {
        return -1;
    }

    while (1) {
        int result = spi_xfer(spi_handle, tx_buf, rx_buf, 3);
        if (result >= 0) {
            break;
        } else {
            fprintf(stderr, "SPI transfer failed: %s. Retrying...\n", pi_strerror(result));
            usleep(100000); // 100 ms delay before retry
        }
    }

    spi_close(spi_handle);
    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    double moisture = 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

void log_data(double moisture_level) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f\n", time_str, moisture_level);
    fclose(file);

    printf("%s,%.2f\n", time_str, moisture_level);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_strerror(gpioInitialise()));
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int spi_handle = spi_setup((spi_config_t){SPI_CHANNEL, SPI_BAUD});
    if (spi_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!terminate_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read MCP3008\n");
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);

        sleep(READ_DELAY);
    }

    spi_close(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

