#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/wait.h>
#include <errno.h>
#include <sys/stat.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 200000 // 200 ms in microseconds
#define POLL_INTERVAL 50000   // 50 ms in microseconds
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_DIR "/home/pi/security_cam/"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *event) {
    syslog(LOG_INFO, "%s", event);
}

int check_directory(const char *dir) {
    struct stat st;
    if (stat(dir, &st) == 0 && S_ISDIR(st.st_mode)) {
        return 1;
    }
    return 0;
}

void capture_image() {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    char filename[256];
    snprintf(filename, sizeof(filename), "%simage_%s.jpg", IMAGE_DIR, timestamp);

    char *args[] = {"libcamera-still", "-o", filename, "--width", "1280", "--height", "720", NULL};
    pid_t pid = fork();
    if (pid == 0) {
        execvp("libcamera-still", args);
        perror("execvp");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            log_event("Capture success");
        } else {
            log_event("Capture failure");
        }
    } else {
        perror("fork");
    }
}

int main() {
    openlog("PIR_Motion_Detector", LOG_PID | LOG_CONS, LOG_USER);
    log_event("Startup");

    if (gpioInitialise() < 0) {
        log_event("Failed to initialize pigpio");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0 || gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        log_event("Failed to configure GPIO");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (!check_directory(IMAGE_DIR)) {
        log_event("Image directory does not exist");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = 0;
    while (keep_running) {
        int state = gpioRead(GPIO_PIN);
        if (state != last_state) {
            usleep(DEBOUNCE_DELAY);
            int confirmed_state = gpioRead(GPIO_PIN);
            if (confirmed_state != last_state) {
                last_state = confirmed_state;
                if (last_state == 1) {
                    log_event("Motion detected");
                    capture_image();
                }
            }
        }
        usleep(POLL_INTERVAL);
    }

    gpioTerminate();
    log_event("Shutdown");
    closelog();
    return EXIT_SUCCESS;
}

