        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
    }
    return fd;
}

int set_format(int fd) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int init_mmap(int fd) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        return -1;
    }

    struct v4l2_buffer buf_out;
    memset(&buf_out, 0, sizeof(buf_out));
    buf_out.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf_out.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_STREAMON, &buf_out.type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        return -1;
    }

    return (int)buffer;
}

void save_frame(void *buffer, int fd, int frame_number) {
    char filename[32];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_number);
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return;
    }

    fprintf(file, "P5\n%d %d\n255\n", WIDTH, HEIGHT);
    if (fwrite(buffer, 1, WIDTH * HEIGHT, file) != WIDTH * HEIGHT) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
    }
    fclose(file);
}

void cleanup(int fd, void *buffer, int buffer_fd) {
    if (buffer) {
        munmap(buffer, buffer_fd);
    }
    if (ioctl(fd, VIDIOC_STREAMOFF, &buffer_fd) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }
    close(fd);
}

int main(int argc, char *argv[]) {
    const char *device = argc > 1 ? argv[1] : DEVICE;
    int fd = open_device(device);
    if (fd < 0) return EXIT_FAILURE;

    if (set_format(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    void *buffer = init_mmap(fd);
    if (buffer == (void *)-1) {
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    int frame_number = 1;
    while (!stop_flag) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv = {TIMEOUT_SEC, TIMEOUT_USEC};
        int ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error in select: %s\n", strerror(errno));
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout occurred\n");
            continue;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        save_frame(buffer, fd, frame_number++);
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            break;
        }
    }

    cleanup(fd, buffer, buf.memory);
    return EXIT_SUCCESS;
}
