#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FRAMES 4
#define BUFFER_SIZE (WIDTH * HEIGHT * 2) // YUYV format
#define MAX_UDP_PAYLOAD 65000
#define HEADER_SIZE 12

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

struct buffer {
    void *start;
    size_t length;
};

struct buffer buffers[FRAMES];
int fd;
int sockfd;
struct sockaddr_in server_addr;
char *server_ip;
int server_port;

int init_socket(const char *ip, int port) {
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip, &server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(sockfd);
        return -1;
    }

    return 0;
}

int init_device() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = FRAMES;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return -1;
    }

    for (int i = 0; i < FRAMES; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return -1;
        }
    }

    for (int i = 0; i < FRAMES; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            close(fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        close(fd);
        return -1;
    }

    return 0;
}

void cleanup() {
    for (int i = 0; i < FRAMES; ++i) {
        if (buffers[i].start) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }
    close(fd);
    close(sockfd);
}

void stream_video() {
    struct v4l2_buffer buf;
    int frame_index = 0;
    int fragment_index = 0;
    int total_fragments;

    while (keep_running) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("VIDIOC_DQBUF");
            break;
        }

        total_fragments = (buffers[buf.index].length + MAX_UDP_PAYLOAD - 1) / MAX_UDP_PAYLOAD;
        for (fragment_index = 0; fragment_index < total_fragments; ++fragment_index) {
            int payload_size = (buffers[buf.index].length - fragment_index * MAX_UDP_PAYLOAD > MAX_UDP_PAYLOAD) ?
                               MAX_UDP_PAYLOAD : buffers[buf.index].length - fragment_index * MAX_UDP_PAYLOAD;

            char header[HEADER_SIZE];
            header[0] = frame_index;
            header[1] = fragment_index;
            header[2] = total_fragments;
            header[3] = payload_size;
            memcpy(header + 4, &frame_index, 4);
            memcpy(header + 8, &fragment_index, 4);

            ssize_t sent_bytes = sendto(sockfd, header, HEADER_SIZE, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
            if (sent_bytes < 0) {
                perror("sendto");
                break;
            }

            sent_bytes = sendto(sockfd, (char *)buffers[buf.index].start + fragment_index * MAX_UDP_PAYLOAD, payload_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
            if (sent_bytes < 0) {
                perror("sendto");
                break;
            }
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }

        frame_index = (frame_index + 1) % FRAMES;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    server_ip = argv[1];
    server_port = atoi(argv[2]);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_socket(server_ip, server_port) < 0) {
        return EXIT_FAILURE;
    }

    if (init_device() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    stream_video();

    cleanup();
    return EXIT_SUCCESS;
}

