#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_GPIO 4
#define TILT_GPIO 5
#define TILT_UP_GPIO 6
#define TILT_DOWN_GPIO 7
#define PAN_LEFT_GPIO 8
#define PAN_RIGHT_GPIO 9

#define PERIOD_NS 20000
#define MIN_DUTY 5000
#define MAX_DUTY 10000
#define DUTY_STEP 500
#define INITIAL_DUTY 7500
#define POLL_INTERVAL_MS 50

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *pan_line, *tilt_line, *tilt_up_line, *tilt_down_line, *pan_left_line, *pan_right_line;
    struct gpiod_line_event *event;
    int pan_duty = INITIAL_DUTY;
    int tilt_duty = INITIAL_DUTY;
    int ret;

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_GPIO);
    tilt_line = gpiod_chip_get_line(chip, TILT_GPIO);
    tilt_up_line = gpiod_chip_get_line(chip, TILT_UP_GPIO);
    tilt_down_line = gpiod_chip_get_line(chip, TILT_DOWN_GPIO);
    pan_left_line = gpiod_chip_get_line(chip, PAN_LEFT_GPIO);
    pan_right_line = gpiod_chip_get_line(chip, PAN_RIGHT_GPIO);

    if (!pan_line || !tilt_line || !tilt_up_line || !tilt_down_line || !pan_left_line || !pan_right_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(pan_line, "pan_servo", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request pan line: %s\n", gpiod_strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(tilt_line, "tilt_servo", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request tilt line: %s\n", gpiod_strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(tilt_up_line, "tilt_up_button", GPIOD_LINE_REQUEST_FLAG_FALLING_EDGE | GPIOD_LINE_REQUEST_FLAG_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request tilt up line: %s\n", gpiod_strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(tilt_down_line, "tilt_down_button", GPIOD_LINE_REQUEST_FLAG_FALLING_EDGE | GPIOD_LINE_REQUEST_FLAG_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request tilt down line: %s\n", gpiod_strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(pan_left_line, "pan_left_button", GPIOD_LINE_REQUEST_FLAG_FALLING_EDGE | GPIOD_LINE_REQUEST_FLAG_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request pan left line: %s\n", gpiod_strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(pan_right_line, "pan_right_button", GPIOD_LINE_REQUEST_FLAG_FALLING_EDGE | GPIOD_LINE_REQUEST_FLAG_BOTH_EDGES);
    if (ret < 0) {
        fprintf(stderr, "Failed to request pan right line: %s\n", gpiod_strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_set_value(pan_line, 1);
    gpiod_line_set_value(tilt_line, 1);
    usleep(PERIOD_NS / 2);
    gpiod_line_set_value(pan_line, 0);
    gpiod_line_set_value(tilt_line, 0);

    while (keep_running) {
        gpiod_line_set_value(pan_line, 1);
        gpiod_line_set_value(tilt_line, 1);
        usleep(PERIOD_NS - MIN_DUTY);
        gpiod_line_set_value(pan_line, 0);
        gpiod_line_set_value(tilt_line, 0);
        usleep(MIN_DUTY);

        event = gpiod_line_event_wait(tilt_up_line, -1);
        if (event && gpiod_line_event_get_value(event) == 0) {
            tilt_duty = (tilt_duty + DUTY_STEP <= MAX_DUTY) ? tilt_duty + DUTY_STEP : MAX_DUTY;
        }
        gpiod_line_event_free(event);

        event = gpiod_line_event_wait(tilt_down_line, -1);
        if (event && gpiod_line_event_get_value(event) == 0) {
            tilt_duty = (tilt_duty - DUTY_STEP >= MIN_DUTY) ? tilt_duty - DUTY_STEP : MIN_DUTY;
        }
        gpiod_line_event_free(event);

        event = gpiod_line_event_wait(pan_left_line, -1);
        if (event && gpiod_line_event_get_value(event) == 0) {
            pan_duty = (pan_duty - DUTY_STEP >= MIN_DUTY) ? pan_duty - DUTY_STEP : MIN_DUTY;
        }
        gpiod_line_event_free(event);

        event = gpiod_line_event_wait(pan_right_line, -1);
        if (event && gpiod_line_event_get_value(event) == 0) {
            pan_duty = (pan_duty + DUTY_STEP <= MAX_DUTY) ? pan_duty + DUTY_STEP : MAX_DUTY;
        }
        gpiod_line_event_free(event);

        usleep(POLL_INTERVAL_MS * 1000 - PERIOD_NS);
    }

    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_line_release(tilt_up_line);
    gpiod_line_release(tilt_down_line);
    gpiod_line_release(pan_left_line);
    gpiod_line_release(pan_right_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

