#include <time.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define TIMEOUT 2
#define JPEG_QUALITY 75

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_device(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Failed to open device");
        return -1;
    }
    return fd;
}

int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to get device capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        return -1;
    }

    return 0;
}

int mmap_buffers(int fd, struct v4l2_buffer *buffers, void **start, size_t *length, int count) {
    for (int i = 0; i < count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            return -1;
        }

        start[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (start[i] == MAP_FAILED) {
            perror("Failed to mmap buffer");
            return -1;
        }

        buffers[i] = buf;
        length[i] = buf.length;
    }
    return 0;
}

int queue_buffers(int fd, struct v4l2_buffer *buffers, int count) {
    for (int i = 0; i < count; ++i) {
        struct v4l2_buffer buf = buffers[i];
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            return -1;
        }
    }
    return 0;
}

int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        return -1;
    }
    return 0;
}

int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        if (errno == EAGAIN) {
            return 0; // No buffer available yet
        }
        perror("Failed to dequeue buffer");
        return -1;
    }
    return 1;
}

int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
        return -1;
    }
    return 0;
}

void unmap_buffers(void **start, size_t *length, int count) {
    for (int i = 0; i < count; ++i) {
        if (munmap(start[i], length[i]) < 0) {
            perror("Failed to unmap buffer");
        }
    }
}

void free_buffers(int fd, struct v4l2_buffer *buffers, int count) {
    for (int i = 0; i < count; ++i) {
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) < 0) {
            perror("Failed to unqueue buffer");
        }
    }
}

void yuyv_to_rgb24(const void *yuyv, uint8_t *rgb, int width, int height) {
    const uint8_t *src = (const uint8_t *)yuyv;
    for (int j = 0; j < height; ++j) {
        for (int i = 0; i < width; i += 2) {
            int y0 = src[0] - 16;
            int u = src[1] - 128;
            int y1 = src[2] - 16;
            int v = src[3] - 128;

            int r0 = (298 * y0 + 409 * v + 128) >> 8;
            int g0 = (298 * y0 - 100 * u - 208 * v + 128) >> 8;
            int b0 = (298 * y0 + 516 * u + 128) >> 8;

            int r1 = (298 * y1 + 409 * v + 128) >> 8;
            int g1 = (298 * y1 - 100 * u - 208 * v + 128) >> 8;
            int b1 = (298 * y1 + 516 * u + 128) >> 8;

            r0 = r0 < 0 ? 0 : r0 > 255 ? 255 : r0;
            g0 = g0 < 0 ? 0 : g0 > 255 ? 255 : g0;
            b0 = b0 < 0 ? 0 : b0 > 255 ? 255 : b0;

            r1 = r1 < 0 ? 0 : r1 > 255 ? 255 : r1;
            g1 = g1 < 0 ? 0 : g1 > 255 ? 255 : g1;
            b1 = b1 < 0 ? 0 : b1 > 255 ? 255 : b1;

            rgb[0] = (uint8_t)r0;
            rgb[1] = (uint8_t)g0;
            rgb[2] = (uint8_t)b0;

            rgb[3] = (uint8_t)r1;
            rgb[4] = (uint8_t)g1;
            rgb[5] = (uint8_t)b1;

            src += 4;
            rgb += 6;
        }
    }
}

void box_blur(uint8_t *rgb, int width, int height) {
    int radius = 2;
    int kernel_size = 2 * radius + 1;
    int kernel_sum = kernel_size * kernel_size;
    uint8_t *temp = malloc(width * height * 3);
    if (!temp) {
        perror("Failed to allocate memory for temp buffer");
        exit(EXIT_FAILURE);
    }

    for (int channel = 0; channel < 3; ++channel) {
        for (int y = 0; y < height; ++y) {
            int sum = 0;
            for (int dy = -radius; dy <= radius; ++dy) {
                int ny = y + dy;
                if (ny < 0) ny = 0;
                if (ny >= height) ny = height - 1;
                for (int x = 0; x < width; ++x) {
                    sum += rgb[(ny * width + x) * 3 + channel];
                }
            }
            for (int x = 0; x < width; ++x) {
                int sx = x - radius;
                int ex = x + radius + 1;
                if (sx < 0) sx = 0;
                if (ex > width) ex = width;
                int local_sum = 0;
                for (int xx = sx; xx < ex; ++xx) {
                    local_sum += rgb[(y * width + xx) * 3 + channel];
                }
                temp[(y * width + x) * 3 + channel] = local_sum / kernel_sum;
            }
        }
        memcpy(rgb, temp, width * height * 3);
    }

    free(temp);
}

void save_as_jpeg(const uint8_t *rgb, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Can't open %s\n", filename);
        exit(EXIT_FAILURE);
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
}

int main() {
    signal(SIGINT, handle_sigint);

    int fd = open_device(DEVICE);
    if (fd < 0) return EXIT_FAILURE;

    if (init_device(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buffers[4];
    void *start[4];
    size_t length[4];

    if (mmap_buffers(fd, buffers, start, length, 4) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (queue_buffers(fd, buffers, 4) < 0) {
        unmap_buffers(start, length, 4);
        close(fd);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd) < 0) {
        free_buffers(fd, buffers, 4);
        unmap_buffers(start, length, 4);
        close(fd);
        return EXIT_FAILURE;
    }

    struct timeval timeout = {TIMEOUT, 0};
    fd_set fds;
    struct v4l2_buffer buf;

    while (keep_running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        int ret = select(fd + 1, &fds, NULL, NULL, &timeout);
        if (ret < 0) {
            perror("Select error");
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            break;
        }

        if (dequeue_buffer(fd, &buf) > 0) {
            uint8_t *rgb = malloc(WIDTH * HEIGHT * 3);
            if (!rgb) {
                perror("Failed to allocate RGB buffer");
                break;
            }

            yuyv_to_rgb24(start[buf.index], rgb, WIDTH, HEIGHT);
            box_blur(rgb, WIDTH, HEIGHT);

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char filename[64];
            strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", tm_info);

            save_as_jpeg(rgb, WIDTH, HEIGHT, filename);

            free(rgb);
            if (queue_buffer(fd, &buf) < 0) {
                break;
            }
        }
    }

    if (stop_streaming(fd) < 0) {
        fprintf(stderr, "Failed to stop streaming\n");
    }

    free_buffers(fd, buffers, 4);
    unmap_buffers(start, length, 4);
    close(fd);

    return EXIT_SUCCESS;
}

