            for (int dy = -radius; dy <= radius; ++dy) {
                int ny = y + dy;
                if (ny < 0) ny = 0;
                if (ny >= height) ny = height - 1;
                for (int x = 0; x < width; ++x) {
                    sum += rgb[(ny * width + x) * 3 + channel];
                }
            }
            for (int x = 0; x < width; ++x) {
                int sx = x - radius;
                int ex = x + radius + 1;
                if (sx < 0) sx = 0;
                if (ex > width) ex = width;
                int local_sum = 0;
                for (int xx = sx; xx < ex; ++xx) {
                    local_sum += rgb[(y * width + xx) * 3 + channel];
                }
                temp[(y * width + x) * 3 + channel] = local_sum / kernel_sum;
            }
        }
        memcpy(rgb, temp, width * height * 3);
    }

    free(temp);
}

void save_as_jpeg(const uint8_t *rgb, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Can't open %s\n", filename);
        exit(EXIT_FAILURE);
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
}

int main() {
    signal(SIGINT, handle_sigint);

    int fd = open_device(DEVICE);
    if (fd < 0) return EXIT_FAILURE;

    if (init_device(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buffers[4];
    void *start[4];
    size_t length[4];

    if (mmap_buffers(fd, buffers, start, length, 4) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    if (queue_buffers(fd, buffers, 4) < 0) {
        unmap_buffers(start, length, 4);
        close(fd);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd) < 0) {
        free_buffers(fd, buffers, 4);
        unmap_buffers(start, length, 4);
        close(fd);
        return EXIT_FAILURE;
    }

    struct timeval timeout = {TIMEOUT, 0};
    fd_set fds;
    struct v4l2_buffer buf;

    while (keep_running) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        int ret = select(fd + 1, &fds, NULL, NULL, &timeout);
        if (ret < 0) {
            perror("Select error");
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            break;
        }

        if (dequeue_buffer(fd, &buf) > 0) {
            uint8_t *rgb = malloc(WIDTH * HEIGHT * 3);
            if (!rgb) {
                perror("Failed to allocate RGB buffer");
                break;
            }

            yuyv_to_rgb24(start[buf.index], rgb, WIDTH, HEIGHT);
            box_blur(rgb, WIDTH, HEIGHT);

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char filename[64];
            strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", tm_info);

            save_as_jpeg(rgb, WIDTH, HEIGHT, filename);

            free(rgb);
            if (queue_buffer(fd, &buf) < 0) {
                break;
            }
        }
    }

    if (stop_streaming(fd) < 0) {
        fprintf(stderr, "Failed to stop streaming\n");
    }

    free_buffers(fd, buffers, 4);
    unmap_buffers(start, length, 4);
    close(fd);

    return EXIT_SUCCESS;
}
