    int fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        if (errno == ENOENT) {
            fprintf(stderr, "Error: Device %s does not exist.\n", DEVICE);
        } else {
            print_error_and_exit("Error opening device");
        }
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        print_error_and_exit("Error querying device capabilities");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Device Name: %s\n", cap.card);
    printf("Driver Name: %s\n", cap.driver);
    printf("Capabilities: ");
    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) printf("Video Capture ");
    if (cap.capabilities & V4L2_CAP_VIDEO_OUTPUT) printf("Video Output ");
    if (cap.capabilities & V4L2_CAP_VIDEO_OVERLAY) printf("Video Overlay ");
    if (cap.capabilities & V4L2_CAP_VBI_CAPTURE) printf("VBI Capture ");
    if (cap.capabilities & V4L2_CAP_VBI_OUTPUT) printf("VBI Output ");
    if (cap.capabilities & V4L2_CAP_SLICED_VBI_CAPTURE) printf("Sliced VBI Capture ");
    if (cap.capabilities & V4L2_CAP_SLICED_VBI_OUTPUT) printf("Sliced VBI Output ");
    if (cap.capabilities & V4L2_CAP_RDS_CAPTURE) printf("RDS Capture ");
    if (cap.capabilities & V4L2_CAP_RDS_OUTPUT) printf("RDS Output ");
    if (cap.capabilities & V4L2_CAP_TUNER) printf("Tuner ");
    if (cap.capabilities & V4L2_CAP_AUDIO) printf("Audio ");
    if (cap.capabilities & V4L2_CAP_RADIO) printf("Radio ");
    if (cap.capabilities & V4L2_CAP_MODULATOR) printf("Modulator ");
    if (cap.capabilities & V4L2_CAP_READWRITE) printf("Read/Write ");
    if (cap.capabilities & V4L2_CAP_ASYNCIO) printf("Async IO ");
    if (cap.capabilities & V4L2_CAP_STREAMING) printf("Streaming ");
    printf("\n");

    struct v4l2_fmtdesc fmt;
    fmt.index = 0;
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == 0) {
        printf("Format: %s\n", fmt.description);
        fmt.index++;
    }

    struct v4l2_frmsizeenum frmsize;
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_MJPEG; // Assuming MJPEG format

    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("Frame Size: %dx%d (%s)\n", frmsize.discrete.width, frmsize.discrete.height, frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE ? "Discrete" : "Stepwise");
        frmsize.index++;
    }

    struct v4l2_frmivalenum frmintrvl;
    frmintrvl.index = 0;
    frmintrvl.pixel_format = V4L2_PIX_FMT_MJPEG; // Assuming MJPEG format
    frmintrvl.width = frmsize.discrete.width;
    frmintrvl.height = frmsize.discrete.height;

    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmintrvl) == 0) {
        printf("Frame Interval: %d/%d (%s)\n", frmintrvl.discrete.numerator, frmintrvl.discrete.denominator, frmintrvl.type == V4L2_FRMIVAL_TYPE_DISCRETE ? "Discrete" : "Stepwise");
        frmintrvl.index++;
    }

    struct v4l2_queryctrl ctrl;
    ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        if (errno == EINVAL) {
            printf("Autofocus not supported.\n");
        } else {
            print_error_and_exit("Error querying autofocus control");
        }
    } else {
        printf("Autofocus supported.\n");
    }

    close(fd);
    return EXIT_SUCCESS;
}

