#define PAN_PIN 4
#define TILT_PIN 5
#define UP_PIN 6
#define DOWN_PIN 7
#define LEFT_PIN 8
#define RIGHT_PIN 9

#define CENTER_PULSE 1500
#define MIN_PULSE 1000
#define MAX_PULSE 2000
#define PULSE_STEP 10
#define LOOP_DELAY 50

static int pan_pulse = CENTER_PULSE;
static int tilt_pulse = CENTER_PULSE;

void handle_signal(int sig) {
    gpioPWM(PAN_PIN, 0);
    gpioPWM(TILT_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Pan servo on GPIO %d, Tilt servo on GPIO %d\n", PAN_PIN, TILT_PIN);
    printf("UP button on GPIO %d, DOWN button on GPIO %d\n", UP_PIN, DOWN_PIN);
    printf("LEFT button on GPIO %d, RIGHT button on GPIO %d\n", LEFT_PIN, RIGHT_PIN);
    printf("Center position pulse width: %d microseconds\n", CENTER_PULSE);

    if (gpioSetMode(UP_PIN, PI_INPUT) < 0 ||
        gpioSetMode(DOWN_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LEFT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set button pins as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(UP_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(DOWN_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(LEFT_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(RIGHT_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistors on button pins\n");
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(PAN_PIN, pan_pulse) < 0 || gpioPWM(TILT_PIN, tilt_pulse) < 0) {
        fprintf(stderr, "Failed to initialize servos\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        if (gpioRead(UP_PIN) == 0) {
            tilt_pulse = (tilt_pulse + PULSE_STEP > MAX_PULSE) ? MAX_PULSE : tilt_pulse + PULSE_STEP;
            gpioPWM(TILT_PIN, tilt_pulse);
        } else if (gpioRead(DOWN_PIN) == 0) {
            tilt_pulse = (tilt_pulse - PULSE_STEP < MIN_PULSE) ? MIN_PULSE : tilt_pulse - PULSE_STEP;
            gpioPWM(TILT_PIN, tilt_pulse);
        } else if (gpioRead(LEFT_PIN) == 0) {
            pan_pulse = (pan_pulse - PULSE_STEP < MIN_PULSE) ? MIN_PULSE : pan_pulse - PULSE_STEP;
            gpioPWM(PAN_PIN, pan_pulse);
        } else if (gpioRead(RIGHT_PIN) == 0) {
            pan_pulse = (pan_pulse + PULSE_STEP > MAX_PULSE) ? MAX_PULSE : pan_pulse + PULSE_STEP;
            gpioPWM(PAN_PIN, pan_pulse);
        }

        usleep(LOOP_DELAY * 1000);
    }

    // This point is never reached due to the infinite loop
    gpioTerminate();
    return 0;
}

