#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/stat.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2000 // 2 seconds
#define POLL_INTERVAL 100  // 100 ms
#define JPEG_QUALITY 85
#define JPEG_WIDTH 640
#define JPEG_HEIGHT 480

static volatile sig_atomic_t keep_running = 1;
static char *server_ip = NULL;
static int server_port = 0;
static int pi_camera_fd = -1;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void check_error(int result, const char *message) {
    if (result != 0) {
        fprintf(stderr, "%s: %s\n", message, strerror(result));
        keep_running = 0;
    }
}

void create_directory(const char *path) {
    struct stat st = {0};
    if (stat(path, &st) == -1) {
        if (mkdir(path, 0700) == -1) {
            if (errno != EEXIST) {
                perror("mkdir");
                keep_running = 0;
            }
        }
    }
}

void capture_snapshot(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d --quality %d", filename, JPEG_WIDTH, JPEG_HEIGHT, JPEG_QUALITY);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Failed to capture snapshot: %s\n", strerror(result));
    }
}

void send_snapshot(const char *filename) {
    CURL *curl;
    CURLcode res;
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    char iso_timestamp[40];
    snprintf(iso_timestamp, sizeof(iso_timestamp), "%s.%06ldZ", timestamp, (long int)now);

    char url[256];
    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

    curl = curl_easy_init();
    if (curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        char json_payload[512];
        snprintf(json_payload, sizeof(json_payload), "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": \"detected\", \"gpio_pin\": %d}", filename, iso_timestamp, GPIO_PIN);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    server_ip = argv[1];
    server_port = atoi(argv[2]);

    if (curl_global_init(CURL_GLOBAL_ALL) != CURLE_OK) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return EXIT_FAILURE;
    }

    setup_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        curl_global_cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        curl_global_cleanup();
        return EXIT_FAILURE;
