static char *server_ip = NULL;
static int server_port = 0;
static int pi_camera_fd = -1;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

void check_error(int result, const char *message) {
    if (result != 0) {
        fprintf(stderr, "%s: %s\n", message, strerror(result));
        keep_running = 0;
    }
}

void create_directory(const char *path) {
    struct stat st = {0};
    if (stat(path, &st) == -1) {
        if (mkdir(path, 0700) == -1) {
            if (errno != EEXIST) {
                perror("mkdir");
                keep_running = 0;
            }
        }
    }
}

void capture_snapshot(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d --quality %d", filename, JPEG_WIDTH, JPEG_HEIGHT, JPEG_QUALITY);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Failed to capture snapshot: %s\n", strerror(result));
    }
}

