    char iso_timestamp[40];
    snprintf(iso_timestamp, sizeof(iso_timestamp), "%s.%06ldZ", timestamp, (long int)now);

    char url[256];
    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

