#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <sys/wait.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define CAMERA_CMD "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log, "[%s] %s\n", timestamp, message);
        fclose(log);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Claim GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "motion_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_event("PIR motion sensor initialized");

    while (keep_running) {
        ret = gpiod_line_event_wait(line, DEBOUNCE_MS * 1000);
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            break;
        }

        if (gpiod_line_event_read(line) == GPIOD_LINE_EVENT_FALLING_EDGE) {
            char filename[64];
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%3N.jpg", tm_info);
            snprintf(filename, sizeof(filename), "%s/%s", IMAGE_DIR, filename);

            char cmd[256];
            snprintf(cmd, sizeof(cmd), CAMERA_CMD, filename);

            log_event("Motion detected, capturing image");

            int status = system(cmd);
            if (status != 0) {
                log_event("Failed to capture image");
            } else {
                log_event("Image captured successfully");
            }
        }
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    log_event("Exiting program");

    return EXIT_SUCCESS;
}

