#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define TIMEOUT_SEC 2

static int fd = -1;
static void *buffers[1];
static int buffer_size;
static int quit = 0;

void error_exit(const char *msg) {
    perror(msg);
    cleanup();
    exit(EXIT_FAILURE);
}

void cleanup() {
    if (buffers[0]) {
        if (munmap(buffers[0], buffer_size) == -1) {
            perror("munmap");
        }
    }
    if (fd != -1) {
        if (close(fd) == -1) {
            perror("close");
        }
    }
}

void sigint_handler(int sig) {
    quit = 1;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_buffer *buffers_ptr;
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        error_exit("Failed to open device");
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        error_exit("Failed to get device capabilities");
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        error_exit("Failed to set format");
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Could not set pixel format to YUYV\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        error_exit("Failed to request buffers");
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        error_exit("Failed to query buffer");
    }

    buffer_size = buf.length;
    buffers[0] = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffers[0] == MAP_FAILED) {
        error_exit("Failed to mmap buffer");
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        error_exit("Failed to queue buffer");
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        error_exit("Failed to start streaming");
    }

    fd_set fds;
    struct timeval tv;
    int r;

    while (!quit) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = TIMEOUT_SEC;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) {
                continue;
            }
            error_exit("Select error");
        } else if (r == 0) {
            fprintf(stderr, "Timeout occurred\n");
            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        while (1) {
            ret = ioctl(fd, VIDIOC_DQBUF, &buf);
            if (ret == -1) {
                if (errno == EAGAIN) {
                    break;
                }
                error_exit("Failed to dequeue buffer");
            }
            if (buf.bytesused != buffer_size) {
                fprintf(stderr, "Buffer size mismatch\n");
                cleanup();
                exit(EXIT_FAILURE);
            }
            if (buf.bytesused != WIDTH * HEIGHT * 2) {
                fprintf(stderr, "Captured frame size mismatch\n");
                cleanup();
                exit(EXIT_FAILURE);
            }
            break;
        }

        FILE *fp = fopen("cropped.yuv", "wb");
        if (!fp) {
            error_exit("Failed to open file");
        }

        unsigned char *src = (unsigned char *)buffers[0];
        unsigned char *dst = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
        if (!dst) {
            perror("Failed to allocate memory for cropped frame");
            fclose(fp);
            cleanup();
            exit(EXIT_FAILURE);
        }

        for (int y = 0; y < CROP_HEIGHT; y++) {
            for (int x = 0; x < CROP_WIDTH; x++) {
                int src_index = ((CROP_Y + y) * WIDTH + (CROP_X + x)) * 2;
                int dst_index = (y * CROP_WIDTH + x) * 2;
                memcpy(&dst[dst_index], &src[src_index], 4);
            }
        }

        if (fwrite(dst, 1, CROP_WIDTH * CROP_HEIGHT * 2, fp) != CROP_WIDTH * CROP_HEIGHT * 2) {
            perror("Failed to write cropped frame to file");
            free(dst);
            fclose(fp);
            cleanup();
            exit(EXIT_FAILURE);
        }

        free(dst);
        fclose(fp);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            error_exit("Failed to queue buffer");
        }

        if (quit) {
            break;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        error_exit("Failed to stop streaming");
    }

    cleanup();
    return EXIT_SUCCESS;
}

