        for (int y = 0; y < CROP_HEIGHT; y++) {
            for (int x = 0; x < CROP_WIDTH; x++) {
                int src_index = ((CROP_Y + y) * WIDTH + (CROP_X + x)) * 2;
                int dst_index = (y * CROP_WIDTH + x) * 2;
                memcpy(&dst[dst_index], &src[src_index], 4);
            }
        }

        if (fwrite(dst, 1, CROP_WIDTH * CROP_HEIGHT * 2, fp) != CROP_WIDTH * CROP_HEIGHT * 2) {
            perror("Failed to write cropped frame to file");
            free(dst);
            fclose(fp);
            cleanup();
            exit(EXIT_FAILURE);
        }

        free(dst);
        fclose(fp);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            error_exit("Failed to queue buffer");
        }

        if (quit) {
            break;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        error_exit("Failed to stop streaming");
    }

    cleanup();
    return EXIT_SUCCESS;
}
