#define MAX_PULSE_WIDTH 2500
#define PULSE_INCREMENT 50
#define ANGLE_INCREMENT 5
#define NEUTRAL_ANGLE 90
#define NEUTRAL_PULSE_WIDTH 1500
#define DELAY_MS 100

volatile sig_atomic_t terminate = 0;

void handle_sigint(int sig) {
    terminate = 1;
}

int calculate_pulse_width(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Angle out of range (0-180 degrees).\n");
        return -1;
    }
    return MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180);
}

void set_servo_angle(int pin, int angle) {
    int pulse_width = calculate_pulse_width(angle);
    if (pulse_width == -1) {
        return;
    }
    if (gpioPWM(pin, PWM_FREQUENCY, pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set PWM for GPIO %d.\n", pin);
    }
}

void cleanup(int pan_pin, int tilt_pin) {
    set_servo_angle(pan_pin, NEUTRAL_ANGLE);
    set_servo_angle(tilt_pin, NEUTRAL_ANGLE);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    set_servo_angle(PAN_PIN, pan_angle);
    set_servo_angle(TILT_PIN, tilt_angle);

    char input;
    while (!terminate) {
        input = getchar();
        if (input == 'q') {
            terminate = 1;
        } else if (input == 'w') {
            if (tilt_angle + ANGLE_INCREMENT <= 180) {
                tilt_angle += ANGLE_INCREMENT;
            }
        } else if (input == 's') {
            if (tilt_angle - ANGLE_INCREMENT >= 0) {
                tilt_angle -= ANGLE_INCREMENT;
            }
        } else if (input == 'a') {
            if (pan_angle - ANGLE_INCREMENT >= 0) {
                pan_angle -= ANGLE_INCREMENT;
            }
        } else if (input == 'd') {
            if (pan_angle + ANGLE_INCREMENT <= 180) {
                pan_angle += ANGLE_INCREMENT;
            }
        }

        set_servo_angle(PAN_PIN, pan_angle);
        set_servo_angle(TILT_PIN, tilt_angle);

        usleep(DELAY_MS * 1000);
    }

    cleanup(PAN_PIN, TILT_PIN);
    return 0;
}

