    {0x27, 0x45, 0x45, 0x45, 0x39}, // 5
    {0x3C, 0x4A, 0x49, 0x49, 0x30}, // 6
    {0x01, 0x71, 0x09, 0x05, 0x03}, // 7
    {0x36, 0x49, 0x49, 0x49, 0x36}, // 8
    {0x06, 0x49, 0x49, 0x29, 0x1E}, // 9
    {0x00, 0x36, 0x36, 0x00, 0x00}, // :
    {0x00, 0x56, 0x36, 0x00, 0x00}, // ;
    {0x08, 0x14, 0x22, 0x41, 0x00}, // <
    {0x14, 0x14, 0x14, 0x14, 0x14}, // =
    {0x00, 0x41, 0x22, 0x14, 0x08}, // >
    {0x02, 0x01, 0x51, 0x09, 0x06}, // ?
    {0x32, 0x49, 0x79, 0x41, 0x3E}, // @
    // Add more characters as needed
};

// Function prototypes
void display_init();
void display_clear();
void display_draw_char(int x, int y, char c);
void display_update();
void display_text(const char *text, int x, int y);
void read_temperature(char *buffer, size_t size);
void read_cpu_usage(char *buffer, size_t size);
void handle_sigint(int sig);
void log_error(const char *message);

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    display_init();

    while (1) {
        char temp_buffer[32];
        char cpu_buffer[32];

        read_temperature(temp_buffer, sizeof(temp_buffer));
        read_cpu_usage(cpu_buffer, sizeof(cpu_buffer));

        display_clear();
        display_text(temp_buffer, 0, 0);
        display_text(cpu_buffer, 0, 8);
        display_update();

        sleep(1);
    }

    gpioTerminate();
    return 0;
}

void display_init() {
    if (gpioI2CSetup(OLED_I2C_BUS, OLED_I2C_ADDR) < 0) {
        log_error("Failed to setup I2C");
        exit(1);
    }

    // Initialize SSD1306
    unsigned char init_sequence[] = {
        0xAE, // Display off
        0xD5, 0x80, // Set display clock divide ratio/oscillator frequency
        0xA8, 0x3F, // Set multiplex ratio
        0xD3, 0x00, // Set display offset
        0x40, // Set display start line
        0x8D, 0x14, // Set charge pump
        0x20, 0x00, // Set memory addressing mode
        0xA1, // Set segment re-map
        0xC8, // Set COM output scan direction
        0xDA, 0x12, // Set COM pins hardware configuration
        0x81, 0xCF, // Set contrast control
        0xD9, 0xF1, // Set pre-charge period
        0xDB, 0x40, // Set VCOMH deselect level
        0xA4, // Disable entire display on
        0xA6, // Set normal display
        0x2E, // Deactivate scroll
        0xAF // Display on
    };

    for (size_t i = 0; i < sizeof(init_sequence); i++) {
        if (gpioI2CWriteByte(OLED_I2C_BUS, OLED_I2C_ADDR, init_sequence[i]) < 0) {
            log_error("Failed to write I2C byte");
            exit(1);
        }
    }
}

void display_clear() {
    unsigned char buffer[OLED_WIDTH * OLED_HEIGHT / 8] = {0};
    for (int i = 0; i < 8; i++) {
        if (gpioI2CWrite(OLED_I2C_BUS, OLED_I2C_ADDR, 0xB0 + i, 0x00, 0x10, buffer) < 0) {
            log_error("Failed to clear display");
            exit(1);
        }
    }
}

void display_draw_char(int x, int y, char c) {
    if (x >= OLED_WIDTH || y >= OLED_HEIGHT) return;

    int char_index = c - 32;
    if (char_index < 0 || char_index >= sizeof(font5x7) / sizeof(font5x7[0])) return;

    for (int i = 0; i < FONT_HEIGHT; i++) {
        unsigned char line = font5x7[char_index][i];
        for (int j = 0; j < FONT_WIDTH; j++) {
            if (line & (1 << (FONT_WIDTH - 1 - j))) {
                int byte_index = (y + i) * OLED_WIDTH + (x + j);
                int bit_index = byte_index % 8;
                int byte_offset = byte_index / 8;
                unsigned char buffer[OLED_WIDTH * OLED_HEIGHT / 8];
                if (gpioI2CRead(OLED_I2C_BUS, OLED_I2C_ADDR, 0xB0 + (y + i), 0x00, 0x10, buffer) < 0) {
                    log_error("Failed to read display buffer");
                    exit(1);
                }
                buffer[byte_offset] |= (1 << (7 - bit_index));
                if (gpioI2CWrite(OLED_I2C_BUS, OLED_I2C_ADDR, 0xB0 + (y + i), 0x00 + (byte_offset / 16), 0x02, &buffer[byte_offset / 16]) < 0) {
                    log_error("Failed to write display buffer");
                    exit(1);
                }
            }
        }
    }
}

void display_update() {
    // No explicit update needed for SSD1306
}

void display_text(const char *text, int x, int y) {
    while (*text) {
        display_draw_char(x, y, *text++);
        x += FONT_WIDTH;
    }
}

void read_temperature(char *buffer, size_t size) {
    FILE *file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!file) {
        snprintf(buffer, size, "Temp Error");
        return;
    }

    int temp;
    if (fscanf(file, "%d", &temp) != 1) {
        snprintf(buffer, size, "Temp Error");
    } else {
        snprintf(buffer, size, "Temp: %d.%dC", temp / 1000, (temp / 10) % 100);
    }

    fclose(file);
}

void read_cpu_usage(char *buffer, size_t size) {
    FILE *file = fopen("/proc/stat", "r");
    if (!file) {
        snprintf(buffer, size, "CPU Error");
        return;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal;
    if (fscanf(file, "cpu %llu %llu %llu %llu %llu %llu %llu %llu", &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) != 8) {
        snprintf(buffer, size, "CPU Error");
    } else {
        static unsigned long long prev_total = 0, prev_idle = 0;
        unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal;
        unsigned long long idle_time = idle + iowait;
        unsigned long long total_diff = total - prev_total;
        unsigned long long idle_diff = idle_time - prev_idle;
        float usage = 100.0 * (total_diff - idle_diff) / total_diff;

        snprintf(buffer, size, "CPU: %.1f%%", usage);

        prev_total = total;
        prev_idle = idle_time;
    }

    fclose(file);
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

