    if (fscanf(file, "cpu %llu %llu %llu %llu %llu %llu %llu %llu", &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) != 8) {
        snprintf(buffer, size, "CPU Error");
    } else {
        static unsigned long long prev_total = 0, prev_idle = 0;
        unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal;
        unsigned long long idle_time = idle + iowait;
        unsigned long long total_diff = total - prev_total;
        unsigned long long idle_diff = idle_time - prev_idle;
        float usage = 100.0 * (total_diff - idle_diff) / total_diff;

        snprintf(buffer, size, "CPU: %.1f%%", usage);

        prev_total = total;
        prev_idle = idle_time;
    }

    fclose(file);
}

void handle_sigint(int sig) {
    gpioTerminate();
    exit(0);
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}
