            break;
        }

        pulse_count += new_pulse_count;
        total_volume += (pulse_count / (float)PULSES_PER_LITER);
        pulse_count = 0;

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            float flow_rate = (PULSES_PER_LITER * (pulse_count / (current_time - last_log_time))) / 60.0;
            printf("Flow rate: %.2f L/min, Total volume: %.2f L\n", flow_rate, total_volume);
            last_log_time = current_time;
        }

        if (current_time - last_lcd_update_time >= 10) {
            float flow_rate = (PULSES_PER_LITER * (pulse_count / 10.0)) / 60.0;
            update_lcd(gpioInitialise(), fd, flow_rate, total_volume);
            last_lcd_update_time = current_time;
        }

        usleep(100000); // Sleep for 100ms
    }

    i2cClose(fd);
    gpioTerminate();
    return 0;
