#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <pcf8574.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define GPIO_ANEMOMETER 17
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0
#define ADC_STUCK_THRESHOLD 10
#define UPDATE_INTERVAL 500000 // 500 ms in microseconds

static int i2c_handle = -1;
static int spi_handle = -1;
static int pigpio_handle = -1;
static int adc_stuck_count = 0;
static unsigned long last_pulse_count = 0;
static unsigned long pulse_count = 0;

void handle_signal(int sig) {
    if (i2c_handle >= 0) {
        pcf8574Close(i2c_handle);
    }
    if (spi_handle >= 0) {
        gpioClose(spi_handle);
    }
    if (pigpio_handle >= 0) {
        gpioTerminate(pigpio_handle);
    }
    exit(0);
}

void anemometer_callback(int gpio, unsigned level, uint32_t tick) {
    if (level == 1) {
        pulse_count++;
    }
}

int read_adc_value() {
    uint8_t adc_command[3] = {1, 0x00, 0x00};
    uint8_t adc_response[3] = {0};

    if (gpioWrite(spi_handle, adc_command, 3, adc_response, 3) < 0) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = (adc_response[1] & 0x03) << 8 | adc_response[2];
    return adc_value;
}

void update_lcd() {
    char lcd_buffer[16];
    unsigned long elapsed_time = gpioTickDiff(last_pulse_count, gpioTick());
    float wind_speed = (pulse_count * 0.5) / (elapsed_time / 1000000.0);
    int wind_direction = (read_adc_value() * 359) / ADC_MAX_VALUE;

    if (wind_direction == -1) {
        fprintf(stderr, "ADC read error\n");
        return;
    }

    if (wind_direction == ADC_MIN_VALUE || wind_direction == ADC_MAX_VALUE) {
        adc_stuck_count++;
        if (adc_stuck_count > ADC_STUCK_THRESHOLD) {
            fprintf(stderr, "ADC stuck at %d\n", wind_direction);
        }
    } else {
        adc_stuck_count = 0;
    }

    snprintf(lcd_buffer, sizeof(lcd_buffer), "Speed: %.2f m/s", wind_speed);
    pcf8574Write(i2c_handle, 0, lcd_buffer, 16);
    snprintf(lcd_buffer, sizeof(lcd_buffer), "Dir: %d deg", wind_direction);
    pcf8574Write(i2c_handle, 1, lcd_buffer, 16);

    last_pulse_count = gpioTick();
    pulse_count = 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    pigpio_handle = gpioInitialise();
    if (pigpio_handle < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(GPIO_ANEMOMETER, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        handle_signal(0);
    }

    if (gpioSetAlertFuncEx(GPIO_ANEMOMETER, PI_RISING_EDGE, anemometer_callback, 0) < 0) {
        fprintf(stderr, "Failed to set alert function: %s\n", strerror(errno));
        handle_signal(0);
    }

    i2c_handle = pcf8574Open(pigpio_handle, I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C: %s\n", strerror(errno));
        handle_signal(0);
    }

    spi_handle = gpioSPIOpen(pigpio_handle, SPI_BUS, SPI_CHANNEL, SPI_MODE, SPI_SPEED);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        handle_signal(0);
    }

    last_pulse_count = gpioTick();

    while (1) {
        update_lcd();
        gpioDelay(UPDATE_INTERVAL);
    }

    handle_signal(0);
    return 0;
}

