#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <pcf8574.h>

#define GPIO_PIN 17
#define CALIBRATION_FACTOR 7.5
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, 1, 0, 0, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_lcd() {
    if (pcf8574Open(I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    pcf8574Write(0x00); // Turn on display
    pcf8574Write(0x06); // Entry mode set
    pcf8574Write(0x0C); // Display on, cursor off
    pcf8574Write(0x01); // Clear display
    usleep(2000);       // Wait for clear display command to execute

    // Display "Flow Rate:"
    const char *flow_rate_text = "Flow Rate:     ";
    for (int i = 0; i < LCD_WIDTH; i++) {
        pcf8574Write(pcf8574Read() & ~(1 << i) | ((flow_rate_text[i] & 0x01) << i));
    }
}

void display_flow_rate(double flow_rate) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, sizeof(buffer), " %6.2f L/min", flow_rate);

    for (int i = 0; i < LCD_WIDTH; i++) {
        pcf8574Write(pcf8574Read() & ~(1 << i) | ((buffer[i] & 0x01) << i));
    }
}

void cleanup() {
    gpioTerminate();
    pcf8574Close();
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_lcd();

    int pulse_count = 0;
    double flow_rate = 0.0;

    while (keep_running) {
        usleep(1000000); // 1 second interval

        int pulses = gpioGetAlertLevel(GPIO_PIN);
        if (pulses < 0) {
            fprintf(stderr, "Failed to get alert level\n");
            cleanup();
            exit(EXIT_FAILURE);
        }

        pulse_count += pulses;
        flow_rate = (pulse_count / CALIBRATION_FACTOR) * 60.0; // Convert to L/min
        display_flow_rate(flow_rate);

        pulse_count = 0; // Reset pulse count for next interval
    }

    cleanup();
    return 0;
}

