#include <gpiod.h>
#include <string.h>

#define ROWS 8
#define COLUMNS 8
#define SCAN_DELAY 800 // microseconds

// GPIO line numbers for rows and columns
static const int row_pins[ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[COLUMNS] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip;
static struct gpiod_line *row_lines[ROWS];
static struct gpiod_line *col_lines[COLUMNS];

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get line for row %d\n", row_pins[i]);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(row_lines[i], "row", GPIOD_OUT_LOW)) {
