#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define ROW_COUNT 8
#define COL_COUNT 8
#define DELAY_MS 150

static gpiod_chip *chip;
static gpiod_line *row_lines[ROW_COUNT];
static gpiod_line *col_lines[COL_COUNT];
static volatile sig_atomic_t keep_running = 1;

static const int row_pins[ROW_COUNT] = {2, 3, 4, 17, 27, 22, 10, 9};
static const int col_pins[COL_COUNT] = {14, 15, 18, 23, 24, 25, 8, 7};

void cleanup() {
    for (int i = 0; i < ROW_COUNT; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < COL_COUNT; i++) {
        gpiod_line_release(col_lines[i]);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < ROW_COUNT; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i] || gpiod_line_request_output(row_lines[i], "row", 1) < 0) {
            fprintf(stderr, "Failed to request row pin %d\n", row_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < COL_COUNT; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i] || gpiod_line_request_output(col_lines[i], "col", 0) < 0) {
            fprintf(stderr, "Failed to request column pin %d\n", col_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        for (int col = 0; col < COL_COUNT; col++) {
            // Clear the matrix
            for (int i = 0; i < COL_COUNT; i++) {
                gpiod_line_set_value(col_lines[i], 1);
            }
            for (int i = 0; i < ROW_COUNT; i++) {
                gpiod_line_set_value(row_lines[i], 0);
            }

            // Set the current column LOW
            gpiod_line_set_value(col_lines[col], 0);

            // Light up the entire column
            for (int i = 0; i < ROW_COUNT; i++) {
                gpiod_line_set_value(row_lines[i], 1);
            }

            usleep(DELAY_MS * 1000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

