#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define DISTANCE_REGISTER 0x0D
#define SAMPLE_INTERVAL_MS 100

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_i2c() {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    i2c_handle = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pi_i2c_error(i2c_handle));
        return -1;
    }
    return 0;
}

int read_distance(int16_t *distance) {
    uint8_t buffer[2] = {0};
    if (i2c_write_byte_data(i2c_handle, DISTANCE_REGISTER, 0) < 0) {
        fprintf(stderr, "Failed to write register address: %s\n", pi_i2c_error(i2c_handle));
        return -1;
    }
    if (i2c_read(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read distance: %s\n", pi_i2c_error(i2c_handle));
        return -1;
    }
    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

void log_distance(int16_t distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (log_file == NULL) {
        log_file = fopen("depth_log.csv", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
            fprintf(log_file, "Timestamp,Distance\n");
        }
    }

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    if (open_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (log_file == NULL) {
        log_file = fopen("depth_log.csv", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        int16_t distance = -1;
        if (read_distance(&distance) < 0) {
            log_distance(-1);
            if (open_i2c() < 0) {
                break;
            }
        } else {
            log_distance(distance);
        }
        pi_sleep(SAMPLE_INTERVAL_MS);
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
        i2c_handle = -1;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

