#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_LINE 4
#define LED_LINE 17
#define POLL_INTERVAL 100000 // 100 ms in microseconds
#define LED_BLINK_DURATION 100000 // 100 ms in microseconds

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static int last_sensor_state = 1; // Assume HIGH initially

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *event) {
    FILE *log_file = fopen("proximity.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    fprintf(log_file, "%s %s\n", timestamp, event);
    fclose(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            return EXIT_FAILURE;
        }
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_LINE);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(sensor_line, "proximity_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        fprintf(stderr, "Failed to request sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "proximity_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int events = gpiod_line_event_wait(sensor_line, POLL_INTERVAL);
        if (events < 0) {
            fprintf(stderr, "Error waiting for sensor events\n");
            break;
        }

        if (events > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(sensor_line, &event) < 0) {
                fprintf(stderr, "Error reading sensor event\n");
                break;
            }

            int current_state = event.event_value;
            if (last_sensor_state == 1 && current_state == 0) {
                // Falling edge detected
                log_event("Object detected");

                gpiod_line_set_value(led_line, 1);
                usleep(LED_BLINK_DURATION);
                gpiod_line_set_value(led_line, 0);
                usleep(LED_BLINK_DURATION);
            }
            last_sensor_state = current_state;
        }
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

