        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2cWriteReg8(i2c_handle, COMMAND_REG, 0x06) < 0 || // ALS_FORCE
            i2cWriteReg8(i2c_handle, COMMAND_REG, 0x07) < 0) { // PS_FORCE
