        fprintf(log_file, "%s,%u,%u\n", timestamp, ps1_data, als_vis_data);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

