#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TRIGGER_GPIO_CHIP "bcm2835_gpio"
#define ECHO_GPIO_CHIP "bcm2835_gpio"
#define TRIGGER_LINE 17
#define ECHO_LINE 27
#define TRIGGER_PULSE_NS 10000
#define TIMEOUT_NS 30000000
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2
#define WATER_DISTANCE_CM 15
#define POLL_INTERVAL 60

static volatile int keep_running = 1;
static FILE *log_file;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

double measure_distance(struct gpiod_line *trigger_line, struct gpiod_line *echo_line) {
    struct timespec start, end;
    long long pulse_width_ns = 0;
    int ret;

    // Generate 10us trigger pulse
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        log_message("Failed to set trigger line high");
        return -1;
    }
    nanosleep(&((struct timespec){0, TRIGGER_PULSE_NS}), NULL);
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        log_message("Failed to set trigger line low");
        return -1;
    }

    // Wait for echo to go high
    ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, TIMEOUT_NS);
    if (ret < 0) {
        log_message("Echo line did not go high (sensor absent or timeout)");
        return -1;
    }

    // Get start time
    if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
        log_message("Failed to get start time");
        return -1;
    }

    // Wait for echo to go low
    ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, TIMEOUT_NS);
    if (ret < 0) {
        log_message("Echo line did not go low (timeout)");
        return -1;
    }

    // Get end time
    if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
        log_message("Failed to get end time");
        return -1;
    }

    // Calculate pulse width
    pulse_width_ns = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

    // Calculate distance in cm
    double distance_cm = (pulse_width_ns * 34300.0) / 2000000000.0;
    return distance_cm;
}

int main() {
    struct gpiod_chip *trigger_chip, *echo_chip;
    struct gpiod_line *trigger_line, *echo_line;
    double distance_cm;
    char log_entry[100];

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chips
    trigger_chip = gpiod_chip_open_by_name(TRIGGER_GPIO_CHIP);
    if (!trigger_chip) {
        perror("Failed to open trigger GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    echo_chip = gpiod_chip_open_by_name(ECHO_GPIO_CHIP);
    if (!echo_chip) {
