    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chips
    trigger_chip = gpiod_chip_open_by_name(TRIGGER_GPIO_CHIP);
    if (!trigger_chip) {
        perror("Failed to open trigger GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    echo_chip = gpiod_chip_open_by_name(ECHO_GPIO_CHIP);
    if (!echo_chip) {
        perror("Failed to open echo GPIO chip");
        gpiod_chip_close(trigger_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Get lines
    trigger_line = gpiod_chip_get_line(trigger_chip, TRIGGER_LINE);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(echo_chip, ECHO_LINE);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Configure lines
    if (gpiod_line_request(trigger_line, "trigger", GPIOD_LINE_REQUEST_DIRECTIONS_OUT) < 0) {
        perror("Failed to request trigger line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(echo_line, "echo", GPIOD_LINE_REQUEST_DIRECTIONS_IN) < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(trigger_chip);
        gpiod_chip_close(echo_chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        distance_cm = measure_distance(trigger_line, echo_line);

        if (distance_cm < 0) {
