#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define SENSOR_ID_REG 0x92
#define SENSOR_ID_EXPECTED 0xAB
#define ENABLE_REG 0x80
#define ATIME_REG 0x81
#define WTIME_REG 0x83
#define PPULSE_REG 0x8E
#define CONTROL_REG 0xF1
#define CONFIG2_REG 0x90
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void initialize_sensor() {
    if (i2c_write_byte_data(I2C_BUS, I2C_ADDR, ENABLE_REG, 0x03) != 0) {
        log_error("Failed to write ENABLE register");
        exit(EXIT_FAILURE);
    }
    if (i2c_write_byte_data(I2C_BUS, I2C_ADDR, ATIME_REG, 0xDB) != 0) {
        log_error("Failed to write ATIME register");
        exit(EXIT_FAILURE);
    }
    if (i2c_write_byte_data(I2C_BUS, I2C_ADDR, WTIME_REG, 0xF6) != 0) {
        log_error("Failed to write WTIME register");
        exit(EXIT_FAILURE);
    }
    if (i2c_write_byte_data(I2C_BUS, I2C_ADDR, PPULSE_REG, 0x87) != 0) {
        log_error("Failed to write PPULSE register");
        exit(EXIT_FAILURE);
    }
    if (i2c_write_byte_data(I2C_BUS, I2C_ADDR, CONTROL_REG, 0x03) != 0) {
        log_error("Failed to write CONTROL register");
        exit(EXIT_FAILURE);
    }
    if (i2c_write_byte_data(I2C_BUS, I2C_ADDR, CONFIG2_REG, 0x01) != 0) {
        log_error("Failed to write CONFIG2 register");
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data(FILE *log_file) {
    uint8_t data[3];
    uint16_t red, green, blue;
    uint8_t proximity;

    if (i2c_read_i2c_block_data(I2C_BUS, I2C_ADDR, 0x94, data, 3) != 3) {
        log_error("Failed to read RGB data");
        return;
    }
    red = (data[0] << 8) | data[1];
    green = (data[2] << 8) | data[3];
    blue = (data[4] << 8) | data[5];

    if (i2c_read_byte_data(I2C_BUS, I2C_ADDR, 0x9C) != 0xFF) {
        proximity = i2c_read_byte_data(I2C_BUS, I2C_ADDR, 0x9C);
        if (proximity > PROXIMITY_THRESHOLD) {
            time_t now = time(NULL);
            fprintf(log_file, "%ld,%u,%u,%u,%u\n", now, red, green, blue, proximity);
            fflush(log_file);
        }
    }
}

void reinitialize_sensor() {
    if (i2c_close(I2C_BUS) != 0) {
        log_error("Failed to close I2C bus");
        exit(EXIT_FAILURE);
    }
    if (i2c_open(I2C_BUS, I2C_ADDR) != 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    initialize_sensor();
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (i2c_open(I2C_BUS, I2C_ADDR) != 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t sensor_id;
    if (i2c_read_byte_data(I2C_BUS, I2C_ADDR, SENSOR_ID_REG) != 0xFF) {
        sensor_id = i2c_read_byte_data(I2C_BUS, I2C_ADDR, SENSOR_ID_REG);
        if (sensor_id != SENSOR_ID_EXPECTED) {
            log_error("Sensor ID mismatch");
            gpioTerminate();
            return EXIT_FAILURE;
        }
    } else {
        log_error("Failed to read sensor ID");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    initialize_sensor();

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "timestamp,red,green,blue,proximity\n");

    while (keep_running) {
        read_sensor_data(log_file);
        usleep(100000); // 100 ms
    }

    fclose(log_file);
    i2c_close(I2C_BUS);
    gpioTerminate();
    return EXIT_SUCCESS;
}

