#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SLAVE_ADDRESS 0x5A
#define PART_ID_REG 0x00
#define MEAS_RATE0_REG 0x08
#define COMMAND_REG 0x47
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25
#define SI1182_PART_ID 0x12 // Example part ID, replace with actual

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    FILE *csv_file;
    struct timespec ts;
    char timestamp[30];

    // Install signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SLAVE_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read PART_ID register
    uint8_t part_id;
    if (ioctl(i2c_fd, I2C_SLAVE, SLAVE_ADDRESS) < 0 || i2c_smbus_read_byte_data(i2c_fd, PART_ID_REG) != I2C_SMBUS_OK) {
        perror("Failed to read PART_ID register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    part_id = i2c_smbus_data;

    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X\n", part_id);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure continuous proximity measurement
    if (i2c_smbus_write_byte_data(i2c_fd, MEAS_RATE0_REG, 0x01) != I2C_SMBUS_OK) { // Example rate value
        perror("Failed to write MEAS_RATE0 register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Issue reset/start command
    if (i2c_smbus_write_byte_data(i2c_fd, COMMAND_REG, 0x01) != I2C_SMBUS_OK) { // Example command value
        perror("Failed to write COMMAND register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen("heartrate.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write CSV header
    fprintf(csv_file, "timestamp,bpm\n");
    fflush(csv_file);

    while (running) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        // Read proximity data
        uint16_t ps_data0, ps_data1;
        if (i2c_smbus_read_word_data(i2c_fd, PS_DATA0_REG) != I2C_SMBUS_OK) {
            fprintf(stderr, "Warning: Failed to read PS_DATA0 register\n");
            continue;
        }
        ps_data0 = i2c_smbus_data;

        if (i2c_smbus_read_word_data(i2c_fd, PS_DATA1_REG) != I2C_SMBUS_OK) {
            fprintf(stderr, "Warning: Failed to read PS_DATA1 register\n");
            continue;
        }
        ps_data1 = i2c_smbus_data;

        // Combine little-endian data
        uint32_t proximity_data = ps_data1 | (ps_data0 << 16);

        // Placeholder BPM calculation
        int bpm = (proximity_data % 100) + 60; // Example calculation

        // Log to CSV
        fprintf(csv_file, "%s,%d\n", timestamp, bpm);
        fflush(csv_file);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Cleanup
    fclose(csv_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

