#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define GPIO_PIN 17
#define TIMEOUT_MS 100

static int i2c_handle;
static int log_file;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int check_sensor_presence() {
    unsigned char data[1] = {0x00};
    if (i2c_write_i2c_block_data(i2c_handle, I2C_ADDR, data, 1) < 0) {
        fprintf(stderr, "Error: Sensor not present at address 0x%02X\n", I2C_ADDR);
        return -1;
    }
    return 0;
}

int trigger_measurement() {
    if (i2c_write_byte_data(i2c_handle, I2C_ADDR, SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start measurement\n");
        return -1;
    }
    return 0;
}

int wait_for_measurement() {
    unsigned char data[1];
    int start_time = millis();
    while (millis() - start_time < TIMEOUT_MS) {
        if (i2c_read_byte_data(i2c_handle, I2C_ADDR, RESULT_INTERRUPT_STATUS, data) < 0) {
            fprintf(stderr, "Error: Failed to read interrupt status\n");
            return -1;
        }
        if (data[0] & 0x01) {
            return 0;
        }
        usleep(1000); // Sleep for 1 ms
    }
    fprintf(stderr, "Error: Measurement timeout\n");
    return -1;
}

int read_distance(int *distance) {
    unsigned char data[14];
    if (i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, RESULT_RANGE_STATUS, data, 14) < 0) {
        fprintf(stderr, "Error: Failed to read distance data\n");
        return -1;
    }
    *distance = (data[10] << 8) | data[11];
    return 0;
}

void clear_interrupt() {
    if (i2c_write_byte_data(i2c_handle, I2C_ADDR, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to clear interrupt\n");
    }
}

void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistor\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetAlertFuncEx(GPIO_PIN, 0, 1, 0, 0, 0) < 0) {
        fprintf(stderr, "Error: Failed to set alert function\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    if (log_file >= 0) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    signal(SIGINT, handle_sigint);

    setup_gpio();

    i2c_handle = i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (check_sensor_presence() < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file < 0) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        if (gpioWait(1 << GPIO_PIN, 0) < 0) {
            fprintf(stderr, "Error: Failed to wait for GPIO event\n");
            continue;
        }

        if (trigger_measurement() < 0 || wait_for_measurement() < 0) {
            continue;
        }

        int distance;
        if (read_distance(&distance) < 0) {
            continue;
        }

        log_distance(distance);
        clear_interrupt();
    }

    cleanup();
    return 0;
}

