#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define TRIGGER_REGISTER 0x00
#define RESULT_REGISTER 0x02
#define SAMPLE_INTERVAL 200 // milliseconds
#define MEASURE_DELAY 50    // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    char timestamp_buffer[20];
    while (keep_running) {
        // Trigger measurement
        if (i2cWriteByteData(i2c_handle, TRIGGER_REGISTER, 0x01) < 0) {
            fprintf(stderr, "Failed to write trigger register\n");
        }

        // Wait for measurement to complete
        usleep(MEASURE_DELAY * 1000);

        // Read distance result
        uint8_t result_bytes[2] = {0};
        if (i2cRead(i2c_handle, RESULT_REGISTER, result_bytes, 2) < 0) {
            fprintf(stderr, "Failed to read distance result\n");
        } else {
            uint16_t distance_mm = (result_bytes[0] << 8) | result_bytes[1];

            // Get current timestamp
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            strftime(timestamp_buffer, sizeof(timestamp_buffer), "%Y-%m-%d %H:%M:%S", tm_info);

            // Log and print the distance
            fprintf(log_file, "%s, %u\n", timestamp_buffer, distance_mm);
            printf("%s, %u\n", timestamp_buffer, distance_mm);
            fflush(log_file);
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

