        log_error("Failed to set GPIO mode.");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int value1 = gpioRead(SENSOR_1);
        int value2 = gpioRead(SENSOR_2);

        if (value1 < 0) {
            log_error("Failed to read from sensor 1.");
        } else {
            time_t timestamp = time(NULL);
            log_reading(SENSOR_1, value1, timestamp);
        }

        if (value2 < 0) {
            log_error("Failed to read from sensor 2.");
        } else {
            time_t timestamp = time(NULL);
            log_reading(SENSOR_2, value2, timestamp);
        }

        usleep(POLL_INTERVAL * 1000);
