#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x6A
#define LED_GPIO 17
#define MEASUREMENT_INTERVAL 100 // milliseconds
#define DISTANCE_THRESHOLD 20 // cm

static int i2c_handle = -1;
static int led_gpio = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_distance(int i2c_handle) {
    unsigned char tx_buffer[2] = {0x00, 0x00};
    unsigned char rx_buffer[2] = {0x00, 0x00};

    if (i2c_write(i2c_handle, I2C_ADDRESS, tx_buffer, 2) < 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }

    if (i2c_read(i2c_handle, I2C_ADDRESS, rx_buffer, 2) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }

    int distance = (rx_buffer[0] << 8) | rx_buffer[1];
    return distance;
}

void log_distance(int distance) {
    FILE *file = fopen("distance_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(file, "%s: %d cm\n", timestamp, distance);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    led_gpio = gpioInitialise();
    if (led_gpio < 0) {
        fprintf(stderr, "Failed to initialize LED GPIO\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(led_gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int distance = read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
