#define AMBIENT_LIGHT_REG 0x16
#define RETRY_LIMIT 3
#define LOG_FILE "biometric_log.txt"

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_read_retry(int handle, unsigned char reg, unsigned short *data, int retries) {
    int result;
    for (int attempt = 0; attempt < retries; ++attempt) {
        result = i2c_read_reg16(handle, reg, data);
        if (result == 0) {
            return 0; // Success
        }
        usleep(100000); // Wait 100 ms before retrying
    }
    return result; // Return the last error code
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        unsigned short proximity_data, ambient_light_data;
        int result;

        result = i2c_read_retry(i2c_handle, PROXIMITY_REG, &proximity_data, RETRY_LIMIT);
        if (result != 0) {
            fprintf(stderr, "Failed to read proximity data: %d\n", result);
            continue;
        }

        result = i2c_read_retry(i2c_handle, AMBIENT_LIGHT_REG, &ambient_light_data, RETRY_LIMIT);
        if (result != 0) {
            fprintf(stderr, "Failed to read ambient light data: %d\n", result);
            continue;
        }

        time_t now = time(NULL);
        fprintf(log_file, "%s - Proximity: %u, Ambient Light: %u\n", ctime(&now), proximity_data, ambient_light_data);
        fflush(log_file);

        usleep(500000); // Sleep for 500 ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

