#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x6A
#define WHO_AM_I_REG 0x00
#define WHO_AM_I_VALUE 0x20
#define DISTANCE_REG 0x04
#define LED_PIN 17
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"
#define READ_INTERVAL 50

static int threshold = DEFAULT_THRESHOLD;
static int pi = -1;
static int i2c_handle = -1;
static int led_pin = -1;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    if (led_pin >= 0) {
        gpioWrite(led_pin, 0);
        gpioTerminate();
    }
    if (pi >= 0) {
        pigpio_stop(pi);
    }
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    signal(SIGINT, cleanup);

    pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio daemon\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup(0);
        return 1;
    }

    led_pin = gpioOpen(LED_PIN, O_RDWR);
    if (led_pin < 0) {
        fprintf(stderr, "Failed to open GPIO pin %d\n", LED_PIN);
        cleanup(0);
        return 1;
    }
    gpioSetMode(led_pin, PI_OUTPUT);

    i2c_handle = i2cOpen(pi, I2C_BUS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        cleanup(0);
        return 1;
    }

    int who_am_i = i2cReadReg8(i2c_handle, I2C_ADDRESS, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        cleanup(0);
        return 1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Sensor not detected or incorrect device\n");
        cleanup(0);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
        return 1;
    }

    while (1) {
        int distance = i2cReadReg8(i2c_handle, I2C_ADDRESS, DISTANCE_REG);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            break;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s: Distance = %d mm\n", time_str, distance);
        fflush(log_file);

        if (distance < threshold) {
            gpioWrite(led_pin, 1);
        } else {
            gpioWrite(led_pin, 0);
        }

        usleep(READ_INTERVAL * 1000);
    }

    fclose(log_file);
    cleanup(0);
    return 0;
}

