#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x50
#define COMMAND_FRAME_SIZE 4
#define RESPONSE_FRAME_SIZE 15
#define SAMPLE_COUNT 10
#define MIN_DISTANCE_MM 1000
#define DELAY_MS 100

int i2c_fd = -1;
FILE *log_file = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void log_intrusion(double average_distance) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "Intrusion detected at %s: Average distance = %.2f mm\n", timestamp, average_distance);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int total_distance = 0;
        int valid_samples = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            uint8_t command_frame[COMMAND_FRAME_SIZE] = {0x50, 0x0A, 0x00, 0x01};
            uint8_t response_frame[RESPONSE_FRAME_SIZE];

            if (write(i2c_fd, command_frame, COMMAND_FRAME_SIZE) != COMMAND_FRAME_SIZE) {
                perror("Failed to write to I2C device");
                continue;
            }

            usleep(10000); // Wait 10 ms

            if (read(i2c_fd, response_frame, RESPONSE_FRAME_SIZE) != RESPONSE_FRAME_SIZE) {
                perror("Failed to read from I2C device");
                continue;
            }

            if (response_frame[0] != 0x50) {
                fprintf(stderr, "Invalid response header\n");
                continue;
            }

            int distance = (response_frame[11] << 8) | response_frame[12];
            total_distance += distance;
            valid_samples++;
        }

        if (valid_samples > 0) {
            double average_distance = (double)total_distance / valid_samples;
            if (average_distance < MIN_DISTANCE_MM) {
                log_intrusion(average_distance);
            }
        }

        usleep(DELAY_MS * 1000); // Wait 100 ms
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

