#define MODEL_ID_REG 0xC0
#define MODEL_ID_EXPECTED 0xEE
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define TIMEOUT_MS 100
#define SLEEP_MS 500

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t model_id;
    if (i2cReadReg8(i2c_handle, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (model_id != MODEL_ID_EXPECTED) {
        fprintf(stderr, "Model ID mismatch: expected 0x%02X, got 0x%02X\n", MODEL_ID_EXPECTED, model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

