            int16_t proximity_value = (msb << 8) | lsb;
            printf("Proximity value: %d\n", proximity_value);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
