#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x4C
#define DISTANCE_REGISTER 0x00
#define READ_INTERVAL 500000000 // 500 ms in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    uint8_t buffer[2];
    uint16_t distance_raw;
    double distance_mm;
    struct timespec ts;

    // Set up signal handler for clean exit
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device presence by reading a known register
    buffer[0] = DISTANCE_REGISTER;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }

    if (read(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "I2C device not responding, exiting\n");
        close(i2c_fd);
        return 1;
    }

    while (keep_running) {
        // Read distance register
        buffer[0] = DISTANCE_REGISTER;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            continue;
        }

        // Convert raw value to distance in millimeters
        distance_raw = buffer[0] | (buffer[1] << 8);
        distance_mm = distance_raw * 0.125;

        // Print distance
        printf("Distance: %.2f mm\n", distance_mm);

        // Sleep for 500 ms
        ts.tv_sec = 0;
        ts.tv_nsec = READ_INTERVAL;
        nanosleep(&ts, NULL);
    }

    // Clean up
    close(i2c_fd);
    return 0;
}

