#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE_US 38000 // 38 ms in microseconds
#define TIMEOUT_US 200000 // 200 ms in microseconds
#define PULSE_WIDTH_US 10 // 10 microseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double calculate_distance(unsigned long pulse_width_us) {
    return (pulse_width_us * 0.0343) / 2.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned long start_tick, end_tick, pulse_width_us;
    unsigned long last_trigger_tick = 0;

    while (keep_running) {
        // Send 10 microsecond trigger pulse
        gpioWrite(TRIGGER_PIN, 1);
        gpioTick(start_tick);
        gpioTickDelay(PULSE_WIDTH_US);
        gpioWrite(TRIGGER_PIN, 0);

        // Wait for echo rising edge
        if (gpioWaitForEdge(ECHO_PIN, PI_RISING, TIMEOUT_US) < 0) {
            fprintf(stderr, "Echo rising edge timeout\n");
            continue;
        }

        // Measure time of rising edge
        gpioTick(start_tick);

        // Wait for echo falling edge
        if (gpioWaitForEdge(ECHO_PIN, PI_FALLING, TIMEOUT_US) < 0) {
            fprintf(stderr, "Echo falling edge timeout\n");
            continue;
        }

        // Measure time of falling edge
        gpioTick(end_tick);

        // Calculate pulse width
        pulse_width_us = gpioTickDiff(start_tick, end_tick);

        // Validate pulse width
        if (pulse_width_us <= 0 || pulse_width_us > MAX_DISTANCE_US) {
            fprintf(stderr, "Invalid pulse width: %lu us\n", pulse_width_us);
            continue;
        }

        // Calculate distance
        double distance_cm = calculate_distance(pulse_width_us);

        // Log the reading with a timestamp
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Distance: %.2f cm\n", time_str, distance_cm);

        // Ensure the loop runs once per second
        unsigned long current_tick = gpioTick();
        unsigned long elapsed_us = gpioTickDiff(last_trigger_tick, current_tick);
        if (elapsed_us < 1000000) {
            usleep(1000000 - elapsed_us);
        }
        last_trigger_tick = gpioTick();
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

/*
 * Note: The HC-SR04 operates at 5V while the Pi GPIO is only 3.3V tolerant.
 * A 1 kOhm resistor is used in series on the echo line for protection.
 * gpioTick() returns a monotonically increasing microsecond counter.
 */

