#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define MAGIC_WORD_SIZE 8
#define DATA_FRAME_SIZE 128
#define RANGE_BINS 64
#define RANGE_RESOLUTION 0.0486
#define DISTANCE_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int initialize_uart(int *uart_fd) {
    struct termios options;
    *uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (*uart_fd < 0) {
        perror("Error opening UART device");
        return -1;
    }

    if (tcgetattr(*uart_fd, &options) != 0) {
        perror("Error getting UART attributes");
        close(*uart_fd);
        return -1;
    }

    cfsetospeed(&options, B115200);
    cfsetispeed(&options, B115200);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CRTSCTS;

    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    if (tcsetattr(*uart_fd, TCSANOW, &options) != 0) {
        perror("Error setting UART attributes");
        close(*uart_fd);
        return -1;
    }

    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    return 0;
}

void log_intrusion(double distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.3f\n", timestamp, distance);
    fclose(log_file);
}

int read_data_frame(int uart_fd, uint8_t *buffer) {
    ssize_t bytes_read = read(uart_fd, buffer, MAGIC_WORD_SIZE + DATA_FRAME_SIZE);
    if (bytes_read < 0) {
        perror("Error reading from UART");
        return -1;
    }
    if (bytes_read != MAGIC_WORD_SIZE + DATA_FRAME_SIZE) {
        fprintf(stderr, "Incomplete data frame received\n");
        return -1;
    }

    // Validate magic word
    uint8_t expected_magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    for (int i = 0; i < MAGIC_WORD_SIZE; i++) {
        if (buffer[i] != expected_magic_word[i]) {
            fprintf(stderr, "Invalid magic word\n");
            return -1;
        }
    }

    return 0;
}

void process_data_frame(uint8_t *data) {
    uint16_t range_bins[RANGE_BINS];
    for (int i = 0; i < RANGE_BINS; i++) {
        range_bins[i] = (data[MAGIC_WORD_SIZE + 2 * i] | (data[MAGIC_WORD_SIZE + 2 * i + 1] << 8));
    }

    for (int i = 0; i < RANGE_BINS; i++) {
        double distance = i * RANGE_RESOLUTION;
        if (distance <= DISTANCE_THRESHOLD && range_bins[i] > 0) {
            log_intrusion(distance);
            gpioWrite(GPIO_LED, 1);
            sleep(2);
            gpioWrite(GPIO_LED, 0);
            break;
        }
    }
}

int main() {
    int uart_fd;
    if (initialize_uart(&uart_fd) != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint8_t buffer[MAGIC_WORD_SIZE + DATA_FRAME_SIZE];

    while (keep_running) {
        if (read_data_frame(uart_fd, buffer) == 0) {
            process_data_frame(buffer);
        }
    }

    gpioTerminate();
    close(uart_fd);
    return EXIT_SUCCESS;
}

