#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define POLL_INTERVAL_MS 100

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *buzzer_line;
static int last_sensor_state = -1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_state_transition(int new_state) {
    FILE *log_file = fopen("obstacle_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s - Obstacle detected: %s\n", timestamp, new_state ? "Yes" : "No");
    fclose(log_file);
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        perror("Failed to request sensor line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void process_sensor_data() {
    int sensor_value;
    if (gpiod_line_get_value(sensor_line, &sensor_value) < 0) {
        perror("Failed to read sensor value");
        return;
    }

    int obstacle_detected = !sensor_value; // Active-low
    if (obstacle_detected != last_sensor_state) {
        last_sensor_state = obstacle_detected;
        log_state_transition(obstacle_detected);

        if (gpiod_line_set_value(buzzer_line, obstacle_detected) < 0) {
            perror("Failed to set buzzer value");
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (keep_running) {
        process_sensor_data();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio();
    return 0;
}

