#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define HIGH_BYTE_REG 0x31
#define LOW_BYTE_REG 0x32
#define ALERT_PIN 17
#define SAMPLE_INTERVAL_MS 100
#define MIN_DISTANCE_CM 10.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_distance(int i2c_handle) {
    unsigned char high_byte, low_byte;
    int result = i2c_read_byte_data(i2c_handle, HIGH_BYTE_REG, &high_byte);
    if (result < 0) {
        fprintf(stderr, "Error reading high byte: %s\n", pi_error_string(result));
        return -1;
    }

    result = i2c_read_byte_data(i2c_handle, LOW_BYTE_REG, &low_byte);
    if (result < 0) {
        fprintf(stderr, "Error reading low byte: %s\n", pi_error_string(result));
        return -1;
    }

    int distance = (high_byte << 8) | low_byte;
    return distance;
}

void log_distance(FILE *log_file, int distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s: %d\n", timestamp, distance);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pi_error_string(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        i2cClose(i2c_handle);
