#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define LED_PIN 18
#define SDA_PIN 2
#define SCL_PIN 3
#define SAMPLE_INTERVAL 100 // milliseconds
#define MAX_RETRIES 3
#define RETRY_DELAY 10 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int i2c_read_retry(int handle, unsigned char reg, unsigned char *data, int length) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_read_i2c_block_data(handle, reg, length, data);
        if (result >= 0) {
            return result;
        }
        retries++;
        usleep(RETRY_DELAY * 1000);
    }
    return -1;
}

int i2c_write_retry(int handle, unsigned char reg, unsigned char *data, int length) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_write_i2c_block_data(handle, reg, length, data);
        if (result >= 0) {
            return result;
        }
        retries++;
        usleep(RETRY_DELAY * 1000);
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char cmd[2] = {0x00, 0x01}; // Start measurement command
    if (i2c_write_retry(i2c_handle, 0x00, cmd, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C\n");
        gpioSetMode(LED_PIN, PI_INPUT); // Reset LED pin
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char data[2];
    unsigned int distance;
    int led_state = 0;
    unsigned long last_blink_time = 0;
    unsigned long last_sample_time = 0;

    while (keep_running) {
        unsigned long current_time = millis();
        if (current_time - last_sample_time >= SAMPLE_INTERVAL) {
            last_sample_time = current_time;

            if (i2c_read_retry(i2c_handle, 0x02, data, 2) < 0) {
                fprintf(stderr, "Failed to read from I2C\n");
                continue;
            }

            distance = (data[0] << 8) | data[1];
            printf("%lu ms: Distance = %u mm\n", current_time, distance);

            float frequency = 1.0;
            if (distance >= 50 && distance <= 500) {
                frequency = 10.0 - (9.0 * (distance - 50) / 450.0);
            }

            unsigned long blink_period = 1000000 / (frequency * 2); // microseconds per half-cycle
            if (current_time - last_blink_time >= blink_period) {
                last_blink_time = current_time;
                led_state = !led_state;
                gpioWrite(LED_PIN, led_state);
            }
        }

        usleep(1000); // Sleep for 1 ms to prevent busy-waiting
    }

    gpioSetMode(LED_PIN, PI_INPUT); // Reset LED pin
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

