        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state_1 = -1, last_state_2 = -1;
    int debounce_counter_1 = 0, debounce_counter_2 = 0;

    while (keep_running) {
        int state_1 = gpioRead(SENSOR_1_PIN);
        int state_2 = gpioRead(SENSOR_2_PIN);

        if (state_1 != last_state_1) {
            debounce_counter_1++;
            if (debounce_counter_1 >= DEBOUNCE_INTERVAL / POLL_INTERVAL) {
                if (state_1 == 0) {
                    log_event("1", "DETECTED");
                } else {
                    log_event("1", "CLEARED");
                }
                last_state_1 = state_1;
                debounce_counter_1 = 0;
            }
        } else {
            debounce_counter_1 = 0;
        }

        if (state_2 != last_state_2) {
            debounce_counter_2++;
            if (debounce_counter_2 >= DEBOUNCE_INTERVAL / POLL_INTERVAL) {
                if (state_2 == 0) {
                    log_event("2", "DETECTED");
