                }
                last_state_2 = state_2;
                debounce_counter_2 = 0;
            }
        } else {
            debounce_counter_2 = 0;
        }

        usleep(POLL_INTERVAL * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

