#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50
#define SLEEP_MS 500

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("distance_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    fprintf(log_file, "timestamp,distance_mm\n");

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (keep_running) {
        if (write(i2c_fd, &MEAS_TRIGGER, 1) != 1) {
            fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
            continue;
        }

        uint8_t status;
        struct timespec start, now;
        clock_gettime(CLOCK_MONOTONIC, &start);

        do {
            if (read(i2c_fd, &status, 1) != 1) {
                fprintf(stderr, "Failed to read status: %s\n", strerror(errno));
                break;
            }

            clock_gettime(CLOCK_MONOTONIC, &now);
            long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000 + (now.tv_nsec - start.tv_nsec) / 1000000;
            if (elapsed_ms > TIMEOUT_MS) {
                fprintf(stderr, "Measurement timeout\n");
                break;
            }
        } while ((status & 0x01) == 0);

        if ((status & 0x01) == 0) {
            continue;
        }

        uint16_t distance;
        if (i2c_read_register(i2c_fd, DIST_HIGH, &distance) == 0) {
            distance |= (uint16_t)i2c_read_register(i2c_fd, DIST_LOW, &distance) << 8;

            time_t now_time = time(NULL);
            struct tm *now_tm = localtime(&now_time);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", now_tm);

            fprintf(log_file, "%s,%u\n", timestamp, distance);
            fflush(log_file);
        }

        usleep(SLEEP_MS * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

