#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define MLX75030_REG_DISTANCE 0x00
#define MLX75030_REG_STATUS 0x01
#define MLX75030_STATUS_BUSY 0x01
#define MLX75030_STATUS_ERROR 0x02
#define RETRY_LIMIT 3
#define RETRY_DELAY_MS 10

static int i2c_handle = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_read_retry(int handle, unsigned char reg, unsigned char *data, int len) {
    int retries = 0;
    int result;

    while (retries < RETRY_LIMIT) {
        result = i2c_read_i2c_block_data(handle, reg, len, data);
        if (result >= 0) {
            return result;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char status;
    unsigned short distance;
    unsigned long timestamp;

    while (keep_running) {
        if (i2c_read_retry(i2c_handle, MLX75030_REG_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Failed to read status register\n");
            break;
        }

        if (status & MLX75030_STATUS_BUSY) {
            usleep(1000); // Wait for sensor to be ready
            continue;
        }

        if (status & MLX75030_STATUS_ERROR) {
            fprintf(stderr, "Sensor error detected\n");
            break;
        }

        if (i2c_read_retry(i2c_handle, MLX75030_REG_DISTANCE, (unsigned char *)&distance, 2) < 0) {
            fprintf(stderr, "Failed to read distance register\n");
            break;
        }

        timestamp = gpioTickCounter();
        printf("Timestamp: %lu ms, Distance: %u mm\n", timestamp, distance);

        usleep(100000); // Sleep for 100 ms
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

