#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SOFT_RESET_REG 0x7FFF
#define START_RANGING_REG 0x0009
#define INTERRUPT_STATUS_REG 0x0046
#define DISTANCE_HIGH_REG 0x0096
#define DISTANCE_LOW_REG 0x0097

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg8(i2c_handle, SOFT_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write soft reset\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    usleep(10000); // Wait 10 ms

    if (i2cWriteReg8(i2c_handle, START_RANGING_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        int interrupt_status = i2cReadReg8(i2c_handle, INTERRUPT_STATUS_REG);
        if (interrupt_status < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            continue;
        }

        if (interrupt_status & 0x01) {
            uint8_t high_byte, low_byte;
            if (i2cReadReg8(i2c_handle, DISTANCE_HIGH_REG, &high_byte) < 0 ||
                i2cReadReg8(i2c_handle, DISTANCE_LOW_REG, &low_byte) < 0) {
                fprintf(stderr, "Failed to read distance\n");
                continue;
            }

            uint16_t distance = (high_byte << 8) | low_byte;
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

            printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d.%06ld, Distance: %u mm\n",
                   ts.tv_sec / 86400 + 1970, (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60,
                   ts.tv_sec % 60, ts.tv_nsec / 1000000, ts.tv_nsec % 1000000, distance);
        }

        usleep(500000); // Wait 500 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

