#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_BUZZER 22
#define MEASURE_INTERVAL_MS 500
#define DISTANCE_THRESHOLD_MM 100

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int configure_sensor() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library");
        return -1;
    }

    if (gpioI2CSetup(I2C_BUS, I2C_ADDRESS) < 0) {
        log_error("Failed to setup I2C");
        return -1;
    }

    // Soft reset
    if (gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x0001, 0x00) < 0) {
        log_error("Failed to write SOFT_RESET");
        return -1;
    }

    // Set I2C slave device address
    if (gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x0001, I2C_ADDRESS) < 0) {
        log_error("Failed to write I2C_SLAVE__DEVICE_ADDRESS");
        return -1;
    }

    // Start system in continuous ranging mode
    if (gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x0007, 0x00) < 0) {
        log_error("Failed to write SYSTEM__MODE_START");
        return -1;
    }

    return 0;
}

int read_distance(int *distance) {
    int result = gpioI2CReadReg8(I2C_BUS, I2C_ADDRESS, 0x0096);
    if (result < 0) {
        log_error("Failed to read RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM");
        return -1;
    }

    *distance = result;
    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    if (configure_sensor() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_BUZZER, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode for buzzer");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int distance = 0;
    int buzzer_state = 0;

    while (keep_running) {
        if (read_distance(&distance) < 0) {
            if (configure_sensor() < 0) {
                continue; // Skip iteration if reconfiguration fails
            }
            continue; // Skip iteration on read error
        }

        if (distance < DISTANCE_THRESHOLD_MM && !buzzer_state) {
            gpioWrite(GPIO_BUZZER, 1);
            buzzer_state = 1;
        } else if (distance >= DISTANCE_THRESHOLD_MM && buzzer_state) {
            gpioWrite(GPIO_BUZZER, 0);
            buzzer_state = 0;
        }

        usleep(MEASURE_INTERVAL_MS * 1000);
    }

    gpioWrite(GPIO_BUZZER, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

