#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_MS 50
#define LOG_INTERVAL_MS 200

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double measure_distance() {
    if (gpioTrigger(TRIGGER_PIN, 10) < 0) {
        fprintf(stderr, "Failed to trigger\n");
        return -1.0;
    }

    struct timespec start, end;
    if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
        perror("clock_gettime");
        return -1.0;
    }

    while (gpioRead(ECHO_PIN) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            return -1.0;
        }
        if ((end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
            fprintf(stderr, "Echo timeout\n");
            return -1.0;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpioRead(ECHO_PIN) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            perror("clock_gettime");
            return -1.0;
        }
        if ((end.tv_sec - start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
            fprintf(stderr, "Echo timeout\n");
            return -1.0;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    double elapsed_ms = (end.tv_sec - start.tv_sec) * 1000.0 + (end.tv_nsec - start.tv_nsec) / 1000000.0;
    double distance = elapsed_ms * SPEED_OF_SOUND / 20000.0;

    return distance;
}

int map_distance_to_angle(double distance) {
    if (distance < 2.0) return -90;
    if (distance > 400.0) return 90;
    return (int)((distance - 2.0) * 180.0 / 398.0) - 90;
}

void log_distance(double distance) {
    FILE *log_file = fopen("sensor_data.log", "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s: Distance = %.2f cm\n", timestamp, distance);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
