#define VL53L1X_MODEL_ID_REG 0x010F
#define VL53L1X_MODEL_ID 0xEA
#define VL53L1X_SOFT_RESET_REG 0x0000
#define VL53L1X_START_RANGING_REG 0x0080
#define VL53L1X_DATA_READY_REG 0x0089
#define VL53L1X_DISTANCE_HIGH_REG 0x0096
#define VL53L1X_DISTANCE_LOW_REG 0x0097
#define VL53L1X_TIMING_BUDGET_REG 0x0106
#define VL53L1X_TIMING_BUDGET 50
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define MQ_NAME "/vl53l1x_distance"
#define MQ_MAX_MSGS 10
#define MQ_MAX_MSG_SIZE 128

static int i2c_handle;
static mqd_t mq_handle;
static volatile sig_atomic_t keep_running = 1;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    if (mq_handle >= 0) {
        mq_close(mq_handle);
    }
    gpioTerminate();
    keep_running = 0;
}

void log_distance(int distance) {
    char msg[MQ_MAX_MSG_SIZE];
    snprintf(msg, sizeof(msg), "Distance: %d mm\n", distance);
    if (mq_send(mq_handle, msg, strlen(msg) + 1, 0) == -1) {
        perror("mq_send");
    }
}

int read_register(uint8_t reg) {
    uint8_t data[1];
    if (i2c_read_byte_data(i2c_handle, reg, data) < 0) {
        perror("i2c_read_byte_data");
        return -1;
    }
    return data[0];
}

int write_register(uint8_t reg, uint8_t value) {
    if (i2c_write_byte_data(i2c_handle, reg, value) < 0) {
        perror("i2c_write_byte_data");
        return -1;
    }
    return 0;
}

int read_distance() {
    uint8_t data[2];
    if (i2c_read_i2c_block_data(i2c_handle, VL53L1X_DISTANCE_HIGH_REG, 2, data) < 0) {
        perror("i2c_read_i2c_block_data");
        return -1;
    }
    int distance = (data[0] << 8) | data[1];
    return distance;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2c_open(VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_register(VL53L1X_MODEL_ID_REG) != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Invalid sensor model ID\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (write_register(VL53L1X_SOFT_RESET_REG, 0x00) < 0 || write_register(VL53L1X_SOFT_RESET_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (write_register(VL53L1X_TIMING_BUDGET_REG, VL53L1X_TIMING_BUDGET) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (write_register(VL53L1X_START_RANGING_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer GPIO mode\n");
        cleanup(0);
        return EXIT_FAILURE;
    }

    struct mq_attr mq_attr = {
        .mq_flags = 0,
        .mq_maxmsg = MQ_MAX_MSGS,
        .mq_msgsize = MQ_MAX_MSG_SIZE,
        .mq_curmsgs = 0
    };

    mq_handle = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0644, &mq_attr);
    if (mq_handle < 0) {
        perror("mq_open");
        cleanup(0);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (read_register(VL53L1X_DATA_READY_REG) & 0x01) {
            int distance = read_distance();
            if (distance >= 0) {
                log_distance(distance);
                if (distance < DISTANCE_THRESHOLD) {
                    gpioWrite(BUZZER_GPIO, 1);
                    usleep(100000); // Buzz for 100 ms
                    gpioWrite(BUZZER_GPIO, 0);
                }
            }
        }
        usleep(50000); // Poll every 50 ms
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

