#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define SPEED_OF_SOUND_CM_S 34300
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2
#define ALERT_TIMEOUT_US 1000000 // 1 second timeout for echo
#define DISPLAY_INTERVAL_MS 100

volatile int running = 1;
volatile unsigned long start_tick = 0;
volatile unsigned long end_tick = 0;
volatile int buzzer_state = 0;

void handle_sigint(int sig) {
    running = 0;
    gpioWrite(BUZZER_PIN, 0);
    printf("Shutting down...\n");
}

void echo_callback(int gpio, unsigned level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;
    }
}

void check_distance() {
    unsigned long pulse_width = end_tick - start_tick;
    if (pulse_width == 0) {
        printf("Sensor absent (timeout/no echo)\n");
        return;
    }

    double distance_cm = (pulse_width * SPEED_OF_SOUND_CM_S) / 20000000.0; // Convert to cm

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        printf("Invalid reading (out-of-range): %.2f cm\n", distance_cm);
    } else {
        printf("Distance: %.2f cm\n", distance_cm);
        if (distance_cm < 30 && !buzzer_state) {
            gpioWrite(BUZZER_PIN, 1);
            buzzer_state = 1;
        } else if (distance_cm >= 30 && buzzer_state) {
            gpioWrite(BUZZER_PIN, 0);
            buzzer_state = 0;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, ALERT_TIMEOUT_US) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 0);

        usleep(60); // Wait for echo to settle

        check_distance();
        usleep(DISPLAY_INTERVAL_MS * 1000);
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return 0;
}

