#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <paho.mqtt.c/mqtt_client.h>
#include <paho.mqtt.c/mqtt_client_api.h>
#include <paho.mqtt.c/mqtt_internal_types.h>
#include <paho.mqtt.c/mqtt_ssl.h>

#define VL53L1X_I2C_BUS 1
#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_I2C_TIMEOUT 1000
#define VL53L1X_I2C_BUFFER_SIZE 2
#define SERVO_GPIO 18
#define GATE_OPEN_ANGLE 90
#define GATE_CLOSED_ANGLE 0
#define GATE_OPEN_DISTANCE 20
#define MQTT_BROKER "mqtt_broker_address"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "RaspberryPiGate"
#define MQTT_TOPIC_COMMAND "gate/command"
#define MQTT_TOPIC_STATUS "gate/status"

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int sig) {
    exit_flag = 1;
}

void log_event(const char *event) {
    FILE *log_file = fopen("gate_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fclose(log_file);
    }
}

int i2c_write(int bus, int addr, const uint8_t *data, int len) {
    int fd = open("/dev/i2c-" + std::to_string(bus), O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return -1;
    }
    if (write(fd, data, len) != len) {
        perror("Failed to write to the i2c bus");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

