#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000
#define MEASURE_INTERVAL_MS 200
#define TIMEOUT_MS 60

volatile sig_atomic_t keep_running = 1;
FILE *log_file;

void handle_signal(int signal) {
    keep_running = 0;
}

void echo_callback(int gpio, unsigned level, uint32_t tick) {
    static uint32_t rising_edge_tick = 0;
    static uint32_t falling_edge_tick = 0;
    static int edge_count = 0;

    if (level == 1) {
        // Rising edge
        rising_edge_tick = tick;
        edge_count = 1;
    } else if (level == 0 && edge_count == 1) {
        // Falling edge
        falling_edge_tick = tick;
        edge_count = 0;

        // Handle 32-bit tick wraparound
        uint32_t pulse_width_us;
        if (falling_edge_tick >= rising_edge_tick) {
            pulse_width_us = falling_edge_tick - rising_edge_tick;
        } else {
            pulse_width_us = (0xFFFFFFFF - rising_edge_tick) + falling_edge_tick + 1;
        }

        if (pulse_width_us < MIN_PULSE_WIDTH_US) {
            fprintf(stderr, "Warning: Pulse width too short (%u us), likely noise.\n", pulse_width_us);
        } else if (pulse_width_us > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Warning: Pulse width too long (%u us), likely timeout/no object detected.\n", pulse_width_us);
        } else {
            double distance_cm = pulse_width_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

            fprintf(stdout, "%s: Distance: %.2f cm\n", timestamp, distance_cm);
            fprintf(log_file, "%s: Distance: %.2f cm\n", timestamp, distance_cm);
            fflush(log_file);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0 || gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to configure ECHO pin.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure TRIG pin.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioAlertFuncSet(ECHO_PIN, echo_callback, 0) < 0) {
        fprintf(stderr, "Failed to set alert callback for ECHO pin.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        gpioWrite(TRIG_PIN, 0);
        usleep(2); // Ensure TRIG is LOW for at least 2 microseconds

        gpioWrite(TRIG_PIN, 1);
        usleep(10); // 10 microsecond pulse
        gpioWrite(TRIG_PIN, 0);

        usleep(TIMEOUT_MS * 1000); // Wait for echo or timeout
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

