#define VL53L1X_I2C_BUS 1
#define VL53L1X_I2C_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18

volatile sig_atomic_t stop_requested = 0;

void handle_signal(int sig) {
    stop_requested = 1;
}

int i2c_write_retry(int bus, int addr, unsigned char reg, unsigned char value) {
    int retries = 0;
    int max_retries = 5;
    int delay = 10; // initial delay in ms

    while (retries < max_retries) {
        if (i2c_write_byte_data(bus, addr, reg, value) >= 0) {
            return 0;
        }
        retries++;
        printf("I2C write retry %d\n", retries);
        usleep(delay * 1000);
        delay *= 2; // exponential backoff
    }
    return -1;
}

int i2c_read_retry(int bus, int addr, unsigned char reg, unsigned short *value) {
    int retries = 0;
    int max_retries = 5;
    int delay = 10; // initial delay in ms

    while (retries < max_retries) {
        if (i2c_read_i2c_block_data(bus, addr, reg, 2) >= 0) {
            *value = (i2c_read_byte_data(bus, addr, reg) << 8) | i2c_read_byte_data(bus, addr, reg + 1);
            return 0;
        }
        retries++;
        printf("I2C read retry %d\n", retries);
        usleep(delay * 1000);
        delay *= 2; // exponential backoff
    }
    return -1;
}

void motor_control(int forward, int backward, int stop) {
    if (forward) {
        gpioWrite(GPIO_MOTOR_FORWARD, 1);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
        printf("Motor: Forward\n");
    } else if (backward) {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 1);
        printf("Motor: Backward\n");
    } else {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
        printf("Motor: Stop\n");
    }
}

void distance_measurement_callback(int gpio, unsigned level, uint32_t tick) {
    if (stop_requested) return;

    if (i2c_write_retry(VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR, 0x00, 0x00) < 0) {
        printf("Failed to reset VL53L1X\n");
        motor_control(0, 0, 1);
        return;
    }
    usleep(1000 * 1000); // 1 ms

    if (i2c_write_retry(VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR, 0x00, 0x01) < 0) {
        printf("Failed to start measurement\n");
        motor_control(0, 0, 1);
        return;
    }

    while (1) {
        unsigned short data_ready;
        if (i2c_read_retry(VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR, 0x0089, &data_ready) < 0) {
            printf("Failed to read data ready register\n");
            motor_control(0, 0, 1);
            return;
        }
        if (data_ready & 0x01) break;
    }

    unsigned short distance;
    if (i2c_read_retry(VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR, 0x0096, &distance) < 0) {
        printf("Failed to read distance\n");
        motor_control(0, 0, 1);
        return;
    }

    printf("Distance: %d mm\n", distance);

    if (distance < 100) {
        motor_control(1, 0, 0);
    } else if (distance > 300) {
        motor_control(0, 1, 0);
    } else {
        motor_control(0, 0, 1);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) < 0 ||
        gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(GPIO_TRIGGER, distance_measurement_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        gpioTerminate();
        return 1;
    }

    while (!stop_requested) {
        sleep(1);
    }

    motor_control(0, 0, 1);
    gpioTerminate();
    return 0;
}

