#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define GPIO_LED_PINS {17, 18, 27, 22}
#define POLL_INTERVAL 50 // milliseconds

static int i2c_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write_byte_data(int reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read_byte_data(int reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    int pin_values[4] = GPIO_LED_PINS;
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_values[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], "LED", 0) < 0) {
            perror("Failed to request GPIO line");
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpio() {
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

void setup_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Soft reset
    if (i2c_write_byte_data(0x80, 0x63) < 0) {
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify sensor presence
    uint8_t version;
    if (i2c_read_byte_data(0x00, &version) < 0) {
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    printf("MPR121 version: 0x%02X\n", version);

    // Initialize sensor
    if (i2c_write_byte_data(0x5A, 0x0B) < 0 ||
        i2c_write_byte_data(0x5D, 0xC8) < 0 ||
        i2c_write_byte_data(0x5E, 0x82) < 0 ||
        i2c_write_byte_data(0x5F, 0xB4) < 0 ||
        i2c_write_byte_data(0x5C, 0x0C) < 0 ||
        i2c_write_byte_data(0x5B, 0x0C) < 0 ||
        i2c_write_byte_data(0x5A, 0x00) < 0 ||
        i2c_write_byte_data(0x5B, 0x00) < 0 ||
        i2c_write_byte_data(0x5C, 0x0C) < 0 ||
        i2c_write_byte_data(0x5D, 0x01) < 0 ||
        i2c_write_byte_data(0x5E, 0x01) < 0 ||
        i2c_write_byte_data(0x5F, 0x0E) < 0 ||
        i2c_write_byte_data(0x6A, 0x00) < 0 ||
        i2c_write_byte_data(0x6B, 0x00) < 0) {
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void set_led_pattern(int pattern) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], (pattern >> i) & 1);
    }
}

void log_event(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", timestamp, message);
}

void poll_sensor() {
    uint8_t touch_status[2];
    while (!stop) {
        if (i2c_read_i2c_block_data(0x00, touch_status, 2) < 0) {
            log_event("Failed to read touch status");
            continue;
        }

        int active_electrode = -1;
        for (int i = 0; i < 12; i++) {
            if (touch_status[i / 8] & (1 << (i % 8))) {
                active_electrode = i;
                break;
            }
        }

        if (active_electrode >= 0) {
            set_led_pattern(1 << (active_electrode % 4));
            char log_msg[50];
            snprintf(log_msg, sizeof(log_msg), "Electrode %d touched", active_electrode);
            log_event(log_msg);
        } else {
            set_led_pattern(0);
            log_event("No electrode touched");
        }

        usleep(POLL_INTERVAL * 1000);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_i2c();

    poll_sensor();

    cleanup_gpio();
    cleanup_i2c();

    return 0;
}

