        i2c_write_byte_data(0x5D, 0xC8) < 0 ||
        i2c_write_byte_data(0x5E, 0x82) < 0 ||
        i2c_write_byte_data(0x5F, 0xB4) < 0 ||
        i2c_write_byte_data(0x5C, 0x0C) < 0 ||
        i2c_write_byte_data(0x5B, 0x0C) < 0 ||
        i2c_write_byte_data(0x5A, 0x00) < 0 ||
        i2c_write_byte_data(0x5B, 0x00) < 0 ||
        i2c_write_byte_data(0x5C, 0x0C) < 0 ||
        i2c_write_byte_data(0x5D, 0x01) < 0 ||
        i2c_write_byte_data(0x5E, 0x01) < 0 ||
        i2c_write_byte_data(0x5F, 0x0E) < 0 ||
        i2c_write_byte_data(0x6A, 0x00) < 0 ||
        i2c_write_byte_data(0x6B, 0x00) < 0) {
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void set_led_pattern(int pattern) {
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(lines[i], (pattern >> i) & 1);
    }
}

void log_event(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", timestamp, message);
}

void poll_sensor() {
    uint8_t touch_status[2];
    while (!stop) {
        if (i2c_read_i2c_block_data(0x00, touch_status, 2) < 0) {
            log_event("Failed to read touch status");
            continue;
        }

        int active_electrode = -1;
        for (int i = 0; i < 12; i++) {
            if (touch_status[i / 8] & (1 << (i % 8))) {
                active_electrode = i;
                break;
            }
        }

        if (active_electrode >= 0) {
            set_led_pattern(1 << (active_electrode % 4));
            char log_msg[50];
            snprintf(log_msg, sizeof(log_msg), "Electrode %d touched", active_electrode);
            log_event(log_msg);
        } else {
            set_led_pattern(0);
            log_event("No electrode touched");
        }

        usleep(POLL_INTERVAL * 1000);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_i2c();

    poll_sensor();

    cleanup_gpio();
    cleanup_i2c();

    return 0;
}
