#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define TRIGGER_LOW_US 5
#define TRIGGER_HIGH_US 10
#define TIMEOUT_US 30000000 // 30 ms
#define SPEED_OF_SOUND_CM_PER_US 0.0343 / 2.0

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int sig) {
    stop_flag = 1;
}

double measure_distance(struct gpiod_line *echo_line) {
    struct gpiod_line_event event;
    struct timespec start, end;
    long long pulse_width_us = 0;
    double distance_cm = -1.0;

    // Wait for the echo rising edge
    if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: Echo rising edge timeout\n");
        return -1.0;
    }

    // Measure the echo pulse width
    if (gpiod_line_event_read(echo_line, &event, TIMEOUT_US) < 0) {
        fprintf(stderr, "Error: Echo pulse width read timeout\n");
        return -1.0;
    }

    if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("clock_gettime");
            return -1.0;
        }

        if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, TIMEOUT_US) < 0) {
            fprintf(stderr, "Error: Echo falling edge timeout\n");
            return -1.0;
        }

        if (gpiod_line_event_read(echo_line, &event, TIMEOUT_US) < 0) {
            fprintf(stderr, "Error: Echo pulse width read timeout\n");
            return -1.0;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
                perror("clock_gettime");
                return -1.0;
            }

            pulse_width_us = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
            pulse_width_us /= 1000; // Convert to microseconds

            distance_cm = pulse_width_us * SPEED_OF_SOUND_CM_PER_US;
        }
    }

    return distance_cm;
}

void log_distance(FILE *log_file, double distance_cm) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);

    if (utc_time == NULL) {
        perror("gmtime");
        return;
    }

    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ %f cm\n",
            utc_time->tm_year + 1900, utc_time->tm_mon + 1, utc_time->tm_mday,
            utc_time->tm_hour, utc_time->tm_min, utc_time->tm_sec, distance_cm);

    fflush(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct gpiod_line_request req;
    FILE *log_file;
    double distance_cm;

    signal(SIGINT, handle_sigint);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (trigger_line == NULL) {
        fprintf(stderr, "Error: Could not get trigger line\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (echo_line == NULL) {
        fprintf(stderr, "Error: Could not get echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(&req, trigger_line, "trigger", 0) < 0) {
        fprintf(stderr, "Error: Could not request trigger line\n");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(&req, echo_line, "echo", 0) < 0) {
        fprintf(stderr, "Error: Could not request echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        // Trigger sequence
        gpiod_line_set_value(trigger_line, 0);
        usleep(TRIGGER_LOW_US);

        gpiod_line_set_value(trigger_line, 1);
        usleep(TRIGGER_HIGH_US);

        gpiod_line_set_value(trigger_line, 0);

        // Measure distance
        distance_cm = measure_distance(echo_line);

        if (distance_cm < 0) {
            fprintf(log_file, "Error: Invalid reading\n");
        } else if (distance_cm < 2 || distance_cm > 400) {
            fprintf(log_file, "Error: Out of range reading\n");
        } else {
            log_distance(log_file, distance_cm);
        }

        sleep(1);
    }

    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

