#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIGGER_DURATION 10
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 1
#define SOUND_SPEED_M_PER_US 0.000343

volatile int running = 1;
FILE *log_file = NULL;
unsigned long start_tick = 0;
unsigned long end_tick = 0;

void handle_signal(int sig) {
    running = 0;
}

void echo_isr(unsigned gpio, unsigned level, uint32_t tick, void *userdata) {
    if (level == 0) {
        start_tick = tick;
    } else {
        end_tick = tick;
        unsigned long pulse_width = end_tick - start_tick;
        if (pulse_width > 0 && pulse_width <= (MAX_DISTANCE_CM * 58)) {
            double distance_m = pulse_width * SOUND_SPEED_M_PER_US;
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s: Distance: %.2f meters\n", timestamp, distance_m);
            fflush(log_file);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen("distance_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, echo_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (running) {
        gpioWrite(TRIG_PIN, 0);
        usleep(2000);
        gpioWrite(TRIG_PIN, 1);
        usleep(TRIGGER_DURATION);
        gpioWrite(TRIG_PIN, 0);
        usleep(1000000 - TRIGGER_DURATION);
    }

    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, NULL, NULL);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

