#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_GATE 24
#define MODEL_ID_REG 0x010F
#define RANGING_MODE_REG 0x0021
#define START_RANGING_REG 0x0015
#define DISTANCE_HIGH_REG 0x0089
#define DISTANCE_LOW_REG 0x008A
#define DISTANCE_THRESHOLD_CM 20

static int i2c_handle;
static int log_fd;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_message(const char *message) {
    if (log_fd >= 0) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "[%s] %s\n", timestamp, message);
        fflush(log_fd);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    log_fd = open("gate_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_GATE, PI_OUTPUT);
    gpioWrite(GPIO_GATE, PI_LOW);

    uint8_t model_id;
    if (i2cReadReg8(i2c_handle, MODEL_ID_REG, &model_id) < 0 || model_id != 0xEA) {
        log_message("Error: Failed to read model ID or incorrect model ID");
        goto cleanup;
    }

    if (i2cWriteReg8(i2c_handle, RANGING_MODE_REG, 0x00) < 0) {
        log_message("Error: Failed to set ranging mode");
        goto cleanup;
    }

    if (i2cWriteReg8(i2c_handle, START_RANGING_REG, 0x01) < 0) {
        log_message("Error: Failed to start ranging");
        goto cleanup;
    }

    while (keep_running) {
        uint8_t distance_high, distance_low;
        if (i2cReadReg8(i2c_handle, DISTANCE_HIGH_REG, &distance_high) < 0 ||
            i2cReadReg8(i2c_handle, DISTANCE_LOW_REG, &distance_low) < 0) {
            log_message("Error: Failed to read distance");
        } else {
            int distance_mm = (distance_high << 8) | distance_low;
            int distance_cm = distance_mm / 10;
            char log_buffer[100];
            snprintf(log_buffer, sizeof(log_buffer), "Distance: %d cm", distance_cm);
            log_message(log_buffer);

            int gate_state = (distance_cm < DISTANCE_THRESHOLD_CM) ? PI_HIGH : PI_LOW;
            if (gpioRead(GPIO_GATE) != gate_state) {
                gpioWrite(GPIO_GATE, gate_state);
                char state_message[50];
                snprintf(state_message, sizeof(state_message), "Gate %s", gate_state == PI_HIGH ? "opened" : "closed");
                log_message(state_message);
            }
        }
        usleep(100000); // 100 ms
    }

cleanup:
    i2cClose(i2c_handle);
    close(log_fd);
    gpioTerminate();
    return 0;
}

