#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT 30000 // 30 ms
#define SAMPLES 5
#define LOG_INTERVAL 100 // ms

volatile sig_atomic_t stop_flag = 0;
volatile int pulse_width = 0;
volatile int samples[SAMPLES] = {0};
volatile int sample_index = 0;
volatile int valid_samples = 0;
FILE *log_file = NULL;

void handle_sigint(int sig) {
    stop_flag = 1;
}

void echo_callback(int gpio, uint32_t tick) {
    uint32_t tick_diff;
    if (gpio == ECHO_PIN) {
        if (gpioGetLevel(ECHO_PIN) == 1) {
            // Rising edge
            gpioSetAlertFunc(ECHO_PIN, NULL);
            gpioSetAlertFunc(ECHO_PIN, echo_callback);
        } else {
            // Falling edge
            tick_diff = pigpioTickDiff(tick, gpioTick());
            if (tick_diff < TIMEOUT) {
                pulse_width = tick_diff;
                samples[sample_index] = pulse_width;
                sample_index = (sample_index + 1) % SAMPLES;
                valid_samples = SAMPLES;
            } else {
                samples[sample_index] = -1;
                sample_index = (sample_index + 1) % SAMPLES;
                valid_samples = SAMPLES;
            }
        }
    }
}

double calculate_distance() {
    int sum = 0;
    int count = 0;
    for (int i = 0; i < SAMPLES; i++) {
        if (samples[i] != -1) {
            sum += samples[i];
            count++;
        }
    }
    if (count == 0) return -1.0;
    return (double)sum / count / 58.0; // Convert to cm
}

double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    double log_distance = log10(distance);
    double log_min = log10(MIN_DISTANCE);
    double log_max = log10(MAX_DISTANCE);
    double angle = 90 + 45 * (log_distance - log_min) / (log_max - log_min);
    return angle;
}

void log_data(double distance, double angle) {
    if (log_file) {
        fprintf(log_file, "%lu,%.2f,%.2f\n", (unsigned long)gpioTick(), distance, angle);
        fflush(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp,distance_cm,servo_angle_deg\n");

    while (!stop_flag) {
        gpioWrite(TRIGGER_PIN, 1);
        pi_sleep(0.00001); // 10 us
        gpioWrite(TRIGGER_PIN, 0);

        pi_sleep(0.0001); // 100 ms

        double distance = calculate_distance();
        double angle = -1.0;
        if (distance != -1.0) {
            angle = map_distance_to_angle(distance);
            if (angle == -1.0) {
                angle = 90.0;
            }
        } else {
            angle = 90.0;
        }

        int pulse_width_us = (int)(500 + (angle / 180.0) * 2000);
        if (gpioServo(SERVO_PIN, pulse_width_us) < 0) {
            fprintf(stderr, "Failed to set servo pulse width\n");
        }

        log_data(distance, angle);
    }

    gpioServo(SERVO_PIN, 0);
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

