#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_REGISTER_HIGH 0x08
#define PROXIMITY_REGISTER_LOW 0x09

static int i2c_handle = -1;
static int gpio_pin = 27;
static int threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t running = 1;
static volatile int interrupt_triggered = 0;
static FILE *log_file = NULL;

void handle_sigint(int sig) {
    running = 0;
}

void log_proximity(int proximity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity,
            proximity <= threshold ? "SAFE" : "ALERT");
    fflush(log_file);
}

void gpio_callback(int gpio, unsigned level, uint32_t tick) {
    interrupt_triggered = 1;
}

int read_proximity(int i2c_handle, int address) {
    unsigned char buffer[2];
    if (i2c_read(i2c_handle, address, buffer, 2) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    int proximity = (buffer[0] << 8) | buffer[1];
    return proximity;
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
