static int i2c_handle = -1;
static int gpio_pin = 27;
static int threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t running = 1;
static volatile int interrupt_triggered = 0;
static FILE *log_file = NULL;

void handle_sigint(int sig) {
    running = 0;
}

void log_proximity(int proximity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity,
            proximity <= threshold ? "SAFE" : "ALERT");
    fflush(log_file);
}

void gpio_callback(int gpio, unsigned level, uint32_t tick) {
    interrupt_triggered = 1;
}

int read_proximity(int i2c_handle, int address) {
    unsigned char buffer[2];
    if (i2c_read(i2c_handle, address, buffer, 2) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    int proximity = (buffer[0] << 8) | buffer[1];
    return proximity;
}

