#define TIMEOUT_MS 200
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 200
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

static int pi = -1;
static unsigned int wave_id = 0;
static unsigned int prev_frequency = 0;

void handle_signal(int sig) {
    if (wave_id != 0) {
        gpioWaveDelete(wave_id);
        wave_id = 0;
    }
    if (pi >= 0) {
        gpioTerminate(pi);
        pi = -1;
    }
    exit(0);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

double calculate_frequency(int distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return prev_frequency;
    }
    double frequency = 200 * exp(distance_cm / 50.0);
    if (frequency < MIN_FREQUENCY_HZ) {
        frequency = MIN_FREQUENCY_HZ;
    } else if (frequency > MAX_FREQUENCY_HZ) {
        frequency = MAX_FREQUENCY_HZ;
    }
    return frequency;
}

