#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5
#define MAX_DIST 50
#define TIMEOUT 100000 // 100 ms in microseconds
#define DELAY 10000    // 10 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
}

double read_distance() {
    if (gpioTrigger(TRIGGER_PIN, 10) < 0) {
        fprintf(stderr, "Error triggering ultrasonic sensor\n");
        return -1;
    }

    if (gpioDelay(ECHO_PIN, TIMEOUT) < 0) {
        fprintf(stderr, "Error reading echo pulse\n");
        return -1;
    }

    unsigned long pulse_width = gpioTickDiff(gpioTick(), gpioTick());
    if (pulse_width == 0) {
        fprintf(stderr, "Timeout reading echo pulse\n");
        return -1;
    }

    double distance = pulse_width / 58.0; // Convert to cm
    return distance;
}

double calculate_frequency(double distance) {
    if (distance < MIN_DIST) distance = MIN_DIST;
    if (distance > MAX_DIST) distance = MAX_DIST;

    double frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
    if (frequency < MIN_FREQ) frequency = MIN_FREQ;
    if (frequency > MAX_FREQ) frequency = MAX_FREQ;

    return frequency;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioHardwarePWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set hardware PWM\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    double last_valid_distance = -1;
    double frequency = 0;

    while (keep_running) {
        double distance = read_distance();
        if (distance >= 0) {
            last_valid_distance = distance;
        } else {
            distance = last_valid_distance;
        }

        if (distance >= 0) {
            frequency = calculate_frequency(distance);
            if (gpioHardwarePWM(BUZZER_PIN, frequency * 1000) < 0) {
                fprintf(stderr, "Failed to set PWM frequency\n");
                break;
            }
        }

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        usleep(DELAY);
    }

    gpioHardwarePWM(BUZZER_PIN, 0);
    gpioTerminate();
    return 0;
}

