#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define PULSE_WIDTH_US 10
#define TIMEOUT_MS 50
#define MEASURE_INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);

    while (keep_running) {
        // Send 10 us pulse
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelayMicroseconds(PULSE_WIDTH_US);
        gpioWrite(TRIGGER_PIN, 0);

        // Measure echo pulse width
        unsigned long pulse_width = gpioPulseIn(ECHO_PIN, 1, TIMEOUT_MS);
        if (pulse_width == -1) {
            fprintf(stderr, "Timeout occurred\n");
        } else {
            double distance_cm = pulse_width / 2.0 / 29.1;
            if (distance_cm < 2.0 || distance_cm > 400.0) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm", distance_cm);
                if (distance_cm < 10.0) {
                    printf(" Too close!\n");
                } else {
                    printf("\n");
                }
            }
        }

        usleep(MEASURE_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

