#define SPI_SPEED 1000000
#define CS_PIN 8
#define CONTINUOUS_MEASUREMENT_MODE 0x01
#define RANGE_5M 0x00
#define TRIGGER_MEASUREMENT 0x01
#define LOW_BYTE_REGISTER 0x0C
#define HIGH_BYTE_REGISTER 0x0D

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int init_sensor() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return -1;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        log_error("Failed to setup SPI");
        return -1;
    }

    if (gpioSPIDataRW(SPI_CHANNEL, &CONTINUOUS_MEASUREMENT_MODE, 1) < 0) {
        log_error("Failed to set continuous measurement mode");
        return -1;
    }

    if (gpioSPIDataRW(SPI_CHANNEL, &RANGE_5M, 1) < 0) {
        log_error("Failed to set range to 5m");
        return -1;
    }

    if (gpioSPIDataRW(SPI_CHANNEL, &TRIGGER_MEASUREMENT, 1) < 0) {
        log_error("Failed to trigger measurement");
        return -1;
    }

    return 0;
}

int read_distance(int *distance) {
    unsigned char tx[1] = {LOW_BYTE_REGISTER};
    unsigned char rx[2] = {0, 0};

    if (gpioSPIDataRW(SPI_CHANNEL, tx, 1) < 0) {
        log_error("Failed to read low byte");
        return -1;
    }

    if (gpioSPIDataRW(SPI_CHANNEL, tx, 1) < 0) {
        log_error("Failed to read high byte");
        return -1;
    }

    *distance = (rx[1] << 8) | rx[0];
    return 0;
}

void log_distance(FILE *log_file, int distance) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, distance);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_sensor() < 0) {
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int distance = 0;
        if (read_distance(&distance) == 0) {
            if (distance >= 200 && distance <= 5000) {
                log_distance(log_file, distance);
            } else {
                log_error("Distance out of range");
            }
        } else {
            log_error("SPI communication error");
        }
        usleep(100000); // 100 ms delay
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}
