volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return -1;
    }
    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return file;
}

int read_i2c_register(int file, uint8_t reg, uint8_t *data) {
    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to the I2C bus");
        return -1;
    }
    if (read(file, data, 1) != 1) {
        perror("Failed to read from the I2C bus");
        return -1;
    }
    return 0;
}

void log_reading(FILE *log_file, uint16_t als_visible) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_file = open_i2c_device(I2C_DEVICE, I2C_ADDRESS);
    if (i2c_file < 0) {
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_file);
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
        fflush(log_file);
    }

    uint8_t low_byte, high_byte;
    uint16_t als_visible;

    while (keep_running) {
        if (read_i2c_register(i2c_file, REG_VISIBLE_LOW, &low_byte) == 0 &&
            read_i2c_register(i2c_file, REG_VISIBLE_HIGH, &high_byte) == 0) {
            als_visible = (high_byte << 8) | low_byte;
            log_reading(log_file, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        sleep(5);
    }

    fclose(log_file);
    close(i2c_file);
    return EXIT_SUCCESS;
}

