#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_write_retry(int handle, unsigned char reg, unsigned char value) {
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2c_write_byte_data(handle, reg, value) >= 0) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read_retry(int handle, unsigned char reg, unsigned char *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2c_read_byte_data(handle, reg, value) >= 0) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int read_16bit_little_endian(int handle, unsigned char reg_low, unsigned char reg_high, unsigned short *value) {
    unsigned char low, high;
    if (i2c_read_retry(handle, reg_low, &low) < 0 || i2c_read_retry(handle, reg_high, &high) < 0) {
        return -1;
    }
    *value = (high << 8) | low;
    return 0;
}

void log_reading(FILE *log_file, time_t timestamp, unsigned short als, unsigned short ps1) {
    char time_str[20];
    struct tm *tm_info = localtime(&timestamp);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s ALS: %u PS1: %u\n", time_str, als, ps1);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("si1120_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_retry(i2c_handle, 0x30, 0x01) < 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char part_id;
    if (i2c_read_retry(i2c_handle, 0x00, &part_id) < 0 || part_id != 0x41) {
        fprintf(stderr, "Failed to verify Si1120 part ID\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        unsigned short als, ps1;
        if (read_16bit_little_endian(i2c_handle, 0x22, 0x23, &als) < 0 ||
            read_16bit_little_endian(i2c_handle, 0x18, 0x19, &ps1) < 0) {
            fprintf(stderr, "Failed to read ALS or PS1 data\n");
        } else {
            log_reading(log_file, time(NULL), als, ps1);
        }
        usleep(500 * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

