#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x39
#define PART_ID_REG 0x00
#define MEASUREMENT_RATE_REG 0x08
#define AMBIENT_LIGHT_REG_START 0x22
#define PROXIMITY_REG_START 0x24
#define MEASUREMENT_RATE_VALUE 0x07

static int i2c_fd = -1;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void log_error(const char *message) {
    perror(message);
    handle_signal(SIGINT);
}

int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        log_error("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_word_data(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        log_error("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, buffer, 2) != 2) {
        log_error("Failed to read from I2C device");
        return -1;
    }
    *value = buffer[0] | (buffer[1] << 8);
    return 0;
}

void log_reading(const char *timestamp, float lux, uint16_t proximity) {
    fprintf(log_file, "%s,%f,%u\n", timestamp, lux, proximity);
    fprintf(stdout, "%s,%f,%u\n", timestamp, lux, proximity);
    fflush(log_file);
    fflush(stdout);
}

void get_timestamp(char *buffer, size_t size) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&ts.tv_sec);
    strftime(buffer, size, "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(buffer + strlen(buffer), size - strlen(buffer), ".%03ld", ts.tv_nsec / 1000000);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        log_error("Failed to open I2C device");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        log_error("Failed to set I2C address");
    }

    uint8_t part_id;
    if (i2c_read_word_data(i2c_fd, PART_ID_REG, (uint16_t *)&part_id) != 0 || part_id != 0x1182) {
        fprintf(stderr, "Sensor not found or incorrect part ID\n");
        handle_signal(SIGINT);
    }

    if (i2c_write_byte_data(i2c_fd, MEASUREMENT_RATE_REG, MEASUREMENT_RATE_VALUE) != 0) {
        log_error("Failed to set measurement rate");
    }

    log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        log_error("Failed to open log file");
    }

    char timestamp[30];
    while (1) {
        get_timestamp(timestamp, sizeof(timestamp));

        uint16_t ambient_light_raw, proximity_raw;
        if (i2c_read_word_data(i2c_fd, AMBIENT_LIGHT_REG_START, &ambient_light_raw) != 0 ||
            i2c_read_word_data(i2c_fd, PROXIMITY_REG_START, &proximity_raw) != 0) {
            log_error("Failed to read sensor data");
        }

        float lux = ambient_light_raw * 0.1;
        log_reading(timestamp, lux, proximity_raw);

        usleep(100000); // Sleep for 100 ms
    }

    handle_signal(SIGINT);
    return 0;
}

