#define I2C_ADDRESS 0x60
#define MAX_RETRIES 3

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "[%s] ERROR: %s\n", time_str, message);
}

void log_proximity(unsigned int proximity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen("proximity_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "[%s] Proximity: %u\n", time_str, proximity);
        fclose(log_file);
    } else {
        log_error("Failed to open log file for writing.");
    }
}

int write_register(int i2c_handle, unsigned char reg, unsigned char value) {
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cWriteByteData(i2c_handle, I2C_ADDRESS, reg, value) == 0) {
            return 0;
        }
        log_error("I2C write failed, retrying...");
    }
    return -1;
}

int read_proximity(int i2c_handle, unsigned int *proximity) {
    unsigned char low_byte, high_byte;
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2cReadByteData(i2c_handle, I2C_ADDRESS, 0x16, &low_byte) == 0 &&
            i2cReadByteData(i2c_handle, I2C_ADDRESS, 0x17, &high_byte) == 0) {
            *proximity = (high_byte << 8) | low_byte;
            return 0;
        }
        log_error("I2C read failed, retrying...");
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library.");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(1, I2C_ADDRESS);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C handle.");
        gpioTerminate();
        return 1;
    }

    if (write_register(i2c_handle, 0x07, 0x03) < 0 ||
        write_register(i2c_handle, 0x06, 0x02) < 0 ||
        write_register(i2c_handle, 0x1A, 0x00) < 0 ||
        write_register(i2c_handle, 0x21, 0x0B) < 0 ||
        write_register(i2c_handle, 0x24, 0x00) < 0 ||
        write_register(i2c_handle, 0x22, 0x49) < 0 ||
        write_register(i2c_handle, 0x0C, 0x03) < 0 ||
        write_register(i2c_handle, 0x0F, 0x0F) < 0 ||
        write_register(i2c_handle, 0x11, 0x03) < 0 ||
        write_register(i2c_handle, 0x0D, 0x07) < 0 ||
        write_register(i2c_handle, 0x80, 0x03) < 0) {
        log_error("Failed to initialize Si1145 sensor.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        unsigned int proximity;
        if (read_proximity(i2c_handle, &proximity) == 0) {
            log_proximity(proximity);
        } else {
            log_error("Failed to read proximity data.");
        }
        sleep(1);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

