#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define MAX_DISTANCE_CM 20
#define SPEED_OF_SOUND_CM_PER_US 0.0343

volatile unsigned long rising_edge_time = 0;
volatile unsigned long falling_edge_time = 0;
volatile int distance_ready = 0;

void handle_sigint(int sig) {
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void echo_callback(int gpio, unsigned level, uint32_t tick) {
    if (level == 1) {
        rising_edge_time = tick;
    } else {
        falling_edge_time = tick;
        distance_ready = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, 0) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(2);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        while (!distance_ready) {
            // Wait for the echo callback to set distance_ready
        }

        unsigned long pulse_width = falling_edge_time - rising_edge_time;
        float distance_cm = pulse_width * SPEED_OF_SOUND_CM_PER_US / 2;

        printf("Distance: %.2f cm\n", distance_cm);

        if (distance_cm < MAX_DISTANCE_CM) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }

        distance_ready = 0;
        gpioDelay(1000); // Delay for 1 second
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

