#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 20.0
#define UPDATE_INTERVAL 100000 // 100 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

double measure_distance() {
    if (gpioTrigger(TRIGGER_PIN, 10) < 0) {
        fprintf(stderr, "Error triggering ultrasonic sensor\n");
        return -1.0;
    }

    gpioDelay(10); // 10 us delay

    if (gpioTrigger(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error stopping ultrasonic sensor trigger\n");
        return -1.0;
    }

    if (gpioWaitEcho(ECHO_PIN, 1) < 0) {
        fprintf(stderr, "Echo timeout\n");
        return -1.0;
    }

    unsigned long usec = gpioEchoTime(ECHO_PIN);
    if (usec < 0) {
        fprintf(stderr, "Error reading echo time\n");
        return -1.0;
    }

    double distance = usec / 58.0; // Convert time to distance in cm
    return distance;
}

void set_servo_angle(double distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;

    double angle = 0.0;
    if (distance <= MIN_DISTANCE) {
        angle = 180.0;
    } else if (distance >= MAX_DISTANCE) {
        angle = 0.0;
    } else {
        angle = 180.0 - (180.0 * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
    }

    unsigned int pulse_width = 500 + (angle * 1000 / 180);
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error setting servo pulse width\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        double distance = measure_distance();
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
            set_servo_angle(distance);
        } else {
            fprintf(stderr, "Error measuring distance, retrying...\n");
        }

        gpioDelay(UPDATE_INTERVAL);
    }

    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
    printf("Exiting gracefully\n");
    return EXIT_SUCCESS;
}

