#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_I2C_BUS 1
#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_MODEL_ID_REG 0x010F
#define VL53L1X_MODEL_ID 0xEA
#define VL53L1X_TIMING_BUDGET_REG 0x0006
#define VL53L1X_START_RANGING_REG 0x00EA
#define VL53L1X_RESULT_RANGE_STATUS 0x04
#define VL53L1X_RESULT_RANGE_VAL 0x14
#define SERVO_GPIO 18
#define PULSE_WIDTH_CLOSED 1000
#define PULSE_WIDTH_OPEN 2000
#define THRESHOLD_OPEN 200
#define THRESHOLD_CLOSE 250

static int pi = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

void cleanup(int sig) {
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    if (pi >= 0) {
        gpioTerminate(pi);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

void log_event(const char *event) {
    if (log_file) {
        fprintf(log_file, "%s\n", event);
        fflush(log_file);
    }
}

int main() {
    struct timespec ts;
    int distance;
    int pulse_width = PULSE_WIDTH_CLOSED;
    int last_state = 0; // 0: closed, 1: open

    signal(SIGINT, cleanup);

    pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    i2c_handle = i2c_open(pi, VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        cleanup(0);
    }

    if (i2c_read_reg8(i2c_handle, VL53L1X_MODEL_ID_REG) != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Invalid VL53L1X model ID\n");
        cleanup(0);
    }

    i2c_write_reg8(i2c_handle, VL53L1X_TIMING_BUDGET_REG, 200);
    i2c_write_reg8(i2c_handle, VL53L1X_START_RANGING_REG, 0x00);

    gpioSetMode(pi, SERVO_GPIO, PI_OUTPUT);
    gpioPWM(pi, SERVO_GPIO, pulse_width);

    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    while (1) {
        if (i2c_read_reg8(i2c_handle, VL53L1X_RESULT_RANGE_STATUS) & 0x01) {
            distance = i2c_read_reg16(i2c_handle, VL53L1X_RESULT_RANGE_VAL);
            printf("Distance: %d mm\n", distance);

            if (distance < THRESHOLD_OPEN && last_state == 0) {
                pulse_width = PULSE_WIDTH_OPEN;
                gpioPWM(pi, SERVO_GPIO, pulse_width);
                log_event("Gate opened");
                last_state = 1;
            } else if (distance > THRESHOLD_CLOSE && last_state == 1) {
                pulse_width = PULSE_WIDTH_CLOSED;
                gpioPWM(pi, SERVO_GPIO, pulse_width);
                log_event("Gate closed");
                last_state = 0;
            }
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        usleep(100000); // Poll every 100 ms
    }

    cleanup(0);
    return 0;
}

