        fprintf(stderr, "Failed to open I2C handle\n");
        cleanup(0);
    }

    if (i2c_read_reg8(i2c_handle, VL53L1X_MODEL_ID_REG) != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Invalid VL53L1X model ID\n");
        cleanup(0);
    }

    i2c_write_reg8(i2c_handle, VL53L1X_TIMING_BUDGET_REG, 200);
    i2c_write_reg8(i2c_handle, VL53L1X_START_RANGING_REG, 0x00);

    gpioSetMode(pi, SERVO_GPIO, PI_OUTPUT);
    gpioPWM(pi, SERVO_GPIO, pulse_width);

    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(0);
    }

    while (1) {
        if (i2c_read_reg8(i2c_handle, VL53L1X_RESULT_RANGE_STATUS) & 0x01) {
            distance = i2c_read_reg16(i2c_handle, VL53L1X_RESULT_RANGE_VAL);
            printf("Distance: %d mm\n", distance);

            if (distance < THRESHOLD_OPEN && last_state == 0) {
                pulse_width = PULSE_WIDTH_OPEN;
                gpioPWM(pi, SERVO_GPIO, pulse_width);
                log_event("Gate opened");
                last_state = 1;
            } else if (distance > THRESHOLD_CLOSE && last_state == 1) {
                pulse_width = PULSE_WIDTH_CLOSED;
                gpioPWM(pi, SERVO_GPIO, pulse_width);
                log_event("Gate closed");
                last_state = 0;
            }
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        usleep(100000); // Poll every 100 ms
    }

    cleanup(0);
    return 0;
}
