double measure_distance() {
    if (gpioTrigger(TRIGGER_PIN, PULSE_WIDTH_US, 0) < 0) {
        fprintf(stderr, "Error triggering ultrasonic sensor\n");
        return -1.0;
    }

    uint32_t start_tick = gpioTick();
    if (gpioWaitTrigger(ECHO_PIN, GPIO_WAIT_FOR_RISING_EDGE | GPIO_TIMEOUT, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge\n");
        return -1.0;
    }

    uint32_t start_us = gpioTick();
    if (gpioWaitTrigger(ECHO_PIN, GPIO_WAIT_FOR_FALLING_EDGE | GPIO_TIMEOUT, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return -1.0;
    }

    uint32_t end_us = gpioTick();
    uint32_t pulse_duration_us = end_us - start_us;

    return (pulse_duration_us * SPEED_OF_SOUND) / 2.0;
}

int map_distance_to_angle(double distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) {
        return 0;
    } else if (distance_cm > MAX_DISTANCE_CM) {
        return 180;
    } else {
        return (int)((distance_cm - MIN_DISTANCE_CM) * 180.0 / (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
    }
}

int map_angle_to_pulse_width(int angle) {
    return MIN_PULSE_WIDTH_US + (angle * (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US) / 180);
}

