    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
