        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Write to CONFIG register
        if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to write to CONFIG register\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }
        usleep(10000); // Wait 10 ms

        // Read temperature
        if (i2cWriteByteData(i2c_handle, TEMP_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to write to TEMP register\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }
        usleep(10000); // Wait 10 ms
        int temp_raw = i2cReadByteData(i2c_handle, TEMP_REG);
        if (temp_raw < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }
