            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }
        usleep(10000); // Wait 10 ms
        int humidity_raw = i2cReadByteData(i2c_handle, HUMIDITY_REG);
        if (humidity_raw < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }
        double humidity = (125.0 * humidity_raw) / 65536.0 - 6.0;

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        sleep(2);
