#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    printf("Starting MPU-6050 data logging...\n");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(1, MPU6050_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    if (i2cReadReg8(i2c_handle, WHO_AM_I) != 0x68) {
        fprintf(stderr, "MPU-6050 not found\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    i2cWriteReg8(i2c_handle, PWR_MGMT_1, 0x80); // Reset device
    usleep(100000); // Wait 100 ms for reset

    i2cWriteReg8(i2c_handle, PWR_MGMT_1, 0x01); // Clear sleep bit
    i2cWriteReg8(i2c_handle, SMPLRT_DIV, 7);    // Set sample rate divider to 7 (125 Hz)
    i2cWriteReg8(i2c_handle, ACCEL_CONFIG, 0x00); // ±2 g range
    i2cWriteReg8(i2c_handle, GYRO_CONFIG, 0x00);  // ±250 deg/s range

    while (keep_running) {
        uint8_t data[14];
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, 14, data) != 14) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gyro_x = (data[8] << 8) | data[9];
        int16_t gyro_y = (data[10] << 8) | data[11];
        int16_t gyro_z = (data[12] << 8) | data[13];

        printf("Accel: X=%d Y=%d Z=%d Temp=%d Gyro: X=%d Y=%d Z=%d\n",
               accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        usleep(100000); // Wait 100 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Shutting down MPU-6050 data logging...\n");

    return 0;
}

