#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define SHT40_HIGH_REPEATABILTY_CMD 0xFD
#define SHT40_READ_BYTES 6
#define SHT40_TEMP_RAW_OFFSET 0
#define SHT40_TEMP_CRC_OFFSET 2
#define SHT40_HUMIDITY_RAW_OFFSET 3
#define SHT40_HUMIDITY_CRC_OFFSET 5
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length, uint8_t initial) {
    uint8_t crc = initial;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sht40(int pi, int *temperature, int *humidity) {
    uint8_t buffer[SHT40_READ_BYTES];
    int result;

    // Send high repeatability command
    result = i2c_write_i2c_block_data(pi, I2C_ADDR, SHT40_HIGH_REPEATABILTY_CMD, NULL, 0);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    // Wait at least 10 ms
    usleep(10000);

    // Read 6 bytes
    result = i2c_read_i2c_block_data(pi, I2C_ADDR, NULL, buffer, SHT40_READ_BYTES);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    // Validate CRC for temperature
    uint8_t temp_crc = calculate_crc8(buffer + SHT40_TEMP_RAW_OFFSET, 2, SHT40_CRC_INIT);
    if (temp_crc != buffer[SHT40_TEMP_CRC_OFFSET]) {
        fprintf(stderr, "Temperature CRC error\n");
        return -1;
    }

    // Validate CRC for humidity
    uint8_t humidity_crc = calculate_crc8(buffer + SHT40_HUMIDITY_RAW_OFFSET, 2, SHT40_CRC_INIT);
    if (humidity_crc != buffer[SHT40_HUMIDITY_CRC_OFFSET]) {
        fprintf(stderr, "Humidity CRC error\n");
        return -1;
    }

    // Convert raw values
