#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return file;
}

int read_i2c_register(int file, uint8_t reg) {
    uint8_t buffer[1] = {reg};
    if (write(file, buffer, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }
    if (read(file, buffer, 1) != 1) {
        perror("Failed to read from the i2c bus");
        return -1;
    }
    return buffer[0];
}

int main() {
    int i2c_file = -1;
    FILE *log_file = NULL;
    struct sigaction sa;

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    if ((i2c_file = open_i2c_device(I2C_DEVICE, I2C_ADDRESS)) < 0) {
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_file);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Ambient Temperature,Object Temperature\n");

    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        int ambient_temp = read_i2c_register(i2c_file, AMBIENT_TEMP_REG);
        int object_temp = read_i2c_register(i2c_file, OBJECT_TEMP_REG);

        if (ambient_temp == -1 || object_temp == -1) {
            fprintf(stderr, "Error reading from sensor, skipping this cycle\n");
        } else {
            fprintf(log_file, "%s,%.2f,%.2f\n", time_str, ambient_temp / 16.0, object_temp / 16.0);
            fflush(log_file);
        }

        sleep(5);
    }

    if (fclose(log_file) != 0) {
        perror("Failed to close log file");
    }

    if (close(i2c_file) != 0) {
        perror("Failed to close i2c device");
    }

    return EXIT_SUCCESS;
}

