#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define TEMP_REG 0x00
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    FILE *error_log = fopen(ERROR_LOG_FILE, "a");
    if (error_log) {
        fprintf(error_log, "%s\n", message);
        fclose(error_log);
    }
}

void log_temperature(double temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "%s: %.2f°C\n", ctime(&now), temperature);
        fclose(log_file);
    }
}

int read_temperature(int pi, int fd, double *temperature) {
    unsigned char buf[2];
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        return -1;
    }

    if (i2c_read_reg8(pi, fd, TEMP_REG, &buf[0]) < 0) {
        log_error("Failed to read temperature MSB");
        return -1;
    }

    if (i2c_read_reg8(pi, fd, TEMP_REG + 1, &buf[1]) < 0) {
        log_error("Failed to read temperature LSB");
        return -1;
    }

    *temperature = ((buf[0] << 8) | buf[1]) / 16.0;
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int fd = open("/dev/i2c-" + std::to_string(I2C_BUS), O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);

    while (keep_running) {
        double temperature;
        if (read_temperature(gpioMyPigpioID(), fd, &temperature) == 0) {
            log_temperature(temperature);
        } else {
            log_error("Error reading temperature");
        }
        sleep(SAMPLE_INTERVAL);
    }

    close(fd);
    gpioTerminate();
    return 0;
}

