#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x36
#define CMD_CONTINUOUS_MEASUREMENT_VALUE 0x08
#define DATA_FRAME_SIZE 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int pi, uint8_t *data) {
    if (gpioI2CReadReg8(pi, I2C_BUS, I2C_ADDR, 0, data, DATA_FRAME_SIZE) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }
    return 0;
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioI2CSetup(pi, I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteReg8(pi, I2C_BUS, I2C_ADDR, 0, CMD_CONTINUOUS_MEASUREMENT) < 0 ||
        gpioI2CWriteReg8(pi, I2C_BUS, I2C_ADDR, 1, CMD_CONTINUOUS_MEASUREMENT_VALUE) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    usleep(1000); // Wait at least 1 ms

    FILE *file = fopen("pressure_log.csv", "a");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "Timestamp,Differential Pressure (Pa),Temperature (°C)\n");
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        uint8_t data[DATA_FRAME_SIZE];
        if (read_sensor_data(pi, data) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break;
        }

        uint8_t pressure_crc = data[2];
        uint8_t temperature_crc = data[5];
        uint8_t scale_crc = data[8];

        if (calculate_crc8(&data[0], 2) != pressure_crc ||
            calculate_crc8(&data[3], 2) != temperature_crc ||
            calculate_crc8(&data[6], 2) != scale_crc) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int16_t pressure_raw = (data[0] << 8) | data[1];
        int16_t temperature_raw = (data[3] << 8) | data[4];
        int16_t scale_factor = (data[6] << 8) | data[7];

        double pressure = pressure_raw / (double)scale_factor;
        double temperature = temperature_raw / (double)scale_factor;

        time_t now = time(NULL);
        struct tm *utc = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

        fprintf(file, "%s,%f,%f\n", timestamp, pressure, temperature);
        fflush(file);

        sleep(1);
    }

    fclose(file);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
}

