            calculate_crc8(&data[3], 2) != temperature_crc ||
            calculate_crc8(&data[6], 2) != scale_crc) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int16_t pressure_raw = (data[0] << 8) | data[1];
        int16_t temperature_raw = (data[3] << 8) | data[4];
        int16_t scale_factor = (data[6] << 8) | data[7];

        double pressure = pressure_raw / (double)scale_factor;
        double temperature = temperature_raw / (double)scale_factor;

        time_t now = time(NULL);
        struct tm *utc = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

        fprintf(file, "%s,%f,%f\n", timestamp, pressure, temperature);
        fflush(file);

        sleep(1);
    }

    fclose(file);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
