    FILE *log = fopen(LOG_FILE, "w");
    if (!log) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    fclose(log);

    while (!stop) {
        uint8_t command[1] = {MEASUREMENT_COMMAND};
        if (write(i2c_fd, command, 1) != 1) {
            log_error("Failed to write measurement command");
