#define CMD_TRIGGER_DATA 0x96
#define SAMPLE_INTERVAL_MS 100
#define RETRY_ATTEMPTS 3
#define RETRY_BACKOFF_MS 100

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signal) {
    stop_flag = 1;
}

int i2c_write_with_retry(int handle, unsigned char *data, int length) {
    int attempt = 0;
    int delay = RETRY_BACKOFF_MS;
    while (attempt < RETRY_ATTEMPTS) {
        if (i2cWriteDevice(handle, data, length) >= 0) {
            return 0;
        }
        attempt++;
        usleep(delay * 1000);
        delay *= 2;
    }
    return -1;
}

int i2c_read_with_retry(int handle, unsigned char *data, int length) {
    int attempt = 0;
    int delay = RETRY_BACKOFF_MS;
    while (attempt < RETRY_ATTEMPTS) {
        if (i2cReadDevice(handle, data, length) >= 0) {
            return 0;
        }
        attempt++;
        usleep(delay * 1000);
        delay *= 2;
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("airflow.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char trigger_cmd[] = {CMD_TRIGGER, CMD_TRIGGER_DATA};
    unsigned char read_data[6];

    while (!stop_flag) {
        if (i2c_write_with_retry(i2c_handle, trigger_cmd, sizeof(trigger_cmd)) < 0) {
            fprintf(stderr, "Failed to write trigger command\n");
            break;
        }

        usleep(1000); // Wait at least 1 ms

        if (i2c_read_with_retry(i2c_handle, read_data, sizeof(read_data)) < 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        int raw_pressure = (read_data[0] << 8) | read_data[1];
        int raw_temperature = (read_data[3] << 8) | read_data[4];

        double pressure_pa = raw_pressure / 60.0;
        double temperature_c = raw_temperature / 200.0;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%f,%f\n", timestamp, pressure_pa, temperature_c);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

