#include <pigpio.h>

#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define I2C_BUS 1
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 100

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

double read_sensor(int i2c_handle, uint8_t command) {
    uint8_t buffer[2];
    int retries = 0;
    int err;

    // Write command
    err = i2c_write_i2c_block_data(i2c_handle, SI7015_ADDR, &command, 1);
    if (err < 0) {
        fprintf(stderr, "I2C write error: %s\n", pierror(err));
        return -1;
    }

    // Poll for measurement ready
    while (retries < MAX_RETRIES) {
        err = i2c_read_i2c_block_data(i2c_handle, SI7015_ADDR, buffer, 2);
        if (err == 2) {
            uint16_t raw = (buffer[0] << 8) | buffer[1];
            return raw;
        } else if (err < 0) {
            fprintf(stderr, "I2C read error: %s\n", pierror(err));
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
        } else {
            usleep(10000); // Poll every 10 ms
        }
    }

    fprintf(stderr, "I2C read failed after retries\n");
    return -1;
}

double convert_temperature(uint16_t raw) {
    return (175.72 * raw / 65536.0) - 46.85;
}

double convert_humidity(uint16_t raw) {
    double humidity = (125.0 * raw / 65536.0) - 6.0;
    return (humidity < 0) ? 0 : (humidity > 100) ? 100 : humidity;
}

void log_and_print(double temperature, double humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("[%s] Temperature: %.2f°C, Humidity: %.2f%%RH\n", timestamp, temperature, humidity);

    FILE *file = fopen("sensor_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "[%s] Temperature: %.2f°C, Humidity: %.2f%%RH\n", timestamp, temperature, humidity);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pierror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pierror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("sensor_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fclose(file);

    while (keep_running) {
        uint16_t temp_raw = read_sensor(i2c_handle, TEMP_CMD);
        if (temp_raw < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            break;
        }
        double temperature = convert_temperature(temp_raw);

        uint16_t humid_raw = read_sensor(i2c_handle, HUMID_CMD);
        if (humid_raw < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            break;
        }
        double humidity = convert_humidity(humid_raw);

        log_and_print(temperature, humidity);
        sleep(5);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

