#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x25
#define CMD_TRIGGER_MEASUREMENT 0x362F
#define DATA_LENGTH 9
#define LOG_FILE "airflow_data.txt"
#define MEASUREMENT_INTERVAL 100000 // 100 ms in microseconds
#define WAIT_TIME 45000 // 45 ms in microseconds

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int fd, uint8_t *buffer) {
    if (write(fd, &CMD_TRIGGER_MEASUREMENT, 2) != 2) {
        perror("Failed to write trigger command");
        return -1;
    }
    usleep(WAIT_TIME);

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

