    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temperature, humidity);
        fclose(log_file);
    }
}

