uint8_t calculate_crc8(uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct timespec ts;

    signal(SIGINT, handle_sigint);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("airflow_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t write_buf[1] = {CONTINUOUS_MEASUREMENT_CMD};
        if (write(i2c_fd, write_buf, 1) != 1) {
            perror("Failed to write to I2C device");
            break;
        }

        usleep(1000); // Wait at least 1 ms

        uint8_t read_buf[RESPONSE_LENGTH];
        if (read(i2c_fd, read_buf, RESPONSE_LENGTH) != RESPONSE_LENGTH) {
            perror("Failed to read from I2C device");
            break;
        }

        uint8_t pressure_crc = calculate_crc8(read_buf, 2);
        uint8_t temperature_crc = calculate_crc8(read_buf + 3, 2);

        if (pressure_crc != read_buf[2] || temperature_crc != read_buf[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int16_t raw_pressure = (read_buf[0] << 8) | read_buf[1];
        int16_t raw_temperature = (read_buf[3] << 8) | read_buf[4];

        double pressure_pa = raw_pressure / SCALE_FACTOR_PRESSURE;
        double temperature_c = raw_temperature / SCALE_FACTOR_TEMPERATURE + TEMPERATURE_OFFSET;

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Failed to get timestamp");
            break;
        }

        fprintf(log_file, "%ld.%09ld,%f,%f\n", ts.tv_sec, ts.tv_nsec, pressure_pa, temperature_c);
        fflush(log_file);

        usleep(100000); // Sample every 100 ms
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}
