        if (i2cWriteReg8(fd, 0, cmd) < 0) {
            fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
            i2cClose(fd);
            continue;
        }

        pi_sleep(10); // Wait at least 10 ms

        uint8_t data[2];
        if (i2cReadReg8s(fd, 0, data, 2) < 0) {
            fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
            i2cClose(fd);
            continue;
        }

        i2cClose(fd);

        uint16_t raw = (data[0] << 8) | data[1];
        *value = (cmd == TEMP_CMD) ? (175.72 * raw / 65536.0 - 46.85) : (125.0 * raw / 65536.0 - 6.0);
        return 0;
    }

    fprintf(stderr, "Failed to read sensor after 3 attempts\n");
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    setup_signal_handler();
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    SensorData buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int fan_state = 0;

    while (keep_running) {
        float temperature, humidity;
        if (read_sensor(TEMP_CMD, &temperature) == 0 && read_sensor(HUMID_CMD, &humidity) == 0) {
            time(&buffer[buffer_index].timestamp);
            buffer[buffer_index].temperature = temperature;
            buffer[buffer_index].humidity = humidity;

            printf("Timestamp: %ld, Temperature: %.2f°C, Humidity: %.2f%%\n",
                   buffer[buffer_index].timestamp, temperature, humidity);

            if (temperature > TEMP_THRESHOLD_HIGH && fan_state == 0) {
                gpioWrite(FAN_GPIO, 1);
                fan_state = 1;
            } else if (temperature < TEMP_THRESHOLD_LOW && fan_state == 1) {
                gpioWrite(FAN_GPIO, 0);
                fan_state = 0;
            }

            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        } else {
            fprintf(stderr, "Sensor read error, retrying...\n");
        }

        pi_sleep(2000);
    }

    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
    return 0;
}

