volatile sig_atomic_t stop_requested = 0;

void handle_sigint(int sig) {
    stop_requested = 1;
}

uint8_t crc8(uint16_t data, uint8_t crc) {
    for (int i = 0; i < 16; i++) {
        if ((data ^ crc) & 0x80) {
            crc = (crc << 1) ^ POLYNOMIAL;
        } else {
            crc <<= 1;
        }
        data <<= 1;
    }
    return crc;
}

int check_crc(uint8_t *data, int length) {
    for (int i = 0; i < length; i += 2) {
        uint16_t word = (data[i] << 8) | data[i + 1];
        uint8_t crc = crc8(word, INIT_CRC);
        if (crc != data[i + 2]) {
            return 0;
        }
    }
    return 1;
}

