uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(SensorData *data) {
    uint8_t command[2] = {0xEC, 0x05};
    uint8_t response[9];
    uint8_t status_command[2] = {0xE4, 0xB8};
    uint8_t status_response[2];
    int retries = 10;

    while (retries-- > 0) {
        if (i2c_write_i2c_block_data(i2c_handle, I2C_ADDR, status_command, 2) < 0) {
            perror("Failed to write status command");
            return -1;
        }

        if (i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, status_response, 2) < 0) {
            perror("Failed to read status response");
            return -1;
        }

        if (status_response[1] & 0x01) {
            break;
        }
        usleep(100000); // 100 ms
    }

    if (retries <= 0) {
        fprintf(stderr, "Sensor data not ready\n");
        return -1;
    }

    if (i2c_write_i2c_block_data(i2c_handle, I2C_ADDR, command, 2) < 0) {
        perror("Failed to write read command");
        return -1;
    }

    if (i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, response, 9) < 0) {
        perror("Failed to read sensor data");
        return -1;
    }

    uint8_t crc1 = crc8(response, 2);
    if (crc1 != response[2]) {
        fprintf(stderr, "CRC error in CO2 data\n");
        return -1;
    }
    data->co2 = (response[0] << 8) | response[1];

    uint8_t crc2 = crc8(response + 3, 2);
    if (crc2 != response[5]) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }
    data->temperature = (response[3] << 8 | response[4]) / 16.0;

    uint8_t crc3 = crc8(response + 6, 2);
    if (crc3 != response[8]) {
        fprintf(stderr, "CRC error in humidity data\n");
        return -1;
    }
    data->humidity = (response[6] << 8 | response[7]) / 1024.0;

    return 0;
}

void log_data(SensorData data) {
    buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void print_data(SensorData data) {
    printf("CO2: %u ppm, Temperature: %.2f C, Humidity: %.2f %%\n",
           data.co2, data.temperature, data.humidity);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x21, 0xB1, 0) < 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        SensorData data;
        if (read_sensor_data(&data) == 0) {
            log_data(data);
            print_data(data);
            gpioWrite(LED_PIN, data.co2 > 1000 ? PI_HIGH : PI_LOW);
        }
        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x3F, 0x86, 0) < 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}
