#define SAMPLE_INTERVAL 5
#define MAX_FAILURES 3

volatile sig_atomic_t keep_running = 1;
FILE *log_file = NULL;
int consecutive_failures = 0;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (temperature < -40 || temperature > 150) {
        fprintf(log_file, "%s ERROR: Temperature out of range: %.2f°C\n", timestamp, temperature);
    } else {
        fprintf(log_file, "%s %.2f°C\n", timestamp, temperature);
    }
    fflush(log_file);
}

void log_sensor_malfunction() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s SENSOR MALFUNCTION\n", timestamp);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((log_file = fopen("temperature_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        unsigned long start_tick = gpioTick();
        unsigned long th = 0, tl = 0;
        int edge = 0;

        // Wait for the first edge
        if (gpioWait(TMP05_GPIO, GPIO_EDGE_FALLING | GPIO_EDGE_RISING, TIMEOUT_US) < 0) {
            consecutive_failures++;
            if (consecutive_failures >= MAX_FAILURES) {
                log_sensor_malfunction();
                consecutive_failures = 0;
            }
            continue;
        }

        // Measure TH
        edge = gpioWait(TMP05_GPIO, GPIO_EDGE_RISING, TIMEOUT_US);
        if (edge < 0) {
            consecutive_failures++;
            if (consecutive_failures >= MAX_FAILURES) {
                log_sensor_malfunction();
                consecutive_failures = 0;
            }
            continue;
        }
        th = gpioTick() - start_tick;

        // Measure TL
        edge = gpioWait(TMP05_GPIO, GPIO_EDGE_FALLING, TIMEOUT_US);
        if (edge < 0) {
            consecutive_failures++;
            if (consecutive_failures >= MAX_FAILURES) {
                log_sensor_malfunction();
                consecutive_failures = 0;
            }
            continue;
        }
        tl = gpioTick() - start_tick;

        if (tl == 0) {
            consecutive_failures++;
            if (consecutive_failures >= MAX_FAILURES) {
                log_sensor_malfunction();
                consecutive_failures = 0;
            }
            continue;
        }

        double temperature = 4215.0 - (2143.0 * th / tl);
        log_temperature(temperature);
        consecutive_failures = 0;

        usleep(SAMPLE_INTERVAL * 1000000);
    }

    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

