#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define MEASUREMENT_INTERVAL 1

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc8(const uint8_t *data, size_t length) {
    if (length < 2) return 0;
    uint8_t crc = calculate_crc8(data, length - 1);
    return crc == data[length - 1];
}

void log_data(FILE *file, double pressure, double temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            pressure, temperature);
    fflush(file);
}

int main() {
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *file = fopen("airflow.csv", "a");
    if (!file) {
        perror("Failed to open file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        uint8_t cmd[1] = {CMD_CONTINUOUS_MEASUREMENT};
        if (write(i2c_fd, cmd, 1) != 1) {
            perror("Failed to write to I2C bus");
            break;
        }

        usleep(45000); // Wait for conversion time

        uint8_t buffer[9];
        if (read(i2c_fd, buffer, 9) != 9) {
            perror("Failed to read from I2C bus");
            break;
        }

        if (!validate_crc8(buffer, 3) || !validate_crc8(buffer + 3, 3) || !validate_crc8(buffer + 6, 3)) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int32_t pressure_raw = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        int32_t temperature_raw = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
        int32_t scale_factor_raw = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

        double pressure = pressure_raw * 0.0001; // Convert to Pa
        double temperature = temperature_raw * 0.01; // Convert to °C

        log_data(file, pressure, temperature);

        sleep(MEASUREMENT_INTERVAL);
    }

    fclose(file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

