#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL 5

static int i2c_handle = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_reading(double temperature, double humidity) {
    FILE *file = fopen("environment.csv", "a+");
    if (!file) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }

    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "timestamp,temperature_c,humidity_pct\n");
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(file);
}

void read_sensor() {
    uint8_t buffer[6];
    if (i2c_write_i2c_block_data(i2c_handle, I2C_ADDR, (uint8_t *)&MEASUREMENT_CMD, 2) < 0) {
        fprintf(stderr, "Error writing to I2C bus\n");
        return;
    }

    usleep(15000); // Wait at least 15 ms

    if (i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, buffer, 6) < 0) {
        fprintf(stderr, "Error reading from I2C bus\n");
        return;
    }

    uint8_t temp_crc = calculate_crc8(buffer, 2);
    uint8_t hum_crc = calculate_crc8(buffer + 3, 2);

    if (temp_crc != buffer[2] || hum_crc != buffer[5]) {
        fprintf(stderr, "CRC check failed\n");
        return;
    }

    int16_t raw_temp = (buffer[0] << 8) | buffer[1];
    int16_t raw_hum = (buffer[3] << 8) | buffer[4];

    double temperature = -45 + 175 * raw_temp / 65535.0;
    double humidity = 100 * raw_hum / 65535.0;

    log_reading(temperature, humidity);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
