    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        read_sensor();
        sleep(SAMPLE_INTERVAL);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

