#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x40
#define SI7021_MEASURE_NOHOLD_HUMIDITY 0xF5
#define SI7021_MEASURE_NOHOLD_TEMPERATURE 0xF3
#define SI7021_MEASURE_NOHOLD_TEMPERATURE_RH 0xE0
#define SI7021_RESET 0xFE
#define TIMEOUT_MS 100
#define POLL_INTERVAL_MS 10
#define LOG_INTERVAL_SEC 5

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

double read_sensor(int fd, uint8_t command) {
    uint8_t buffer[3];
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    if (write(fd, &command, 1) != 1) {
        perror("Failed to write command");
        return -1;
    }

    while (keep_running) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if ((now.tv_sec - start.tv_sec) * 1000 + (now.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for sensor data\n");
            return -1;
        }

        ssize_t n = read(fd, buffer, sizeof(buffer));
        if (n == 3) {
            if (crc8(buffer, 2) == buffer[2]) {
                return (buffer[0] << 8 | buffer[1]) / 65536.0;
            } else {
                fprintf(stderr, "CRC error\n");
                return -1;
            }
        } else if (n < 0 && errno != EAGAIN) {
            perror("Failed to read sensor data");
            return -1;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return -1;
}

void log_data(FILE *log_file, double temperature, double humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (temperature < 0 || humidity < 0) {
        fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    }
}

int main() {
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("environment.log", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");

    double temperature = 0, humidity = 0;
    while (keep_running) {
        if (write(i2c_fd, &SI7021_MEASURE_NOHOLD_HUMIDITY, 1) != 1) {
            perror("Failed to write humidity command");
            break;
        }

        humidity = 125.0 * read_sensor(i2c_fd, SI7021_MEASURE_NOHOLD_TEMPERATURE_RH) - 6.0;
        if (humidity < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            if (write(i2c_fd, &SI7021_RESET, 1) != 1) {
                perror("Failed to reset sensor");
            }
            continue;
        }

        if (write(i2c_fd, &SI7021_MEASURE_NOHOLD_TEMPERATURE, 1) != 1) {
            perror("Failed to write temperature command");
            break;
        }

        temperature = 175.72 * read_sensor(i2c_fd, 0x00) - 46.85;
        if (temperature < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            if (write(i2c_fd, &SI7021_RESET, 1) != 1) {
                perror("Failed to reset sensor");
            }
            continue;
        }

        log_data(log_file, temperature, humidity);
        fflush(log_file);
        sleep(LOG_INTERVAL_SEC);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

