#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define SAMPLE_INTERVAL 1

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("airflow.dat", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        fclose(file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2cWriteByteData(i2c_handle, CMD_CONTINUOUS_MEASUREMENT, 0x00) < 0) {
            fprintf(stderr, "Failed to write measurement command\n");
            break;
        }

        usleep(100000); // Wait for conversion time (100ms)

        unsigned char buffer[9];
        if (i2cRead(i2c_handle, buffer, 9) != 9) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break;
        }

        // Validate CRC-8 for pressure
        unsigned char pressure_crc = buffer[2];
        unsigned char pressure_raw = (buffer[0] << 8) | buffer[1];
        if (pressure_crc != crc8(buffer, 2)) {
            fprintf(stderr, "Pressure CRC check failed\n");
            continue;
        }

        // Validate CRC-8 for temperature
        unsigned char temp_crc = buffer[5];
        unsigned char temp_raw = (buffer[3] << 8) | buffer[4];
        if (temp_crc != crc8(buffer + 3, 2)) {
            fprintf(stderr, "Temperature CRC check failed\n");
            continue;
        }

        // Calculate scale factor
        unsigned int scale_factor = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

        // Convert pressure and temperature
        float pressure = (pressure_raw / (float)scale_factor) - 1000.0f;
        float temperature = (temp_raw / 200.0f) - 45.0f;

        // Write to file
        if (fwrite(&pressure, sizeof(float), 1, file) != 1 ||
            fwrite(&temperature, sizeof(float), 1, file) != 1) {
            fprintf(stderr, "Failed to write to file\n");
            break;
        }

        usleep(1000000); // Sample once per second
    }

    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

unsigned char crc8(const unsigned char *data, size_t length) {
    unsigned char crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (unsigned char j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}
