#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_MEASURE 0x3603
#define SCALE_FACTOR 60.0
#define LOG_INTERVAL 5

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int crc8(const uint8_t *data, size_t length, uint8_t polynomial) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_pressure() {
    uint8_t buffer[9];
    int result = i2c_write_i2c_block_data(i2c_handle, CMD_MEASURE, 2);
    if (result != 2) {
        fprintf(stderr, "I2C write error: %d\n", result);
        return -1;
    }

    usleep(45000); // Wait for conversion time

    result = i2c_read_i2c_block_data(i2c_handle, 0, 9);
    if (result != 9) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }

    uint8_t crc1 = crc8(buffer, 2, 0x31);
    uint8_t crc2 = crc8(buffer + 2, 2, 0x31);
    uint8_t crc3 = crc8(buffer + 4, 2, 0x31);

    if (buffer[2] != crc1 || buffer[4] != crc2 || buffer[6] != crc3) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    int32_t pressure_raw = (buffer[0] << 8) | buffer[1];
    double pressure_pa = pressure_raw * SCALE_FACTOR;
    return pressure_pa;
}

void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d - Pressure: %.2f Pa\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, pressure);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        double pressure = read_pressure();
        if (pressure >= 0) {
            log_pressure(pressure);
        }
        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

