#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define PWM_PIN 18
#define PWM_FREQUENCY 25000
#define SAMPLE_INTERVAL 100
#define LOG_FILE "flow_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_sensor(int i2c_handle) {
    unsigned char buf[2];
    int res = i2c_read(i2c_handle, I2C_ADDR, buf, 2);
    if (res < 0) {
        fprintf(stderr, "I2C read error: %s\n", pi_strerror(res));
        return -1;
    }
    if (res != 2) {
        fprintf(stderr, "Unexpected I2C read length: %d\n", res);
        return -1;
    }
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return (raw_value & 0x3FFF) >> 2; // Mask off status bits and shift
}

double convert_to_slpm(int raw_value) {
    if (raw_value < 1638) return 0.0;
    if (raw_value > 14745) return 10.0;
    return (raw_value - 1638) * 10.0 / (14745 - 1638);
}

void setup_pwm() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioPWMfrequency(PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup(int i2c_handle, FILE *log_file) {
    gpioPWM(PWM_PIN, 0); // Turn off the fan
    gpioTerminate();
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_pwm();

    int i2c_handle = i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pi_strerror(i2c_handle));
        cleanup(i2c_handle, NULL);
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(i2c_handle, NULL);
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        int raw_value = read_sensor(i2c_handle);
        if (raw_value < 0) {
            continue; // Skip this iteration on I2C error
        }

        double slpm = convert_to_slpm(raw_value);
        int duty_cycle = (int)(slpm * 100); // Scale to 0-100%

        gpioPWM(PWM_PIN, duty_cycle);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%d\n", timestamp, raw_value);
        fflush(log_file);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup(i2c_handle, log_file);
    return 0;
}

