#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5D
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xB1
#define CTRL_REG1 0x10
#define CTRL_REG1_VALUE 0xB0
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

volatile sig_atomic_t stop_flag = 0;

void handle_sigint(int sig) {
    stop_flag = 1;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm;
    localtime_r(&now, &tm);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(stderr, "[%s] %s\n", timestamp, message);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cReadReg8(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0 || who_am_i != WHO_AM_I_VALUE) {
        log_error("WHO_AM_I register check failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg8(i2c_handle, CTRL_REG1, CTRL_REG1_VALUE) < 0) {
        log_error("Failed to write to CTRL_REG1");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop_flag) {
        int32_t pressure_raw = 0;
        int16_t temperature_raw = 0;

        uint8_t pressure_data[3];
        if (i2cReadReg8s(i2c_handle, PRESS_OUT_XL, pressure_data, 3) < 0) {
            log_error("Failed to read pressure data");
        } else {
            pressure_raw = (int32_t)pressure_data[0] | ((int32_t)pressure_data[1] << 8) | ((int32_t)pressure_data[2] << 16);
            if (pressure_raw & 0x800000) {
                pressure_raw |= 0xFF000000; // Sign extend
            }
            double pressure_hpa = pressure_raw / 4096.0;

            uint8_t temp_data[2];
            if (i2cReadReg8s(i2c_handle, TEMP_OUT_L, temp_data, 2) < 0) {
                log_error("Failed to read temperature data");
            } else {
                temperature_raw = (int16_t)temp_data[0] | ((int16_t)temp_data[1] << 8);
                if (temperature_raw & 0x8000) {
                    temperature_raw |= 0xFFFF0000; // Sign extend
                }
                double temperature_c = 42.5 + temperature_raw / 480.0;

                time_t now = time(NULL);
                struct tm tm;
                localtime_r(&now, &tm);

                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

                fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure_hpa, temperature_c);
                fflush(log_file);
            }
        }

        gpioDelay(1000000); // Delay for 1 second
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

