        int16_t temperature_raw = 0;

        uint8_t pressure_data[3];
        if (i2cReadReg8s(i2c_handle, PRESS_OUT_XL, pressure_data, 3) < 0) {
            log_error("Failed to read pressure data");
        } else {
            pressure_raw = (int32_t)pressure_data[0] | ((int32_t)pressure_data[1] << 8) | ((int32_t)pressure_data[2] << 16);
            if (pressure_raw & 0x800000) {
                pressure_raw |= 0xFF000000; // Sign extend
            }
            double pressure_hpa = pressure_raw / 4096.0;

            uint8_t temp_data[2];
            if (i2cReadReg8s(i2c_handle, TEMP_OUT_L, temp_data, 2) < 0) {
                log_error("Failed to read temperature data");
            } else {
                temperature_raw = (int16_t)temp_data[0] | ((int16_t)temp_data[1] << 8);
                if (temperature_raw & 0x8000) {
                    temperature_raw |= 0xFFFF0000; // Sign extend
                }
                double temperature_c = 42.5 + temperature_raw / 480.0;

                time_t now = time(NULL);
                struct tm tm;
                localtime_r(&now, &tm);

                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

                fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure_hpa, temperature_c);
                fflush(log_file);
            }
        }

        gpioDelay(1000000); // Delay for 1 second
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}
