#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SCD30_ADDRESS 0x61
#define CMD_DATA_READY 0x0202
#define CMD_MEASUREMENT 0x0300
#define CMD_MEASUREMENT_INTERVAL 0x2003
#define CMD_AMBIENT_PRESSURE_COMPENSATION 0x2004
#define LOG_FILE "air_quality.log"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int write_i2c_with_crc(int i2c_handle, uint8_t command, const uint8_t *data, size_t length) {
    uint8_t buffer[length + 2];
    buffer[0] = command >> 8;
    buffer[1] = command & 0xFF;
    memcpy(buffer + 2, data, length);
    buffer[length + 2] = calculate_crc8(buffer, length + 2);
    return i2cWriteDevice(i2c_handle, buffer, length + 3);
}

int read_i2c_with_crc(int i2c_handle, uint8_t command, uint8_t *data, size_t length) {
    uint8_t buffer[3];
    buffer[0] = command >> 8;
    buffer[1] = command & 0xFF;
    buffer[2] = calculate_crc8(buffer, 2);
    if (i2cWriteDevice(i2c_handle, buffer, 3) < 0) {
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, length + 6) < 0) {
        return -1;
    }
    if (calculate_crc8(data, length) != data[length] ||
        calculate_crc8(data + length + 1, length) != data[length + length + 2]) {
        return -1;
    }
    return 0;
}

void log_error(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "%s,ERROR,%s\n", timestamp, message);
        fclose(log_file);
    }
}

void log_data(double co2, double temperature, double humidity) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "%s,CO2,%f,Temperature,%f,Humidity,%f\n", timestamp, co2, temperature, humidity);
        fflush(log_file);
        fclose(log_file);
    }
}

void control_ventilation(double co2) {
    if (co2 < 800) {
        printf("Ventilation: OFF\n");
    } else if (co2 < 1200) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 0;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_handle = i2cOpen(I2C_BUS, SCD30_ADDRESS);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 0;
    }

    uint8_t interval_data[4] = {0x00, 0x00, 0x00, 0x07}; // 2 seconds
    if (write_i2c_with_crc(i2c_handle, CMD_MEASUREMENT_INTERVAL, interval_data, 4) < 0) {
        log_error("Failed to set measurement interval");
    }

    uint8_t compensation_data[4] = {0x00, 0x00, 0x00, 0x00}; // Disable compensation
    if (write_i2c_with_crc(i2c_handle, CMD_AMBIENT_PRESSURE_COMPENSATION, compensation_data, 4) < 0) {
        log_error("Failed to set ambient pressure compensation");
    }

    while (keep_running) {
        uint8_t data_ready;
        if (read_i2c_with_crc(i2c_handle, CMD_DATA_READY, &data_ready, 1) < 0) {
            log_error("Failed to read data-ready flag");
            continue;
        }

        if (data_ready & 0x01) {
            uint8_t measurement_data[18];
            if (read_i2c_with_crc(i2c_handle, CMD_MEASUREMENT, measurement_data, 18) < 0) {
                log_error("Failed to read measurement data");
                continue;
            }

            double co2 = (measurement_data[0] << 16 | measurement_data[1] << 8 | measurement_data[2]) / 1000.0;
            double temperature = (measurement_data[4] << 16 | measurement_data[5] << 8 | measurement_data[6]) / 1000.0;
            double humidity = (measurement_data[8] << 16 | measurement_data[9] << 8 | measurement_data[10]) / 1000.0;

            log_data(co2, temperature, humidity);
            control_ventilation(co2);
        }

        usleep(1000000); // Sleep for 1 second
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

