#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x21
#define CMD_START_MEASUREMENT 0x36
#define CMD_START_MEASUREMENT_CONTINUOUS 0x2F
#define SAMPLE_INTERVAL_DEFAULT 1000

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int pi, uint16_t *pressure, int16_t *temperature, uint16_t *scale_factor) {
    uint8_t buffer[9];
    if (i2c_read_i2c_block_data(pi, I2C_ADDR, 0, buffer, 9) != 9) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }

    uint8_t pressure_crc = buffer[2];
    uint8_t temperature_crc = buffer[5];
    uint8_t scale_factor_crc = buffer[8];

    if (crc8(&buffer[0], 2) != pressure_crc ||
        crc8(&buffer[3], 2) != temperature_crc ||
        crc8(&buffer[6], 2) != scale_factor_crc) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8) | buffer[4];
    *scale_factor = (buffer[6] << 8) | buffer[7];

    return 0;
}

int main(int argc, char *argv[]) {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        pigpio_stop(pi);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sample_interval = SAMPLE_INTERVAL_DEFAULT;
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
    }

    if (i2c_open(pi, I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_stop(pi);
        return 1;
    }

    if (i2c_write_i2c_block_data(pi, I2C_ADDR, CMD_START_MEASUREMENT, (uint8_t[]){CMD_START_MEASUREMENT_CONTINUOUS}, 1) < 0) {
        fprintf(stderr, "Failed to start sensor measurement\n");
        i2c_close(pi);
        pigpio_stop(pi);
        return 1;
    }

    while (keep_running) {
        uint16_t pressure;
        int16_t temperature;
        uint16_t scale_factor;

        if (read_sensor_data(pi, &pressure, &temperature, &scale_factor) == 0) {
            double pressure_pa = (double)pressure / scale_factor;
            printf("%ld: Pressure: %.2f Pa, Temperature: %d C\n", time(NULL), pressure_pa, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        usleep(sample_interval * 1000);
    }

    i2c_close(pi);
    pigpio_stop(pi);
    return 0;
}

