#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x3615
#define I2C_SDA 2
#define I2C_SCL 3
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define MEASUREMENT_INTERVAL 1000 // 1 second

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int i2c_handle, uint8_t *buffer, size_t length) {
    if (i2c_read(i2c_handle, buffer, length) != length) {
        fprintf(stderr, "Error reading from sensor\n");
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t command[2] = {CMD_CONTINUOUS_MEASUREMENT >> 8, CMD_CONTINUOUS_MEASUREMENT & 0xFF};
    if (i2cWrite(i2c_handle, command, 2) != 2) {
        fprintf(stderr, "Failed to write command to sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        usleep(45000); // Wait at least 45 ms

        uint8_t buffer[9];
        if (read_sensor_data(i2c_handle, buffer, 9) != 0) {
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        for (int i = 0; i < 3; i++) {
            uint8_t data[3] = {buffer[i * 3], buffer[i * 3 + 1], buffer[i * 3 + 2]};
            uint8_t crc = crc8(data, 2);
            if (crc != data[2]) {
                fprintf(stderr, "CRC mismatch for data word %d\n", i);
                continue;
            }
        }

        int32_t raw_pressure = (int32_t)buffer[0] << 16 | (int32_t)buffer[1] << 8 | buffer[2];
        int32_t scale_factor_pressure = (int32_t)buffer[3] << 16 | (int32_t)buffer[4] << 8 | buffer[5];
        int32_t raw_temperature = (int32_t)buffer[6] << 16 | (int32_t)buffer[7] << 8 | buffer[8];

        double pressure = raw_pressure / (double)scale_factor_pressure;
        double temperature = raw_temperature / 200.0;

        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);

        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

