#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HDC1000_ADDRESS 0x40
#define CONFIG_REGISTER 0x02
#define TEMP_REGISTER 0x00
#define CONFIGURATION_MASK 0x1000
#define CONFIGURATION_VALUE 0x1000
#define SAMPLE_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_fd;
    uint8_t buffer[4];
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure the sensor
    buffer[0] = CONFIG_REGISTER;
    buffer[1] = CONFIGURATION_VALUE;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to configuration register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Write to temperature register to start conversion
        buffer[0] = TEMP_REGISTER;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to temperature register");
            continue;
        }

        // Wait for conversion to complete
        usleep(20000);

        // Read temperature and humidity
        buffer[0] = TEMP_REGISTER;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to temperature register for read");
            continue;
        }

        if (read(i2c_fd, buffer, 4) != 4) {
            perror("Failed to read temperature and humidity");
            continue;
        }

        // Convert raw values
        int16_t raw_temp = (buffer[0] << 8) | buffer[1];
        int16_t raw_humidity = (buffer[2] << 8) | buffer[3];

        float temperature = (raw_temp / 65536.0) * 165.0 - 40.0;
        float humidity = (raw_humidity / 65536.0) * 100.0;

        // Log readings
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

