    keep_running = 0;
}

int read_temperature(int pi, int *temperature) {
    unsigned char buffer[2];
    int err;

    // Send temperature measurement command
    err = pi_i2c_write_byte_data(pi, SI7051_ADDRESS, SI7051_TEMP_MEASURE_NO_HOLD);
    if (err < 0) {
        fprintf(stderr, "Error writing to Si7051: %s\n", pi_error(err));
        return -1;
    }

    // Wait for the measurement to complete
    usleep(50000); // 50ms

    // Read the temperature data
    err = pi_i2c_read_i2c_block_data(pi, SI7051_ADDRESS, 0, buffer, 2);
    if (err < 0) {
        fprintf(stderr, "Error reading from Si7051: %s\n", pi_error(err));
        return -1;
    }

    // Convert the data to temperature
    int raw_temp = (buffer[0] << 8) | buffer[1];
    *temperature = (((175.72 * raw_temp) / 65536.0) - 46.85);

    return 0;
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Unable to start pigpio: %s\n", pi_error(pi));
        return EXIT_FAILURE;
    }

    if (pi_i2c_open(pi, 1) < 0) {
