#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define MLX90833_REG_PRESSURE 0x00
#define MLX90833_REG_CONFIG 0x01
#define MLX90833_CONFIG_MODE 0x80
#define MLX90833_CONFIG_RESET 0x40
#define MLX90833_CONFIG_ENABLE 0x20
#define MLX90833_CONFIG_POLARITY 0x10
#define MLX90833_CONFIG_FILTER 0x08
#define MLX90833_CONFIG_OSR 0x04
#define MLX90833_CONFIG_DRDY 0x02
#define MLX90833_CONFIG_DRDY_POLARITY 0x01

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioI2CSetup(I2C_BUS, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure the sensor
    uint8_t config = MLX90833_CONFIG_MODE | MLX90833_CONFIG_ENABLE | MLX90833_CONFIG_POLARITY | MLX90833_CONFIG_FILTER | MLX90833_CONFIG_OSR | MLX90833_CONFIG_DRDY | MLX90833_CONFIG_DRDY_POLARITY;
    if (gpioI2CWriteByte(I2C_BUS, I2C_ADDRESS, MLX90833_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to write to sensor configuration register\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t pressure_raw;
        if (gpioI2CReadWord(I2C_BUS, I2C_ADDRESS, MLX90833_REG_PRESSURE, &pressure_raw) < 0) {
            fprintf(stderr, "Failed to read pressure value\n");
            break;
        }

        // Convert raw value to pressure in mbar
        float pressure = (pressure_raw * 0.001) - 500.0;

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Log the reading
        printf("%02d:%02d:%02d - Pressure: %.2f mbar\n", timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, pressure);

        // Sleep for 500 ms
        usleep(500000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

