#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x60
#define MSB_REGISTER 0xAA
#define LSB_REGISTER 0xAB
#define SCALING_FACTOR 0.1

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd;
    uint8_t msb, lsb;
    uint16_t raw_pressure;
    double pressure_kpa;
    struct timespec ts;

    // Install signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Trigger measurement
        if (i2c_write(i2c_fd, 0x00, 0x00) < 0) {
            fprintf(stderr, "Error triggering measurement\n");
            continue;
        }

        // Read MSB
        if (i2c_read(i2c_fd, MSB_REGISTER, &msb) < 0) {
            fprintf(stderr, "Error reading MSB\n");
            continue;
        }

        // Read LSB
        if (i2c_read(i2c_fd, LSB_REGISTER, &lsb) < 0) {
            fprintf(stderr, "Error reading LSB\n");
            continue;
        }

        // Combine MSB and LSB
        raw_pressure = (msb << 8) | lsb;

        // Convert to kPa
        pressure_kpa = raw_pressure * SCALING_FACTOR;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log reading with timestamp
        printf("%ld.%09ld: Pressure = %.2f kPa\n", ts.tv_sec, ts.tv_nsec, pressure_kpa);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

