#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define PRESSURE_DIVISOR 60.0
#define TEMPERATURE_DIVISOR 200.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int fd, uint8_t *buffer, size_t length) {
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write command to I2C device");
        return -1;
    }
    usleep(45000); // Wait 45 ms

    if (read(fd, buffer, length) != length) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t buffer[9];
    buffer[0] = CMD_CONTINUOUS_MEASUREMENT;

    while (keep_running) {
        if (read_sensor(i2c_fd, buffer, sizeof(buffer)) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            continue;
        }

        uint8_t pressure_raw = (buffer[1] << 8) | buffer[2];
        uint8_t pressure_crc = buffer[3];
        uint8_t temperature_raw = (buffer[4] << 8) | buffer[5];
        uint8_t temperature_crc = buffer[6];

        if (calculate_crc8(buffer + 1, 2) != pressure_crc ||
            calculate_crc8(buffer + 4, 2) != temperature_crc) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        double pressure = pressure_raw / PRESSURE_DIVISOR;
        double temperature = temperature_raw / TEMPERATURE_DIVISOR;

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%.2f\n", time_str, pressure, temperature);
        fflush(log_file);

        usleep(100000); // Sleep for 100 ms
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

