#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x36, 0x2F
#define DATA_LENGTH 3
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MEASUREMENT_DELAY_MS 8
#define CSV_FILENAME "airflow_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_pressure(int pi, int *pressure) {
    uint8_t buffer[DATA_LENGTH];
    int err;

    // Trigger continuous measurement
    err = i2c_write_i2c_block_data(pi, I2C_ADDR, CMD_CONTINUOUS_MEASUREMENT, sizeof(CMD_CONTINUOUS_MEASUREMENT));
    if (err < 0) {
        fprintf(stderr, "Failed to write measurement command: %s\n", pi_error(err));
        return -1;
    }

    // Wait for measurement to complete
    usleep(MEASUREMENT_DELAY_MS * 1000);

    // Read data
    err = i2c_read_i2c_block_data(pi, I2C_ADDR, 0x00, DATA_LENGTH, buffer);
    if (err < 0) {
        fprintf(stderr, "Failed to read data: %s\n", pi_error(err));
        return -1;
    }

    // Verify CRC
    if (buffer[2] != calculate_crc8(buffer, 2)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert raw value to pressure
    int16_t raw_value = (buffer[0] << 8) | buffer[1];
    *pressure = raw_value / 60.0;

    return 0;
}

void log_pressure(int pi) {
    FILE *file;
    int pressure;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    // Check if file exists
    if (access(CSV_FILENAME, F_OK) == -1) {
        file = fopen(CSV_FILENAME, "w");
        if (file == NULL) {
            perror("Failed to open file for writing");
            return;
        }
        fprintf(file, "Timestamp,Pressure(Pa)\n");
    } else {
        file = fopen(CSV_FILENAME, "a");
        if (file == NULL) {
            perror("Failed to open file for appending");
            return;
        }
    }

    // Read pressure
    if (read_pressure(pi, &pressure) == 0) {
        // Get current time
        now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Log to file
        fprintf(file, "%s,%.2f\n", timestamp, pressure);
    }

    fclose(file);
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio daemon\n");
        return EXIT_FAILURE;
    }

    if (i2c_open(pi, I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_stop(pi);
