#define DATA_LENGTH 3
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MEASUREMENT_DELAY_MS 8
#define CSV_FILENAME "airflow_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_pressure(int pi, int *pressure) {
    uint8_t buffer[DATA_LENGTH];
    int err;

    // Trigger continuous measurement
    err = i2c_write_i2c_block_data(pi, I2C_ADDR, CMD_CONTINUOUS_MEASUREMENT, sizeof(CMD_CONTINUOUS_MEASUREMENT));
    if (err < 0) {
        fprintf(stderr, "Failed to write measurement command: %s\n", pi_error(err));
        return -1;
    }

    // Wait for measurement to complete
    usleep(MEASUREMENT_DELAY_MS * 1000);

    // Read data
    err = i2c_read_i2c_block_data(pi, I2C_ADDR, 0x00, DATA_LENGTH, buffer);
    if (err < 0) {
        fprintf(stderr, "Failed to read data: %s\n", pi_error(err));
        return -1;
    }

    // Verify CRC
    if (buffer[2] != calculate_crc8(buffer, 2)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert raw value to pressure
    int16_t raw_value = (buffer[0] << 8) | buffer[1];
    *pressure = raw_value / 60.0;

    return 0;
}

void log_pressure(int pi) {
    FILE *file;
    int pressure;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

