#define SCALE_FACTOR 0.01
#define SAFE_PRESSURE_MIN 200.0
#define SAFE_PRESSURE_MAX 250.0
#define LOG_FILE "pressure_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static int log_file_initialized = 0;

void handle_signal(int sig) {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_log_file() {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return -1;
        }
        if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
            fprintf(log_file, "timestamp,pressure_kPa\n");
            log_file_initialized = 1;
        }
    }
    return 0;
}

int read_pressure(int *pressure) {
    unsigned char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", piErrString(result));
        i2cClose(i2c_handle);
        i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
        if (i2c_handle < 0) {
            fprintf(stderr, "Failed to reopen I2C handle: %s\n", piErrString(i2c_handle));
            return -1;
        }
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);
        if (result < 0) {
            fprintf(stderr, "Retry I2C read error: %s\n", piErrString(result));
            return -1;
        }
    }
    *pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

void log_pressure(double pressure_kPa) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);
    fprintf(log_file, "%s,%f\n", timestamp, pressure_kPa);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", piErrString(gpioInitialise()));
        return 1;
    }

    setup_signal_handlers();

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %s\n", piErrString(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (open_log_file() < 0) {
        gpioTerminate();
        return 1;
    }

    while (1) {
        int raw_pressure;
        if (read_pressure(&raw_pressure) < 0) {
            fprintf(stderr, "Failed to read pressure\n");
            continue;
        }

        double pressure_kPa = raw_pressure * SCALE_FACTOR;
        log_pressure(pressure_kPa);

        if (pressure_kPa < SAFE_PRESSURE_MIN || pressure_kPa > SAFE_PRESSURE_MAX) {
            fprintf(stderr, "Warning: Pressure out of safe range: %.2f kPa\n", pressure_kPa);
        }

        sleep(1);
    }

    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

