#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define MEASUREMENT_DELAY_MS 40
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1 MB

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_reading(double temperature, double humidity) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s, Temperature: %.2f°C, Humidity: %.2f%%\n", timestamp, temperature, humidity);
    fclose(log_file);

    // Check log file size and truncate if necessary
    struct stat st;
    if (stat(LOG_FILE, &st) == 0 && st.st_size > MAX_LOG_SIZE) {
        FILE *temp_file = fopen(LOG_FILE, "w");
        if (temp_file) {
            fclose(temp_file);
        }
    }
}

int read_sensor(double *temperature, double *humidity) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    int fd = i2cOpen(I2C_BUS, I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return -1;
    }

    // Trigger measurement
    if (i2cWriteReg8(fd, 0, 0x00) < 0) {
        fprintf(stderr, "Failed to write to I2C bus\n");
        i2cClose(fd);
        gpioTerminate();
        return -1;
    }

    // Wait for measurement to complete
    usleep(MEASUREMENT_DELAY_MS * 1000);

    // Read 4 bytes from the sensor
    uint8_t data[4];
    if (i2cReadReg8s(fd, 0, data, 4) < 0) {
        fprintf(stderr, "Failed to read from I2C bus\n");
        i2cClose(fd);
        gpioTerminate();
        return -1;
    }

    i2cClose(fd);
    gpioTerminate();

    // Validate status bits
    if ((data[0] & 0x80) != 0 || (data[1] & 0x80) != 0) {
        fprintf(stderr, "Sensor error or data not ready\n");
        return -1;
    }

    // Convert raw values
    uint16_t raw_T = (data[0] << 8) | data[1];
    uint16_t raw_H = (data[2] << 8) | data[3];

    *temperature = raw_T * 165.0 / 16383.0 - 40.0;
    *humidity = raw_H * 100.0 / 16383.0;

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);

    while (keep_running) {
        double temperature, humidity;
        if (read_sensor(&temperature, &humidity) == 0) {
            log_reading(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor\n");
        }
        sleep(5);
    }

    return 0;
}

