#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define VALID_MIN_TICKS 12
#define VALID_MAX_TICKS 271
#define SCALE 0.1
#define OFFSET 0.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *file = fopen("pressure_log.txt", "a");
    if (file) {
        fprintf(file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fclose(file);
    } else {
        log_error("Failed to open pressure_log.txt for writing.");
    }
}

int read_sent_data(int pi, int gpio, int *status, int *data, int *checksum) {
    int sync_ticks = 0;
    int nibble_ticks = 0;
    int nibble_value = 0;
    int nibble_count = 0;
    int sum = 0;

    // Wait for synchronization pulse
    while (sync_ticks < SYNC_PULSE_TICKS) {
        if (gpioRead(gpio) == 0) {
            sync_ticks++;
        } else {
            sync_ticks = 0;
        }
    }

    // Read nibbles
    for (nibble_count = 0; nibble_count < 5; nibble_count++) {
        while (gpioRead(gpio) == 1) {
            if (nibble_ticks > VALID_MAX_TICKS) {
                log_error("Bus error: Pulse width too long.");
                return -1;
            }
        }

        while (gpioRead(gpio) == 0) {
            if (nibble_ticks > VALID_MAX_TICKS) {
                log_error("Bus error: Pulse width too long.");
                return -1;
            }
            nibble_ticks++;
        }

        if (nibble_ticks < VALID_MIN_TICKS || nibble_ticks > VALID_MAX_TICKS) {
            log_error("Bus error: Invalid pulse width.");
            return -1;
        }

        nibble_value = (nibble_ticks - VALID_MIN_TICKS) / (VALID_MAX_TICKS - VALID_MIN_TICKS + 1);
        sum += nibble_value;

        if (nibble_count == 0) {
            *status = nibble_value;
        } else if (nibble_count == 1) {
            *data = (nibble_value << 4);
        } else if (nibble_count == 2) {
            *data |= nibble_value;
        } else if (nibble_count == 3) {
            *data = (*data << 4) | nibble_value;
        } else {
            *checksum = nibble_value;
        }

        nibble_ticks = 0;
    }

    if ((sum & 0x0F) != *checksum) {
        log_error("Checksum error.");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO.");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        log_error("Failed to set GPIO mode.");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        log_error("Failed to set pull-up resistor.");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int status, data, checksum;
        if (read_sent_data(gpioInitialise(), GPIO_PIN, &status, &data, &checksum) == 0) {
            int raw_value = (data & 0x0FFF);
            double pressure = raw_value * SCALE + OFFSET;
            log_pressure(pressure);
        } else {
            log_error("Sensor absent or bus error.");
        }

        usleep(TICK_TIME_US * 1000); // Sleep for 1 ms
    }

    gpioTerminate();
    return 0;
}

