    if (read_device_id(pi, TMP117_I2C_BUS, TMP117_I2C_ADDR, &device_id) < 0 || device_id != TMP117_DEVICE_ID) {
        fprintf(stderr, "Invalid device ID: 0x%04X\n", device_id);
        close(file);
        pigpio_stop(pi);
        return EXIT_FAILURE;
