        float temperature;
        if (read_temperature(pi, TMP117_I2C_BUS, TMP117_I2C_ADDR, &temperature) == 0) {
            uint8_t temp_bytes[4];
            memcpy(temp_bytes, &temperature, sizeof(float));
            if (write(file, temp_bytes, sizeof(float)) != sizeof(float)) {
                fprintf(stderr, "Failed to write temperature to file\n");
            }
        }
        sleep(60);
    }

    close(file);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
