#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define CMD_HIGH_PRECISION 0xFD
#define TEMP_REG 0x00
#define HUMIDITY_REG 0x02
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int pi, int fd, float *temperature, float *humidity) {
    uint8_t buffer[6];
    int err;

    // Issue high-precision measurement command
    err = i2c_write_i2c_block_data(pi, fd, CMD_HIGH_PRECISION, NULL, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to write command: %s\n", pi_error(err));
        return -1;
    }

    // Wait for conversion
    usleep(8500);

    // Read 6 bytes: 2 bytes temperature, 1 CRC byte, 2 bytes humidity, 1 CRC byte
    err = i2c_read_i2c_block_data(pi, fd, TEMP_REG, buffer, 6);
    if (err < 0) {
        fprintf(stderr, "Failed to read data: %s\n", pi_error(err));
        return -1;
    }

    // Validate CRC for temperature
    if (calculate_crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Validate CRC for humidity
    if (calculate_crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw values
    uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
    uint16_t raw_hum = (buffer[3] << 8) | buffer[4];

    *temperature = -45 + 175 * (raw_temp / 65535.0);
    *humidity = -6 + 125 * (raw_hum / 65535.0);

    return 0;
}

void log_reading(float temperature, float humidity) {
    FILE *file = fopen("environmental_data.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d - Temperature: %.2f°C, Humidity: %.2f%%RH\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            temperature, humidity);

    if (fflush(file) != 0) {
        perror("Failed to flush log file");
    }

    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int fd = i2cOpen(I2C_BUS, I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pi_error(fd));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fclose(log_file);

    signal(SIGINT, handle_sigint);

    float temperature, humidity;

    while (keep_running) {
        if (read_sensor(gpioMyPigpioID(), fd, &temperature, &humidity) == 0) {
            log_reading(temperature, humidity);
        }
        sleep(5);
    }

    i2cClose(fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

