    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temp_buffer[TEMP_BUFFER_SIZE] = {0};
    int buffer_index = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        unsigned char temp_data[2] = {0};
        int result = i2cReadReg8(i2c_handle, TMP117_TEMP_REG, temp_data, 2);
        if (result < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        } else {
            int16_t temp_raw = (temp_data[0] << 8) | temp_data[1];
            float temperature = temp_raw * TEMP_LSB_RESOLUTION;
            temp_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % TEMP_BUFFER_SIZE;
            write_buffer_to_file(temp_buffer, TEMP_BUFFER_SIZE);
        }
        sleep(5);
    }

    write_buffer_to_file(temp_buffer, TEMP_BUFFER_SIZE);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

