#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SHTC3_I2C_ADDR 0x70
#define SHTC3_MEASUREMENT_CMD 0x7866
#define SHTC3_READ_LENGTH 6
#define SHTC3_TEMP_RANGE_MIN -40.0
#define SHTC3_TEMP_RANGE_MAX 125.0
#define SHTC3_HUMIDITY_RANGE_MIN 0.0
#define SHTC3_HUMIDITY_RANGE_MAX 100.0
#define SHTC3_POLYNOMIAL 0x31
#define SHTC3_INITIAL_CRC 0xFF

static int pi = -1;
static int i2c_handle = -1;

void handle_sigint(int sig) {
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    if (pi >= 0) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SHTC3_INITIAL_CRC;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHTC3_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_shtc3(float *temperature, float *humidity) {
    uint8_t buffer[SHTC3_READ_LENGTH];
    int err;

    // Write measurement command
    err = i2c_write_i2c_block_data(i2c_handle, SHTC3_I2C_ADDR, SHTC3_MEASUREMENT_CMD, 2);
    if (err != 2) {
        fprintf(stderr, "I2C write error: %d\n", err);
        return -1;
    }

    // Wait for conversion
    gpioDelay(12400);

    // Read data
    err = i2c_read_i2c_block_data(i2c_handle, SHTC3_I2C_ADDR, SHTC3_READ_LENGTH, buffer);
    if (err != SHTC3_READ_LENGTH) {
        fprintf(stderr, "I2C read error: %d\n", err);
        return -1;
    }

    // Validate CRC
    if (buffer[2] != crc8(buffer, 2) || buffer[5] != crc8(buffer + 3, 2)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert raw data
