#define TMP117_I2C_ADDRESS 0x48
#define TMP117_TEMP_REGISTER 0x00
#define TMP117_RESOLUTION 0.0078125
#define I2C_BUS 1
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int read_temperature(int16_t *temperature) {
    uint8_t buffer[2];
    int result = i2cReadReg8(i2c_handle, TMP117_TEMP_REGISTER, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }

    *temperature = (int16_t)(buffer[0] << 8 | buffer[1]);
    return 0;
}

void log_temperature(int16_t temperature) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(log_file, "%s, Temperature: %.3f C\n", timestamp, temperature * TMP117_RESOLUTION);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (initialize_i2c() == 0) {
            break;
        }
        retries++;
        fprintf(stderr, "Retrying I2C initialization (%d/%d)\n", retries, MAX_RETRIES);
        sleep(1);
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize I2C after %d attempts\n", MAX_RETRIES);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int16_t temperature;
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error reading temperature, retrying...\n");
        }
        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

