#define I2C_REG 0x00
#define I2C_LEN 4

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    FILE *log_file = fopen("flow_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "ERROR: %s\n", message);
        fclose(log_file);
    }
}

void log_data(double timestamp, double slpm, double celsius) {
    FILE *log_file = fopen("flow_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%f, %f, %f\n", timestamp, slpm, celsius);
        fclose(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C handle");
        gpioTerminate();
        return 1;
    }

    int retries = 0;
    while (keep_running) {
        unsigned char buffer[I2C_LEN];
        int result = i2cReadDevice(i2c_handle, I2C_REG, buffer, I2C_LEN);
        if (result < 0) {
            log_error("I2C read failed");
            if (retries < 2) {
                retries++;
                continue;
            }
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                log_error("Failed to re-open I2C handle");
                gpioTerminate();
                return 1;
            }
            retries = 0;
        } else {
            retries = 0;
            if (retries < 2) {
                continue;
            }

            int raw_flow = (buffer[0] << 6) | (buffer[1] >> 2);
            int raw_temp = ((buffer[1] & 0x03) << 10) | (buffer[2] << 2) | (buffer[3] >> 6);

            double slpm = ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
            double celsius = ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;

            double timestamp = (double)time(NULL);
            log_data(timestamp, slpm, celsius);
        }
        sleep(1);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

