#define ERROR_LOG_FILE "dht11_errors.log"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    FILE *file = fopen(ERROR_LOG_FILE, "a");
    if (file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(file, "[%s] ERROR: %s\n", timestamp, message);
        fclose(file);
    }
}

void log_reading(int humidity, int temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(file, "[%s] Humidity: %d%%, Temperature: %d°C\n", timestamp, humidity, temperature);
        fclose(file);
    }
}

int read_dht11(int *humidity, int *temperature) {
    unsigned char data[5] = {0};
    int bit_idx = 0;
    int byte_idx = 0;
    int level = 0;
    int count = 0;
    int loop_count = 0;

    if (gpioWrite(DHT11_PIN, 0) < 0) {
        log_error("Failed to pull GPIO low");
        return -1;
    }
    if (gpioDelay(18000) < 0) { // 18 ms
        log_error("Failed to delay for 18 ms");
        return -1;
    }
