#define I2C_BUS 1
#define I2C_ADDR 0x44
#define MEASUREMENT_CMD 0x2C06
#define RETRY_LIMIT 3
#define LOG_FILE "sht31d_data.log"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int pi, int fd, float *temperature, float *humidity) {
    uint8_t buf[6];
    int retries = 0;
    int err;

    while (retries < RETRY_LIMIT) {
        err = i2c_write(fd, &MEASUREMENT_CMD, 2);
        if (err < 0) {
            retries++;
            usleep(100000); // 100 ms
            continue;
        }

        usleep(15000); // 15 ms

        err = i2c_read(fd, buf, 6);
        if (err == 6) {
            if (crc8(buf, 2) == buf[2] && crc8(buf + 3, 2) == buf[5]) {
                int16_t raw_temp = (buf[0] << 8) | buf[1];
                int16_t raw_hum = (buf[3] << 8) | buf[4];

                *temperature = -45.0 + 175.0 * raw_temp / 65535.0;
                *humidity = 100.0 * raw_hum / 65535.0;

                return 0;
            }
        }
        retries++;
        usleep(100000); // 100 ms
    }

    return -1;
}

void log_reading(FILE *log_file, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

void log_error(FILE *log_file, const char *error_message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s ERROR: %s\n", timestamp, error_message);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = i2cOpen(I2C_BUS, I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        float temperature, humidity;
        if (read_sensor(gpioContext, fd, &temperature, &humidity) == 0) {
            log_reading(log_file, temperature, humidity);
        } else {
            log_error(log_file, "Failed to read from sensor");
        }
        sleep(5);
    }

    fclose(log_file);
    i2cClose(fd);
    gpioTerminate();

    return 0;
}

