#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_VALUE 0x2A
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double compute_cct(int red, int green, int blue) {
    double x = (0.4360747 * red + 0.3850649 * green + 0.1430804 * blue) /
               (red + green + blue);
    double y = (0.2225045 * red + 0.7168786 * green + 0.0606169 * blue) /
               (red + green + blue);
    double n = (x - 0.3320) / (0.1858 - y);
    return 449.0 * n * n * n + 3525.0 * n * n + 6823.3 * n + 5520.33;
}

void log_cct(double cct1, double cct2) {
    FILE *file = fopen("cct_log.csv", "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    if (fseek(file, 0, SEEK_END) == 0 && ftell(file) == 0) {
        fprintf(file, "Timestamp,Average_CCT\n");
    }

    time_t now = time(NULL);
    double average_cct = (cct1 + cct2) / 2.0;
    fprintf(file, "%ld,%f\n", now, average_cct);

    fclose(file);
}

int read_sensor_data(int i2c_handle, int addr, int *red, int *green, int *blue) {
    unsigned char buffer[2];

    if (i2cReadReg8(i2c_handle, addr, DEVICE_ID_REG) != DEVICE_ID_VALUE) {
        fprintf(stderr, "Device ID mismatch or sensor absent at address 0x%02X\n", addr);
        return -1;
    }

    if (i2cReadReg16(i2c_handle, addr, RED_REG, buffer) != 0) {
        fprintf(stderr, "Failed to read RED register at address 0x%02X\n", addr);
        return -1;
    }
    *red = (buffer[0] << 8) | buffer[1];

    if (i2cReadReg16(i2c_handle, addr, GREEN_REG, buffer) != 0) {
        fprintf(stderr, "Failed to read GREEN register at address 0x%02X\n", addr);
        return -1;
    }
    *green = (buffer[0] << 8) | buffer[1];

    if (i2cReadReg16(i2c_handle, addr, BLUE_REG, buffer) != 0) {
        fprintf(stderr, "Failed to read BLUE register at address 0x%02X\n", addr);
        return -1;
    }
    *blue = (buffer[0] << 8) | buffer[1];

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C bus for sensor 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C bus for sensor 2\n");
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int red1, green1, blue1;
        int red2, green2, blue2;

        if (read_sensor_data(i2c_handle1, SENSOR1_ADDR, &red1, &green1, &blue1) == 0 &&
            read_sensor_data(i2c_handle2, SENSOR2_ADDR, &red2, &green2, &blue2) == 0) {
            double cct1 = compute_cct(red1, green1, blue1);
            double cct2 = compute_cct(red2, green2, blue2);
            log_cct(cct1, cct2);
        }

        sleep(1);
    }

    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return EXIT_SUCCESS;
}

