#define TEMPERATURE_REGISTER 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN_KPA 0
#define P_MAX_KPA 800

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double convert_pressure_to_kPa(int raw) {
    return (raw - OUTPUT_MIN) * (P_MAX_KPA - P_MIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
}

double convert_temperature_to_C(int raw) {
    return raw * 0.01 - 40;
}

void log_error(const char *message) {
