#define ON_TEMP 28.0
#define OFF_TEMP 26.0

static int i2c_handle = -1;
static int fan_gpio = -1;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int running_sum = 0;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_temperature() {
    int temp_raw;
    if (i2c_read(i2c_handle, LM75B_I2C_ADDR, LM75B_TEMP_REG, &temp_raw, 2) < 0) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }
    // Convert to signed 9-bit value
    int temp = (temp_raw << 1) >> 1;
    return temp;
}

void update_running_average(int new_temp) {
    running_sum -= buffer[buffer_index];
    buffer[buffer_index] = new_temp;
    running_sum += new_temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void control_fan(double average_temp) {
    if (average_temp > ON_TEMP && gpioRead(fan_gpio) == 0) {
        if (gpioWrite(fan_gpio, 1) < 0) {
            fprintf(stderr, "GPIO write error\n");
        }
    } else if (average_temp < OFF_TEMP && gpioRead(fan_gpio) == 1) {
        if (gpioWrite(fan_gpio, 0) < 0) {
            fprintf(stderr, "GPIO write error\n");
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_handle = i2cOpen(LM75B_I2C_BUS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    fan_gpio = gpioInitialise();
    if (fan_gpio < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(fan_gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        int temp_raw = read_temperature();
        if (temp_raw >= 0) {
            double temp_c = temp_raw * 0.5;
            update_running_average(temp_raw);
            double average_temp = (double)running_sum / BUFFER_SIZE;
            control_fan(average_temp);
        }
        sleep(1);
    }

    if (gpioRead(fan_gpio) == 1) {
        gpioWrite(fan_gpio, 0);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

