#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define MEASUREMENT_INTERVAL_MS 1000
#define WAIT_FOR_MEASUREMENT_MS 45
#define LOG_FILE "airflow.log"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int pi, int *pressure, int *temperature, int *status) {
    uint8_t buffer[9];
    if (i2c_write_i2c_block_data(pi, I2C_ADDR, CMD_CONTINUOUS_MEASUREMENT, 2) < 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }
    usleep(WAIT_FOR_MEASUREMENT_MS * 1000);

    if (i2c_read_i2c_block_data(pi, I2C_ADDR, 0, buffer, 9) < 0) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    if (calculate_crc8(buffer, 2) != buffer[2] ||
        calculate_crc8(buffer + 3, 2) != buffer[5] ||
        calculate_crc8(buffer + 6, 1) != buffer[8]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    *pressure = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8) | buffer[4];
    *status = buffer[6];

    return 0;
}

void log_data(int pressure, int temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            pressure / 60.0, temperature / 200.0);

    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int pi = openI2CDevice(I2C_BUS, I2C_ADDR);
    if (pi < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int pressure_raw, temperature_raw, status;
        if (read_sensor_data(pi, &pressure_raw, &temperature_raw, &status) == 0) {
            float pressure = pressure_raw / 60.0;
            float temperature = temperature_raw / 200.0;

            log_data(pressure, temperature);

            if (pressure > 5.0) {
                fprintf(stderr, "Warning: Pressure exceeded 5.0 Pa: %.2f Pa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    closeI2CDevice(pi);
    gpioTerminate();
    return EXIT_SUCCESS;
}

