#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x4A
#define TEMP_REG 0x00
#define GPIO_LED 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void cleanup_and_exit(int signum) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (line) {
        gpiod_line_request_output(line, "temp_sensor_led", 0);
        gpiod_line_set_value(line, 0);
    }
    exit(0);
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int read_temperature(int16_t *temperature) {
    uint8_t buffer[2];
    if (write(i2c_fd, &TEMP_REG, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *temperature = (buffer[0] << 8) | buffer[1];
    return 0;
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(line, "temp_sensor_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
        return -1;
    }

    return 0;
}

void handle_temperature(int16_t raw_temp) {
    double temperature = (raw_temp >> 4) * 0.0625;
    printf("Temperature: %.2f °C\n", temperature);

    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpiod_line_set_value(line, 1);
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpiod_line_set_value(line, 0);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup_and_exit;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
