#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define I2C_READ_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int pi, int *pressure, int *temperature) {
    uint8_t buffer[I2C_READ_LENGTH];
    if (i2c_write_i2c_block_data(pi, I2C_ADDR, CMD_CONTINUOUS_MEASUREMENT, 2) < 0) {
        fprintf(stderr, "Failed to send continuous measurement command\n");
        return -1;
    }
    usleep(45000); // Wait at least 45 ms

    if (i2c_read_i2c_block_data(pi, I2C_ADDR, 0, I2C_READ_LENGTH, buffer) < 0) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return -1;
    }

    // Validate CRC for pressure
    if (calculate_crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }

    // Validate CRC for temperature
    if (calculate_crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Extract scale factor (last 16 bits)
    int scale_factor = (buffer[6] << 8) | buffer[7];

    // Extract and convert pressure
    int raw_pressure = (buffer[0] << 8) | buffer[1];
    *pressure = raw_pressure / scale_factor;

    // Extract and convert temperature
    int raw_temperature = (buffer[3] << 8) | buffer[4];
    *temperature = raw_temperature / 200;

    return 0;
}

void log_data(int pressure, int temperature) {
    FILE *file = fopen("flow_data.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s - Pressure: %d, Temperature: %d\n", time_str, pressure, temperature);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int pi = 0; // Default I2C bus
    if (i2cOpen(pi, I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pressure, temperature;
    while (keep_running) {
        if (read_sensor_data(pi, &pressure, &temperature) == 0) {
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        usleep(100000); // Read every 100 ms
    }

    i2cClose(pi);
    gpioTerminate();
    return EXIT_SUCCESS;
}

