#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SI7021_ADDRESS 0x40
#define MEASURE_RH_NO_MASTER_HOLD 0xF5
#define MEASURE_TEMP_NO_MASTER_HOLD 0xF3
#define READ_TEMP_FROM_PREVIOUS_RH 0xE0
#define READ_ELECTRONIC_ID 0xFA
#define READ_FIRMWARE_REVISION 0x84
#define I2C_BUS 1
#define RETRY_LIMIT 3
#define SLEEP_INTERVAL 60

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int i2c_transaction(int pi, int bus, uint8_t address, uint8_t *tx, int tx_len, uint8_t *rx, int rx_len) {
    for (int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
        if (i2cWriteDevice(pi, bus, address, tx, tx_len) == 0 &&
            i2cReadDevice(pi, bus, address, rx, rx_len) == 0) {
            return 0;
        }
        usleep(100000); // 100 ms
    }
    return -1;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(stderr, "%s ERROR: %s\n", timestamp, message);
    FILE *log_file = fopen("environment.log", "a");
    if (log_file) {
        fprintf(log_file, "%s ERROR: %s\n", timestamp, message);
        fclose(log_file);
    }
}

void log_reading(double temperature, double humidity) {
    time_t now = time(NULL);
    char timestamp[20];
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    FILE *log_file = fopen("environment.log", "a");
    if (log_file) {
        fprintf(log_file, "%s", log_entry);
        fflush(log_file);
        fclose(log_file);
    }
    printf("%s", log_entry);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    int pi = 0;
    uint8_t electronic_id[2] = {0};
    if (i2c_transaction(pi, I2C_BUS, SI7021_ADDRESS, &READ_ELECTRONIC_ID, 1, electronic_id, 2) != 0) {
        log_error("Failed to read electronic ID from Si7021");
        gpioTerminate();
        return 1;
    }

    uint16_t raw_id = (electronic_id[0] << 8) | electronic_id[1];
    if (raw_id != 0x5449) {
        log_error("Invalid Si7021 electronic ID");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        uint8_t tx[1] = {MEASURE_RH_NO_MASTER_HOLD};
        uint8_t rx[3] = {0};

        usleep(20000); // 20 ms

        if (i2c_transaction(pi, I2C_BUS, SI7021_ADDRESS, tx, 1, rx, 2) == 0) {
            uint16_t raw_humidity = (rx[0] << 8) | rx[1];
            double humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
            humidity = humidity < 0 ? 0 : (humidity > 100 ? 100 : humidity);

            tx[0] = READ_TEMP_FROM_PREVIOUS_RH;
            if (i2c_transaction(pi, I2C_BUS, SI7021_ADDRESS, tx, 1, rx, 2) == 0) {
                uint16_t raw_temperature = (rx[0] << 8) | rx[1];
                double temperature = 175.72 * raw_temperature / 65536.0 - 46.85;

                log_reading(temperature, humidity);
            } else {
                log_error("Failed to read temperature from Si7021");
            }
        } else {
            log_error("Failed to measure relative humidity from Si7021");
        }

        sleep(SLEEP_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

