        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        usleep(20000); // Wait for conversion

        uint8_t buffer[4];
        if (i2cReadReg8s(i2c_handle, HDC1080_TEMP_REG, buffer, 4) < 0) {
