#define MEASURE_COMMAND_HIGH_REPEATABILTY 0xE0
#define LOG_FILE "temperature_log.txt"
#define POLL_INTERVAL 5
#define CONVERSION_DELAY 10

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

double ticks_to_celsius(uint16_t ticks) {
    return -45.0 + 175.0 * ticks / 65535.0;
}

