    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s: %.2f°C\n", timestamp, temperature);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = NULL;
    while (keep_running) {
        uint8_t command[2] = {MEASURE_COMMAND, MEASURE_COMMAND_HIGH_REPEATABILTY};
        if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        }

        usleep(CONVERSION_DELAY * 1000);

        uint8_t buffer[3];
        if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        } else {
            uint8_t crc = calculate_crc8(buffer, 2);
            if (crc != buffer[2]) {
                fprintf(stderr, "CRC mismatch: expected 0x%02X, got 0x%02X\n", crc, buffer[2]);
            } else {
                uint16_t raw_ticks = (buffer[0] << 8) | buffer[1];
                double temperature = ticks_to_celsius(raw_ticks);
                log_temperature(temperature);
            }
        }

        sleep(POLL_INTERVAL);
    }

    if (log_file) {
        fclose(log_file);
    }
    close(i2c_fd);

    return EXIT_SUCCESS;
}

