#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x3615
#define I2C_BUFFER_SIZE 9

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("hvac_pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t buffer[I2C_BUFFER_SIZE];
    uint8_t cmd[] = {CMD_CONTINUOUS_MEASUREMENT >> 8, CMD_CONTINUOUS_MEASUREMENT & 0xFF};

    while (keep_running) {
        if (i2cWrite(i2c_handle, cmd, sizeof(cmd)) != sizeof(cmd)) {
            fprintf(log_file, "%ld, I2C write error\n", time(NULL));
            continue;
        }

        usleep(50000); // Wait at least 50 ms

        if (i2cRead(i2c_handle, buffer, I2C_BUFFER_SIZE) != I2C_BUFFER_SIZE) {
            fprintf(log_file, "%ld, I2C read error\n", time(NULL));
            continue;
        }

        uint8_t pressure_crc = crc8(buffer, 2);
        if (pressure_crc != buffer[2]) {
            fprintf(log_file, "%ld, Pressure CRC error\n", time(NULL));
            continue;
        }

        uint8_t temperature_crc = crc8(buffer + 3, 2);
        if (temperature_crc != buffer[5]) {
            fprintf(log_file, "%ld, Temperature CRC error\n", time(NULL));
            continue;
        }

        int16_t pressure_raw = (buffer[0] << 8) | buffer[1];
        int16_t temperature_raw = (buffer[3] << 8) | buffer[4];
        int32_t scale_factor = (buffer[6] << 16) | (buffer[7] << 8) | buffer[8];

        double pressure_Pa = (double)pressure_raw / scale_factor;
        double temperature_C = (double)temperature_raw / 200.0;

        fprintf(log_file, "%ld, %.2f, %.2f\n", time(NULL), pressure_Pa, temperature_C);
        fflush(log_file);

        sleep(1);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

