#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x62
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG "/var/log/scd40_error.log"
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define READ_DATA 0xE000

typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

volatile sig_atomic_t running = 1;
CircularBuffer buffer;
int pi;
int i2c_handle;

void log_error(const char *message) {
    FILE *log_file = fopen(ERROR_LOG, "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    }
}

void handle_sigint(int sig) {
    running = 0;
}

int crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buffer[9];
    if (i2c_read(i2c_handle, I2C_ADDR, READ_DATA, buffer, 9) != 9) {
        log_error("I2C read failed");
        return -1;
    }

    if (crc8(buffer, 2) != buffer[2] ||
        crc8(buffer + 3, 2) != buffer[5] ||
        crc8(buffer + 6, 2) != buffer[8]) {
        log_error("CRC check failed");
        return -1;
    }

    *co2 = (buffer[0] << 8) | buffer[1];
    int raw_temp = (buffer[3] << 8) | buffer[4];
    *temperature = -45.0 + 175.0 * raw_temp / 65535.0;
    int raw_hum = (buffer[6] << 8) | buffer[7];
    *humidity = 100.0 * raw_hum / 65535.0;

    return 0;
}

void *log_data(void *arg) {
    while (running) {
        sleep(60);

        pthread_mutex_lock(&buffer.mutex);
        if (buffer.count == 0) {
            pthread_mutex_unlock(&buffer.mutex);
            continue;
        }

        char filename[256];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(filename, sizeof(filename), LOG_DIR "/scd40_data_%Y%m%d%H%M%S.csv", tm_info);

        FILE *file = fopen(filename, "w");
        if (!file) {
            log_error("Failed to open log file");
            pthread_mutex_unlock(&buffer.mutex);
            continue;
        }

        fprintf(file, "Timestamp,CO2,Temp,Humidity\n");
        for (int i = 0; i < buffer.count; i++) {
            int idx = (buffer.tail + i) % BUFFER_SIZE;
            fprintf(file, "%ld,%d,%.2f,%.2f\n",
                    buffer.data[idx].timestamp,
                    buffer.data[idx].co2,
                    buffer.data[idx].temperature,
                    buffer.data[idx].humidity);
        }
        fclose(file);

        buffer.head = buffer.tail;
        buffer.count = 0;
        pthread_mutex_unlock(&buffer.mutex);
    }

    // Flush remaining data
    if (buffer.count > 0) {
        pthread_mutex_lock(&buffer.mutex);
        char filename[256];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(filename, sizeof(filename), LOG_DIR "/scd40_data_final.csv", tm_info);

        FILE *file = fopen(filename, "w");
        if (!file) {
            log_error("Failed to open final log file");
            pthread_mutex_unlock(&buffer.mutex);
            return NULL;
        }

        fprintf(file, "Timestamp,CO2,Temp,Humidity\n");
        for (int i = 0; i < buffer.count; i++) {
            int idx = (buffer.tail + i) % BUFFER_SIZE;
            fprintf(file, "%ld,%d,%.2f,%.2f\n",
                    buffer.data[idx].timestamp,
                    buffer.data[idx].co2,
                    buffer.data[idx].temperature,
                    buffer.data[idx].humidity);
        }
        fclose(file);

        buffer.head = buffer.tail;
        buffer.count = 0;
        pthread_mutex_unlock(&buffer.mutex);
    }

    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    pi = gpioInitialise();
    if (pi < 0) {
        log_error("Failed to initialize pigpio");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(pi, I2C_BUS);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, I2C_ADDR, START_PERIODIC_MEASUREMENT, 0) != 0) {
        log_error("Failed to start periodic measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    pthread_mutex_init(&buffer.mutex, NULL);
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    pthread_t logger_thread;
    if (pthread_create(&logger_thread, NULL, log_data, NULL) != 0) {
        log_error("Failed to create logger thread");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sleep(1);

    while (running) {
        uint16_t co2;
        float temperature, humidity;

        if (read_sensor_data(&co2, &temperature, &humidity) == 0) {
            pthread_mutex_lock(&buffer.mutex);
            buffer.data[buffer.head].timestamp = time(NULL);
            buffer.data[buffer.head].co2 = co2;
            buffer.data[buffer.head].temperature = temperature;
            buffer.data[buffer.head].humidity = humidity;
            buffer.head = (buffer.head + 1) % BUFFER_SIZE;
            if (buffer.count < BUFFER_SIZE) {
                buffer.count++;
            } else {
                buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
            }
            pthread_mutex_unlock(&buffer.mutex);
        }

        sleep(5);
    }

    if (i2cWriteByteData(i2c_handle, I2C_ADDR, STOP_PERIODIC_MEASUREMENT, 0) != 0) {
        log_error("Failed to stop periodic measurement");
    }

    pthread_join(logger_thread, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

