#define I2C_TIMEOUT 1000
#define LOG_FILE "sdp810_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int crc8(const uint8_t *data, size_t length, uint8_t polynomial, uint8_t initial) {
    uint8_t crc = initial;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor_data(int pi, int fd, float *pressure_Pa, float *temperature_C) {
    uint8_t buffer[9];
    int err;

    // Send continuous measurement command
    err = i2c_write_i2c_block_data(pi, fd, CMD_CONTINUOUS_MEASUREMENT, NULL, 0);
    if (err < 0) {
        fprintf(stderr, "I2C write error: %s\n", pi_i2c_error(pi));
        return -1;
    }

    // Wait at least 45 ms
    usleep(45000);

    // Read 9 bytes from the sensor
    err = i2c_read_i2c_block_data(pi, fd, 0, buffer, 9);
    if (err < 0) {
        fprintf(stderr, "I2C read error: %s\n", pi_i2c_error(pi));
        return -1;
    }

    // Validate CRCs
    if (crc8(buffer, 2, 0x31, 0xFF) != buffer[2] ||
        crc8(buffer + 3, 2, 0x31, 0xFF) != buffer[5] ||
        crc8(buffer + 6, 2, 0x31, 0xFF) != buffer[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract and convert data
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temp = (buffer[3] << 8) | buffer[4];
    int16_t scale_factor = (buffer[6] << 8) | buffer[7];

    *pressure_Pa = raw_pressure * scale_factor / 1000.0f;
    *temperature_C = -45 + 175 * raw_temp / 65535.0f;

    return 0;
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    int fd = pi_i2c_open(pi, I2C_BUS, I2C_ADDR, I2C_TIMEOUT);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pi_i2c_error(pi));
        pigpio_stop(pi);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pi_i2c_close(pi, fd);
        pigpio_stop(pi);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        float pressure_Pa, temperature_C;
        if (read_sensor_data(pi, fd, &pressure_Pa, &temperature_C) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_Pa, temperature_C);
            fflush(log_file);
        } else {
            fprintf(log_file, "Error reading sensor data\n");
            fflush(log_file);
        }

        sleep(1);
    }

    fclose(log_file);
    pi_i2c_close(pi, fd);
    pigpio_stop(pi);

    return 0;
}

