#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VALUE 0x08
#define MEASUREMENT_TRIGGER_REG 0x00
#define DATA_REG 0x00
#define CALIBRATION_START_REG 0x05
#define CALIBRATION_COUNT 4
#define SAMPLE_INTERVAL 5
#define MEASUREMENT_DELAY 10

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char who_am_i;
    if (i2cReadReg8(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0 || who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Sensor identity verification failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char calibration_coeffs[CALIBRATION_COUNT];
    if (i2cReadI2CBlockData(i2c_handle, CALIBRATION_START_REG, CALIBRATION_COUNT, calibration_coeffs) < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2cWriteReg8(i2c_handle, MEASUREMENT_TRIGGER_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        usleep(MEASUREMENT_DELAY * 1000);

        unsigned char data[6];
        if (i2cReadI2CBlockData(i2c_handle, DATA_REG, 6, data) < 0) {
            fprintf(stderr, "Failed to read measurement data\n");
            continue;
        }

        int32_t pressure_raw = (data[0] << 16) | (data[1] << 8) | data[2];
        int32_t temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5];

        // Convert raw data to hPa and Celsius using the ICP-10110 datasheet formulas
        float pressure = (pressure_raw / 4096.0) * 1000.0; // Example conversion
        float temperature = (temperature_raw / 100.0) - 50.0; // Example conversion

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "%s Pressure: %.2f hPa, Temperature: %.2f C\n",
                 timestamp, pressure, temperature);

        fprintf(log_file, "%s", log_entry);
        fflush(log_file);
        printf("%s", log_entry);

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

