#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <stdint.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x63
#define OTP_MEMORY_REG 0x66
#define MEASUREMENT_COMMAND 0x4011
#define LED_GPIO 17
#define NORMAL_BLINK_ON_MS 500
#define NORMAL_BLINK_OFF_MS 500
#define WARNING_BLINK_ON_MS 100
#define WARNING_BLINK_OFF_MS 100
#define POLL_INTERVAL 1

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

int read_i2c(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write I2C register address");
        return -1;
    }

    if (read(i2c_fd, buf, len) != len) {
        perror("Failed to read I2C data");
        return -1;
    }

    return 0;
}

int write_i2c(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write I2C data");
        return -1;
    }
    return 0;
}

int read_calibration_coefficients(uint8_t *coefficients) {
    return read_i2c(OTP_MEMORY_REG, coefficients, 4);
}

int trigger_measurement() {
    return write_i2c(0x00, MEASUREMENT_COMMAND >> 8) || write_i2c(0x01, MEASUREMENT_COMMAND & 0xFF);
}

int read_measurement(uint8_t *data) {
    return read_i2c(0x02, data, 6);
}

int verify_crc(uint8_t *data) {
    uint16_t crc = (data[4] << 8) | data[5];
    uint16_t calculated_crc = 0xFFFF;
    for (int i = 0; i < 4; i++) {
        calculated_crc ^= (data[i] << 8);
        for (int j = 0; j < 8; j++) {
            if (calculated_crc & 0x8000) {
                calculated_crc = (calculated_crc << 1) ^ 0x1021;
            } else {
                calculated_crc <<= 1;
            }
        }
    }
    return crc == calculated_crc;
}

void blink_led(int on_time_ms, int off_time_ms) {
    gpiod_line_set_value(led_line, 1);
    usleep(on_time_ms * 1000);
    gpiod_line_set_value(led_line, 0);
    usleep(off_time_ms * 1000);
}

void init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "pressure_warning", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void calculate_pressure_and_temperature(uint8_t *data, uint8_t *coefficients, double *pressure, double *temperature) {
