#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define OBJECT_TEMP_THRESHOLD_HIGH 30.0
#define OBJECT_TEMP_THRESHOLD_LOW 28.0
#define RETRY_LIMIT 3
#define RETRY_DELAY_MS 10

static int i2c_handle;
static int fan_gpio;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double read_temperature(int reg) {
    unsigned char buffer[2];
    int retries = 0;
    int result;

    while (retries < RETRY_LIMIT) {
        result = i2c_read(i2c_handle, I2C_ADDR, reg, buffer, 2);
        if (result == 2) {
            int raw = (buffer[0] << 8) | buffer[1];
            return raw * 0.02 - 273.15;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    return NAN;
}

void log_temperature(double ambient_temp, double object_temp) {
    FILE *file = fopen("temperature_log.txt", "a");
    if (file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d - Ambient: %.2f °C, Object: %.2f °C\n",
                tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
                ambient_temp, object_temp);
        fclose(file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fan_gpio = FAN_GPIO;
    gpioSetMode(fan_gpio, PI_OUTPUT);
    gpioWrite(fan_gpio, PI_LOW);

    while (keep_running) {
        double ambient_temp = read_temperature(AMBIENT_TEMP_REG);
        double object_temp = read_temperature(OBJECT_TEMP_REG);

        if (!isnan(ambient_temp) && !isnan(object_temp)) {
            log_temperature(ambient_temp, object_temp);

            if (object_temp > OBJECT_TEMP_THRESHOLD_HIGH) {
                gpioWrite(fan_gpio, PI_HIGH);
            } else if (object_temp < OBJECT_TEMP_THRESHOLD_LOW) {
                gpioWrite(fan_gpio, PI_LOW);
            }
        }

        sleep(2);
    }

    gpioWrite(fan_gpio, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

