#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define MEASUREMENT_CMD 0xFD
#define RETRIES 3
#define PORT 8080

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_sht40(float *temperature, float *humidity) {
    int fd = i2cOpen(I2C_BUS, I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    for (int attempt = 0; attempt < RETRIES; ++attempt) {
        if (i2cWriteReg8(fd, 0x2C, MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Failed to write measurement command: %s\n", strerror(errno));
            i2cClose(fd);
            return -1;
        }

        usleep(10000); // Wait at least 10 ms

        uint8_t data[6];
        if (i2cRead(fd, data, 6) != 6) {
            fprintf(stderr, "Failed to read data from sensor: %s\n", strerror(errno));
            i2cClose(fd);
            return -1;
        }

        int16_t raw_T = (data[0] << 8) | data[1];
        int16_t raw_RH = (data[3] << 8) | data[4];

        *temperature = -45 + 175 * ((float)raw_T / 65535);
        *humidity = -6 + 125 * ((float)raw_RH / 65535);

        if (*humidity < 0) *humidity = 0;
        if (*humidity > 100) *humidity = 100;

        i2cClose(fd);
        return 0;
    }

    i2cClose(fd);
    return -1;
}

void start_http_server() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            continue;
        }

        float temperature, humidity;
        if (read_sht40(&temperature, &humidity) == 0) {
            char response[1024];
            snprintf(response, sizeof(response),
                     "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n"
                     "<html><body>"
                     "<h1>SHT40 Sensor Data</h1>"
                     "<p>Temperature: %.2f C</p>"
                     "<p>Humidity: %.2f %%</p>"
                     "</body></html>", temperature, humidity);

            send(new_socket, response, strlen(response), 0);
        } else {
            char *error_response = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n"
                                   "<html><body><h1>Failed to read sensor data</h1></body></html>";
            send(new_socket, error_response, strlen(error_response), 0);
        }

        close(new_socket);
    }

    close(server_fd);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    start_http_server();

    gpioTerminate();
    return EXIT_SUCCESS;
}

