void handle_signal(int signal) {
    stop_flag = 1;
}

int i2c_write_byte_data(int handle, uint8_t reg, uint8_t value) {
    for (int retries = 0; retries < MAX_RETRIES; ++retries) {
        if (i2c_write_byte_data(handle, reg, value) >= 0) {
            return 0;
        }
        printf("I2C write error, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
        usleep(100000); // 100 ms
    }
    return -1;
}

int i2c_read_word_data(int handle, uint8_t reg, uint16_t *value) {
    for (int retries = 0; retries < MAX_RETRIES; ++retries) {
        if (i2c_read_word_data(handle, reg, value) >= 0) {
            return 0;
        }
        printf("I2C read error, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
        usleep(100000); // 100 ms
    }
    return -1;
}

