    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2c_write_byte_data(i2c_handle, CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!stop_flag) {
        if (i2c_write_byte_data(i2c_handle, MEASUREMENT_CONFIG, 0x01) < 0) {
            fprintf(stderr, "Failed to start measurement\n");
            break;
