#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define CMD_READ_PRESSURE 0x3630
#define CMD_READ_TEMPERATURE 0x3631
#define MEASUREMENT_INTERVAL 500000 // 500 ms in microseconds
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, CMD_CONTINUOUS_MEASUREMENT, 0x00) < 0) {
        fprintf(stderr, "Failed to write continuous measurement command\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        usleep(MEASUREMENT_INTERVAL);

        uint8_t pressure_data[3];
        if (i2cReadBytes(i2c_handle, CMD_READ_PRESSURE, pressure_data, 3) < 0) {
            fprintf(stderr, "Failed to read pressure data\n");
            continue;
        }

        uint8_t temperature_data[3];
        if (i2cReadBytes(i2c_handle, CMD_READ_TEMPERATURE, temperature_data, 3) < 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            continue;
        }

        uint8_t pressure_crc = calculate_crc8(pressure_data, 2);
        uint8_t temperature_crc = calculate_crc8(temperature_data, 2);

        if (pressure_crc != pressure_data[2]) {
            fprintf(stderr, "Pressure CRC mismatch\n");
            continue;
        }

        if (temperature_crc != temperature_data[2]) {
            fprintf(stderr, "Temperature CRC mismatch\n");
            continue;
        }

        int16_t pressure = (pressure_data[0] << 8) | pressure_data[1];
        int16_t temperature = (temperature_data[0] << 8) | temperature_data[1];

        printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

