#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_RELAY 17
#define MAX6675_READ_CMD 0x00
#define MAX6675_OPEN_CIRCUIT_BIT 2
#define MAX6675_TEMP_BITS 12
#define REFLOW_LOG "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define PID_KP 2.0
#define PID_KI 0.5
#define PID_KD 1.0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double pid_controller(double setpoint, double measured, double *integral, double *previous_error, double dt) {
    double error = setpoint - measured;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    *previous_error = error;
    return PID_KP * error + PID_KI * *integral + PID_KD * derivative;
}

int read_max6675(int spi_fd, uint16_t *temperature) {
    uint8_t tx[] = {MAX6675_READ_CMD};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .delay_usecs = 0,
        .speed_hz = 5000000,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    *temperature = (rx[1] << 8) | rx[2];
    if (*temperature & (1 << MAX6675_OPEN_CIRCUIT_BIT)) {
        fprintf(stderr, "Open circuit detected\n");
        return -1;
    }

    *temperature >>= MAX6675_TEMP_BITS;
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "reflow_relay", 0)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *profile_file = fopen(PROFILE_FILE, "r");
    if (!profile_file) {
        perror("Failed to open profile file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(REFLOW_LOG, "w");
    if (!log_file) {
        perror("Failed to open log file");
        fclose(profile_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "time_seconds,target_temp_celsius,measured_temp_celsius\n");

    double integral = 0.0, previous_error = 0.0;
    double setpoint = 0.0, measured = 0.0;
    uint16_t raw_temp;
    int time_seconds = 0;

    while (keep_running) {
        if (fscanf(profile_file, "%d,%lf", &time_seconds, &setpoint) != 2) {
            if (feof(profile_file)) {
                break;
            } else {
                perror("Failed to read profile file");
                break;
            }
        }

        if (read_max6675(spi_fd, &raw_temp) == 0) {
            measured = raw_temp * 0.25; // Convert to Celsius
        } else {
            measured = -999.0; // Error value
        }

        double output = pid_controller(setpoint, measured, &integral, &previous_error, 1.0);
        output = output < 0.0 ? 0.0 : (output > 1.0 ? 1.0 : output);

        gpiod_line_set_value(line, output > 0.5);

        fprintf(log_file, "%d,%.2f,%.2f\n", time_seconds, setpoint, measured);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    fclose(profile_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

