    if (gpiod_line_request_output(line, "reflow_relay", 0)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *profile_file = fopen(PROFILE_FILE, "r");
    if (!profile_file) {
        perror("Failed to open profile file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(REFLOW_LOG, "w");
    if (!log_file) {
        perror("Failed to open log file");
        fclose(profile_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "time_seconds,target_temp_celsius,measured_temp_celsius\n");

    double integral = 0.0, previous_error = 0.0;
    double setpoint = 0.0, measured = 0.0;
    uint16_t raw_temp;
    int time_seconds = 0;

    while (keep_running) {
        if (fscanf(profile_file, "%d,%lf", &time_seconds, &setpoint) != 2) {
            if (feof(profile_file)) {
                break;
            } else {
                perror("Failed to read profile file");
                break;
            }
        }

        if (read_max6675(spi_fd, &raw_temp) == 0) {
            measured = raw_temp * 0.25; // Convert to Celsius
        } else {
            measured = -999.0; // Error value
        }

        double output = pid_controller(setpoint, measured, &integral, &previous_error, 1.0);
        output = output < 0.0 ? 0.0 : (output > 1.0 ? 1.0 : output);

        gpiod_line_set_value(line, output > 0.5);

        fprintf(log_file, "%d,%.2f,%.2f\n", time_seconds, setpoint, measured);
        fflush(log_file);

        sleep(1);
    }

    fclose(log_file);
    fclose(profile_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}
