    char *ptr = strstr(line, "t=");
    if (!ptr) {
        syslog(LOG_ERR, "Failed to find temperature value in sensor data");
        return -1;
    }

    double temp = strtod(ptr + 2, NULL) / 1000.0;
    return temp;
}

void log_data(double timestamp, double temperature, double setpoint, double pid_output, int pwm_duty) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return;
    }

    fprintf(log_file, "%f, %f, %f, %f, %d\n", timestamp, temperature, setpoint, pid_output, pwm_duty);
    fclose(log_file);
}

void cleanup(gpiod_chip *chip, gpiod_line *relay_line, gpiod_line *pwm_line) {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (pwm_line) {
        gpiod_line_release(pwm_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    openlog("greenhouse_heater", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line: %s", strerror(errno));
        cleanup(chip, NULL, NULL);
        return EXIT_FAILURE;
    }

    gpiod_line *pwm_line = gpiod_chip_get_line(chip, PWM_GPIO);
    if (!pwm_line) {
        syslog(LOG_ERR, "Failed to get PWM line: %s", strerror(errno));
        cleanup(chip, relay_line, NULL);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        syslog(LOG_ERR, "Failed to request relay line: %s", strerror(errno));
        cleanup(chip, relay_line, pwm_line);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(pwm_line, "pwm", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to request PWM line: %s", strerror(errno));
        cleanup(chip, relay_line, pwm_line);
        return EXIT_FAILURE;
    }

    gpiod_line_set_flags(pwm_line, GPIOD_LINE_FLAG_ACTIVE_LOW);
    gpiod_line_set_request_type(pwm_line, GPIOD_LINE_REQ_TYPE_PULSE);
    gpiod_line_set_period(pwm_line, 1000000 / PWM_FREQ);

    double prev_error = 0, integral = 0;
    int pwm_duty = 0;

    while (!stop) {
        double temperature = read_temperature(TEMP_SENSOR_PATH);
        if (temperature < 0) {
            syslog(LOG_WARNING, "Temperature read error, skipping cycle");
            sleep(5);
            continue;
        }

        double error = setpoint - temperature;
        integral += error;
        double derivative = error - prev_error;
        double output = Kp * error + Ki * integral + Kd * derivative;

        if (output < 0) {
            output = 0;
        } else if (output > 100) {
            output = 100;
        }

        pwm_duty = (int)(output * (1000000 / PWM_FREQ));
        gpiod_line_set_pulses(pwm_line, pwm_duty);

        if (output > 0) {
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }

        double timestamp = time(NULL);
        log_data(timestamp, temperature, setpoint, output, pwm_duty);

        prev_error = error;
        sleep(5);
    }

    gpiod_line_set_value(relay_line, 0);
    gpiod_line_set_pulses(pwm_line, 0);

    cleanup(chip, relay_line, pwm_line);
    closelog();

    return EXIT_SUCCESS;
}

