#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60
#define HUMIDITY_THRESHOLD_LOW 55
#define RETRY_LIMIT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 5000
#define MEASURE_DELAY_MS 80

static int i2c_fd = -1;
static int gpio_fd = -1;
static struct gpiod_line *relay_line = NULL;

void cleanup_and_exit(int signum) {
    if (relay_line) {
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (gpio_fd != -1) {
        close(gpio_fd);
        gpio_fd = -1;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(0);
}

int i2c_write_bytes(uint8_t *data, size_t length) {
    for (int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
        if (write(i2c_fd, data, length) == length) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int i2c_read_bytes(uint8_t *buffer, size_t length) {
    for (int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
        if (read(i2c_fd, buffer, length) == length) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int initialize_sensor() {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    return i2c_write_bytes(init_cmd, sizeof(init_cmd));
}

int trigger_measurement() {
    uint8_t measure_cmd[] = {0xAC, 0x33, 0x00};
    return i2c_write_bytes(measure_cmd, sizeof(measure_cmd));
}

int read_humidity(float *humidity) {
    uint8_t buffer[6];
    if (i2c_read_bytes(buffer, sizeof(buffer)) != 0) {
        return -1;
    }

    if ((buffer[0] & 0x03) != 0x03) {
        return -1; // Sensor not calibrated or busy
    }

    uint32_t raw_humidity = (buffer[3] << 16) | (buffer[4] << 8) | buffer[5];
    *humidity = (raw_humidity * 100.0) / 0x100000;
    return 0;
}

void set_relay(int state) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, state);
    }
}

int main() {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(gpio_fd, GPIO_RELAY);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "dehumidifier_relay", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(relay_line);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        gpiod_line_release(relay_line);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(relay_line);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    if (initialize_sensor() != 0) {
        fprintf(stderr, "Failed to initialize AHT20 sensor\n");
    }

    while (1) {
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
        }

        usleep(MEASURE_DELAY_MS * 1000);

        float humidity;
        if (read_humidity(&humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Humidity: %.2f%%\n", time_str, humidity);

            if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                set_relay(1);
            } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                set_relay(0);
            }
        } else {
            fprintf(stderr, "Failed to read humidity\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_and_exit(0);
    return 0;
}

