#include <errno.h>
#include <netdb.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x40
#define HTU21D_CMD_MEASURE_RH 0xF5
#define HTU21D_CMD_READ_DATA 0xE7
#define HTU21D_CRC_POLYNOMIAL 0x131
#define API_URL "http://api.example.com/humidity"
#define API_PORT 80

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ HTU21D_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_humidity(int i2c_fd, float *humidity) {
    uint8_t cmd = HTU21D_CMD_MEASURE_RH;
    if (write(i2c_fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "Failed to write measurement command: %s", strerror(errno));
        return -1;
    }

    usleep(10000); // Wait for measurement to complete

    uint8_t data[3];
    if (read(i2c_fd, data, 3) != 3) {
        syslog(LOG_ERR, "Failed to read data: %s", strerror(errno));
        return -1;
    }

    uint8_t crc = calculate_crc8(data, 2);
    if (crc != data[2]) {
        syslog(LOG_ERR, "CRC mismatch");
        return -1;
    }

    int raw = (data[0] << 8) | data[1];
    if (raw == 0x8000) {
        syslog(LOG_ERR, "Sensor saturation");
        return -1;
    }

    *humidity = -6.0 + 125.0 * (raw / 65536.0);
    return 0;
}

int post_humidity(float humidity) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(API_PORT);

    if (inet_pton(AF_INET, "93.184.216.34", &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char request[256];
    snprintf(request, sizeof(request),
             "POST /humidity HTTP/1.1\r\n"
             "Host: api.example.com\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n\r\n"
             "{\"humidity\": %.2f}",
             strlen("{\"humidity\": %.2f}") + sizeof(float), humidity);

    if (write(sock, request, strlen(request)) < 0) {
        syslog(LOG_ERR, "Failed to send request: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char response[1024];
    int bytes_received = read(sock, response, sizeof(response) - 1);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Failed to read response: %s", strerror(errno));
        close(sock);
        return -1;
    }
    response[bytes_received] = '\0';

    close(sock);
    return 0;
}

int main() {
    openlog("humidity_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        float humidity;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }
        sleep(60);
    }

    close(i2c_fd);
    closelog();
    return EXIT_SUCCESS;
}

