    return i2c_read_i2c_block_data(i2c_handle, BMP280_I2C_ADDR, BMP280_CALIBRATION_START_REG, 24, calib_data);
}

double calculate_pressure(unsigned char *calib_data, unsigned int raw_pressure) {
    // Extract calibration data
    int16_t dig_P1 = (calib_data[1] << 8) | calib_data[0];
    int16_t dig_P2 = (calib_data[3] << 8) | calib_data[2];
    int16_t dig_P3 = (calib_data[5] << 8) | calib_data[4];
    int16_t dig_P4 = (calib_data[7] << 8) | calib_data[6];
    int16_t dig_P5 = (calib_data[9] << 8) | calib_data[8];
    int16_t dig_P6 = (calib_data[11] << 8) | calib_data[10];
    int16_t dig_P7 = (calib_data[13] << 8) | calib_data[12];
    int16_t dig_P8 = (calib_data[15] << 8) | calib_data[14];
    int16_t dig_P9 = (calib_data[17] << 8) | calib_data[16];

    // Compensation formula
    int32_t var1, var2, p;
    var1 = ((int32_t)raw_pressure / 256.0) - ((int32_t)dig_P6 << 7);
    var2 = (((int32_t)dig_P5) * ((int32_t)var1)) >> 15;
    var2 = var2 + (((int32_t)dig_P4) << 20);
    var2 = var2 + (((int32_t)dig_P3) * ((int32_t)var1)) >> 8;
    var1 = (((int32_t)var1 * ((int32_t)var1)) >> 12) * ((int32_t)dig_P2) >> 13;
    var1 = ((int32_t)var1 + ((int32_t)dig_P1) << 16) >> 15;
    if (var1 == 0) {
