#define AHT20_MEASURE_CMD 0xAC, 0x33, 0x00
#define PIR_GPIO_CHIP 4
#define PIR_GPIO_LINE 17
#define I2C_DEVICE "/dev/i2c-1"
#define MAX_RETRIES 3
#define BACKOFF_MS 10

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_device(int addr) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write I2C register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read I2C register");
        return -1;
    }

    return 0;
}

int write_i2c_bytes(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != len) {
        perror("Failed to write I2C bytes");
        return -1;
    }
    return 0;
}

int read_tmp117_temperature(int fd) {
    uint8_t buf[2];
    int16_t raw_temp;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (read_i2c_register(fd, TMP117_TEMP_REG, buf, 2) == 0) {
            raw_temp = (buf[0] << 8) | buf[1];
            return raw_temp * 0.0078125;
        }
        retries++;
        usleep(BACKOFF_MS * 1000);
    }

    fprintf(stderr, "Failed to read TMP117 temperature after %d retries\n", MAX_RETRIES);
    return -1;
}

int read_aht20_humidity_and_temperature(int fd) {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    uint8_t measure_cmd[] = {0xAC, 0x33, 0x00};
    uint8_t buf[7];
    int retries = 0;

    if (write_i2c_bytes(fd, init_cmd, sizeof(init_cmd)) < 0) {
        return -1;
    }

    while (retries < MAX_RETRIES) {
        if (write_i2c_bytes(fd, measure_cmd, sizeof(measure_cmd)) < 0) {
            return -1;
        }

        if (read(fd, buf, sizeof(buf)) == sizeof(buf)) {
            if (!(buf[0] & 0x80)) { // Check busy bit
                int16_t raw_humidity = ((buf[1] << 8) | buf[2]) >> 4;
                int16_t raw_temperature = (((buf[3] & 0x0F) << 8) | buf[4]) >> 4;
                return (raw_humidity * 100.0 / 0xFFFF) - 1000, (raw_temperature * 200.0 / 0xFFFF) - 1000;
            }
        }
        retries++;
        usleep(BACKOFF_MS * 1000);
    }

    fprintf(stderr, "Failed to read AHT20 data after %d retries\n", MAX_RETRIES);
    return -1, -1;
}

int setup_pir_sensor() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_number(PIR_GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(line, "PIR Sensor") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

int read_pir_sensor() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    chip = gpiod_chip_open_by_number(PIR_GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    value = gpiod_line_get_value(line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return value;
}

void create_new_log_file(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to create log file");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    fclose(file);
}

void log_data(const char *filename, double temperature, double humidity, int motion) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_pir_sensor() < 0) {
        fprintf(stderr, "PIR sensor setup failed\n");
        return EXIT_FAILURE;
    }

    int tmp117_fd = open_i2c_device(TMP117_I2C_ADDR);
    if (tmp117_fd < 0) {
        fprintf(stderr, "TMP117 sensor not found\n");
    }

    int aht20_fd = open_i2c_device(AHT20_I2C_ADDR);
    if (aht20_fd < 0) {
        fprintf(stderr, "AHT20 sensor not found\n");
    }

    char log_filename[256];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(log_filename, sizeof(log_filename), "/tmp/sensor_log_%Y-%m-%d.csv", tm_info);
    create_new_log_file(log_filename);

    while (!stop) {
        double temperature = -1.0;
        double humidity = -1.0;
        int motion = 0;

        if (tmp117_fd >= 0) {
            temperature = read_tmp117_temperature(tmp117_fd);
        }

        if (aht20_fd >= 0) {
            humidity = read_aht20_humidity_and_temperature(aht20_fd);
        }

        motion = read_pir_sensor();

        log_data(log_filename, temperature, humidity, motion);

        sleep(1);

        now = time(NULL);
        struct tm *new_tm_info = localtime(&now);
        if (tm_info->tm_mday != new_tm_info->tm_mday) {
            fclose(log_filename);
            strftime(log_filename, sizeof(log_filename), "/tmp/sensor_log_%Y-%m-%d.csv", new_tm_info);
            create_new_log_file(log_filename);
            tm_info = new_tm_info;
        }
    }

    if (tmp117_fd >= 0) {
        close(tmp117_fd);
    }
    if (aht20_fd >= 0) {
        close(aht20_fd);
    }

    return EXIT_SUCCESS;
}

