#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL 2
#define MOTOR_RUN_TIME 5

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *event) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", timestamp, event);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *rain_sensor_line, *motor_ena_line, *motor_in1_line, *motor_in2_line;
    int value;

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get lines
    rain_sensor_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    if (!rain_sensor_line) {
        perror("Failed to get rain sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_ena_line = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    if (!motor_ena_line) {
        perror("Failed to get motor ENA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    if (!motor_in1_line) {
        perror("Failed to get motor IN1 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);
    if (!motor_in2_line) {
        perror("Failed to get motor IN2 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure lines
    if (gpiod_line_request_input(rain_sensor_line, "rain_sensor") < 0) {
        perror("Failed to request rain sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_ena_line, "motor_ena", 0) < 0) {
        perror("Failed to request motor ENA line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_in1_line, "motor_in1", 0) < 0) {
        perror("Failed to request motor IN1 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_in2_line, "motor_in2", 0) < 0) {
        perror("Failed to request motor IN2 line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (keep_running) {
        // Read rain sensor
        value = gpiod_line_get_value(rain_sensor_line);
        if (value < 0) {
            perror("Failed to read rain sensor value");
            break;
        }

        if (value == 0) { // Rain detected
            log_event("Rain detected");

            // Set motor direction to forward
            if (gpiod_line_set_value(motor_in1_line, 1) < 0) {
                perror("Failed to set motor IN1 line");
                break;
            }

            if (gpiod_line_set_value(motor_in2_line, 0) < 0) {
                perror("Failed to set motor IN2 line");
                break;
            }

            // Enable motor
            if (gpiod_line_set_value(motor_ena_line, 1) < 0) {
                perror("Failed to set motor ENA line");
                break;
            }

            // Run motor for 5 seconds
            sleep(MOTOR_RUN_TIME);

            // Disable motor
            if (gpiod_line_set_value(motor_ena_line, 0) < 0) {
                perror("Failed to set motor ENA line");
                break;
            }

            log_event("Motor stopped");
        }

        // Poll every 2 seconds
        sleep(POLL_INTERVAL);
    }

    // Cleanup
    gpiod_line_release(rain_sensor_line);
    gpiod_line_release(motor_ena_line);
    gpiod_line_release(motor_in1_line);
    gpiod_line_release(motor_in2_line);
    gpiod_chip_close(chip);

    log_event("Program exited");

    return EXIT_SUCCESS;
}

