#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define SAMPLE_INTERVAL 500 // milliseconds

volatile sig_atomic_t terminate = 0;

void handle_signal(int sig) {
    terminate = 1;
}

double get_cpu_load() {
    FILE *fp;
    char buffer[256];
    double idle1, idle2, total1, total2, load;

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open /proc/stat\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        return -1;
    }
    fclose(fp);

    sscanf(buffer, "cpu %lf %*d %*d %*d %lf %*d %*d %*d %*d", &total1, &idle1);

    sleep(SAMPLE_INTERVAL / 1000.0);

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open /proc/stat\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        return -1;
    }
    fclose(fp);

    sscanf(buffer, "cpu %lf %*d %*d %*d %lf %*d %*d %*d %*d", &total2, &idle2);

    double total_diff = total2 - total1;
    double idle_diff = idle2 - idle1;

    if (total_diff == 0) {
        return 0;
    }

    load = (total_diff - idle_diff) / total_diff;
    return load;
}

void set_rgb_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    while (!terminate) {
        double load = get_cpu_load();
        if (load < 0) {
            fprintf(stderr, "Error reading CPU load\n");
            break;
        }

        int red = (int)(load * 255);
        int green = (int)((1.0 - load) * 255);
        int blue = 0;

        set_rgb_color(red, green, blue);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Turn off the LED
    set_rgb_color(0, 0, 0);

    gpioTerminate();
    return 0;
}

