#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <json-c/json.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REG 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIB_START_REG 0x88
#define BMP280_CALIB_END_REG 0xA1
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_PRESSURE_MSB_REG 0xF7
#define BMP280_FORCED_MODE 0x34
#define UDP_PORT 5000
#define UDP_IP "192.168.1.100"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_udp_socket() {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(UDP_PORT);
    servaddr.sin_addr.s_addr = inet_addr(UDP_IP);

    return sockfd;
}

int send_udp_data(int sockfd, const char *data) {
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(UDP_PORT);
    servaddr.sin_addr.s_addr = inet_addr(UDP_IP);

    int len = strlen(data);
    int n = sendto(sockfd, data, len, 0, (const struct sockaddr *)&servaddr, sizeof(servaddr));
    if (n < 0) {
        perror("sendto failed");
        return -1;
    }
    return 0;
}

int read_i2c_byte(int pi, uint8_t reg) {
    int fd = i2c_open(pi, BMP280_I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    int result = i2c_read_byte_data(fd, reg);
    i2c_close(fd);
    if (result < 0) {
        fprintf(stderr, "Failed to read I2C byte\n");
        return -1;
    }
    return result;
}

int read_i2c_block(int pi, uint8_t reg, uint8_t *buf, int len) {
    int fd = i2c_open(pi, BMP280_I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    int result = i2c_read_i2c_block_data(fd, reg, buf, len);
    i2c_close(fd);
    if (result < 0) {
        fprintf(stderr, "Failed to read I2C block\n");
        return -1;
    }
    return 0;
}

int write_i2c_byte(int pi, uint8_t reg, uint8_t value) {
    int fd = i2c_open(pi, BMP280_I2C_ADDR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    int result = i2c_write_byte_data(fd, reg, value);
    i2c_close(fd);
    if (result < 0) {
        fprintf(stderr, "Failed to write I2C byte\n");
        return -1;
    }
    return 0;
}

int read_temperature_and_pressure(int pi, int *temperature, int *pressure) {
    uint8_t data[6];
    if (write_i2c_byte(pi, BMP280_CTRL_MEAS_REG, BMP280_FORCED_MODE) < 0) {
        return -1;
    }

    usleep(10000); // Wait for measurement to complete

    if (read_i2c_block(pi, BMP280_PRESSURE_MSB_REG, data, 6) < 0) {
        return -1;
    }

    int32_t adc_p = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    int32_t adc_t = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    // Calibration data
    uint8_t calib[26];
    if (read_i2c_block(pi, BMP280_CALIB_START_REG, calib, 26) < 0) {
        return -1;
    }

    int32_t dig_T1 = (int32_t)calib[1] << 8 | calib[0];
    int32_t dig_T2 = (int32_t)calib[3] << 8 | calib[2];
    int32_t dig_T3 = (int32_t)calib[5] << 8 | calib[4];

    int32_t dig_P1 = (int32_t)calib[7] << 8 | calib[6];
    int32_t dig_P2 = (int32_t)calib[9] << 8 | calib[8];
    int32_t dig_P3 = (int32_t)calib[11] << 8 | calib[10];
    int32_t dig_P4 = (int32_t)calib[13] << 8 | calib[12];
    int32_t dig_P5 = (int32_t)calib[15] << 8 | calib[14];
    int32_t dig_P6 = (int32_t)calib[17] << 8 | calib[16];
    int32_t dig_P7 = (int32_t)calib[19] << 8 | calib[18];
    int32_t dig_P8 = (int32_t)calib[21] << 8 | calib[20];
    int32_t dig_P9 = (int32_t)calib[23] << 8 | calib[22];

    int32_t t_fine;

    // Temperature calculation
    int32_t var1 = ((((adc_t >> 3) - ((int32_t)dig_T1 << 1))) * ((int32_t)dig_T2)) >> 11;
    int32_t var2 = (((((adc_t >> 4) - ((int32_t)dig_T1)) * ((adc_t >> 4) - ((int32_t)dig_T1))) >> 12) * ((int32_t)dig_T3)) >> 14;
    t_fine = var1 + var2;
    *temperature = (t_fine * 5 + 128) >> 8;

    // Pressure calculation
    int64_t var1 = ((int64_t)t_fine) - 128000;
    int64_t var2 = var1 * var1 * (int64_t)dig_P6;
    var2 = var2 + ((var1 * (int64_t)dig_P5) << 17);
    var2 = var2 + (((int64_t)dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)dig_P3) >> 8) + ((var1 * (int64_t)dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)dig_P1) >> 33;
    if (var1 == 0) {
        return -1; // Avoid division by zero
    }
    int64_t p = 1048576 - adc_p;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)dig_P7) << 4);
    *pressure = (int32_t)p;

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    int pi = pigpio_get_instance();
    if (pi < 0) {
        fprintf(stderr, "Failed to get pigpio instance\n");
        gpioTerminate();
        return -1;
    }

    int chip_id = read_i2c_byte(pi, BMP280_CHIP_ID_REG);
    if (chip_id < 0 || chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "BMP280 not found or invalid chip ID\n");
        gpioTerminate();
        return -1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sockfd = setup_udp_socket();
    if (sockfd < 0) {
        gpioTerminate();
        return -1;
    }

    while (keep_running) {
        int temperature, pressure;
        if (read_temperature_and_pressure(pi, &temperature, &pressure) < 0) {
            fprintf(stderr, "Failed to read temperature and pressure\n");
            break;
        }

        json_object *jobj = json_object_new_object();
        json_object *jtemp = json_object_new_int(temperature);
        json_object *jpres = json_object_new_int(pressure);
        json_object_object_add(jobj, "temperature", jtemp);
        json_object_object_add(jobj, "pressure", jpres);

        const char *json_str = json_object_to_json_string(jobj);
        if (send_udp_data(sockfd, json_str) < 0) {
            fprintf(stderr, "Failed to send UDP data\n");
            break;
        }

        json_object_put(jobj);
        sleep(5);
    }

    close(sockfd);
    gpioTerminate();
    return 0;
}

