#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <pigpio.h>

#define GPIO_FAN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    double temperature;
    int pwm_duty;
} LogEntry;

volatile sig_atomic_t keep_running = 1;
LogEntry log_buffer[BUFFER_SIZE];
int log_index = 0;

void handle_sigint(int sig) {
    keep_running = 0;
}

int calculate_pwm_duty(double temperature) {
    if (temperature < 25.0) {
        return 0;
    } else if (temperature < 40.0) {
        return (int)((temperature - 25.0) * (50.0 / 15.0));
    } else if (temperature < 60.0) {
        return 50 + (int)((temperature - 40.0) * (150.0 / 20.0));
    } else {
        return 255;
    }
}

void log_entry(double temperature, int pwm_duty) {
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].temperature = temperature;
    log_buffer[log_index].pwm_duty = pwm_duty;
    log_index = (log_index + 1) % BUFFER_SIZE;
}

void print_log_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %ld, Temperature: %.2f°C, PWM Duty: %d%%\n",
