    int result = i2c_read_byte_data(pi, BMP180_ADDRESS, reg);
    if (result == -1) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return result;
}

int write_i2c_byte(int pi, uint8_t reg, uint8_t value) {
    int result = i2c_write_byte_data(pi, BMP180_ADDRESS, reg, value);
    if (result == -1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return result;
}

float read_temperature(int pi) {
    write_i2c_byte(pi, 0xF4, 0x2E); // Start temperature measurement
    usleep(5000); // Wait for conversion

    uint8_t msb = read_i2c_byte(pi, 0xF6);
    uint8_t lsb = read_i2c_byte(pi, 0xF7);
    int raw_temp = ((msb << 8) | lsb) >> 4;

    int ac5 = read_i2c_byte(pi, 0xAC);
    int ac6 = read_i2c_byte(pi, 0xAE);
    int mc = read_i2c_byte(pi, 0xBC);
    int md = read_i2c_byte(pi, 0xBE);

    int x1 = (raw_temp - ac6) * ac5 >> 15;
    int x2 = mc << 11 / (x1 + md);
    int b5 = x1 + x2;
    float temperature = (b5 + 8) >> 4 / 10.0;

    return temperature;
}

float read_pressure(int pi) {
    write_i2c_byte(pi, 0xF4, 0x34 + (OSS << 6)); // Start pressure measurement
    usleep(2 << (OSS + 1) * 1000); // Wait for conversion

    uint8_t msb = read_i2c_byte(pi, 0xF6);
    uint8_t lsb = read_i2c_byte(pi, 0xF7);
    uint8_t xlsb = read_i2c_byte(pi, 0xF8);
    int raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);

    int ac1 = read_i2c_byte(pi, 0xAA) << 8 | read_i2c_byte(pi, 0xAB);
    int ac2 = read_i2c_byte(pi, 0xAC) << 8 | read_i2c_byte(pi, 0xAD);
    int ac3 = read_i2c_byte(pi, 0xAE) << 8 | read_i2c_byte(pi, 0xAF);
    int ac4 = read_i2c_byte(pi, 0xB0) << 8 | read_i2c_byte(pi, 0xB1);
    int ac5 = read_i2c_byte(pi, 0xB2) << 8 | read_i2c_byte(pi, 0xB3);
    int ac6 = read_i2c_byte(pi, 0xB4) << 8 | read_i2c_byte(pi, 0xB5);
    int b1 = read_i2c_byte(pi, 0xB6) << 8 | read_i2c_byte(pi, 0xB7);
    int b2 = read_i2c_byte(pi, 0xB8) << 8 | read_i2c_byte(pi, 0xB9);
    int mb = read_i2c_byte(pi, 0xBA) << 8 | read_i2c_byte(pi, 0xBB);
    int mc = read_i2c_byte(pi, 0xBC) << 8 | read_i2c_byte(pi, 0xBD);
    int md = read_i2c_byte(pi, 0xBE) << 8 | read_i2c_byte(pi, 0xBF);

    int b6 = b5 - 4000;
    int x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    int x2 = ac2 * b6 >> 11;
    int x3 = x1 + x2;
    int b3 = (((ac1 * 4 + x3) << OSS) + 2) >> 2;
    x1 = ac3 * b6 >> 13;
    x2 = (b1 * (b6 * b6 >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - b3) * (50000 >> OSS);
    int p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return p / 100.0;
}

