#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_CR0_REG 0x01
#define MAX31865_FAULT_REG 0x07
#define MAX31865_SR_REG 0x08
#define MAX31865_LSB_REG 0x09
#define MAX31865_MSB_REG 0x0A
#define MAX31865_XLSB_REG 0x0B

#define MAX31865_CONFIG_3WIRE 0x60
#define MAX31865_CR0_1V 0x80

#define RTD_NOMINAL 100.0
#define RTD_RESISTANCE 100.0
#define CALLANDER_VAN_DUSEN_A 3.9083e-3
#define CALLANDER_VAN_DUSEN_B -5.775e-7
#define CALLANDER_VAN_DUSEN_C -4.183e-12

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_spi(int *fd) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long) &MAX31865_CONFIG_REG,
        .rx_buf = (unsigned long) NULL,
        .len = 1,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        return -1;
    }

    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(*fd);
        return -1;
    }

    uint8_t config = MAX31865_CONFIG_3WIRE | MAX31865_CR0_1V;
    transfer.tx_buf = (unsigned long) &config;
    if (ioctl(*fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Failed to write to SPI device");
        close(*fd);
        return -1;
    }

    return 0;
}

int read_max31865(int fd, uint8_t reg, uint16_t *value) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long) &reg,
        .rx_buf = (unsigned long) value,
        .len = 2,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    return 0;
}

double calculate_temperature(uint16_t rtd) {
    double rtd_resistance = (rtd * 0.0078125);
    double logRt = log(rtd_resistance);
    double R0 = RTD_NOMINAL;
    double temp = -CALLANDER_VAN_DUSEN_B + sqrt(CALLANDER_VAN_DUSEN_B * CALLANDER_VAN_DUSEN_B - 4 * CALLANDER_VAN_DUSEN_C * (CALLANDER_VAN_DUSEN_A - logRt));
    temp = 1 / (CALLANDER_VAN_DUSEN_A + temp / 2) - 273.15;
    return temp;
}

int main() {
    int spi_fd = -1;
    int cs_fd = -1;
    FILE *log_file = NULL;
    struct timespec ts = {5, 0};

    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handlers\n");
        return EXIT_FAILURE;
    }

    if (setup_spi(&spi_fd) != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("rtd_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Temperature\n");

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    gpiod_line *line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(spi_fd);
        return EXIT_FAILURE;
    }

