                       (i2cReadByteData(i2c_handle, BMP180_REG_PRESSURE_LSB) << 8) |
                       i2cReadByteData(i2c_handle, BMP180_REG_PRESSURE_XLSB);

    int b6 = 0;
    int x1 = ((raw_pressure >> 3) - (ac6 << 1)) * ac5 >> 15;
    int x2 = (mc << 11) / (x1 + md);
    b6 = x1 + x2;
    int x3 = ((b2 * ((b6 * b6) >> 12)) >> 11) + ((ac2 * b6) >> 11);
    int x4 = (ac3 * b6) >> 13;
    int b5 = (x3 + x4) >> 3;
    int b4 = (ac4 * (unsigned long)(b5 + 32768)) >> 15;
    int b7 = ((unsigned long)(raw_pressure << 12) - b4) * (unsigned long)(6250 >> BMP180_OSS_0);
