#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <json-c/json.h>
#include <pigpio.h>

#define GPIO_HEATER 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 1
#define SPI_CS 0
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_CONFIG_VALUE 0xC1
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07
#define MAX31865_FAULT_MASK 0x1F
#define MAX31865_FAULT_OPEN 0x01
#define MAX31865_FAULT_SHORT 0x02
#define MAX31865_FAULT_OVERV 0x04
#define MAX31865_FAULT_UNDERR 0x08
#define R_REF 430.0
#define R0 100.0
#define A 3.9083e-3
#define B -5.775e-7
#define TARGET_TEMP_DEFAULT 25.0
#define KP_DEFAULT 1.0
#define KI_DEFAULT 0.1
#define KD_DEFAULT 0.01
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define CONTROL_INTERVAL 100
#define MAX_TEMP 80.0

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

double read_temperature() {
    uint16_t msb, lsb;
    uint8_t fault;

    if (gpioSPIReadReg(SPI_CHANNEL, SPI_CS, MAX31865_RTD_MSB_REG, &msb, 1) < 0 ||
        gpioSPIReadReg(SPI_CHANNEL, SPI_CS, MAX31865_RTD_LSB_REG, &lsb, 1) < 0 ||
        gpioSPIReadReg(SPI_CHANNEL, SPI_CS, MAX31865_FAULT_REG, &fault, 1) < 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    if (fault & MAX31865_FAULT_MASK) {
        fprintf(stderr, "MAX31865 fault detected: 0x%02X\n", fault);
        return -1;
    }

    uint16_t rtd_code = (msb << 8) | lsb;
    double r_rtd = (rtd_code / 32768.0) * R_REF;
    double t = (r_rtd / R0 - 1) / (A + B * (r_rtd / R0 - 1));
    return t;
}

void load_config(const char *filename, double *target_temp, double *kp, double *ki, double *kd) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        *target_temp = TARGET_TEMP_DEFAULT;
        *kp = KP_DEFAULT;
        *ki = KI_DEFAULT;
        *kd = KD_DEFAULT;
        return;
    }

    struct json_object *parsed_json;
    struct json_object *target_temp_obj, *kp_obj, *ki_obj, *kd_obj;
    char buffer[1024];

    fread(buffer, 1, sizeof(buffer), file);
    fclose(file);

    parsed_json = json_tokener_parse(buffer);
    json_object_object_get_ex(parsed_json, "target_temp", &target_temp_obj);
    json_object_object_get_ex(parsed_json, "kp", &kp_obj);
    json_object_object_get_ex(parsed_json, "ki", &ki_obj);
    json_object_object_get_ex(parsed_json, "kd", &kd_obj);

    *target_temp = json_object_get_double(target_temp_obj) != 0 ? json_object_get_double(target_temp_obj) : TARGET_TEMP_DEFAULT;
    *kp = json_object_get_double(kp_obj) != 0 ? json_object_get_double(kp_obj) : KP_DEFAULT;
    *ki = json_object_get_double(ki_obj) != 0 ? json_object_get_double(ki_obj) : KI_DEFAULT;
    *kd = json_object_get_double(kd_obj) != 0 ? json_object_get_double(kd_obj) : KD_DEFAULT;

    json_object_put(parsed_json);
}

void pid_control(double target_temp, double kp, double ki, double kd) {
    static double prev_error = 0;
    static double integral = 0;
    double error, derivative, output;
    double temperature = read_temperature();

    if (temperature < 0 || temperature > MAX_TEMP) {
        gpioPWMSetRange(GPIO_HEATER, PWM_RANGE);
        gpioPWMSetClock(GPIO_HEATER, PWM_FREQUENCY);
        gpioPWMSet(GPIO_HEATER, 0);
        exit(EXIT_FAILURE);
    }

    error = target_temp - temperature;
    integral += error;
    derivative = error - prev_error;
    output = kp * error + ki * integral + kd * derivative;

    if (output < 0) output = 0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    gpioPWMSet(GPIO_HEATER, (int)output);
    prev_error = error;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSPIClassSetup(SPI_CHANNEL, 0, 0, 0, 0) < 0) {
        fprintf(stderr, "Failed to setup SPI class\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSPIWriteReg(SPI_CHANNEL, SPI_CS, MAX31865_CONFIG_REG, MAX31865_CONFIG_VALUE, 1) < 0) {
        fprintf(stderr, "Failed to write to MAX31865 config register\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double target_temp, kp, ki, kd;
    load_config("config.json", &target_temp, &kp, &ki, &kd);

    gpioPWMSetRange(GPIO_HEATER, PWM_RANGE);
    gpioPWMSetClock(GPIO_HEATER, PWM_FREQUENCY);

    while (!stop) {
        pid_control(target_temp, kp, ki, kd);
        usleep(CONTROL_INTERVAL * 1000);
    }

    gpioPWMSet(GPIO_HEATER, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

