#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define BMP180_I2C_ADDR 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_TEMP 0xF6
#define BMP180_REG_PRESSURE 0xF6
#define BMP180_REG_RESULT 0xF6
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_CONFIG 0xF5
#define BMP180_REG_AC1 0xAA
#define BMP180_REG_AC2 0xAC
#define BMP180_REG_AC3 0xAE
#define BMP180_REG_AC4 0xB0
#define BMP180_REG_AC5 0xB2
#define BMP180_REG_AC6 0xB4
#define BMP180_REG_B1 0xB6
#define BMP180_REG_B2 0xB8
#define BMP180_REG_MB 0xBA
#define BMP180_REG_MC 0xBC
#define BMP180_REG_MD 0xBE
#define BMP180_REG_CONTROL_MEASUREMENT 0xF4
#define BMP180_REG_CONFIG 0xF5
#define BMP180_REG_RESULT 0xF6
#define BMP180_MODE_ULTRALOWPOWER 0x74
#define BMP180_MODE_STANDARD 0x74
#define BMP180_MODE_HIGHRES 0x74
#define BMP180_MODE_ULTRAHIGHRES 0x74

#define TEMP_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0

#define MAX_RETRIES 3

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_device(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_block_data(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int write_i2c_byte_data(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

int read_calibration_data(int fd, int16_t *ac1, int16_t *ac2, int16_t *ac3, uint16_t *ac4, uint16_t *ac5, uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mb, int16_t *mc, int16_t *md) {
    uint8_t buf[22];
    if (read_i2c_block_data(fd, BMP180_REG_CALIB, buf, 22) < 0) {
        return -1;
    }

    *ac1 = (buf[0] << 8) | buf[1];
    *ac2 = (buf[2] << 8) | buf[3];
    *ac3 = (buf[4] << 8) | buf[5];
    *ac4 = (buf[6] << 8) | buf[7];
    *ac5 = (buf[8] << 8) | buf[9];
    *ac6 = (buf[10] << 8) | buf[11];
    *b1 = (buf[12] << 8) | buf[13];
    *b2 = (buf[14] << 8) | buf[15];
    *mb = (buf[16] << 8) | buf[17];
    *mc = (buf[18] << 8) | buf[19];
    *md = (buf[20] << 8) | buf[21];

    return 0;
}

int read_temperature(int fd, int16_t *temperature) {
    uint8_t buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write_i2c_byte_data(fd, BMP180_REG_CONTROL_MEASUREMENT, BMP180_MODE_STANDARD) < 0) {
            retries++;
            continue;
        }

        usleep(5000); // Wait for conversion

        if (read_i2c_block_data(fd, BMP180_REG_RESULT, buf, 2) < 0) {
            retries++;
            continue;
        }

        *temperature = (buf[0] << 8) | buf[1];
        return 0;
    }

    return -1;
}

int read_pressure(int fd, int32_t *pressure) {
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write_i2c_byte_data(fd, BMP180_REG_CONTROL_MEASUREMENT, BMP180_MODE_STANDARD) < 0) {
            retries++;
