    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void timer_callback(int gpio, uint32_t level, uint32_t tick) {
    if (!running) return;

    double temperature = read_temperature();
    double pressure = read_pressure();
    time_t now = time(NULL);

    if (temperature == 0.0 || pressure == 0.0) {
        return; // Skip invalid sample
    }

    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].pressure = pressure;
    buffer[buffer_index].timestamp = now;

    if (temperature > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    printf("Time: %ld, Temp: %.2f°C, Pressure: %.2f Pa\n", now, temperature, pressure);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    read_calibration_data();

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    piHiPri(99);
    gpioSetTimerFunc(500, timer_callback, 0);

    while (running) {
        piSleep(1000);
    }

    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
