        fprintf(stderr, "Failed to read calibration data\n");
        exit(EXIT_FAILURE);
    }
    *ac1 = (buffer[0] << 8) | buffer[1];
    // Continue reading other calibration registers similarly...
}

double read_pressure() {
    // Implement BMP180 pressure reading using calibration data and compensation formulas
    // Return the pressure in Pa
    return 101325.0; // Placeholder value
}

