    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_i2c();

    int ac1, ac2, ac3, b1, b2, mb, mc, md;
    unsigned short ac4, ac5, ac6;
    read_calibration_data(&ac1, &ac2, &ac3, &ac4, &ac5, &ac6, &b1, &b2, &mb, &mc, &md);

    while (keep_running) {
        if (logging_enabled) {
            double pressure = read_pressure();
            log_pressure(pressure);
        }
        sleep(LOG_INTERVAL);
    }

    cleanup();
    return 0;
}

