#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <max31855.h>

#define GPIO_RELAY 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define MAX_DUTY_CYCLE 80
#define DEFAULT_TARGET_TEMP 25.0

volatile sig_atomic_t keep_running = 1;
FILE *log_file;
double target_temp = DEFAULT_TARGET_TEMP;
double integral = 0.0;
double last_error = 0.0;
double kp = 1.0; // Proportional gain
double ki = 0.1; // Integral gain
double max_integral = 100.0; // Anti-windup limit

void handle_signal(int signal) {
    keep_running = 0;
}

void log_temperature_and_duty_cycle(double temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

void set_heater_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;
    gpioPWM(GPIO_RELAY, duty_cycle);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(GPIO_RELAY, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPIClass(SPI_CHANNEL, MAX31855_SPI_CLASS) < 0) {
        fprintf(stderr, "Failed to set SPI class\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPIClassSetChannel(SPI_CHANNEL, MAX31855_SPI_CHANNEL) < 0) {
        fprintf(stderr, "Failed to set SPI channel\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heater_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Temperature,DutyCycle\n");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        double temperature = max31855ReadTemp(SPI_CHANNEL);
        if (temperature == MAX31855_FAULT) {
            fprintf(log_file, "Error: MAX31855 fault detected\n");
            set_heater_duty_cycle(0);
            log_temperature_and_duty_cycle(temperature, 0);
            continue;
        }

        double error = target_temp - temperature;
        integral += error;
        if (integral > max_integral) integral = max_integral;
        if (integral < -max_integral) integral = -max_integral;

        double derivative = error - last_error;
        last_error = error;

        double output = kp * error + ki * integral;
        int duty_cycle = (int)(output + 0.5);

        set_heater_duty_cycle(duty_cycle);
        log_temperature_and_duty_cycle(temperature, duty_cycle);

        usleep(100000); // 100 ms loop delay
    }

    set_heater_duty_cycle(0);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

