#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

void cleanup() {
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        cleanup();
        return 1;
    }

    if (gpioPWM(RED_PIN, 255) < 0 ||
        gpioPWM(GREEN_PIN, 255) < 0 ||
        gpioPWM(BLUE_PIN, 255) < 0) {
        fprintf(stderr, "Failed to set PWM\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        cleanup();
        return 1;
    }

    while (!stop_flag) {
        FILE *file = fopen(TEMP_FILE, "r");
        if (!file) {
            fprintf(stderr, "Failed to open temperature file\n");
        } else {
            char buffer[64];
            if (fgets(buffer, sizeof(buffer), file) == NULL || ferror(file)) {
                fprintf(stderr, "Failed to read temperature file\n");
            } else {
                int temp = atoi(buffer);
                int red = 0, green = 0, blue = 0;

                if (temp < 40000) {
                    blue = 255;
                } else if (temp < 60000) {
                    green = 255;
                } else {
                    red = 255;
                }

                if (gpioPWM(RED_PIN, 255 - red) < 0 ||
                    gpioPWM(GREEN_PIN, 255 - green) < 0 ||
                    gpioPWM(BLUE_PIN, 255 - blue) < 0) {
                    fprintf(stderr, "Failed to set PWM values\n");
                } else {
                    printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, red, green, blue);
                }
            }
            fclose(file);
        }
        sleep(0.5);
    }

    cleanup();
    return 0;
}

