#define DHT22_GPIO 4
#define DHT22_MAX_RETRIES 3
#define DHT22_TIMEOUT 1000 // Timeout in milliseconds
#define DHT22_SIGNAL_DURATION 1000 // Signal duration in microseconds

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int read_dht22(float *temperature, float *humidity) {
    unsigned long data[5] = {0};
    int retries = 0;
    int result = -1;

    while (retries < DHT22_MAX_RETRIES && result != 0) {
        if (gpioInitialise() < 0) {
            fprintf(stderr, "Failed to initialize GPIO\n");
            return -1;
        }

        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        usleep(DHT22_SIGNAL_DURATION);
        gpioWrite(DHT22_GPIO, 1);
        usleep(40);
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        if (gpioWaitForEdge(DHT22_GPIO, PI_EDGE_FALLING, DHT22_TIMEOUT) < 0) {
            fprintf(stderr, "Timeout waiting for DHT22 response\n");
            gpioTerminate();
            retries++;
            continue;
