bmp180_calibration_t calibration;

void signal_handler(int sig) {
    if (bmp180_fd != -1) {
        close(bmp180_fd);
    }
    if (pi != -1) {
        gpioTerminate(pi);
    }
    exit(EXIT_SUCCESS);
}

void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
}

int read_calibration_coefficients() {
    unsigned char buffer[22];
    int bytes_read = read_i2c_block_data(pi, BMP180_ADDRESS, BMP180_REG_CALIB, buffer, 22);
    if (bytes_read != 22) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return -1;
    }

    calibration.ac1 = (buffer[0] << 8) | buffer[1];
    calibration.ac2 = (buffer[2] << 8) | buffer[3];
    calibration.ac3 = (buffer[4] << 8) | buffer[5];
    calibration.ac4 = (buffer[6] << 8) | buffer[7];
    calibration.ac5 = (buffer[8] << 8) | buffer[9];
    calibration.ac6 = (buffer[10] << 8) | buffer[11];
    calibration.b1 = (buffer[12] << 8) | buffer[13];
    calibration.b2 = (buffer[14] << 8) | buffer[15];
    calibration.mb = (buffer[16] << 8) | buffer[17];
    calibration.mc = (buffer[18] << 8) | buffer[19];
    calibration.md = (buffer[20] << 8) | buffer[21];

    return 0;
}

int read_raw_pressure() {
    unsigned char control = OSS << 6;
    if (write_i2c_byte_data(pi, BMP180_ADDRESS, BMP180_REG_CONTROL, control) != 1) {
        fprintf(stderr, "Failed to write control register\n");
        return -1;
    }

    usleep(CONVERSION_TIME * 1000);

    unsigned char buffer[2];
    int bytes_read = read_i2c_block_data(pi, BMP180_ADDRESS, BMP180_REG_RESULT, buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read raw pressure\n");
        return -1;
    }

    int32_t raw_pressure = (buffer[0] << 8) | buffer[1];
    return raw_pressure;
}

int32_t calculate_pressure(int32_t raw_pressure) {
    int32_t ut = raw_pressure;
    int32_t up = raw_pressure;

    int32_t x1 = ((ut - calibration.ac6) * calibration.ac5) >> 15;
    int32_t x2 = (calibration.mc << 11) / (x1 + calibration.md);
    int32_t b5 = x1 + x2;

    x1 = (calibration.b2 * ((b5 >> 3) * (b5 >> 3) >> 13)) >> 12;
    x2 = (calibration.ac2 * b5) >> 13;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((calibration.ac1 * 4 + x3) << OSS) + 2) / 4) + 2) >> 2;

    x1 = (calibration.ac3 * b5) >> 13;
    x2 = (calibration.b1 * ((b5 >> 2) * (b5 >> 2) >> 13)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    int32_t b6 = b5 - x3;

    x1 = (calibration.b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = (calibration.ac2 * b6) >> 11;
    x3 = x1 + x2;
    int32_t x4 = (calibration.ac1 * 4 + x3) << OSS;
    x3 = (calibration.b1 * ((b6 * b6) >> 12)) >> 16;
    x4 = ((x4 + (x3 << 2)) + 2) >> 2;
    x1 = calibration.ac3 * b6 >> 13;
    x2 = (calibration.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    int32_t b4 = (calibration.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return p / 100; // Convert to hPa
}

