        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(button_gpio, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(button_gpio, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(button_gpio, PI_FALLING_EDGE, button_isr) < 0) {
        fprintf(stderr, "Failed to set ISR\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    bmp180_fd = i2c_open(pi, 1, BMP180_ADDRESS);
    if (bmp180_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    if (read_calibration_coefficients() != 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        i2c_close(bmp180_fd);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(bmp180_fd);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    while (1) {
        if (logging_enabled) {
            int32_t raw_pressure = read_raw_pressure();
            if (raw_pressure < 0) {
                fprintf(stderr, "Failed to read raw pressure\n");
                continue;
            }

            int32_t pressure = calculate_pressure(raw_pressure);
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s: %d hPa\n", time_str, pressure);
            fflush(log_file);
        } else {
            printf("Logging is currently disabled.\n");
        }

        sleep(2);
    }

    fclose(log_file);
    i2c_close(bmp180_fd);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
}

