    }

    if (read_calibration_coefficients() != 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        i2c_close(bmp180_fd);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(bmp180_fd);
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    while (1) {
        if (logging_enabled) {
            int32_t raw_pressure = read_raw_pressure();
            if (raw_pressure < 0) {
                fprintf(stderr, "Failed to read raw pressure\n");
                continue;
            }

            int32_t pressure = calculate_pressure(raw_pressure);
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s: %d hPa\n", time_str, pressure);
            fflush(log_file);
        } else {
            printf("Logging is currently disabled.\n");
        }

        sleep(2);
    }

    fclose(log_file);
    i2c_close(bmp180_fd);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
}
