#define DHT22_GPIO 4
#define DHT22_TIMEOUT 1000
#define DHT22_MAX_RETRIES 3
#define DHT22_RETRY_DELAY 2000
#define READ_INTERVAL 10

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_dht22(float *humidity) {
    unsigned long response[5] = {0};
    int retries = 0;
    int res;

    while (retries < DHT22_MAX_RETRIES) {
        // Send start signal
        if (gpioWrite(DHT22_GPIO, 0) < 0) {
            syslog(LOG_ERR, "Failed to write GPIO low");
            return -1;
        }
        usleep(1000); // 1 ms

        if (gpioWrite(DHT22_GPIO, 1) < 0) {
            syslog(LOG_ERR, "Failed to write GPIO high");
            return -1;
        }
        usleep(30); // 20-40 µs

        if (gpioSetMode(DHT22_GPIO, PI_INPUT) < 0) {
            syslog(LOG_ERR, "Failed to set GPIO as input");
            return -1;
        }

        // Wait for response
        res = gpioWait(DHT22_GPIO, 1, DHT22_TIMEOUT);
        if (res < 0) {
            syslog(LOG_ERR, "Timeout waiting for DHT22 response");
            retries++;
            usleep(DHT22_RETRY_DELAY * 1000);
            continue;
        }

        // Read 40 bits
        for (int i = 0; i < 40; i++) {
            res = gpioWait(DHT22_GPIO, 0, DHT22_TIMEOUT);
            if (res < 0) {
                syslog(LOG_ERR, "Timeout waiting for DHT22 bit");
                retries++;
                usleep(DHT22_RETRY_DELAY * 1000);
                break;
            }
            unsigned long length = res;
            res = gpioWait(DHT22_GPIO, 1, DHT22_TIMEOUT);
            if (res < 0) {
                syslog(LOG_ERR, "Timeout waiting for DHT22 bit");
                retries++;
                usleep(DHT22_RETRY_DELAY * 1000);
                break;
            }
            if (res - length > 50) {
                response[i / 8] <<= 1;
                response[i / 8] |= 1;
            } else {
                response[i / 8] <<= 1;
            }
        }

        // Validate checksum
        unsigned long sum = (response[0] + response[1] + response[2] + response[3]) & 0xFF;
        if (sum == response[4]) {
            *humidity = (float)((response[0] << 8) + response[1]) / 10.0;
            return 0;
        } else {
            syslog(LOG_ERR, "Checksum failed");
            retries++;
            usleep(DHT22_RETRY_DELAY * 1000);
        }
    }

    return -1;
}

int post_humidity(const char *url, float humidity) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char post_data[64];

    snprintf(post_data, sizeof(post_data), "{\"humidity\": %.2f}", humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "Failed to initialize libcurl");
        return -1;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);

    int retries = 0;
    while (retries < DHT22_MAX_RETRIES) {
        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 200 && response_code < 300) {
                return 0;
            } else {
                syslog(LOG_ERR, "HTTP error: %ld", response_code);
            }
        } else {
            syslog(LOG_ERR, "libcurl error: %s", curl_easy_strerror(res));
        }
        retries++;
        usleep(DHT22_RETRY_DELAY * 1000);
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return -1;
}

void cleanup() {
    gpioTerminate();
    curl_global_cleanup();
    closelog();
}

int main(int argc, char *argv[]) {
    const char *url = "http://your-server.com/api/humidity";
    int opt;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    openlog("dht22_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        cleanup();
        exit(EXIT_FAILURE);
    }

    atexit(cleanup);

    while (keep_running) {
        float humidity;
        if (read_dht22(&humidity) == 0) {
            if (post_humidity(url, humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from DHT22");
        }
        sleep(READ_INTERVAL);
    }

    cleanup();
    return 0;
}

