        perror("Failed to read max state");
        fclose(file);
        return -1;
    }

    fclose(file);
    return max_state;
}

int write_fan_state(int state) {
    FILE *file = fopen(FAN_STATE_FILE, "w");
    if (!file) {
        perror("Failed to open fan state file");
        return -1;
    }

    if (fprintf(file, "%d", state) < 0) {
        perror("Failed to write fan state");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

void log_fan_change(int new_state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] Fan state changed to %d\n", timestamp, new_state);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int max_state = read_max_state();
    if (max_state == -1) {
        return EXIT_FAILURE;
    }

    int current_state = 0;
    while (keep_running) {
        int temp = read_temperature();
        if (temp == -1) {
            sleep(5);
            continue;
        }

        int new_state = 0;
        if (temp >= 65) {
            new_state = 3;
        } else if (temp >= 55) {
            new_state = 2;
        } else if (temp >= 45) {
            new_state = 1;
        }

        if (new_state <= max_state && new_state != current_state) {
            if (write_fan_state(new_state) == 0) {
                current_state = new_state;
                log_fan_change(new_state);
            }
        }

        sleep(5);
    }

    // Graceful shutdown
    if (write_fan_state(0) == 0) {
        log_fan_change(0);
    }

    return EXIT_SUCCESS;
}

