#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_HEATER 18
#define GPIO_SPI_CLK 11
#define GPIO_SPI_CS 8
#define GPIO_SPI_DO 9
#define PWM_FREQUENCY 1000
#define PWM_RESOLUTION 100
#define SPI_SPEED 500000
#define LOG_FILE "heater_log.txt"
#define TARGET_TEMP 50.0
#define KP 1.0
#define KI 0.1
#define KD 0.01

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

double read_temperature() {
    unsigned char buffer[4];
    int result = piSPIRead(GPISPI0, 0, buffer, 4);
    if (result < 0) {
        fprintf(stderr, "SPI read error: %s\n", piStrerror(result));
        return -1.0;
    }

    unsigned int raw_temp = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
    int fault = buffer[3];

    if (fault & 0x01) {
        fprintf(stderr, "Thermocouple open circuit fault\n");
        return -1.0;
    }
    if (fault & 0x02) {
        fprintf(stderr, "Thermocouple short to GND fault\n");
        return -1.0;
    }
    if (fault & 0x04) {
        fprintf(stderr, "Thermocouple short to VCC fault\n");
        return -1.0;
    }

    double temperature = raw_temp * 0.25;
    return temperature;
}

void log_data(double temperature, int duty_cycle, double pid_output) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "Temperature: %.2f°C, Duty Cycle: %d%%, PID Output: %.2f\n",
            temperature, duty_cycle, pid_output);
    fclose(log_file);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_HEATER, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_SPI_CLK, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_SPI_CS, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_SPI_DO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (piSPISetup(GPISPI0, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioPWMSet(GPIO_HEATER, PWM_FREQUENCY, 0) < 0) {
        fprintf(stderr, "Failed to set PWM\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioPWMSet(GPIO_HEATER, 0, 0);
    piSPIClose(GPISPI0);
    gpioTerminate();
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    double prev_error = 0.0, integral = 0.0;
    int duty_cycle = 0;

    while (keep_running) {
        double temperature = read_temperature();
        if (temperature < 0.0 || temperature > 100.0) {
            fprintf(stderr, "Temperature out of range: %.2f°C\n", temperature);
            gpioPWMSet(GPIO_HEATER, 0, 0);
            prev_error = 0.0;
            integral = 0.0;
            continue;
        }

        double error = TARGET_TEMP - temperature;
        integral += error;
        double derivative = error - prev_error;
        double pid_output = KP * error + KI * integral + KD * derivative;

        if (pid_output < 0.0) pid_output = 0.0;
        if (pid_output > PWM_RESOLUTION) pid_output = PWM_RESOLUTION;

        duty_cycle = (int)pid_output;
        gpioPWMSet(GPIO_HEATER, PWM_FREQUENCY, duty_cycle);

        log_data(temperature, duty_cycle, pid_output);

        prev_error = error;
        sleep(1);
    }

    cleanup();
    return 0;
}

