    if (temp <= TEMP_MIN) {
        return 0;
    } else if (temp >= TEMP_MAX) {
        return 100;
    } else {
        return (temp - TEMP_MIN) * 100 / (TEMP_MAX - TEMP_MIN);
    }
}

