        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWMfrequency(GPIO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int temp = read_cpu_temperature();
        if (temp < 0) {
            sleep(5);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temp);
        if (gpioPWMdutycycle(GPIO_PIN, duty_cycle * 1023 / 100) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        log_data(temp, duty_cycle);
        sleep(5);
    }

    gpioPWMstop(GPIO_PIN);
    gpioTerminate();

    return EXIT_SUCCESS;
}

