#define I2C_BUS 1
#define SLF3S_1300F_ADDR1 0x08
#define SLF3S_1300F_ADDR2 0x09
#define SLF3S_1300F_CMD 0x3608
#define MAX_RETRIES 3

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int i2c_handle, uint8_t address, uint8_t *data, size_t length) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_i2c_block_data(i2c_handle, address, SLF3S_1300F_CMD, 2) == 0 &&
            i2c_read_i2c_block_data(i2c_handle, address, length, data) == 0) {
            return 0;
        }
        usleep(100000); // Wait 100ms before retrying
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(I2C_BUS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        uint8_t data1[3], data2[3];
        int result1 = read_sensor(i2c_handle, SLF3S_1300F_ADDR1, data1, 3);
        int result2 = read_sensor(i2c_handle, SLF3S_1300F_ADDR2, data2, 3);

        if (result1 == 0 && result2 == 0) {
            uint8_t crc1 = crc8(data1, 2);
            uint8_t crc2 = crc8(data2, 2);

            if (data1[2] == crc1 && data2[2] == crc2) {
                int16_t raw_value1 = (data1[0] << 8) | data1[1];
                int16_t raw_value2 = (data2[0] << 8) | data2[1];
                float flow_rate1 = raw_value1 * 0.01;
                float flow_rate2 = raw_value2 * 0.01;

                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char time_str[20];
                strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(log_file, "%s,%.2f,%.2f\n", time_str, flow_rate1, flow_rate2);
                fflush(log_file);
            }
        }

        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

