#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define CHANNEL_A 17
#define CHANNEL_B 18
#define PULSES_PER_REVOLUTION 360

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_state_change(int state, double angle) {
    FILE *log_file = fopen("encoder_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "Timestamp: %s, State: %d, Angle: %.2f\n", timestamp, state, angle);
    fclose(log_file);
}

void encoder_callback(int gpio, unsigned level, uint32_t tick, void *userdata) {
    static int last_state = 0;
    static int state = 0;
    static int count = 0;
    static int last_gpio = -1;

    int current_state = (gpio == CHANNEL_A) ? (level << 1) : (level | (last_gpio << 1));
    last_gpio = level;

    if (current_state != last_state) {
        if (current_state == 0b01 || current_state == 0b10) {
            count++;
        } else if (current_state == 0b11 || current_state == 0b00) {
            count--;
        }

        last_state = current_state;
        double angle = (double)count / PULSES_PER_REVOLUTION * 360.0;
        log_state_change(current_state, angle);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioSetMode(CHANNEL_A, PI_INPUT) < 0 || gpioSetMode(CHANNEL_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(CHANNEL_A, PI_PUD_UP) < 0 || gpioSetPullUpDown(CHANNEL_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioCallback(CHANNEL_A, EITHER_EDGE, encoder_callback) < 0 || gpioCallback(CHANNEL_B, EITHER_EDGE, encoder_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO callback\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

