#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL 100000000 // 100 ms in nanoseconds

static volatile sig_atomic_t keep_running = 1;
static int i2c_fd = -1;
static int led_line = -1;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_gpio() {
    struct gpiod_line_request req = {
        .consumer = "adpd144ri_led",
        .type = GPIOD_LINE_REQUEST_OUTPUT,
        .flags = GPIOD_LINE_REQUEST_DIRECTIONS,
    };

    led_line = gpiod_chip_open_by_name("gpiochip0");
    if (led_line < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(led_line, LED_GPIO);
    if (led_line < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(led_line);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(led_line, &req)) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(led_line);
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data(int *red, int *ir) {
    uint8_t buffer[4];
    buffer[0] = FIFO_DATA_REG;

    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C bus");
        *red = *ir = -1;
        return;
    }

    if (read(i2c_fd, buffer, 4) != 4) {
        perror("Failed to read from I2C bus");
        *red = *ir = -1;
        return;
    }

