#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
volatile sig_atomic_t running = 1;
FILE *log_file = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void handle_signal(int sig) {
    running = 0;
}

void gpio_callback(int gpio, unsigned level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pthread_mutex_lock(&mutex);
        pulse_count++;
        pthread_mutex_unlock(&mutex);
    }
}

void log_rpm(int rpm) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - RPM: %.2f\n", time_str, rpm);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-up/down resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, gpio_callback, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        sleep(1);

        pthread_mutex_lock(&mutex);
        int rpm = pulse_count * 60.0; // Convert pulses per second to RPM
        pulse_count = 0;
        pthread_mutex_unlock(&mutex);

        log_rpm(rpm);
    }

    gpioTerminate();
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&mutex);

    return EXIT_SUCCESS;
}

