#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x10
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL 100 // milliseconds

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_device(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_register(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("Failed to read data from register");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd = -1;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file;
    uint8_t part_id;
    uint8_t fifo_data[2];
    int ir_value, red_value;
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "LED", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    i2c_fd = open_i2c_device(I2C_DEVICE, I2C_ADDRESS);
    if (i2c_fd < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (read_i2c_register(i2c_fd, PART_ID_REG, &part_id, 1) < 0) {
        fprintf(stderr, "Sensor not present or failed to read PART_ID\n");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,IR,Red\n");

    while (!stop) {
        if (read_i2c_register(i2c_fd, FIFO_DATA_REG, fifo_data, 2) < 0) {
            fprintf(stderr, "Failed to read FIFO data\n");
            break;
        }

        ir_value = (fifo_data[0] << 8) | fifo_data[1];
        red_value = ir_value; // Assuming same data for red and IR for simplicity

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, ir_value, red_value);

        if (ir_value > IR_THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

