#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define OUT_PIN 17
#define GAIN_PIN 18
#define INTERVAL 10 // 10 ms

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_peak_event() {
    FILE *log_file = fopen("audio_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s LEVEL 1\n", timestamp);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *out_line, *gain_line;
    int ret;

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Starting audio peak detection...\n");

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get OUT pin line
    out_line = gpiod_chip_get_line(chip, OUT_PIN);
    if (!out_line) {
        perror("Failed to get OUT pin line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get GAIN pin line
    gain_line = gpiod_chip_get_line(chip, GAIN_PIN);
    if (!gain_line) {
        perror("Failed to get GAIN pin line");
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure GAIN pin as output and set it LOW
    ret = gpiod_line_request_output(gain_line, "gain_control", 0);
    if (ret < 0) {
        perror("Failed to request GAIN pin as output");
        gpiod_line_release(out_line);
        gpiod_line_release(gain_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure OUT pin as input
    ret = gpiod_line_request_input(out_line, "out_input", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        perror("Failed to request OUT pin as input");
        gpiod_line_release(gain_line);
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line_event event;
    int last_value = -1;

    while (keep_running) {
        ret = gpiod_line_event_wait(out_line, &event, INTERVAL * 1000);
        if (ret < 0) {
            perror("Failed to wait for event");
            break;
        }

        int value = gpiod_line_event_value(&event);
        if (value == 1 && last_value == 0) {
            log_peak_event();
        }
        last_value = value;
    }

    // Cleanup
    gpiod_line_release(out_line);
    gpiod_line_release(gain_line);
    gpiod_chip_close(chip);

    printf("Exiting...\n");
    return EXIT_SUCCESS;
}

