#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x36
#define COMMAND_START_CONTINUOUS_MEASUREMENT 0x08
#define POLL_INTERVAL_MS 1000
#define LOG_FILE "flow_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

uint8_t sensirion_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWrite(i2c_handle, &COMMAND_START_CONTINUOUS_MEASUREMENT, 1) != 1) {
        fprintf(stderr, "Failed to send start command to sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t buffer[3];
    while (keep_running) {
        if (i2cRead(i2c_handle, buffer, 3) != 3) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
        uint8_t crc = sensirion_crc8(buffer, 2);
        if (crc != buffer[2]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        double flow_rate = (double)raw_flow / 1000.0;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%f\n", time_str, flow_rate);
        fflush(log_file);

        gpioDelay(POLL_INTERVAL_MS);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

