#define I2C_BUS 1
#define I2C_ADDR 0x70
#define REG_START 0x00
#define REG_COUNT 7
#define LOG_FILE "air_quality_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int clamp(int value, int min, int max) {
    if (value < min) return min;
    if (value > max) return max;
    return value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,IAQ,TVOC,eCO2\n");

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        unsigned char buffer[REG_COUNT];
        int result = i2cReadReg8s(i2c_handle, REG_START, buffer, REG_COUNT);
        if (result < 0) {
            fprintf(stderr, "I2C read error: %d\n", result);
            continue;
        }

        int tvoc = (buffer[1] << 8) | buffer[2];
        int eco2 = (buffer[5] << 8) | buffer[6];

        double iaq = clamp(100 - (tvoc / 10.0) - ((eco2 - 400) / 50.0), 0, 100);

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, iaq, tvoc, eco2);
        fflush(log_file);

        sleep(5);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

