#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NUM 17
#define POLL_INTERVAL_NS 100000000 // 100 ms in nanoseconds
#define TOUCH_THRESHOLD_NS 5000000000 // 5 seconds in nanoseconds

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct timespec ts_start, ts_last_touch;
    struct sigaction sa;
    int ret;

    // Set up signal handling for graceful shutdown
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handling: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE_NUM);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "ttp223_tamper", GPIOD_LINE_REQUEST_DIRECTIONS);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line as input: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize the touch timer
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    ts_last_touch = ts_start;

    while (keep_running) {
        int value;
        ret = gpiod_line_get_value(line, &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read line value: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (value) { // Sensor is touched
            clock_gettime(CLOCK_MONOTONIC, &ts_last_touch);
            if (ts_last_touch.tv_sec - ts_start.tv_sec > 5) {
                printf("Intrusion alert!\n");
                ts_start = ts_last_touch; // Reset the timer
            }
        } else { // Sensor is released
            ts_start = ts_last_touch; // Reset the timer
        }

        // Poll every 100 ms
        struct timespec ts_poll = { .tv_sec = 0, .tv_nsec = POLL_INTERVAL_NS };
        nanosleep(&ts_poll, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

