#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define GPIO_MIC_LR_SELECT 17
#define PCM_DEVICE "hw:0,0"
#define PCM_SUBDEVICE "0"
#define PCM_FORMAT SND_PCM_FORMAT_S16_LE
#define PCM_SAMPLE_RATE 16000
#define PCM_CHANNELS 1
#define PCM_BUFFER_SIZE 1024

volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_MIC_LR_SELECT);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "mic_lr_select", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_strerror(ret));
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(line, 1); // Select left channel

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

int init_alsa(snd_pcm_t **pcm_handle) {
    int err;

    err = snd_pcm_open(pcm_handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to open PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_t *params;
    snd_pcm_hw_params_alloca(&params);
    snd_pcm_hw_params_any(*pcm_handle, params);
    snd_pcm_hw_params_set_access(*pcm_handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(*pcm_handle, params, PCM_FORMAT);
    snd_pcm_hw_params_set_channels(*pcm_handle, params, PCM_CHANNELS);
    snd_pcm_hw_params_set_rate_near(*pcm_handle, params, &PCM_SAMPLE_RATE, NULL);
    snd_pcm_hw_params_set_period_size_near(*pcm_handle, params, &PCM_BUFFER_SIZE, NULL);

    err = snd_pcm_hw_params(*pcm_handle, params);
    if (err < 0) {
        fprintf(stderr, "Failed to set hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

int main() {
    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    snd_pcm_t *pcm_handle;
    if (init_alsa(&pcm_handle) < 0) {
        return EXIT_FAILURE;
    }

    FILE *file = fopen("audio_capture.pcm", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        snd_pcm_close(pcm_handle);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int err;
    while (!stop) {
        snd_pcm_sframes_t frames;
        uint32_t *buffer = malloc(PCM_BUFFER_SIZE * sizeof(uint32_t));
        if (!buffer) {
            fprintf(stderr, "Failed to allocate buffer\n");
            break;
        }

        frames = snd_pcm_readi(pcm_handle, buffer, PCM_BUFFER_SIZE);
        if (frames < 0) {
            fprintf(stderr, "Failed to read from PCM device: %s\n", snd_strerror(frames));
            free(buffer);
            break;
        }

        for (int i = 0; i < frames; i++) {
            int16_t sample = (buffer[i] >> 8) & 0xFFFF; // Extract 16-bit PCM sample
            fwrite(&sample, sizeof(int16_t), 1, file);
        }

        free(buffer);
    }

    fclose(file);
    snd_pcm_close(pcm_handle);

    return EXIT_SUCCESS;
}

