#include <pigpio.h>

#define SENSOR_GPIO 4
#define FAN_GPIO 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 50
#define MAX_DUTY_CYCLE 255
#define DUTY_CYCLE_SCALE 0.8

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_event(const char *event) {
    FILE *log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    log_event("System start");

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0 || gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWMFrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = -1;
    int debounce_counter = 0;
    int flame_duration = 0;
    int duty_cycle = 0;

    while (keep_running) {
        int state = gpioRead(SENSOR_GPIO);
        if (state < 0) {
            fprintf(stderr, "Failed to read sensor GPIO\n");
            break;
        }

        if (state == last_state) {
            debounce_counter++;
            if (debounce_counter >= (DEBOUNCE_MS / POLL_INTERVAL_MS)) {
                if (state == 0) { // Flame detected
                    if (last_state != 0) {
                        log_event("Flame detected");
                    }
                    flame_duration += POLL_INTERVAL_MS;
                    duty_cycle = (int)(MAX_DUTY_CYCLE * (1 - exp(-flame_duration / 1000.0)) * DUTY_CYCLE_SCALE);
                    if (duty_cycle > MAX_DUTY_CYCLE) {
                        duty_cycle = MAX_DUTY_CYCLE;
                    }
                    gpioPWM(FAN_GPIO, duty_cycle);
                } else { // No flame detected
                    if (last_state != 1) {
                        log_event("Flame ended");
                    }
                    gpioPWM(FAN_GPIO, 0);
                    flame_duration = 0;
                }
            }
        } else {
            debounce_counter = 0;
        }

        last_state = state;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event("Shutdown");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

