#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define MAGIC_NUMBER 0x52444144
#define FRAME_SIZE 32768
#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

typedef struct {
    uint32_t start_frequency; // in GHz
    uint32_t end_frequency;   // in GHz
    uint32_t chirps;
    uint32_t samples;
    uint32_t frame_period;    // in ms
} Config;

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_DATA_READY, PI_INPUT) < 0) {
        gpioTerminate();
        log_error("Failed to set GPIO modes");
    }

    if (gpioSetAlertFunc(GPIO_DATA_READY, NULL, NULL) < 0) {
        gpioTerminate();
        log_error("Failed to set GPIO alert function");
    }

    if (gpioWrite(GPIO_TRIGGER, 0) < 0) {
        gpioTerminate();
        log_error("Failed to write to GPIO trigger");
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        gpioTerminate();
        log_error("Failed to open SPI channel");
    }

    FILE *log_file = fopen("radar_log.bin", "wb");
    if (!log_file) {
        spiClose(spi_handle);
        gpioTerminate();
        log_error("Failed to open log file");
    }

    Config config = {77, 79, 64, 256, 100};
    uint8_t buffer[FRAME_SIZE];
    uint8_t header[16];
    uint64_t timestamp;

    header[0] = (MAGIC_NUMBER >> 24) & 0xFF;
    header[1] = (MAGIC_NUMBER >> 16) & 0xFF;
    header[2] = (MAGIC_NUMBER >> 8) & 0xFF;
    header[3] = MAGIC_NUMBER & 0xFF;

    timestamp = time(NULL);
    for (int i = 0; i < 8; i++) {
        header[4 + i] = (timestamp >> (56 - i * 8)) & 0xFF;
    }

    fwrite(&config, sizeof(config), 1, log_file);
    fwrite(header, sizeof(header), 1, log_file);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint32_t frame_number = 0;
    while (keep_running) {
        gpioWrite(GPIO_TRIGGER, 1);
        gpioDelay(1);
        gpioWrite(GPIO_TRIGGER, 0);

        while (gpioRead(GPIO_DATA_READY) == 0) {
            if (!keep_running) break;
        }

        if (!keep_running) break;

        timestamp = time(NULL);
        if (spiXfer(spi_handle, buffer, buffer, FRAME_SIZE) < 0) {
            log_error("SPI transfer failed");
        }

        fwrite(&timestamp, sizeof(timestamp), 1, log_file);
        fwrite(&frame_number, sizeof(frame_number), 1, log_file);
        fwrite(buffer, FRAME_SIZE, 1, log_file);

        frame_number++;
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

