#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 20
#define POLL_INTERVAL_NS (100 * 1000 * 1000) // 100 milliseconds in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_state_transition(FILE *log_file, int state) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    if (state == 1) {
        fprintf(log_file, "%s: Flame detected\n", timestamp);
    } else {
        fprintf(log_file, "%s: Flame cleared\n", timestamp);
    }
    fflush(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int ret;
    FILE *log_file;
    int last_state = -1;

    // Set up signal handling for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Get line for GPIO 20
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line: %s\n", gpiod_strerror(gpiod_get_last_error()));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as input
    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", gpiod_strerror(gpiod_get_last_error()));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Poll for state changes
    while (keep_running) {
        ret = gpiod_line_event_wait(line, POLL_INTERVAL_NS);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_event_wait: %s\n", gpiod_strerror(gpiod_get_last_error()));
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_event_read: %s\n", gpiod_strerror(gpiod_get_last_error()));
            break;
        }

        int current_state = gpiod_value_get(event.event_value);
        if (current_state != last_state) {
            log_state_transition(log_file, current_state);
            last_state = current_state;
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

