#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define CONTINUOUS_MODE 0x03
#define CONVERSION_TIME_100MS 0x0C
#define FULL_SCALE_AUTO 0x00

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    }
}

void log_data(int lux) {
    FILE *data_file = fopen("light_data.txt", "a");
    if (data_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(data_file, "%s %d\n", timestamp, lux);
        fclose(data_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, REG_CONFIG, CONTINUOUS_MODE | CONVERSION_TIME_100MS | FULL_SCALE_AUTO) < 0) {
        log_error("Failed to configure sensor");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int result = i2cReadByteData(i2c_handle, REG_RESULT);
        if (result < 0) {
            log_error("Failed to read from sensor");
            continue;
        }

        int exponent = (result >> 12) & 0x0F;
        int mantissa = result & 0x0FFF;
        int lux = 0.01 * (1 << exponent) * mantissa;

        log_data(lux);
        usleep(100000); // Sleep for 100 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

