        gpiod_line_config_free(line_config);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line
    line = gpiod_chip_request_lines(chip, &line_config, 1);
    if (!line) {
        fprintf(stderr, "Failed to request line: %s\n", gpiod_strerror(gpiod_chip_get_error(chip)));
        gpiod_line_config_free(line_config);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set line settings
    line_settings = gpiod_line_settings_new();
    if (!line_settings) {
        fprintf(stderr, "Failed to create line settings\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_settings_set_flags(line_settings, GPIOD_LINE_REQUEST_FLAG_DIRECTIONS_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line settings flags: %s\n", gpiod_strerror(ret));
        gpiod_line_settings_free(line_settings);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_config(line, line_settings);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure line: %s\n", gpiod_strerror(ret));
        gpiod_line_settings_free(line_settings);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_settings_free(line_settings);

    // Main loop
    while (!stop_flag) {
        int value;
        ret = gpiod_line_request_get_value(line, &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to get line value: %s\n", gpiod_strerror(ret));
            break;
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        // Print flame detection status
        printf("%04d-%02d-%02d %02d:%02d:%02d - Flame Detected: %s\n",
               1900 + ts.tv_sec / 31556926, (ts.tv_sec / 2592000) % 12 + 1,
               (ts.tv_sec / 86400) % 30 + 1, (ts.tv_sec / 3600) % 24,
               (ts.tv_sec / 60) % 60, ts.tv_sec % 60,
               value == 0 ? "YES" : "NO");

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpiod_line_config_free(line_config);

    return EXIT_SUCCESS;
}

