#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define GPIO_PINS {2, 3, 4, 5, 0, 6, 7, 8} // BCM GPIO pins 2, 3, 4, 5, 6, 7, 8, 9
#define POLL_INTERVAL_MS 100

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_CHANNELS] = {NULL};

void handle_signal(int sig) {
    keep_running = 0;
}

int main(void) {
    struct gpiod_line_request req = {
        .consumer = "touch_sensor_reader",
        .type = GPIOD_LINE_REQ_DIR_IN,
        .flags = GPIOD_LINE_REQ_FANOUT,
    };

    signal(SIGINT, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; ++i) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PINS[i]);
            goto cleanup;
        }

        if (gpiod_line_request(lines[i], &req)) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", GPIO_PINS[i]);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
            goto cleanup;
        }
    }

    while (keep_running) {
        for (int i = 0; i < NUM_CHANNELS; ++i) {
            if (!lines[i]) continue;

            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read value from GPIO %d\n", GPIO_PINS[i]);
                continue;
            }

            printf("GPIO %d: %d\n", GPIO_PINS[i], value);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    for (int i = 0; i < NUM_CHANNELS; ++i) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

