#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define GPIO_BASE 2
#define POLL_INTERVAL 100000 // 100 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(GPIO_BASE + i, PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_BASE + i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(GPIO_BASE + i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", GPIO_BASE + i);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    unsigned long start_time = gpioTick();
    while (keep_running) {
        unsigned long current_time = gpioTick();
        unsigned long elapsed_time = current_time - start_time;
        printf("[%+lu ms] ", elapsed_time / 1000);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int state = gpioRead(GPIO_BASE + i);
            printf("CH%d=%d ", i + 1, state);
        }
        printf("\n");

        gpioDelay(POLL_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

