#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 5
#define POLL_INTERVAL 500000000 // 500 ms in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 || gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) < 0 || gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int sensor1_state = gpioRead(SENSOR_1_PIN);
        int sensor2_state = gpioRead(SENSOR_2_PIN);

        printf("Sensor 1: %s\n", sensor1_state == 0 ? "LOW" : "HIGH");
        printf("Sensor 2: %s\n", sensor2_state == 0 ? "LOW" : "HIGH");

        struct timespec ts = {0, POLL_INTERVAL};
        nanosleep(&ts, NULL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

