#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
    const int line_offsets[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};
    char *line_names[NUM_CHANNELS] = {"GPIO2", "GPIO3", "GPIO4", "GPIO17", "GPIO27", "GPIO22", "GPIO10", "GPIO9"};
    int ret;

    // Install SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %s\n", line_names[i]);
            ret = EXIT_FAILURE;
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], line_names[i], GPIOD_LINE_REQUEST_FLAG_NONE);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %s\n", line_names[i]);
            ret = EXIT_FAILURE;
            goto cleanup;
        }
    }

    // Polling loop
    while (keep_running) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read value from line %s\n", line_names[i]);
                ret = EXIT_FAILURE;
                goto cleanup;
            }
            printf("%s,%s,%d", timestamp, line_names[i], value);
            if (i < NUM_CHANNELS - 1) {
                printf(",");
            }
        }
        printf("\n");

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret == EXIT_FAILURE ? EXIT_FAILURE : EXIT_SUCCESS;
}

