This program sets up the GPIO lines for the TTP226 capacitive touch sensor array, polls their states every 50 ms, and logs the results with timestamps. It handles errors and ensures resources are released properly. The program can be gracefully terminated with Ctrl+C.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define POLL_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] %s\n", time_str, message);
    fflush(stdout);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    log_message("Tilt Sensor Monitoring Started");

    int last_state = -1;
    while (keep_running) {
        int state = gpioRead(GPIO_PIN);
        if (state < 0) {
            fprintf(stderr, "Failed to read GPIO state\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (state != last_state) {
            if (state == 0) {
                log_message("Tilted");
            } else {
                log_message("Not Tilted");
            }
            last_state = state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    log_message("Tilt Sensor Monitoring Stopped");
    return EXIT_SUCCESS;
}

