#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x17
#define CHLIST_REG 0x01
#define ALS_FORCE_CMD 0x06
#define UV_INDEX_REG 0x05
#define ALS_VIS_REG 0x0A

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_to_csv(const char *filename, time_t timestamp, int uv_index, int als_visible) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%ld,%d,%d\n", timestamp, uv_index, als_visible);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioI2CSetup(I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int part_id = gpioI2CReadReg8(I2C_BUS, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART ID\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteReg8(I2C_BUS, HW_KEY_REG, 0x17) < 0) {
        fprintf(stderr, "Failed to write to HW_KEY register\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteReg8(I2C_BUS, CHLIST_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to configure CHLIST register\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteReg8(I2C_BUS, ALS_FORCE_CMD, 0x06) < 0) {
        fprintf(stderr, "Failed to trigger ALS measurement\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("uv_als_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to create log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "timestamp,uv_index,als_visible\n");
    fclose(log_file);

    while (keep_running) {
        int uv_index = gpioI2CReadReg8(I2C_BUS, UV_INDEX_REG);
        int als_visible = gpioI2CReadReg8(I2C_BUS, ALS_VIS_REG);

        if (uv_index < 0 || als_visible < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        time_t now = time(NULL);
        printf("Timestamp: %ld, UV Index: %d, ALS Visible: %d\n", now, uv_index, als_visible);
        log_to_csv("uv_als_log.csv", now, uv_index, als_visible);

        if (gpioI2CWriteReg8(I2C_BUS, ALS_FORCE_CMD, 0x06) < 0) {
            fprintf(stderr, "Failed to trigger ALS measurement\n");
            break;
        }

        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

