#include <errno.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDR1 0x36
#define I2C_SLAVE_ADDR2 0x37
#define I2C_CMD_REG 0x08
#define I2C_START_MEASUREMENT 0x08
#define I2C_DATA_REG 0x00
#define GPIO_PIN 17
#define SCALE_FACTOR 0.036
#define LOG_FILE "flow_log.txt"
#define POLL_INTERVAL 1000000 // 1 second in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_sensor(int fd, int addr, float *flow_rate) {
    uint8_t buffer[9];
    int ret;

    // Start measurement
    buffer[0] = I2C_CMD_REG;
    buffer[1] = I2C_START_MEASUREMENT;
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to start measurement");
        return -1;
    }
    usleep(100000); // 100 ms

    // Read data
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    if (read(fd, buffer, 9) != 9) {
        perror("Failed to read sensor data");
        return -1;
    }

    // Validate CRC
    if (crc8(buffer, 8) != buffer[8]) {
        fprintf(stderr, "CRC check failed for sensor at address 0x%02X\n", addr);
        return -1;
    }

    // Extract flow rate
    int16_t raw_flow = (buffer[1] << 8) | buffer[0];
    *flow_rate = raw_flow * SCALE_FACTOR;
    return 0;
}

int main() {
    int i2c_fd1, i2c_fd2;
    float flow_rate1 = 0.0, flow_rate2 = 0.0;
    float average_flow_rate = 0.0;
    int ret;
    struct timespec ts = {1, 0}; // 1 second interval
    struct sigaction sa;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file;

    // Setup signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C devices
    i2c_fd1 = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd1 < 0) {
        perror("Failed to open I2C device for sensor 1");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd1, I2C_SLAVE, I2C_SLAVE_ADDR1) < 0) {
        perror("Failed to set I2C address for sensor 1");
        close(i2c_fd1);
        return EXIT_FAILURE;
    }

    i2c_fd2 = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd2 < 0) {
        perror("Failed to open I2C device for sensor 2");
        close(i2c_fd1);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd2, I2C_SLAVE, I2C_SLAVE_ADDR2) < 0) {
        perror("Failed to set I2C address for sensor 2");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    // Open GPIO chip and line
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line, "flow_alarm", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read flow rates
        if (read_sensor(i2c_fd1, I2C_SLAVE_ADDR1, &flow_rate1) == 0) {
            average_flow_rate += flow_rate1;
        }
        if (read_sensor(i2c_fd2, I2C_SLAVE_ADDR2, &flow_rate2) == 0) {
            average_flow_rate += flow_rate2;
        }

        // Calculate average flow rate
        average_flow_rate /= 2.0;

        // Log average flow rate
        fprintf(log_file, "Average flow rate: %.2f ml/min\n", average_flow_rate);
        fflush(log_file);

        // Set alarm based on average flow rate
        if (average_flow_rate < 0.5) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        // Reset average flow rate for next cycle
        average_flow_rate = 0.0;

        // Sleep for 1 second
        nanosleep(&ts, NULL);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd1);
    close(i2c_fd2);

    return EXIT_SUCCESS;
}
