#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define POLL_INTERVAL 50 // milliseconds

typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer[i].reading == 0) {
            char time_str[20];
            struct tm *time_info = localtime(&buffer[i].timestamp);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);
            printf("Obstacle detected at %s\n", time_str);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        int reading = gpioRead(GPIO_PIN);
        if (reading == 0) {
            time_t now = time(NULL);
            buffer[buffer_index].timestamp = now;
            buffer[buffer_index].reading = reading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            printf("Alert: Obstacle detected!\n");
        }
        gpioDelay(POLL_INTERVAL);
    }

    print_buffer();

    gpioTerminate();
    return 0;
}

