#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define ACCEL_X_L 0x2A
#define ACCEL_X_H 0x2B
#define ACCEL_Y_L 0x2C
#define ACCEL_Y_H 0x2D
#define ACCEL_Z_L 0x2E
#define ACCEL_Z_H 0x2F
#define SCALING_FACTOR 0.0009765625
#define ACTIVE_TIMEOUT 1
#define SAMPLE_INTERVAL 0.5

int i2c_fd = -1;
FILE *csv_file = NULL;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int i2c_write_byte_data(int reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_word_data(uint8_t reg) {
    uint8_t buffer[2] = {reg, 0};
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return (int16_t)(buffer[1] | (buffer[0] << 8));
}

void log_acceleration(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(csv_file, "%s,%f,%f,%f\n", timestamp, x * SCALING_FACTOR, y * SCALING_FACTOR, z * SCALING_FACTOR);
    fflush(csv_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte_data(MODE_CONTROL, 0x10) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct timespec timeout = {ACTIVE_TIMEOUT, 0};
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - start.tv_sec > timeout.tv_sec) {
            fprintf(stderr, "Sensor did not become active within timeout\n");
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        if (i2c_read_word_data(OPERATING_STATUS) & 0x01) {
            break;
        }
        usleep(100000); // Sleep for 100 ms
    }

    csv_file = fopen("fan_health.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "Timestamp,X_g,Y_g,Z_g\n");
    }

    while (running) {
        int16_t x = i2c_read_word_data(ACCEL_X_L);
        int16_t y = i2c_read_word_data(ACCEL_Y_L);
        int16_t z = i2c_read_word_data(ACCEL_Z_L);

        if (x < 0 || y < 0 || z < 0) {
            usleep(100000); // Sleep for 100 ms
            continue;
        }

        log_acceleration(x, y, z);
        usleep((SAMPLE_INTERVAL - 0.1) * 1000000); // Sleep for 500 ms minus processing time
    }

    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

