#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25
#define POLL_INTERVAL 100 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize LED pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int sensor1_state = gpioRead(SENSOR_1_PIN);
        int sensor2_state = gpioRead(SENSOR_2_PIN);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Failed to read sensor state\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (sensor1_state == 0 || sensor2_state == 0) {
            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
        } else {
            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

