#define SENSOR_1 17
#define SENSOR_2 18
#define STALL_DURATION 2000 // 2 seconds in milliseconds
#define LOG_FILE "stall_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_stall_event() {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "Stall detected at %s\n", timestamp);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1, PI_INPUT) < 0 || gpioSetMode(SENSOR_2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR_1, PI_PUD_UP) < 0 || gpioSetPullUpDown(SENSOR_2, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down resistors.\n");
        gpioTerminate();
        return 1;
    }

