#define I2C_BUS 1
#define I2C_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_EXPECTED 0x8D
#define CONFIG_REG 0x01
#define CONTINUOUS_CONVERSION_MODE 0x01
#define RANGE_50MT 0x00
#define X_AXIS_REG 0x03
#define Y_AXIS_REG 0x05
#define Z_AXIS_REG 0x07
#define LSB_SCALE_FACTOR_50MT 0.15 // 15 µT per LSB for 50 mT range

volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    uint8_t device_id;
    if (i2cReadReg8(i2c_handle, DEVICE_ID_REG, &device_id) < 0) {
        log_error("Failed to read device ID");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (device_id != DEVICE_ID_EXPECTED) {
        log_error("Device ID mismatch");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    uint8_t config = CONTINUOUS_CONVERSION_MODE | RANGE_50MT;
    if (i2cWriteReg8(i2c_handle, CONFIG_REG, config) < 0) {
        log_error("Failed to write configuration register");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if file is newly created
    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X(mT),Y(mT),Z(mT)\n");
    }

    while (keep_running) {
        uint16_t x_raw, y_raw, z_raw;
        if (i2cReadReg16BE(i2c_handle, X_AXIS_REG, &x_raw) < 0 ||
            i2cReadReg16BE(i2c_handle, Y_AXIS_REG, &y_raw) < 0 ||
            i2cReadReg16BE(i2c_handle, Z_AXIS_REG, &z_raw) < 0) {
            log_error("Failed to read magnetic field data");
            continue;
        }

        // Convert raw values to mT
        float x_mt = (float)x_raw * LSB_SCALE_FACTOR_50MT;
        float y_mt = (float)y_raw * LSB_SCALE_FACTOR_50MT;
        float z_mt = (float)z_raw * LSB_SCALE_FACTOR_50MT;

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        // Log data
        fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_mt, y_mt, z_mt);
        fflush(log_file);

        usleep(100000); // Sleep for 100 ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

