volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("flood_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s %s\n", timestamp, message);
        fclose(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-up/down resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            log_message("Error reading GPIO");
            fprintf(stderr, "Error reading GPIO, attempting reinitialization\n");
            sleep(REINIT_INTERVAL);
            if (gpioInitialise() < 0) {
                log_message("Failed to reinitialize pigpio");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0 || gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
                log_message("Failed to reconfigure GPIO after reinitialization");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }

        if (level == 1) {
            printf("ALERT: Water detected\n");
            log_message("ALERT: Water detected");
        }

        sleep(POLL_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

