#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

atomic_int pulse_count = 0;
FILE *log_file = NULL;
volatile sig_atomic_t running = 1;

void handle_signal(int signal) {
    running = 0;
}

void alert_callback(int gpio, uint32_t level, uint32_t tick) {
    if (level == 1) {
        atomic_fetch_add(&pulse_count, 1);
    }
}

void log_rpm() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    int rpm = atomic_load(&pulse_count) * 60;
    atomic_store(&pulse_count, 0);

    char log_entry[50];
    snprintf(log_entry, sizeof(log_entry), "%s %d\n", time_str, rpm);

    if (fprintf(log_file, "%s", log_entry) < 0) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }
    fflush(log_file);
    printf("%s", log_entry);
}

