        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, alert_callback, 0) < 0) {
        fprintf(stderr, "Failed to set alert callback\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        sleep(1);
        log_rpm();
    }

    gpioSetAlertFuncEx(GPIO_PIN, NULL, 0);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

