#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_A 17
#define SENSOR_B 27

volatile sig_atomic_t keep_running = 1;
FILE *log_file = NULL;
pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t state_cond = PTHREAD_COND_INITIALIZER;

typedef enum { STATE_00, STATE_01, STATE_10, STATE_11 } QuadratureState;
QuadratureState current_state = STATE_00;

void log_rotation(const char *direction) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char log_entry[50];
    snprintf(log_entry, sizeof(log_entry), "%s.%03ld %s\n", timestamp, tv.tv_usec / 1000, direction);
    pthread_mutex_lock(&state_mutex);
    if (log_file) {
        fputs(log_entry, log_file);
        fflush(log_file);
    }
    pthread_mutex_unlock(&state_mutex);
}

void handle_signal(int signal) {
    keep_running = 0;
}

void alert_func(int gpio, int level, uint32_t tick) {
    static int last_a = -1, last_b = -1;
    int a = gpio == SENSOR_A ? level : last_a;
    int b = gpio == SENSOR_B ? level : last_b;

    pthread_mutex_lock(&state_mutex);
    if (gpio == SENSOR_A) last_a = level;
    if (gpio == SENSOR_B) last_b = level;

    QuadratureState new_state = (a << 1) | b;

    switch (current_state) {
        case STATE_00:
            if (new_state == STATE_01) log_rotation("CW");
            else if (new_state == STATE_10) log_rotation("CCW");
            break;
        case STATE_01:
            if (new_state == STATE_11) log_rotation("CW");
            else if (new_state == STATE_00) log_rotation("CCW");
            break;
        case STATE_10:
            if (new_state == STATE_00) log_rotation("CW");
            else if (new_state == STATE_11) log_rotation("CCW");
            break;
        case STATE_11:
            if (new_state == STATE_10) log_rotation("CW");
            else if (new_state == STATE_01) log_rotation("CCW");
            break;
    }

    current_state = new_state;
    pthread_mutex_unlock(&state_mutex);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_A, alert_func) < 0 || gpioSetAlertFunc(SENSOR_B, alert_func) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
