#include <gpiod.h>
#include <syslog.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18
#define POLL_INTERVAL_MS 50

static volatile int keep_running = 1;
static gpiod_chip *chip;
static gpiod_line *touch_line;
static gpiod_line *led_line;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_and_exit(const char *message, int status) {
    syslog(LOG_ERR, "%s", message);
    if (touch_line) gpiod_line_release(touch_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    closelog();
    exit(status);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    openlog("TouchSensorLED", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting Touch Sensor LED program");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_and_exit("Failed to open GPIO chip", EXIT_FAILURE);
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        log_and_exit("Failed to get touch sensor line", EXIT_FAILURE);
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        log_and_exit("Failed to request touch sensor line", EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        log_and_exit("Failed to get LED line", EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        log_and_exit("Failed to request LED line", EXIT_FAILURE);
    }

    while (keep_running) {
        int value;
        if (gpiod_line_event_wait(touch_line, POLL_INTERVAL_MS) < 0) {
            syslog(LOG_ERR, "Failed to wait for touch sensor event");
            continue;
        }

        value = gpiod_line_get_value(touch_line);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor value");
            continue;
        }

        if (value) {
            syslog(LOG_INFO, "Touch detected");
            if (gpiod_line_set_value(led_line, 1) < 0) {
                syslog(LOG_ERR, "Failed to turn on LED");
            }
        } else {
            syslog(LOG_INFO, "Touch released");
            if (gpiod_line_set_value(led_line, 0) < 0) {
                syslog(LOG_ERR, "Failed to turn off LED");
            }
        }
    }

    if (gpiod_line_set_value(led_line, 0) < 0) {
        syslog(LOG_ERR, "Failed to turn off LED on shutdown");
    }

    syslog(LOG_INFO, "Shutting down Touch Sensor LED program");
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

