#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18
#define DEBOUNCE_MS 50

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct gpiod_line_event event;
    int ret;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch sensor line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(touch_line, "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request touch sensor line as input: %s\n", strerror(-ret));
        cleanup();
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(-ret));
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize LED to LOW
    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set LED to LOW: %s\n", strerror(-ret));
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up event handling for touch sensor
    ret = gpiod_line_event_configure(touch_line, GPIO_LINE_EVENT_RISING_EDGE, DEBOUNCE_MS);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure touch sensor event: %s\n", strerror(-ret));
        cleanup();
        return EXIT_FAILURE;
    }

    // Event loop
    while (keep_running) {
        ret = gpiod_line_event_wait(touch_line, &event, -1);
        if (ret < 0) {
            if (errno == EINTR) {
                continue; // Interrupted by signal, continue loop
            }
            fprintf(stderr, "Failed to wait for touch sensor event: %s\n", strerror(-ret));
            break;
        }

        // Toggle LED
        int led_value = gpiod_line_get_value(led_line);
        ret = gpiod_line_set_value(led_line, !led_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to toggle LED: %s\n", strerror(-ret));
            break;
        }
    }

    // Cleanup resources
    cleanup();
    return EXIT_SUCCESS;
}

