#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_1 4
#define TOUCH_SENSOR_2 17
#define LED_1 27
#define LED_2 22
#define BUFFER_SIZE 100

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} TouchEvent;

TouchEvent touch_log[BUFFER_SIZE];
int log_index = 0;
int overflow_count = 0;
volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    touch_log[log_index].sensor_pin = sensor_pin;
    touch_log[log_index].timestamp = now;
    touch_log[log_index].state = state;

    log_index = (log_index + 1) % BUFFER_SIZE;
    if (log_index == 0) {
        overflow_count++;
    }
}

void print_log() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (log_index + i) % BUFFER_SIZE;
        printf("Sensor: %d, Time: %ld, State: %d\n",
               touch_log[index].sensor_pin,
               touch_log[index].timestamp,
               touch_log[index].state);
    }
    printf("Overflow Count: %d\n", overflow_count);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_1, PI_INPUT) < 0 ||
        gpioSetMode(TOUCH_SENSOR_2, PI_INPUT) < 0 ||
        gpioSetMode(LED_1, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_1, 0) < 0 || gpioWrite(LED_2, 0) < 0) {
        fprintf(stderr, "Failed to initialize LEDs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state_1 = 0, last_state_2 = 0;
    while (keep_running) {
        int state_1 = gpioRead(TOUCH_SENSOR_1);
        int state_2 = gpioRead(TOUCH_SENSOR_2);

        if (state_1 != last_state_1) {
            if (gpioWrite(LED_1, state_1) < 0) {
                fprintf(stderr, "Failed to write to LED 1\n");
            }
            log_event(TOUCH_SENSOR_1, state_1);
            last_state_1 = state_1;
        }

        if (state_2 != last_state_2) {
            if (gpioWrite(LED_2, state_2) < 0) {
                fprintf(stderr, "Failed to write to LED 2\n");
            }
            log_event(TOUCH_SENSOR_2, state_2);
            last_state_2 = state_2;
        }

        usleep(50000); // 50 ms debounce
    }

    // Graceful shutdown
    if (gpioWrite(LED_1, 0) < 0 || gpioWrite(LED_2, 0) < 0) {
        fprintf(stderr, "Failed to turn off LEDs on shutdown\n");
    }

    print_log();
    gpioTerminate();

    return EXIT_SUCCESS;
}

