#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <time.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define DEBOUNCE_MS 5
#define PULSES_PER_REVOLUTION 2

volatile sig_atomic_t keep_running = 1;
FILE *log_file = NULL;
unsigned long pulse_count = 0;
unsigned long last_pulse_time = 0;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_event(int sensor1_state, int sensor2_state) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fflush(log_file);
}

void sensor_callback(int gpio, unsigned level, uint32_t tick) {
    static int last_level1 = -1;
    static int last_level2 = -1;
    int current_time = pigpio_get_current_tick();

    if (gpio == GPIO_SENSOR1) {
        if (level != last_level1 && (current_time - last_pulse_time) >= DEBOUNCE_MS * 1000) {
            last_level1 = level;
            last_pulse_time = current_time;
            pulse_count++;
            log_event(level, gpioRead(GPIO_SENSOR2));
        }
    } else if (gpio == GPIO_SENSOR2) {
        if (level != last_level2 && (current_time - last_pulse_time) >= DEBOUNCE_MS * 1000) {
            last_level2 = level;
            last_pulse_time = current_time;
            log_event(gpioRead(GPIO_SENSOR1), level);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0 || gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_SENSOR1, PI_PUD_UP) < 0 || gpioSetPullUpDown(GPIO_SENSOR2, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(GPIO_SENSOR1, sensor_callback, 0) < 0 || gpioSetAlertFuncEx(GPIO_SENSOR2, sensor_callback, 0) < 0) {
        fprintf(stderr, "Failed to set alert function: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("shaft_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    while (keep_running) {
        unsigned long current_time = pigpio_get_current_tick();
        if ((current_time - last_pulse_time) >= 1000 * 1000) { // 1 second
            double rpm = (pulse_count / (double)PULSES_PER_REVOLUTION) * 60.0;
            printf("RPM: %.2f\n", rpm);
            pulse_count = 0;
            last_pulse_time = current_time;
        }
        piSleep(100); // Sleep for 100 ms
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

