#define CONFIG_REG 0x30
#define HR_DATA_REG 0x02
#define SPO2_DATA_REG 0x04

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_i2c_byte(int reg) {
    int value;
    if (i2c_read_byte_data(i2c_handle, reg, &value) < 0) {
        fprintf(stderr, "I2C read error at register 0x%02X\n", reg);
        return -1;
    }
    return value;
}

int write_i2c_byte(int reg, int value) {
    if (i2c_write_byte_data(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "I2C write error at register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

void log_biometric_data(int heart_rate, int spo2) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int part_id = read_i2c_byte(PART_ID_REG);
    if (part_id < 0 || part_id != 0x12) { // Assuming 0x12 is the expected PART_ID
        fprintf(stderr, "Si1182 sensor not found\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_i2c_byte(CONFIG_REG, 0x01) < 0) { // Assuming 0x01 configures for continuous measurement
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int heart_rate = read_i2c_byte(HR_DATA_REG);
        int spo2 = read_i2c_byte(SPO2_DATA_REG);

        if (heart_rate >= 0 && spo2 >= 0) {
            log_biometric_data(heart_rate, spo2);
        }

        sleep(1);
    }

    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

