        fprintf(stderr, "Failed to configure GPIO\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(ALARM, PI_LOW);
    gpioTerminate();
}

int main() {
    setup_gpio();

    log_file = fopen("bridge_integrity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sensor1_state = PI_LOW, sensor2_state = PI_LOW;
    int alarm_active = 0;
    unsigned long sensor1_high_time = 0, sensor2_high_time = 0;

    while (keep_running) {
        int sensor1_read = gpioRead(SENSOR_1);
        int sensor2_read = gpioRead(SENSOR_2);

        if (sensor1_read != sensor1_state) {
            sensor1_state = sensor1_read;
            if (sensor1_state == PI_HIGH) {
                log_event("Sensor 1 tilted");
                sensor1_high_time = pigpioGetMicros();
            } else {
                log_event("Sensor 1 returned to normal");
            }
        }

        if (sensor2_read != sensor2_state) {
            sensor2_state = sensor2_read;
            if (sensor2_state == PI_HIGH) {
                log_event("Sensor 2 tilted");
                sensor2_high_time = pigpioGetMicros();
            } else {
                log_event("Sensor 2 returned to normal");
            }
        }

        if (sensor1_state == PI_HIGH && (pigpioGetMicros() - sensor1_high_time > THRESHOLD_DURATION)) {
            if (!alarm_active) {
                gpioWrite(ALARM, PI_HIGH);
                log_event("Alarm activated");
                alarm_active = 1;
            }
        }

        if (sensor2_state == PI_HIGH && (pigpioGetMicros() - sensor2_high_time > THRESHOLD_DURATION)) {
            if (!alarm_active) {
                gpioWrite(ALARM, PI_HIGH);
                log_event("Alarm activated");
                alarm_active = 1;
            }
        }

        if (sensor1_state == PI_LOW && sensor2_state == PI_LOW && alarm_active) {
            gpioWrite(ALARM, PI_LOW);
            log_event("Alarm deactivated");
            alarm_active = 0;
        }

        gpioDelay(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}
