#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_START_REG 0x28
#define ACCEL_REG_COUNT 6
#define LED_PIN 17
#define THRESHOLD 500.0
#define POLL_INTERVAL 100000 // 100 ms in microseconds
#define MAX_RETRIES 3

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void log_event(double magnitude) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] Threshold exceeded: %f\n", timestamp, magnitude);
    fflush(log_file);
}

double read_acceleration() {
    unsigned char data[ACCEL_REG_COUNT];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_read_i2c_block_data(i2c_handle, ACCEL_START_REG, ACCEL_REG_COUNT, data);
        if (result == ACCEL_REG_COUNT) {
            break;
        }
        retries++;
        usleep(100000); // Wait 100 ms before retrying
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read acceleration data after %d retries.\n", MAX_RETRIES);
        return -1.0;
    }

    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];

    return sqrt(x * x + y * y + z * z);
}

void initialize_sensor() {
    unsigned char ctrl1;
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_read_byte_data(i2c_handle, CTRL1_REG, &ctrl1);
        if (result == 0) {
            break;
        }
        retries++;
        usleep(100000); // Wait 100 ms before retrying
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read CTRL1 register after %d retries.\n", MAX_RETRIES);
        exit(EXIT_FAILURE);
    }

    if (!(ctrl1 & 0x01)) {
        ctrl1 |= 0x01; // Clear power-down bit
        retries = 0;
        while (retries < MAX_RETRIES) {
            result = i2c_write_byte_data(i2c_handle, CTRL1_REG, ctrl1);
            if (result == 0) {
                break;
            }
            retries++;
            usleep(100000); // Wait 100 ms before retrying
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to write CTRL1 register after %d retries.\n", MAX_RETRIES);
            exit(EXIT_FAILURE);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    initialize_sensor();

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (keep_running) {
        double magnitude = read_acceleration();
        if (magnitude < 0) {
            continue; // Skip this iteration if read failed
        }

        if (magnitude > THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
            usleep(1000000); // 1 second
            gpioWrite(LED_PIN, PI_LOW);
            log_event(magnitude);
        }

        usleep(POLL_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

