#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_GPIO 18
#define SENSOR_PINS {4, 17, 27, 22}
#define POLL_INTERVAL 50 // milliseconds

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
    struct gpiod_line *led_line;
    int line_offset[] = SENSOR_PINS;
    int ret;
    int i;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines for sensors
    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_offset[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", line_offset[i]);
            ret = EXIT_FAILURE;
            goto cleanup;
        }
        ret = gpiod_line_request_input(lines[i], "sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as input\n", line_offset[i]);
            ret = EXIT_FAILURE;
            goto cleanup;
        }
    }

    // Request line for LED
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get line %d\n", LED_GPIO);
        ret = EXIT_FAILURE;
        goto cleanup;
    }
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output\n", LED_GPIO);
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    while (keep_running) {
        int object_detected = 0;

        // Poll sensor lines
        for (i = 0; i < 4; i++) {
            if (gpiod_line_get_value(lines[i]) == 0) {
                object_detected = 1;
                break;
            }
        }

        // Set LED based on sensor readings
        if (object_detected) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for POLL_INTERVAL milliseconds
        usleep(POLL_INTERVAL * 1000);
    }

cleanup:
    if (led_line) {
        gpiod_line_release(led_line);
    }
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret == EXIT_FAILURE ? EXIT_FAILURE : EXIT_SUCCESS;
}

