#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>
#include <errno.h>

#define NUM_SENSORS 5
#define DEBOUNCE_TIME_MS 50
#define POLL_INTERVAL_MS 1000

static volatile sig_atomic_t stop_flag = 0;

const int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
const char *sensor_ids[NUM_SENSORS] = {"Sensor 1", "Sensor 2", "Sensor 3", "Sensor 4", "Sensor 5"};

gpiod_chip *chip;
gpiod_line *lines[NUM_SENSORS];
int last_states[NUM_SENSORS] = {0};

void handle_signal(int sig) {
    stop_flag = 1;
}

void log_message(const char *message) {
    syslog(LOG_USER | LOG_INFO, "%s", message);
}

void log_error(const char *message) {
    syslog(LOG_USER | LOG_ERR, "%s", message);
}

void log_event(const char *sensor_id, int gpio_pin) {
    FILE *log_file = fopen("/var/log/flame_events.log", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        return;
    }

    if (flock(fileno(log_file), LOCK_EX) == -1) {
        log_error("Failed to lock log file");
        fclose(log_file);
        return;
    }

    time_t now = time(NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));

    fprintf(log_file, "%s - Sensor ID: %s (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);
    fflush(log_file);

    flock(fileno(log_file), LOCK_UN);
    fclose(log_file);
}

void release_resources() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

int main() {
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    log_message("Flame monitor started");

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            log_error("Failed to get line for GPIO");
            release_resources();
            closelog();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(lines[i], sensor_ids[i], 0) < 0) {
            log_error("Failed to request line as input");
            release_resources();
            closelog();
            return EXIT_FAILURE;
        }
    }

    while (!stop_flag) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value;
            if (gpiod_line_get_value(lines[i], &value) < 0) {
                log_error("Failed to read line value");
                continue;
            }

            if (value == 0 && last_states[i] == 1) {
                usleep(DEBOUNCE_TIME_MS * 1000);
                if (gpiod_line_get_value(lines[i], &value) < 0) {
                    log_error("Failed to read line value for debounce");
                    continue;
                }

                if (value == 0) {
                    log_event(sensor_ids[i], sensor_pins[i]);
                }
            }
            last_states[i] = value;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    release_resources();
    log_message("Flame monitor stopped");
    closelog();
    return EXIT_SUCCESS;
}

