            int value;
            if (gpiod_line_get_value(lines[i], &value) < 0) {
                log_error("Failed to read line value");
                continue;
            }

            if (value == 0 && last_states[i] == 1) {
                usleep(DEBOUNCE_TIME_MS * 1000);
                if (gpiod_line_get_value(lines[i], &value) < 0) {
                    log_error("Failed to read line value for debounce");
                    continue;
                }

                if (value == 0) {
                    log_event(sensor_ids[i], sensor_pins[i]);
                }
            }
            last_states[i] = value;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    release_resources();
    log_message("Flame monitor stopped");
    closelog();
    return EXIT_SUCCESS;
}
