        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d: %s\n", bcm_pins[i], strerror(errno));
            gpiod_line_bulk_free(lines);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Get individual lines
    for (i = 0; i < NUM_SENSORS; i++) {
        line = gpiod_line_get(lines, i);
        if (!line) {
            fprintf(stderr, "Failed to get line %d\n", i);
            gpiod_line_bulk_free(lines);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
