            if (state != prev_states[i]) {
                log_state_change(i, bcm_pins[i], state);
                prev_states[i] = state;
            }

            gpiod_line_release(line);
        }

        // Sleep for the polling interval
        struct timespec ts = {0, POLL_INTERVAL_NS};
        nanosleep(&ts, NULL);
    }

    // Clean up
    gpiod_line_bulk_free(lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
