#define VEML7700_I2C_BUS 1
#define VEML7700_I2C_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("grow_log.txt", "a");
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(log_file, "%s %s\n", timestamp, message);
        fflush(log_file);
        fclose(log_file);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_message("Failed to initialize pigpio");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioI2COpen(VEML7700_I2C_BUS, VEML7700_I2C_ADDR) < 0) {
        log_message("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    uint16_t config_value = (0x00 << 8) | 0x00; // ALS gain 1/8, integration time 100 ms
    if (gpioI2CWriteReg16(VEML7700_I2C_BUS, VEML7700_I2C_ADDR, VEML7700_CONFIG_REG, config_value) < 0) {
        log_message("Failed to write to config register");
        gpioI2CClose(VEML7700_I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (gpioServoSetup(GPIO_LED, PWM_FREQUENCY, PWM_RANGE) < 0) {
        log_message("Failed to setup PWM");
        gpioI2CClose(VEML7700_I2C_BUS);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        uint16_t raw_lux;
        if (gpioI2CReadReg16(VEML7700_I2C_BUS, VEML7700_I2C_ADDR, VEML7700_ALS_REG, &raw_lux) < 0) {
            log_message("Failed to read ALS register");
            continue;
        }

        float lux = raw_lux * 0.0576;
        int brightness = 0;

        if (lux < 100) {
            brightness = 100;
        } else if (lux < 500) {
            brightness = 75;
        } else if (lux < 1000) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        if (gpioServoWrite(GPIO_LED, brightness) < 0) {
            log_message("Failed to set PWM brightness");
        }

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "Lux: %.2f, Brightness: %d, Error: 0", lux, brightness);
        log_message(log_entry);

        sleep(1);
    }

    gpioServoWrite(GPIO_LED, 0);
    gpioI2CClose(VEML7700_I2C_BUS);
    gpioTerminate();

    return 0;
}

