#define NUM_CHANNELS 8
#define POLL_INTERVAL 50 // milliseconds
#define DEBOUNCE_TIME 200 // milliseconds

#define GPIO_LED 17
#define GPIO_START 2
#define GPIO_END 9

static int gpiod = -1;
static int last_state[NUM_CHANNELS] = {0};
static int debounce[NUM_CHANNELS] = {0};
static volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
    gpioWrite(GPIO_LED, 0);
    gpioTerminate(gpiod);
    exit(0);
}

void log_touch(int channel) {
    FILE *file = fopen("touch_log.txt", "a");
    if (!file) {
        fprintf(stderr, "Error opening touch_log.txt for writing\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s - Channel %d Touched\n", buffer, channel + 1);
    if (ferror(file)) {
        fprintf(stderr, "Error writing to touch_log.txt\n");
    }
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    gpiod = gpioInitialise();

    if (gpiod < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(GPIO_START + i, PI_INPUT) < 0 ||
            gpioSetPullUpDown(GPIO_START + i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to configure GPIO %d\n", GPIO_START + i);
            gpioTerminate(gpiod);
            return 1;
        }
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure GPIO %d\n", GPIO_LED);
        gpioTerminate(gpiod);
        return 1;
    }

    gpioWrite(GPIO_LED, 0);

    while (!stop) {
        int current_state[NUM_CHANNELS];
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            current_state[i] = gpioRead(GPIO_START + i);

            if (current_state[i] && !last_state[i]) {
                if (debounce[i] == 0) {
                    debounce[i] = 1;
                    log_touch(i);
                }
            } else if (!current_state[i]) {
                debounce[i] = 0;
            }

            if (debounce[i]) {
                if (gpioTickDiff(debounce[i]) > DEBOUNCE_TIME) {
                    debounce[i] = 0;
                }
            }

            if (current_state[i]) {
                any_touched = 1;
            }

            last_state[i] = current_state[i];
        }

        if (any_touched && !gpioRead(GPIO_LED)) {
            gpioWrite(GPIO_LED, 1);
        } else if (!any_touched && gpioRead(GPIO_LED)) {
            gpioWrite(GPIO_LED, 0);
        }

        usleep(POLL_INTERVAL * 1000);
    }

    gpioWrite(GPIO_LED, 0);
    gpioTerminate(gpiod);
    return 0;
}

