#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define LOG_FILE "light_data.txt"

static int i2c_handle;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void write_config_word() {
    uint16_t config_word = CONFIG_WORD;
    // Swap bytes for big-endian
    config_word = (config_word >> 8) | (config_word << 8);
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config_word, 0) != 0) {
        log_error("Failed to write configuration word to OPT3001");
    }
}

uint16_t read_result_word() {
    uint16_t result;
    if (i2cReadWordData(i2c_handle, RESULT_REG, &result, 0) != 0) {
        log_error("Failed to read result from OPT3001");
        return 0;
    }
    // Swap bytes for big-endian
    result = (result >> 8) | (result << 8);
    return result;
}

double compute_lux(uint16_t result) {
    int exponent = (result >> 12) & 0x0F;
    int mantissa = result & 0x0FFF;
    return mantissa * 0.01 * (1 << exponent);
}

void log_lux(double lux) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        log_error("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s, %.2f\n", time_str, lux);
    fflush(file);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_config_word();
    gpioDelay(100); // Wait for the first conversion

    while (keep_running) {
        uint16_t result = read_result_word();
