        snprintf(log_message, sizeof(log_message), "Sensor value: %d", sensor_value);
        log_event(log_message);

        if (sensor_value == 0) { // Flame detected
            if (gpioWrite(ALERT_GPIO, 1) < 0) {
                log_event("Error setting ALERT_GPIO HIGH");
            } else {
                usleep(ALERT_DURATION * 1000);
                if (gpioWrite(ALERT_GPIO, 0) < 0) {
                    log_event("Error setting ALERT_GPIO LOW");
                }
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "Error resetting ALERT_GPIO\n");
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

