#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL_MS 50
#define LOG_FILE "touch_log.txt"

static int line = -1;
static struct gpiod_chip *chip = NULL;
static FILE *log_file = NULL;
static int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_touch_event(const char *event) {
    if (!log_file) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", time_str, event);
    fflush(log_file);
}

void cleanup() {
    if (line >= 0) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line < 0) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "TTP223 Touch Sensor", GPIOD_LINE_REQ_DIR_IN) < 0) {
        fprintf(stderr, "Failed to request line %d as input\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_active_low(line) < 0) {
        fprintf(stderr, "Failed to set line %d as active low\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int last_state = -1;
    while (running) {
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Failed to read line value\n");
            break;
        }

        if (state != last_state) {
            if (state == 0) {
                log_touch_event("Touch Detected");
            } else {
                log_touch_event("Touch Released");
            }
            last_state = state;
        }

        usleep(DEBOUNCE_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

