#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define COMMAND 0x3608
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SAMPLE_INTERVAL 1000 // 1 second in milliseconds
#define FLOW_RATE_DIVISOR 90.0
#define MIN_FLOW_RATE 0.0
#define MAX_FLOW_RATE 100.0

static int i2c_handle = -1;
static int file_descriptor = -1;
static int first_write = 1;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_data(double flow_rate, int status) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (file_descriptor == -1) {
        file_descriptor = open("cooling_log.csv", O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (file_descriptor == -1) {
            fprintf(stderr, "Error opening file: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        dprintf(file_descriptor, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    dprintf(file_descriptor, "%s,%.2f,%s\n", timestamp, flow_rate, status == 0 ? "OK" : status == 1 ? "ERROR" : "INVALID");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (first_write) {
            if (i2cWrite(i2c_handle, (char *)&COMMAND, 2) != 2) {
                fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
                i2cClose(i2c_handle);
                i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Failed to reopen I2C bus: %s\n", strerror(errno));
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
                continue;
            }
            first_write = 0;
            usleep(2000); // Wait at least 2 ms
        }

        uint8_t buffer[3];
        if (i2cRead(i2c_handle, (char *)buffer, 3) != 3) {
            fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
            log_data(0.0, 1); // Log error
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to reopen I2C bus: %s\n", strerror(errno));
                gpioTerminate();
                return EXIT_FAILURE;
            }
            continue;
        }

        int16_t raw_value = (buffer[0] << 8) | buffer[1];
        uint8_t crc = calculate_crc8(buffer, 2);
        int status = 0;

        if (crc != buffer[2]) {
            fprintf(stderr, "CRC check failed\n");
            log_data(0.0, 1); // Log error
            status = 1;
        } else {
            double flow_rate = raw_value / FLOW_RATE_DIVISOR;
            if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
                log_data(flow_rate, 2); // Log invalid
                status = 2;
            } else {
                log_data(flow_rate, 0); // Log OK
            }
        }
        usleep(SAMPLE_INTERVAL * 1000); // Sample once per second
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (file_descriptor >= 0) {
        close(file_descriptor);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

