#define GPIO_MIDDLE 27
#define GPIO_RIGHT 22
#define POLL_INTERVAL_NS 50000000 // 50 ms in nanoseconds

static int fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line_left, *line_middle, *line_right;
static FILE *log_file;

void cleanup_and_exit(int signum) {
    if (line_left) gpiod_line_release(line_left);
    if (line_middle) gpiod_line_release(line_middle);
    if (line_right) gpiod_line_release(line_right);
    if (chip) gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
