    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        perror("fprintf");
        cleanup_and_exit(EXIT_FAILURE);
    }
    fflush(log_file);
}

