    if (!chip) {
        perror("gpiod_chip_get");
        gpiod_chip_close(fd);
        return EXIT_FAILURE;
    }

    line_left = gpiod_chip_get_line(chip, GPIO_LEFT);
    if (!line_left || gpiod_line_request_input(line_left, "left_sensor", GPIOD_LINE_REQ_EV_NONE) < 0) {
        perror("gpiod_line_request_input left");
        cleanup_and_exit(EXIT_FAILURE);
    }

    line_middle = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    if (!line_middle || gpiod_line_request_input(line_middle, "middle_sensor", GPIOD_LINE_REQ_EV_NONE) < 0) {
        perror("gpiod_line_request_input middle");
        cleanup_and_exit(EXIT_FAILURE);
    }

    line_right = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (!line_right || gpiod_line_request_input(line_right, "right_sensor", GPIOD_LINE_REQ_EV_NONE) < 0) {
        perror("gpiod_line_request_input right");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen("path_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        cleanup_and_exit(EXIT_FAILURE);
    }

    setup_signal_handler();

    fprintf(log_file, "timestamp,left,middle,right\n");
    fflush(log_file);

    while (true) {
        int left = gpiod_line_get_value(line_left);
        int middle = gpiod_line_get_value(line_middle);
        int right = gpiod_line_get_value(line_right);

        log_reading(left, middle, right);

        nanosleep((const struct timespec[]){{0, POLL_INTERVAL_NS}}, NULL);
    }

    return EXIT_SUCCESS;
}

