#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_LINE "gpio4" // BCM GPIO4
#define FLAME_DETECTED 0

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *message) {
    FILE *file = fopen("flame_events.txt", "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(file, "[%s] %s\n", timestamp, message);
    fclose(file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int ret;

    // Setup signal handling for clean exit
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the line
    line = gpiod_chip_get_line(chip, gpiod_chip_get_line_by_name(chip, GPIO_LINE));
    if (!line) {
        fprintf(stderr, "Failed to get line %s\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the line as input
    ret = gpiod_line_request_input(line, "flame_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %s as input: %s\n", GPIO_LINE, gpiod_strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up event detection for falling edge
    ret = gpiod_line_event_configure(line, GPIOD_LINE_EVENT_FALLING_EDGE, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure event detection: %s\n", gpiod_strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Event loop
    while (keep_running) {
        ret = gpiod_line_event_wait(line, -1);
        if (ret < 0) {
            if (errno == EINTR) {
                continue; // Interrupted by signal, continue loop
            }
            fprintf(stderr, "Failed to wait for event: %s\n", gpiod_strerror(-ret));
            break;
        }

        // Read the event
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read event: %s\n", gpiod_strerror(-ret));
            break;
        }

        // Check if the event is a falling edge
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
            printf("ALERT: Flame detected at %s\n", timestamp);
            log_event("Flame detected");
        }
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

