#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24
#define GPIO_CHIP "/dev/gpiochip4"
#define LOG_FILE "touch_log.txt"

static int touch_fd = -1;
static int led_fd = -1;
static int log_fd = -1;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *event) {
    if (log_fd < 0) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    dprintf(log_fd, "%s: %s\n", timestamp, event);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *touch_line, *led_line;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handling for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    // Request touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get line for touch sensor\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(touch_line, "touch_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request touch sensor line: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get line for LED\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(-ret));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial LED state to off
    gpiod_line_set_value(led_line, 0);
    log_event("LED turned off");

    // Set up event monitoring
    ret = gpiod_line_event_register_rising_edge(touch_line, &event, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to register event: %s\n", strerror(-ret));
        close(log_fd);
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        ret = gpiod_line_event_wait(&event, 1000000); // 1-second timeout
        if (ret < 0) {
            if (errno == EINTR) {
                continue; // Interrupted by signal
            }
            fprintf(stderr, "Event wait failed: %s\n", strerror(-ret));
            break;
        }

        if (ret == 0) {
            continue; // Timeout, no event
        }

        // Toggle LED state
        int led_state = gpiod_line_get_value(led_line);
        gpiod_line_set_value(led_line, !led_state);
        char *state_str = led_state ? "on" : "off";
        log_event(state_str);
    }

    // Cleanup
    gpiod_line_event_unregister(touch_line);
    gpiod_line_release(led_line);
    gpiod_line_release(touch_line);
    gpiod_chip_close(chip);
    if (log_fd >= 0) {
        close(log_fd);
    }

    return EXIT_SUCCESS;
}

