#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL 10
#define DEBOUNCE_TIME 200
#define LOG_FILE "touch_log.txt"

volatile sig_atomic_t keep_running = 1;
FILE *log_file = NULL;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_touch_event() {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_touch_state = 0;
    int current_touch_state = 0;
    int last_toggle_state = 0;
    unsigned long last_touch_time = 0;

    while (keep_running) {
        current_touch_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_touch_state == 1 && last_touch_state == 0) {
            unsigned long current_time = millis();
            if (current_time - last_touch_time > DEBOUNCE_TIME) {
                last_toggle_state = !last_toggle_state;
                gpioWrite(LED_PIN, last_toggle_state);
                log_touch_event();
                last_touch_time = current_time;
            }
        }

        last_touch_state = current_touch_state;
        usleep(POLL_INTERVAL * 1000);
    }

    gpioWrite(LED_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

