#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_GPIO_1 4
#define SENSOR_GPIO_2 17
#define SENSOR_GPIO_3 27
#define POLL_INTERVAL 100000 // 100 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_state_change(FILE *log_file, int sensor_id, int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "[%s] Sensor %d: %s\n", timestamp, sensor_id, state ? "Magnet Removed" : "Magnet Present");
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Configure GPIOs for input with pull-up
    if (gpioSetMode(SENSOR_GPIO_1, PI_INPUT) != 0 ||
        gpioSetPullUpDown(SENSOR_GPIO_1, PI_PUD_UP) != 0 ||
        gpioSetMode(SENSOR_GPIO_2, PI_INPUT) != 0 ||
        gpioSetPullUpDown(SENSOR_GPIO_2, PI_PUD_UP) != 0 ||
        gpioSetMode(SENSOR_GPIO_3, PI_INPUT) != 0 ||
        gpioSetPullUpDown(SENSOR_GPIO_3, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to configure GPIOs\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("magnet_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    int initial_state[3] = {-1, -1, -1};
    int current_state[3] = {0, 0, 0};

    while (keep_running) {
        int sensor_values[3];
        sensor_values[0] = gpioRead(SENSOR_GPIO_1);
        sensor_values[1] = gpioRead(SENSOR_GPIO_2);
        sensor_values[2] = gpioRead(SENSOR_GPIO_3);

        for (int i = 0; i < 3; i++) {
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
                continue;
            }

            if (initial_state[i] == -1) {
                initial_state[i] = sensor_values[i];
                current_state[i] = sensor_values[i];
            } else if (current_state[i] != sensor_values[i]) {
                log_state_change(log_file, i + 1, sensor_values[i]);
                current_state[i] = sensor_values[i];
            }
        }

        gpioDelay(POLL_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

