#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HR_REG 0x2A

#define PART_ID_EXPECTED 0x02
#define HW_REV_EXPECTED 0x01

#define SAMPLES 5
#define MIN_BPM 30
#define MAX_BPM 220

static int i2c_handle;
static FILE *log_file;
static int samples[SAMPLES] = {0};
static int sample_index = 0;
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_bpm(int bpm) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file);
}

int read_word_data(int reg) {
    int value;
    if (i2cReadWordData(i2c_handle, reg, &value) < 0) {
        fprintf(stderr, "I2C read error on register 0x%02X\n", reg);
        return -1;
    }
    return value;
}

void write_byte_data(int reg, int value) {
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "I2C write error on register 0x%02X\n", reg);
        exit(EXIT_FAILURE);
    }
}

int get_filtered_bpm() {
    int raw_value = read_word_data(HR_REG);
    if (raw_value < 0) return -1;

    int bpm = raw_value * 0.5;
    samples[sample_index] = bpm;
    sample_index = (sample_index + 1) % SAMPLES;

    int sum = 0;
    for (int i = 0; i < SAMPLES; i++) {
        sum += samples[i];
    }
    return sum / SAMPLES;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int part_id = read_word_data(PART_ID_REG);
    if (part_id != PART_ID_EXPECTED) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int hw_rev = read_word_data(HW_REV_REG);
    if (hw_rev != HW_REV_EXPECTED) {
        fprintf(stderr, "Invalid HW_REV: 0x%02X\n", hw_rev);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_byte_data(LED_CURRENT_REG, 0x3F);
    write_byte_data(AVERAGING_REG, 0x04);
    write_byte_data(ENABLE_REG, 0x01);

    log_file = fopen("heart_rate.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int bpm = get_filtered_bpm();
        if (bpm >= MIN_BPM && bpm <= MAX_BPM) {
            log_bpm(bpm);
        }
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

