void log_flame_detection() {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = '\0'; // Remove newline

    fprintf(log_file, "[%s] FLAME DETECTED\n", timestamp);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, gpiod_chip_get_line_by_name(chip, GPIO_LINE_NAME));
    if (!line) {
        fprintf(stderr, "Line %s not found\n", GPIO_LINE_NAME);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "flame_sensor", GPIOD_LINE_REQUEST_DIRENABLE | GPIOD_LINE_REQUEST_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request line %s as input\n", GPIO_LINE_NAME);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

