        if (gpiod_line_event_wait(line, POLL_INTERVAL_NS) < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        if (gpiod_line_event_read(line) == GPIOD_LINE_EVENT_FALLING_EDGE) {
            printf("FLAME DETECTED\n");
            log_flame_detection();
