#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_CHANNELS 8
#define OUTPUT_CHANNELS 8
#define POLL_INTERVAL 10 // milliseconds
#define STABILIZATION_DELAY 200 // milliseconds

static volatile sig_atomic_t keep_running = 1;
static int counter = 0;
static int sensor_lines[SENSOR_CHANNELS];
static int output_lines[OUTPUT_CHANNELS];
static int chip_fd;
static struct timespec ts;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_touch_event(int channel, int counter_value) {
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = gmtime(&now);
        char buffer[80];
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", tm_info);
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", buffer, channel, counter_value);
        fflush(log_file);
    }
}

void update_outputs(int counter_value) {
    for (int i = 0; i < OUTPUT_CHANNELS; i++) {
        int value = (counter_value >> i) & 1;
        if (gpiod_line_set_value(output_lines[i], value) < 0) {
            fprintf(stderr, "Failed to set output line %d: %s\n", i + 17, strerror(errno));
        }
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *requests[SENSOR_CHANNELS];
    struct gpiod_line *lines[SENSOR_CHANNELS];
    struct gpiod_line_request *output_requests[OUTPUT_CHANNELS];
    struct gpiod_line *output_lines_struct[OUTPUT_CHANNELS];
    int sensor_pins[SENSOR_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
    int output_pins[OUTPUT_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};
    int prev_states[SENSOR_CHANNELS] = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip_fd = gpiod_chip_get_fd(chip);
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to get GPIO chip file descriptor: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < SENSOR_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        requests[i] = gpiod_line_request_alloc(lines[i], "touch_sensor", GPIOD_LINE_REQ_DIR_IN);
        if (!requests[i]) {
            fprintf(stderr, "Failed to allocate request for line %d: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_set_flags(requests[i], GPIOD_LINE_REQ_FLAG_ACTIVE_HIGH) < 0) {
            fprintf(stderr, "Failed to set flags for line %d: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_set_consumer(requests[i], "touch_counter") < 0) {
            fprintf(stderr, "Failed to set consumer for line %d: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        sensor_lines[i] = gpiod_line_request_get_line(requests[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get line for request %d: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < OUTPUT_CHANNELS; i++) {
        output_lines_struct[i] = gpiod_chip_get_line(chip, output_pins[i]);
        if (!output_lines_struct[i]) {
            fprintf(stderr, "Failed to get output line %d: %s\n", output_pins[i], strerror(errno));
            goto cleanup;
        }
        output_requests[i] = gpiod_line_request_alloc(output_lines_struct[i], "output_counter", GPIOD_LINE_REQ_DIR_OUT);
        if (!output_requests[i]) {
            fprintf(stderr, "Failed to allocate request for output line %d: %s\n", output_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_set_flags(output_requests[i], GPIOD_LINE_REQ_FLAG_ACTIVE_HIGH) < 0) {
            fprintf(stderr, "Failed to set flags for output line %d: %s\n", output_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_set_consumer(output_requests[i], "touch_counter") < 0) {
            fprintf(stderr, "Failed to set consumer for output line %d: %s\n", output_pins[i], strerror(errno));
            goto cleanup;
        }
        output_lines[i] = gpiod_line_request_get_line(output_requests[i]);
        if (!output_lines[i]) {
            fprintf(stderr, "Failed to get line for output request %d: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    if (gpiod_chip_request_lines(chip, requests, SENSOR_CHANNELS) < 0) {
        fprintf(stderr, "Failed to request sensor lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_chip_request_lines(chip, output_requests, OUTPUT_CHANNELS) < 0) {
        fprintf(stderr, "Failed to request output lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_chip_wait(chip, STABILIZATION_DELAY) < 0) {
        fprintf(stderr, "Failed during stabilization delay: %s\n", strerror(errno));
        goto cleanup;
    }

    if ((log_file = fopen("touch_log.txt", "a")) == NULL) {
        fprintf(stderr, "Warning: Failed to open log file: %s\n", strerror(errno));
    }

    update_outputs(counter);

    while (keep_running) {
        for (int i = 0; i < SENSOR_CHANNELS; i++) {
            int value = gpiod_line_get_value(sensor_lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read sensor line %d: %s\n", i + 1, strerror(errno));
                continue;
            }

            if (value && !prev_states[i]) {
                prev_states[i] = 1;
                counter = (counter + 1) % 256;
                log_touch_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
                update_outputs(counter);
            } else if (!value) {
                prev_states[i] = 0;
            }
        }

        nanosleep(&ts, NULL);
    }

cleanup:
    for (int i = 0; i < SENSOR_CHANNELS; i++) {
        if (requests[i]) {
            gpiod_line_release(sensor_lines[i]);
            gpiod_line_request_free(requests[i]);
        }
    }

    for (int i = 0; i < OUTPUT_CHANNELS; i++) {
        if (output_requests[i]) {
            gpiod_line_release(output_lines[i]);
            gpiod_line_request_free(output_requests[i]);
        }
    }

    if (log_file) {
        fclose(log_file);
    }

    update_outputs(0);

    gpiod_chip_close(chip);
    close(chip_fd);

    return EXIT_SUCCESS;
}

