#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27
#define GPIO_22 22

#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t keep_running = 1;
static FILE *csv_file = NULL;
static struct gpiod_chip *chip;
static struct gpiod_line *lines[4];
static int line_fds[4];

void handle_signal(int sig) {
    keep_running = 0;
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    lines[0] = gpiod_chip_get_line(chip, GPIO_17);
    lines[1] = gpiod_chip_get_line(chip, GPIO_18);
    lines[2] = gpiod_chip_get_line(chip, GPIO_27);
    lines[3] = gpiod_chip_get_line(chip, GPIO_22);

    if (!lines[0] || !lines[1] || !lines[2] || !lines[3]) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_input(lines[i], "tracking_module") < 0) {
            fprintf(stderr, "Failed to request line %d as input\n", GPIO_17 + i);
            gpiod_chip_close(chip);
            return -1;
        }
    }

    return 0;
}

void cleanup_gpio() {
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

void open_csv_file() {
    csv_file = fopen("tracking_log.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    if (fseek(csv_file, 0, SEEK_END) == 0 && ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(csv_file);
    }
}

void close_csv_file() {
    if (csv_file) {
        fclose(csv_file);
        csv_file = NULL;
    }
}

void log_sensor_data() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[64];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    int values[4];
