        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line17, "tilt_sensor_17", GPIOD_LINE_REQ_EV_BOTH_EDGES | GPIOD_LINE_REQ_DEBOUNCE | GPIOD_LINE_REQ_FLAG_BIAS_PULL_UP) < 0) {
