        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to LOW\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

