#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x49
#define ALS_LSB_REG 0x24
#define ALS_MSB_REG 0x25
#define READ_INTERVAL 100 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_read_byte_data(int fd, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buffer, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }

    return buffer[0];
}

int main() {
    int i2c_fd;
    uint8_t lsb, msb;
    uint16_t als_value;
    struct sigaction sa;

    // Set up signal handler for clean exit
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting up signal handler");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read LSB
        lsb = i2c_read_byte_data(i2c_fd, ALS_LSB_REG);
        if (lsb < 0) {
            fprintf(stderr, "Error reading ALS LSB register\n");
            continue;
        }

        // Read MSB
        msb = i2c_read_byte_data(i2c_fd, ALS_MSB_REG);
        if (msb < 0) {
            fprintf(stderr, "Error reading ALS MSB register\n");
            continue;
        }

        // Combine LSB and MSB into a 16-bit value
        als_value = (msb << 8) | lsb;

        // Log the raw sensor value
        printf("ALS Value: 0x%04X\n", als_value);

        // Wait for the next read interval
        usleep(READ_INTERVAL * 1000);
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

