static gpiod_chip *chip = NULL;
static gpiod_line *lines[NUM_CHANNELS] = {NULL};
static int running = 1;

static const int bcm_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

void handle_signal(int signum) {
    running = 0;
}

void log_error_and_exit(const char *message) {
    perror(message);
    cleanup();
    exit(EXIT_FAILURE);
}

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error_and_exit("Failed to set signal handler");
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error_and_exit("Failed to open gpiochip0");
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, bcm_pins[i]);
        if (!lines[i]) {
            log_error_and_exit("Failed to get line for GPIO");
        }
        if (gpiod_line_request_input(lines[i], "TP%d", bcm_pins[i]) < 0) {
            log_error_and_exit("Failed to request line as input");
        }
    }

    while (running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            log_error_and_exit("Failed to get monotonic time");
        }

        printf("[%0.3fs] ", ts.tv_sec + ts.tv_nsec / 1e9);
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value;
            if (gpiod_line_get_value(lines[i], &value) < 0) {
                fprintf(stderr, "Failed to read value from line %d\n", i + 1);
                continue;
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

