#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define FADE_STEPS 50
#define FADE_INTERVAL 50 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

void hsv_to_rgb(uint8_t hue, uint8_t *r, uint8_t *g, uint8_t *b) {
    int sector = hue / 43;
    int remainder = (hue - (sector * 43)) * 6;

    uint8_t p = 0;
    uint8_t q = 255;
    uint8_t t = (remainder * 255) / 43;

    switch (sector) {
        case 0:
            *r = 255;
            *g = t;
            *b = p;
            break;
        case 1:
            *r = q;
            *g = 255;
            *b = p;
            break;
        case 2:
            *r = p;
            *g = 255;
            *b = t;
            break;
        case 3:
            *r = p;
            *g = q;
            *b = 255;
            break;
        case 4:
            *r = t;
            *g = p;
            *b = 255;
            break;
        default:
            *r = 255;
            *g = p;
            *b = q;
            break;
    }
}

void fade_led(int red_pin, int green_pin, int blue_pin, uint8_t start_r, uint8_t start_g, uint8_t start_b, uint8_t end_r, uint8_t end_g, uint8_t end_b) {
    int step_r = (end_r - start_r) / FADE_STEPS;
    int step_g = (end_g - start_g) / FADE_STEPS;
    int step_b = (end_b - start_b) / FADE_STEPS;

    for (int i = 0; i <= FADE_STEPS; i++) {
        uint8_t r = start_r + (i * step_r);
        uint8_t g = start_g + (i * step_g);
        uint8_t b = start_b + (i * step_b);

        gpioPWM(red_pin, PWM_RANGE - r);
        gpioPWM(green_pin, PWM_RANGE - g);
        gpioPWM(blue_pin, PWM_RANGE - b);

        usleep(FADE_INTERVAL * 1000);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode");
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioPWM(RED_PIN, PWM_FREQUENCY) < 0 ||
        gpioPWM(GREEN_PIN, PWM_FREQUENCY) < 0 ||
        gpioPWM(BLUE_PIN, PWM_FREQUENCY) < 0) {
        log_error("Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return 1;
    }

    srand(time(NULL) ^ (getpid() << 16) ^ (getppid() << 8) ^ (getuid()));

    uint8_t start_r = 0, start_g = 0, start_b = 0;
    uint8_t end_r = 0, end_g = 0, end_b = 0;

    while (keep_running) {
        uint8_t hue = rand() % 360;
        hsv_to_rgb(hue, &end_r, &end_g, &end_b);

        fade_led(RED_PIN, GREEN_PIN, BLUE_PIN, start_r, start_g, start_b, end_r, end_g, end_b);

        start_r = end_r;
        start_g = end_g;
        start_b = end_b;

        sleep(5);
    }

    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    gpioTerminate();
    closelog();

    return 0;
}

