#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_RDATAL 0x16
#define TCS34725_GDATAL 0x18
#define TCS34725_BDATAL 0x1A

#define GPIO_LED 17
#define RED_THRESHOLD 200

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_word_data(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = buffer[0] | (buffer[1] << 8);
    return 0;
}

int initialize_sensor(int fd) {
    if (i2c_write_byte_data(fd, TCS34725_ENABLE, TCS34725_COMMAND_BIT | 0x01) != 0) return -1; // PON
    if (i2c_write_byte_data(fd, TCS34725_ENABLE, TCS34725_COMMAND_BIT | 0x03) != 0) return -1; // AEN
    if (i2c_write_byte_data(fd, TCS34725_ATIME, 0x00) != 0) return -1; // ATIME
    if (i2c_write_byte_data(fd, TCS34725_CONTROL, 0x00) != 0) return -1; // CONTROL

    uint16_t id;
    if (i2c_read_word_data(fd, TCS34725_ID, &id) != 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x44, got 0x%04X\n", id);
        return -1;
    }
    return 0;
}

int read_sensor(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (i2c_read_word_data(fd, TCS34725_CDATAL, clear) != 0) return -1;
    if (i2c_read_word_data(fd, TCS34725_RDATAL, red) != 0) return -1;
    if (i2c_read_word_data(fd, TCS34725_GDATAL, green) != 0) return -1;
    if (i2c_read_word_data(fd, TCS34725_BDATAL, blue) != 0) return -1;
    return 0;
}

void calibrate_and_display(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    // Apply per-channel gain and offset calibration (example values)
    float gain = 1.0;
    float offset = 0.0;
    float calibrated_red = (red * gain) + offset;
    float calibrated_green = (green * gain) + offset;
    float calibrated_blue = (blue * gain) + offset;
    float calibrated_clear = (clear * gain) + offset;

    printf("C: %d, R: %.2f, G: %.2f, B: %.2f\n", clear, calibrated_red, calibrated_green, calibrated_blue);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "led_control", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint16_t clear, red, green, blue;
    while (keep_running) {
        if (read_sensor(i2c_fd, &clear, &red, &green, &blue) != 0) {
            fprintf(stderr, "Failed to read sensor data, reinitializing...\n");
            if (initialize_sensor(i2c_fd) != 0) {
                fprintf(stderr, "Failed to reinitialize sensor\n");
                break;
            }
        } else {
            calibrate_and_display(clear, red, green, blue);
            gpiod_line_set_value(line, red > RED_THRESHOLD);
        }
        usleep(200000); // Poll every 200 ms
    }

    // Power down the sensor
    if (i2c_write_byte_data(i2c_fd, TCS34725_ENABLE, 0x00) != 0) {
        fprintf(stderr, "Failed to power down sensor\n");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

