#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_LUX 1000.0
#define RETRY_LIMIT 5

static int pi;
static int i2c_handle;
static int wave_id = -1;
static int running = 1;

void handle_signal(int sig) {
    running = 0;
}

double read_lux() {
    unsigned char data[2];
    int retries = 0;
    int result;

    while (retries < RETRY_LIMIT) {
        result = i2c_write_i2c_block_data(i2c_handle, BH1750_CONTINUOUS_HIGH_RES_MODE, 0, 0);
        if (result < 0) {
            fprintf(stderr, "I2C write error: %s\n", pi_i2c_error(result));
            retries++;
            usleep(100000); // 100 ms
            continue;
        }

        usleep(180000); // 180 ms

        result = i2c_read_i2c_block_data(i2c_handle, 0x00, 2, data);
        if (result < 0) {
            fprintf(stderr, "I2C read error: %s\n", pi_i2c_error(result));
            retries++;
            usleep(100000); // 100 ms
            continue;
        }

        if (result == 2) {
            return ((data[0] << 8) | data[1]) / 1.2;
        }

        retries++;
        usleep(100000); // 100 ms
    }

    fprintf(stderr, "Failed to read from BH1750 after %d retries\n", RETRY_LIMIT);
    return -1;
}

double map_lux_to_brightness(double lux) {
    if (lux < 0) return 0.0;
    double normalized_lux = fmin(lux / MAX_LUX, 1.0);
    return pow(normalized_lux, 0.5) * 255.0; // Logarithmic mapping
}

void update_led_brightness(double brightness) {
    unsigned char led_data[10 * 3]; // 10 LEDs, 3 bytes per LED
    int i;

    for (i = 0; i < 10; i++) {
        int br = (int)brightness;
        led_data[i * 3] = 0xFF; // Red
        led_data[i * 3 + 1] = br; // Green
        led_data[i * 3 + 2] = 0x00; // Blue
    }

    wave_id = piWaveAddGeneric(pi, 10, led_data, 3, 800000, 0, 0);
    if (wave_id < 0) {
        fprintf(stderr, "Failed to create wave: %s\n", pi_error(pi));
        running = 0;
    } else {
        piWaveSendOnce(pi, wave_id, PI_WAVE_MODE_ONE_SHOT);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", pi_error(pi));
        return 1;
    }

    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_error(pi));
        return 1;
    }

    i2c_handle = piI2COpen(pi, I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pi_i2c_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        double lux = read_lux();
        double brightness = map_lux_to_brightness(lux);
        update_led_brightness(brightness);
        usleep(100000); // 100 ms
    }

    if (wave_id >= 0) {
        piWaveDelete(pi, wave_id);
    }

    piI2CClose(pi, i2c_handle);
    gpioTerminate();

    return 0;
}

