#include <linux/spi/spidev.h>
#include <errno.h>

#define BH1750_I2C_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x20
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 1

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int i2c_init(int *fd) {
    *fd = open(I2C_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(*fd);
        return -1;
    }

    return 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *data, size_t length) {
    if (read(fd, data, length) != length) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI parameters");
        close(*fd);
        return -1;
    }

    return 0;
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t length) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = length,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to transfer SPI message");
        return -1;
    }

    return 0;
}

void set_led_brightness(int spi_fd, uint8_t brightness) {
    uint8_t frame[4 * NUM_LEDS + 4];
    memset(frame, 0, sizeof(frame));

    frame[0] = 0x00; // Start frame
    frame[1] = 0x00;
    frame[2] = 0x00;
    frame[3] = 0x00;

    for (int i = 0; i < NUM_LEDS; i++) {
        frame[4 * (i + 1)] = 0xE0 | brightness; // Global brightness
        frame[4 * (i + 1) + 1] = 0x00; // Blue
        frame[4 * (i + 1) + 2] = 0x00; // Green
        frame[4 * (i + 1) + 3] = 0x00; // Red
    }

    frame[4 * (NUM_LEDS + 1)] = 0xFF; // End frame
    frame[4 * (NUM_LEDS + 1) + 1] = 0xFF;
    frame[4 * (NUM_LEDS + 1) + 2] = 0xFF;
    frame[4 * (NUM_LEDS + 1) + 3] = 0xFF;

    spi_transfer(spi_fd, frame, NULL, sizeof(frame));
}

int main() {
    int i2c_fd, spi_fd;
    uint8_t data[2];
    uint16_t raw_lux;
    float lux;
    uint8_t brightness;

    signal(SIGINT, handle_sigint);

    if (i2c_init(&i2c_fd) < 0 || spi_init(&spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2c_write(i2c_fd, BH1750_ONE_TIME_HIGH_RES_MODE, 0x00) < 0) {
            break;
        }

        usleep(120000); // Wait for conversion

        if (i2c_read(i2c_fd, data, 2) < 0) {
            break;
        }

        raw_lux = (data[0] << 8) | data[1];
        lux = raw_lux / 1.2;

        if (lux < 10) {
            brightness = 0;
        } else if (lux > 300) {
            brightness = 31;
        } else {
            brightness = (uint8_t)((lux - 10) * 31 / 290);
        }

        set_led_brightness(spi_fd, brightness);
        usleep(100000); // 100 ms delay
    }

    // Turn off LEDs
    set_led_brightness(spi_fd, 0);

    close(i2c_fd);
    close(spi_fd);

    return EXIT_SUCCESS;
}

