#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define APA102_MOSI 10
#define APA102_SCLK 11
#define APA102_RESET 25
#define APA102_NUM_LEDS 1

#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_ONE_TIME_HIGH_RES_MODE_2 0x21
#define BH1750_CONVERSION_TIME_MS 180
#define FADE_DURATION_MS 500
#define FADE_DELAY_MS 100

static int gpiod = -1;
static int i2c_handle_low = -1;
static int i2c_handle_high = -1;
static int spi_handle = -1;
static int current_brightness = 0;

void cleanup(int signum) {
    if (gpiod >= 0) {
        gpioTerminate(gpiod);
    }
    if (spi_handle >= 0) {
        gpioClose(spi_handle);
    }
    if (i2c_handle_low >= 0) {
        gpioClose(i2c_handle_low);
    }
    if (i2c_handle_high >= 0) {
        gpioClose(i2c_handle_high);
    }
    if (current_brightness > 0) {
        setAPA102Brightness(0);
    }
    exit(0);
}

void setAPA102Brightness(int brightness) {
    unsigned char data[4] = {0xE0, 0x00, brightness, 0};
    gpioWrite(APA102_RESET, 0);
    usleep(1000);
    gpioWrite(APA102_RESET, 1);
    usleep(1000);
    gpioWrite(APA102_RESET, 0);
    usleep(1000);
    gpioWrite(APA102_RESET, 1);
    usleep(1000);
    gpioWrite(spi_handle, data, 4);
}

int readBH1750(int handle, unsigned char *data) {
    if (gpioI2CWriteByte(handle, 0x20, BH1750_ONE_TIME_HIGH_RES_MODE_2) < 0) {
        return -1;
    }
    usleep(BH1750_CONVERSION_TIME_MS * 1000);
    return gpioI2CReadBytes(handle, 0x20, data, 2);
}

int main() {
    signal(SIGINT, cleanup);

    gpiod = gpioInitialise();
    if (gpiod < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle_low = gpioI2CSetup(gpiod, I2C_BUS, BH1750_ADDR_LOW);
    if (i2c_handle_low < 0) {
        fprintf(stderr, "Failed to open I2C handle for address 0x23\n");
    }

    i2c_handle_high = gpioI2CSetup(gpiod, I2C_BUS, BH1750_ADDR_HIGH);
    if (i2c_handle_high < 0) {
        fprintf(stderr, "Failed to open I2C handle for address 0x5C\n");
    }

    spi_handle = gpioSPISetup(gpiod, APA102_MOSI, APA102_SCLK, 0, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        cleanup(0);
    }

    gpioSetMode(APA102_RESET, PI_OUTPUT);
    gpioWrite(APA102_RESET, 1);

    while (1) {
        unsigned char data[2];
        int lux_values[3] = {0, 0, 0};
        int valid_sensors = 0;

        if (i2c_handle_low >= 0 && readBH1750(i2c_handle_low, data) == 2) {
            lux_values[0] = (data[0] << 8) | data[1];
            valid_sensors++;
        }

        if (i2c_handle_high >= 0 && readBH1750(i2c_handle_high, data) == 2) {
            lux_values[1] = (data[0] << 8) | data[1];
            valid_sensors++;
        }

        if (valid_sensors > 0) {
            int total_lux = 0;
            for (int i = 0; i < valid_sensors; i++) {
                total_lux += lux_values[i];
            }
            int average_lux = total_lux / valid_sensors;
            int target_brightness = 31 - (average_lux / 10); // Map lux to brightness
            if (target_brightness < 0) target_brightness = 0;
            if (target_brightness > 31) target_brightness = 31;

            int step = (target_brightness - current_brightness) / (FADE_DURATION_MS / FADE_DELAY_MS);
            for (int i = 0; i < abs(step); i++) {
                current_brightness += (step > 0) ? 1 : -1;
                setAPA102Brightness(current_brightness);
                usleep(FADE_DELAY_MS * 1000);
            }
            current_brightness = target_brightness;
        }

        usleep(FADE_DELAY_MS * 1000);
    }

    cleanup(0);
    return 0;
}

