#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define CONFIG_REG 0x00
#define ALS_DATA_REG 0x04
#define MAX_LUX 120000.0
#define GPIO_PIN 18
#define GPIO_LINE 18
#define HIGH_FREQ 800000
#define DELAY_US 1250 // 1 / HIGH_FREQ in microseconds

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to i2c bus");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("Failed to read from i2c bus");
        return -1;
    }

    return 0;
}

int init_veml7700(int fd) {
    uint8_t config = 0x0000;
    return i2c_write_read(fd, CONFIG_REG, &config, sizeof(config));
}

int read_als(int fd, uint16_t *als_value) {
    uint8_t data[2];
    if (i2c_write_read(fd, ALS_DATA_REG, data, sizeof(data)) < 0) {
        return -1;
    }

    *als_value = (data[0] << 8) | data[1];
    return 0;
}

int init_gpio(gpiod_chip *chip, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!*line) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LINE);
        return -1;
    }

    if (gpiod_line_request_output(*line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output\n", GPIO_LINE);
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

void set_brightness(gpiod_line *line, int brightness) {
    uint32_t period = DELAY_US * 1000; // Convert to nanoseconds
    uint32_t high_time = period * brightness / 255;
    uint32_t low_time = period - high_time;

    gpiod_line_set_value(line, 1);
    usleep(high_time / 1000);
    gpiod_line_set_value(line, 0);
    usleep(low_time / 1000);
}

void cleanup(gpiod_chip *chip, gpiod_line *line, int i2c_fd) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (init_veml7700(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize VEML7700\n");
        cleanup(NULL, NULL, i2c_fd);
        return EXIT_FAILURE;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup(NULL, NULL, i2c_fd);
        return EXIT_FAILURE;
    }

    gpiod_line *line = NULL;
    if (init_gpio(chip, &line) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup(chip, NULL, i2c_fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint16_t als_value = 0;
        int retries = 3;
        while (retries-- > 0) {
            if (read_als(i2c_fd, &als_value) == 0) {
                break;
            }
            usleep(100000); // 100 ms
        }

        if (retries < 0) {
            fprintf(stderr, "Failed to read ALS data after retries\n");
        } else {
            double lux = als_value * 0.0288;
            int brightness = (int)(255 * pow(lux / MAX_LUX, 1.0 / 2.2));
            brightness = brightness < 0 ? 0 : (brightness > 255 ? 255 : brightness);

            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
            set_brightness(line, brightness);
        }

        usleep(200000); // 200 ms
    }

    cleanup(chip, line, i2c_fd);
    return EXIT_SUCCESS;
}

