#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define POLL_INTERVAL 50 // milliseconds
#define SELF_TEST_INTERVAL 100 // milliseconds
#define BLINK_INTERVAL 500 // milliseconds
#define ERROR_BLINK_INTERVAL 100 // milliseconds
#define ERROR_BEEP_PATTERN {200, 200, 600, 200} // milliseconds
#define ERROR_BEEP_REPEATS 3

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *flame_sensor_line;
static struct gpiod_line *buzzer_line;
static struct gpiod_line *led_line;

void log_event(const char *event) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", timestamp, event);
}

void cleanup() {
    if (flame_sensor_line) gpiod_line_release(flame_sensor_line);
    if (buzzer_line) gpiod_line_release(buzzer_line);
    if (led_line) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    log_event("Exiting program");
    exit(0);
}

void signal_handler(int signum) {
    keep_running = 0;
}

int self_test() {
    int flame_detected_count = 0;
    int i;

    // Blink LED twice
    for (i = 0; i < 2; i++) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            log_event("Error setting LED value during self-test");
            return -1;
        }
        usleep(BLINK_INTERVAL * 1000);
        if (gpiod_line_set_value(led_line, 0) < 0) {
            log_event("Error setting LED value during self-test");
            return -1;
        }
        usleep(BLINK_INTERVAL * 1000);
    }

    // Read flame sensor 5 times
    for (i = 0; i < 5; i++) {
        if (gpiod_line_get_value(flame_sensor_line, &flame_detected_count) < 0) {
            log_event("Error reading flame sensor during self-test");
            return -1;
        }
        if (flame_detected_count == 0) {
            flame_detected_count++;
        }
        usleep(SELF_TEST_INTERVAL * 1000);
    }

    if (flame_detected_count == 5) {
        log_event("Self-test failed: Flame sensor fault detected");
        return -1;
    }

    log_event("Self-test passed");
    return 0;
}

void error_signal() {
    int i, j;
    for (i = 0; i < 5; i++) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            log_event("Error setting LED value during error signal");
            return;
        }
        usleep(ERROR_BLINK_INTERVAL * 1000);
        if (gpiod_line_set_value(led_line, 0) < 0) {
            log_event("Error setting LED value during error signal");
            return;
        }
        usleep(ERROR_BLINK_INTERVAL * 1000);
    }

    for (i = 0; i < ERROR_BEEP_REPEATS; i++) {
        for (j = 0; j < 4; j++) {
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                log_event("Error setting buzzer value during error signal");
                return;
            }
            usleep(ERROR_BEEP_PATTERN[j] * 1000);
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                log_event("Error setting buzzer value during error signal");
                return;
            }
        }
    }
}

int main() {
    int flame_detected_count = 0;
    int flame_detected = 0;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        cleanup();
    }
    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        perror("Failed to request flame sensor line");
        cleanup();
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        cleanup();
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line");
        cleanup();
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        cleanup();
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line");
        cleanup();
    }

    if (self_test() < 0) {
        error_signal();
        cleanup();
        exit(1);
    }

    while (keep_running) {
        if (gpiod_line_get_value(flame_sensor_line, &flame_detected_count) < 0) {
            log_event("Error reading flame sensor");
            continue;
        }

        if (flame_detected_count == 0 && !flame_detected) {
            flame_detected = 1;
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                log_event("Error setting buzzer value");
            }
            if (gpiod_line_set_value(led_line, 1) < 0) {
                log_event("Error setting LED value");
            }
            log_event("Flame detected");
        } else if (flame_detected_count != 0 && flame_detected) {
            flame_detected = 0;
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                log_event("Error setting buzzer value");
            }
            if (gpiod_line_set_value(led_line, 0) < 0) {
                log_event("Error setting LED value");
            }
            log_event("Flame gone");
        }

        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

