    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        cleanup();
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line");
        cleanup();
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        cleanup();
    }
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line");
        cleanup();
    }

    if (self_test() < 0) {
        error_signal();
        cleanup();
        exit(1);
    }

    while (keep_running) {
        if (gpiod_line_get_value(flame_sensor_line, &flame_detected_count) < 0) {
            log_event("Error reading flame sensor");
            continue;
        }

        if (flame_detected_count == 0 && !flame_detected) {
            flame_detected = 1;
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                log_event("Error setting buzzer value");
            }
            if (gpiod_line_set_value(led_line, 1) < 0) {
                log_event("Error setting LED value");
            }
            log_event("Flame detected");
        } else if (flame_detected_count != 0 && flame_detected) {
            flame_detected = 0;
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                log_event("Error setting buzzer value");
            }
            if (gpiod_line_set_value(led_line, 0) < 0) {
                log_event("Error setting LED value");
            }
            log_event("Flame gone");
        }

        usleep(POLL_INTERVAL * 1000);
    }

