volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void setup_gpio() {
    int fd, value;
    char path[64];

    snprintf(path, sizeof(path), "%s/export", LED_PATH);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open export for writing");
        exit(EXIT_FAILURE);
    }
    if (write(fd, LED_GPIO, strlen(LED_GPIO)) < 0) {
        perror("Failed to export GPIO");
        close(fd);
        exit(EXIT_FAILURE);
    }
    close(fd);

    snprintf(path, sizeof(path), "%s/gpio%s/direction", LED_PATH, LED_GPIO);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open direction for writing");
        exit(EXIT_FAILURE);
    }
    if (write(fd, "out", 3) < 0) {
        perror("Failed to set GPIO direction");
        close(fd);
        exit(EXIT_FAILURE);
    }
    close(fd);
}

void cleanup_gpio() {
    int fd;
    char path[64];

    snprintf(path, sizeof(path), "%s/gpio%s/unexport", LED_PATH, LED_GPIO);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open unexport for writing");
    } else {
        if (write(fd, LED_GPIO, strlen(LED_GPIO)) < 0) {
            perror("Failed to unexport GPIO");
        }
        close(fd);
    }
}

void blink_led(double rate) {
    int fd;
    char path[64];
    double period = 1.0 / rate;
    double half_period = period / 2.0;

    snprintf(path, sizeof(path), "%s/gpio%s/value", LED_PATH, LED_GPIO);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value for writing");
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        if (write(fd, "1", 1) < 0) {
            perror("Failed to set GPIO value to 1");
            break;
        }
        usleep(half_period * 1000000);
        if (write(fd, "0", 1) < 0) {
            perror("Failed to set GPIO value to 0");
            break;
        }
        usleep(half_period * 1000000);
    }

    close(fd);
}

int main() {
    int i2c_fd, ret;
    uint8_t buf[3];
    uint16_t raw_value;
    double lux, rate;
    double buffer[BUFFER_SIZE];
    int buffer_index = 0;
    double sum = 0.0;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error setting signal handler");
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    buf[0] = 0x10; // Continuous high-resolution mode
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    while (keep_running) {
        buf[0] = 0x20; // Read measurement command
        if (write(i2c_fd, buf, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }

        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            perror("Failed to read from I2C device");
            continue;
        }

        raw_value = (buf[0] << 8) | buf[1];
        lux = raw_value / 1.2;

        sum -= buffer[buffer_index];
        buffer[buffer_index] = lux;
        sum += lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        double avg_lux = sum / BUFFER_SIZE;
        rate = 0.5 + (avg_lux / 1000.0) * 4.5;
        if (rate < 0.5) rate = 0.5;
        if (rate > 5.0) rate = 5.0;

        printf("Lux: %.2f, Average Lux: %.2f, Blink Rate: %.2f Hz\n", lux, avg_lux, rate);

        usleep(1000000); // Sleep for 1 second
    }

    close(i2c_fd);
    cleanup_gpio();

    return 0;
}

