#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEGMENT_5 0b0011111 // Binary representation for digit '5'

void shift_out(gpiod_chip *chip, gpiod_line *data, gpiod_line *clock, gpiod_line *latch, uint8_t value) {
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(data, (value >> i) & 0x01);
        gpiod_line_set_value(clock, 1);
        usleep(1); // Small delay to ensure clock edge is registered
        gpiod_line_set_value(clock, 0);
    }
    gpiod_line_set_value(latch, 1);
    usleep(1); // Small delay to ensure latch edge is registered
    gpiod_line_set_value(latch, 0);
}

int main() {
    gpiod_chip *chip;
    gpiod_line *data_line, *clock_line, *latch_line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    if (!data_line) {
        perror("Failed to get data line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(data_line, "data", 0);
    if (ret < 0) {
        perror("Failed to request data line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    if (!clock_line) {
        perror("Failed to get clock line");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(clock_line, "clock", 0);
    if (ret < 0) {
        perror("Failed to request clock line");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!latch_line) {
        perror("Failed to get latch line");
        gpiod_line_release(clock_line);
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(latch_line, "latch", 0);
    if (ret < 0) {
        perror("Failed to request latch line");
        gpiod_line_release(clock_line);
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        shift_out(chip, data_line, clock_line, latch_line, SEGMENT_5);
        usleep(500000); // 500 ms on

        shift_out(chip, data_line, clock_line, latch_line, 0x00);
        usleep(500000); // 500 ms off
    }

    gpiod_line_release(latch_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(data_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

