#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int ret;
    struct gpiod_line_event event;
    struct timespec timeout = {1, 0}; // 1 second timeout

    // Set up signal handling for graceful termination
    signal(SIGINT, handle_signal);

    // Open GPIO chip 0
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request LED line (BCM GPIO17) as output, initially low
    led_line = gpiod_chip_get_line(chip, 17);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request button line (BCM GPIO18) as input with pull-up and event detection
    button_line = gpiod_chip_get_line(chip, 18);
    if (!button_line) {
        perror("Failed to get button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(button_line, "button", GPIOD_LINE_REQ_EV_FALLING | GPIOD_LINE_REQ_PULL_UP);
    if (ret < 0) {
        perror("Failed to request button line as input");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Blink LED with 2-second period (1 second on, 1 second off)
    while (keep_running) {
        // Turn LED on
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("Failed to set LED value to 1");
            break;
        }

        // Wait for button event or timeout
        ret = gpiod_line_event_wait(button_line, &event, &timeout);
        if (ret < 0) {
            if (ret == -ETIMEDOUT) {
                // Timeout occurred, toggle LED state
                ret = gpiod_line_get_value(led_line, NULL);
                if (ret < 0) {
                    perror("Failed to get LED value");
                    break;
                }
                ret = gpiod_line_set_value(led_line, !ret);
                if (ret < 0) {
                    perror("Failed to toggle LED value");
                    break;
                }
            } else {
                perror("Failed to wait for button event");
                break;
            }
        } else if (ret == 0) {
            // Button event detected, stop blinking
            printf("Button pressed, stopping blink.\n");
            break;
        }

        // Turn LED off
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Failed to set LED value to 0");
            break;
        }

        // Wait for button event or timeout
        ret = gpiod_line_event_wait(button_line, &event, &timeout);
        if (ret < 0) {
            if (ret == -ETIMEDOUT) {
                // Timeout occurred, toggle LED state
                ret = gpiod_line_get_value(led_line, NULL);
                if (ret < 0) {
                    perror("Failed to get LED value");
                    break;
                }
                ret = gpiod_line_set_value(led_line, !ret);
                if (ret < 0) {
                    perror("Failed to toggle LED value");
                    break;
                }
            } else {
                perror("Failed to wait for button event");
                break;
            }
        } else if (ret == 0) {
            // Button event detected, stop blinking
            printf("Button pressed, stopping blink.\n");
            break;
        }
    }

    // Clean up
    gpiod_line_release(button_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

