#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define CHIP_NAME "gpiochip0"

static gpiod_chip *chip = NULL;
static gpiod_line *led_line = NULL;
static gpiod_line *button_line = NULL;

void cleanup() {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void handle_signal(int sig) {
    fprintf(stderr, "Received signal %d, cleaning up and exiting...\n", sig);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_line_request req = {
        .consumer = "led_button_control",
        .flags = GPIOD_LINE_REQUEST_DIRECTIONS,
    };

    // Register signal handlers for graceful shutdown
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", CHIP_NAME);
        return EXIT_FAILURE;
    }

    // Get the LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get line for LED pin %d\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    // Get the button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get line for button pin %d\n", BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure LED line as output
    req.line = led_line;
    req.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    req.default_value = 0; // Initially off
    if (gpiod_line_request(req)) {
        fprintf(stderr, "Failed to configure LED line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure button line as input with internal pull-down
    req.line = button_line;
    req.request_type = GPIOD_LINE_REQUEST_INPUT;
    req.flags = GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW | GPIOD_LINE_REQUEST_DIRECTIONS;
    if (gpiod_line_request(req)) {
        fprintf(stderr, "Failed to configure button line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int button_state;
    int led_state = 0;
    int blink_interval = 500000; // 500 ms in microseconds

    while (1) {
        // Read the button state
        button_state = gpiod_line_get_value(button_line);
        if (button_state < 0) {
            fprintf(stderr, "Failed to read button state\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (button_state == 0) { // Button is pressed
            if (!led_state) {
                // Start blinking
                led_state = 1;
                gpiod_line_set_value(led_line, 1);
            } else {
                // Toggle LED state
                led_state = !led_state;
                gpiod_line_set_value(led_line, led_state);
                usleep(blink_interval);
            }
        } else {
            // Button is released, turn off LED
            if (led_state) {
                gpiod_line_set_value(led_line, 0);
                led_state = 0;
            }
        }
    }

    // Cleanup should not be reached, but just in case
    cleanup();
    return EXIT_SUCCESS;
}

