#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_PERIOD_NS 10000000 // 10 ms period for 100 Hz PWM
#define PWM_DUTY_CYCLE_MAX 100
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_UPDATE_INTERVAL_MS 100

static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

void cleanup_and_exit(int signum) {
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    exit(0);
}

int setup_gpio_line(int pin, const char *name) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_number(0, pin);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip for pin %d: %s\n", pin, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Failed to get line for pin %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, name, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %s: %s\n", name, strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle) {
    int period = PWM_PERIOD_NS;
    int on_time = (duty_cycle * period) / PWM_DUTY_CYCLE_MAX;
    int off_time = period - on_time;

    while (1) {
        gpiod_line_set_value(line, 1);
        struct timespec ts = {0, on_time * 1000}; // Convert ns to ps
        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL);

        gpiod_line_set_value(line, 0);
        ts.tv_nsec = off_time * 1000;
        clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &ts, NULL);
    }
}

int main() {
    if (signal(SIGINT, cleanup_and_exit) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    if (setup_gpio_line(RED_PIN, "red") < 0 ||
        setup_gpio_line(GREEN_PIN, "green") < 0 ||
        setup_gpio_line(BLUE_PIN, "blue") < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        int red_duty = rand() % (PWM_DUTY_CYCLE_MAX + 1);
        int green_duty = rand() % (PWM_DUTY_CYCLE_MAX + 1);
        int blue_duty = rand() % (PWM_DUTY_CYCLE_MAX + 1);

        if (fork() == 0) {
            set_pwm_duty_cycle(red_line, red_duty);
        }
        if (fork() == 0) {
            set_pwm_duty_cycle(green_line, green_duty);
        }
        if (fork() == 0) {
            set_pwm_duty_cycle(blue_line, blue_duty);
        }

        usleep(PWM_UPDATE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

