#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define POLL_INTERVAL 100000000 // 10 Hz in nanoseconds
#define PULSE_DURATION 50000000 // 50 ms in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

double calculate_g_force(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 16384.0;
}

void log_impact(FILE *log_file, int16_t x, int16_t y, int16_t z, struct timespec ts) {
    fprintf(log_file, "Impact detected at %ld.%09ld: X=%d, Y=%d, Z=%d\n",
            ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(log_file);
}

int main(int argc, char *argv[]) {
    int g_threshold = DEFAULT_THRESHOLD;
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0 ||
        i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t data[6];
        if (i2cRead(i2c_handle, OUT_X_L_A | 0x80, data, 6) != 6) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double g_force = calculate_g_force(x, y, z);
        if (g_force > g_threshold) {
            gpioWrite(GPIO_PIN, 1);
            usleep(PULSE_DURATION / 1000);
            gpioWrite(GPIO_PIN, 0);

            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            log_impact(log_file, x, y, z, ts);
        }

        nanosleep((const struct timespec[]){{0, POLL_INTERVAL}}, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

