        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t data[6];
        if (i2cRead(i2c_handle, OUT_X_L_A | 0x80, data, 6) != 6) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double g_force = calculate_g_force(x, y, z);
        if (g_force > g_threshold) {
            gpioWrite(GPIO_PIN, 1);
            usleep(PULSE_DURATION / 1000);
            gpioWrite(GPIO_PIN, 0);

            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            log_impact(log_file, x, y, z, ts);
        }

        nanosleep((const struct timespec[]){{0, POLL_INTERVAL}}, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}
