        gpioPWM(LED_GPIO, 1000, pwm_duty);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    gpioPWM(LED_GPIO, 0, 0);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

