#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1F
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0xC7
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define SAMPLE_INTERVAL_MS 50

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_i2c_byte(int handle, uint8_t reg) {
    uint8_t data[1];
    if (i2c_read_byte_data(handle, reg, data) < 0) {
        fprintf(stderr, "I2C read error at register 0x%02X\n", reg);
        return -1;
    }
    return data[0];
}

int write_i2c_byte(int handle, uint8_t reg, uint8_t value) {
    if (i2c_write_byte_data(handle, reg, value) < 0) {
        fprintf(stderr, "I2C write error at register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

void log_impact(double x, double y, double z, double magnitude) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *file = fopen("impact_log.txt", "a");
    if (file) {
        fprintf(file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open impact_log.txt for writing\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (read_i2c_byte(i2c_handle, WHO_AM_I_REG) != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I check failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_i2c_byte(i2c_handle, CTRL_REG1, 0x00) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_i2c_byte(i2c_handle, XYZ_DATA_CFG, 0x00) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (write_i2c_byte(i2c_handle, CTRL_REG1, 0x01) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        uint8_t data[6];
        if (i2cRead(i2c_handle, OUT_X_MSB, data, 6) < 0) {
            fprintf(stderr, "I2C read error from OUT_X_MSB\n");
        } else {
            int16_t x = (data[0] << 8 | data[1]) >> 2;
            int16_t y = (data[2] << 8 | data[3]) >> 2;
            int16_t z = (data[4] << 8 | data[5]) >> 2;

            double x_g = x / 4096.0 * 9.81;
            double y_g = y / 4096.0 * 9.81;
            double z_g = z / 4096.0 * 9.81;

            double magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);

            if (magnitude > 19.62) {
                log_impact(x_g, y_g, z_g, magnitude);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

