#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define GYRO_ADDRESS 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLES 100
#define LOG_INTERVAL 50 // milliseconds
#define DPS_THRESHOLD 50.0
#define SENSITIVITY 0.00875

int i2c_fd;
FILE *log_file;
volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int check_who_am_i(int fd) {
    char buf[1];
    if (ioctl(fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    if (write(fd, &WHO_AM_I_REG, 1) != 1) {
        perror("Failed to write WHO_AM_I register");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        return -1;
    }
    return buf[0] == WHO_AM_I_VALUE;
}

int configure_gyro(int fd) {
    char buf[2];
    buf[0] = CTRL_REG1;
    buf[1] = 0x0F;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write CTRL_REG1");
        return -1;
    }
    buf[0] = CTRL_REG4;
    buf[1] = 0x00;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write CTRL_REG4");
        return -1;
    }
    return 0;
}

int read_gyro_data(int fd, int16_t *data) {
    char buf[6];
    if (ioctl(fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    buf[0] = OUT_X_L | 0x80; // Auto-increment
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write OUT_X_L register");
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        perror("Failed to read gyro data");
        return -1;
    }
    data[0] = (int16_t)(buf[1] | (buf[0] << 8));
    data[1] = (int16_t)(buf[3] | (buf[2] << 8));
    data[2] = (int16_t)(buf[5] | (buf[4] << 8));
    return 0;
}

void calibrate_gyro(int fd, int16_t *offsets) {
    int16_t data[3];
    memset(offsets, 0, sizeof(int16_t) * 3);
    for (int i = 0; i < SAMPLES; i++) {
        if (read_gyro_data(fd, data) < 0) {
            fprintf(stderr, "Calibration error\n");
            exit(EXIT_FAILURE);
        }
        offsets[0] += data[0];
        offsets[1] += data[1];
        offsets[2] += data[2];
        usleep(10000); // 10 ms delay
    }
    offsets[0] /= SAMPLES;
    offsets[1] /= SAMPLES;
    offsets[2] /= SAMPLES;
}

void log_data(int16_t *data, int16_t *offsets) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    double calibrated_data[3];
    calibrated_data[0] = (data[0] - offsets[0]) * SENSITIVITY;
    calibrated_data[1] = (data[1] - offsets[1]) * SENSITIVITY;
    calibrated_data[2] = (data[2] - offsets[2]) * SENSITIVITY;

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, calibrated_data[0], calibrated_data[1], calibrated_data[2]);

    if (fabs(calibrated_data[0]) > DPS_THRESHOLD || fabs(calibrated_data[1]) > DPS_THRESHOLD || fabs(calibrated_data[2]) > DPS_THRESHOLD) {
        fprintf(stderr, "Warning: Axis exceeded threshold\n");
        fprintf(log_file, "%s, ALERT: Axis exceeded threshold\n", timestamp);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (!check_who_am_i(i2c_fd)) {
        fprintf(stderr, "Sensor not found\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (configure_gyro(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int16_t offsets[3];
    calibrate_gyro(i2c_fd, offsets);

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int16_t data[3];
    while (!stop) {
        if (read_gyro_data(i2c_fd, data) < 0) {
            fprintf(stderr, "Read error\n");
            break;
        }
        log_data(data, offsets);
        usleep(LOG_INTERVAL * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

