#include <string.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define DEVID_REG 0x00
#define DEVID_VALUE 0xE5
#define POWER_CTL_REG 0x2D
#define DATA_FORMAT_REG 0x31
#define DATAX0_REG 0x32
#define LED_PIN 17
#define SAMPLE_INTERVAL 100000000 // 100 ms in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    if (gpioI2CSetup(I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

int configure_sensor() {
    if (gpioI2CWriteReg8(I2C_BUS, I2C_ADDR, POWER_CTL_REG, 0x08) < 0) {
        fprintf(stderr, "Failed to wake up ADXL345\n");
        return -1;
    }
    if (gpioI2CWriteReg8(I2C_BUS, I2C_ADDR, DATA_FORMAT_REG, 0x08) < 0) {
        fprintf(stderr, "Failed to set full resolution\n");
        return -1;
    }
    if (gpioI2CWriteReg8(I2C_BUS, I2C_ADDR, POWER_CTL_REG, 0x08) < 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        return -1;
    }
    return 0;
}

int verify_device_id() {
    uint8_t devid;
    if (gpioI2CReadReg8(I2C_BUS, I2C_ADDR, DEVID_REG, &devid) < 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        return -1;
    }
    if (devid != DEVID_VALUE) {
        fprintf(stderr, "Invalid device ID: 0x%02X\n", devid);
        return -1;
    }
    return 0;
}

int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (gpioI2CReadReg8(I2C_BUS, I2C_ADDR, DATAX0_REG, data) < 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }
    *x = (int16_t)(data[1] << 8 | data[0]);
    *y = (int16_t)(data[3] << 8 | data[2]);
    *z = (int16_t)(data[5] << 8 | data[4]);
    return 0;
}

void log_acceleration(FILE *log_file, int64_t timestamp, int16_t x, int16_t y, int16_t z) {
    fprintf(log_file, "%lld,%.3f,%.3f,%.3f\n", timestamp, x / 256.0, y / 256.0, z / 256.0);
    fflush(log_file);
}

void control_led(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > 512 || abs(y) > 512 || abs(z) > 512) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main() {
    if (setup_i2c() < 0) {
        return EXIT_FAILURE;
    }

    if (configure_sensor() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_device_id() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("accel_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int16_t x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            int64_t timestamp = gpioTickCounter();
            log_acceleration(log_file, timestamp, x, y, z);
            control_led(x, y, z);
        }
        nanosleep((const struct timespec[]){{0, SAMPLE_INTERVAL}}, NULL);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

