#include <pigpio.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E
#define CTRL_REG1_A 0x20
#define MR_REG_M 0x02
#define OUT_X_L_A 0x28
#define OUT_X_H_M 0x03

#define SAMPLE_INTERVAL 100 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_data(FILE *file, double heading, double accel_x, double accel_y, double accel_z, double mag_x, double mag_y, double mag_z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
            tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
            heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(file);
}

double calculate_heading(double mag_x, double mag_y) {
    double heading = atan2(mag_y, mag_x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int accel_handle = i2cOpen(I2C_BUS, ACCEL_ADDR);
    if (accel_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle for accelerometer\n");
        gpioTerminate();
        return 1;
    }

    int mag_handle = i2cOpen(I2C_BUS, MAG_ADDR);
    if (mag_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle for magnetometer\n");
        i2cClose(accel_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(accel_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to accelerometer control register\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(mag_handle, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to magnetometer control register\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }

    while (keep_running) {
        char accel_data[6];
        char mag_data[6];

        if (i2cRead(accel_handle, OUT_X_L_A, accel_data, 6) != 6) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }

        if (i2cRead(mag_handle, OUT_X_H_M, mag_data, 6) != 6) {
            fprintf(stderr, "Failed to read magnetometer data\n");
            break;
        }

        int16_t accel_x = (int16_t)(accel_data[1] | (accel_data[0] << 8));
        int16_t accel_y = (int16_t)(accel_data[3] | (accel_data[2] << 8));
        int16_t accel_z = (int16_t)(accel_data[5] | (accel_data[4] << 8));

        int16_t mag_x = (int16_t)(mag_data[1] | (mag_data[0] << 8));
        int16_t mag_y = (int16_t)(mag_data[3] | (mag_data[2] << 8));
        int16_t mag_z = (int16_t)(mag_data[5] | (mag_data[4] << 8));

        double accel_x_g = accel_x / 16384.0;
        double accel_y_g = accel_y / 16384.0;
        double accel_z_g = accel_z / 16384.0;

        double mag_x_gauss = mag_x / 1100.0;
        double mag_y_gauss = mag_y / 1100.0;
        double mag_z_gauss = mag_z / 1100.0;

        double heading = calculate_heading(mag_x_gauss, mag_y_gauss);

        log_data(log_file, heading, accel_x_g, accel_y_g, accel_z_g, mag_x_gauss, mag_y_gauss, mag_z_gauss);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    fclose(log_file);
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    gpioTerminate();

    return 0;
}

