#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REGISTER 0x01
#define CONTROL_REGISTER 0x00
#define CONTROL_ENABLE 0x80
#define SAMPLING_INTERVAL 10000000 // 10 ms in nanoseconds

volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

int setup_sensor(int i2c_bus, int addr) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (i2cOpen(i2c_bus, addr) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d for address 0x%02X\n", i2c_bus, addr);
        gpioTerminate();
        return -1;
    }

    if (i2cWriteReg8(addr, CONTROL_REGISTER, CONTROL_ENABLE) < 0) {
        fprintf(stderr, "Failed to enable sensor at address 0x%02X\n", addr);
        i2cClose(addr);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int read_sensor(int addr, int16_t *data) {
    uint8_t buffer[2];
    if (i2cReadReg16BE(addr, DATA_REGISTER, buffer) < 0) {
        fprintf(stderr, "Failed to read data from sensor at address 0x%02X\n", addr);
        return -1;
    }
    *data = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    FILE *log_file = fopen("audio_log.dat", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    if (setup_sensor(I2C_BUS, SENSOR1_ADDR) < 0 || setup_sensor(I2C_BUS, SENSOR2_ADDR) < 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    struct timespec ts;
    int16_t sensor1_data, sensor2_data;
    int16_t tdoa;

    while (keep_running) {
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "Failed to get time\n");
            break;
        }

        if (read_sensor(SENSOR1_ADDR, &sensor1_data) < 0 || read_sensor(SENSOR2_ADDR, &sensor2_data) < 0) {
            usleep(SAMPLING_INTERVAL / 1000); // Retry after a short delay
            continue;
        }

        tdoa = sensor1_data - sensor2_data;

        fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa);

        usleep(SAMPLING_INTERVAL / 1000);
    }

    fclose(log_file);

    i2cClose(SENSOR1_ADDR);
    i2cClose(SENSOR2_ADDR);
    gpioTerminate();

    return EXIT_SUCCESS;
}

