#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0b11000000000
#define SPI_MODE 3
#define SPI_WORD_SIZE 16
#define DUMMY_READ_DELAY_US 40
#define SAMPLE_INTERVAL_MS 100

#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025

static int spi_handle;
static FILE *csv_file;
static volatile sig_atomic_t running = 1;

void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    gpioTerminate();
}

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_FLAGS, SPI_WORD_SIZE);
    if (spi_handle < 0) {
        log_error("Failed to open SPI channel");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    csv_file = fopen("imu_data.csv", "w");
    if (!csv_file) {
        log_error("Failed to open CSV file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    while (running) {
        struct timespec start_time, current_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        int16_t gyro_x, gyro_y, gyro_z;
        int16_t accel_x, accel_y, accel_z;

        uint16_t request, response;

        // Read Gyroscope X
        request = (X_GYRO << 1) & 0x7FFF;
        if (spiXfer(spi_handle, &request, &response, 1) < 0) {
            log_error("Failed to read Gyroscope X");
        } else {
            gyro_x = response;
        }

        // Read Gyroscope Y
        request = (Y_GYRO << 1) & 0x7FFF;
        if (spiXfer(spi_handle, &request, &response, 1) < 0) {
            log_error("Failed to read Gyroscope Y");
        } else {
            gyro_y = response;
        }

        // Read Gyroscope Z
        request = (Z_GYRO << 1) & 0x7FFF;
        if (spiXfer(spi_handle, &request, &response, 1) < 0) {
            log_error("Failed to read Gyroscope Z");
        } else {
            gyro_z = response;
        }

        // Read Accelerometer X
        request = (X_ACCEL << 1) & 0x7FFF;
        if (spiXfer(spi_handle, &request, &response, 1) < 0) {
            log_error("Failed to read Accelerometer X");
        } else {
            accel_x = response;
        }

        // Read Accelerometer Y
        request = (Y_ACCEL << 1) & 0x7FFF;
        if (spiXfer(spi_handle, &request, &response, 1) < 0) {
            log_error("Failed to read Accelerometer Y");
        } else {
            accel_y = response;
        }

        // Read Accelerometer Z
        request = (Z_ACCEL << 1) & 0x7FFF;
        if (spiXfer(spi_handle, &request, &response, 1) < 0) {
            log_error("Failed to read Accelerometer Z");
        } else {
            accel_z = response;
        }

        // Log data
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long timestamp = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;
        fprintf(csv_file, "%ld,%f,%f,%f,%f,%f,%f\n",
                timestamp,
                gyro_x * GYRO_SENSITIVITY,
                gyro_y * GYRO_SENSITIVITY,
                gyro_z * GYRO_SENSITIVITY,
                accel_x * ACCEL_SENSITIVITY,
                accel_y * ACCEL_SENSITIVITY,
                accel_z * ACCEL_SENSITIVITY);

        fflush(csv_file);

        // Non-blocking delay
        while (running) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;
            if (elapsed_ms >= SAMPLE_INTERVAL_MS) {
                break;
            }
            usleep(1000); // Check every 1 ms
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

