#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CE_PIN 8

#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int spi_read_16(int handle, uint16_t reg) {
    uint16_t tx[2] = {reg | 0x8000, 0x0000};
    uint16_t rx[2] = {0, 0};

    if (gpioSPIRead(handle, tx, rx, 2) < 0) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    usleep(40); // Stall time

    return rx[1];
}

void read_and_print_imu_data(int spi_handle) {
    int16_t gyro_x, gyro_y, gyro_z;
    int16_t accel_x, accel_y, accel_z;

    gyro_x = spi_read_16(spi_handle, X_GYRO_OUT);
    gyro_y = spi_read_16(spi_handle, Y_GYRO_OUT);
    gyro_z = spi_read_16(spi_handle, Z_GYRO_OUT);

    accel_x = spi_read_16(spi_handle, X_ACCL_OUT);
    accel_y = spi_read_16(spi_handle, Y_ACCL_OUT);
    accel_z = spi_read_16(spi_handle, Z_ACCL_OUT);

    if (gyro_x < 0 || gyro_y < 0 || gyro_z < 0 || accel_x < 0 || accel_y < 0 || accel_z < 0) {
        fprintf(stderr, "Failed to read IMU data\n");
        return;
    }

    printf("Gyro X: %.2f deg/sec, Gyro Y: %.2f deg/sec, Gyro Z: %.2f deg/sec\n",
           gyro_x * GYRO_SCALE, gyro_y * GYRO_SCALE, gyro_z * GYRO_SCALE);
    printf("Accel X: %.4f g, Accel Y: %.4f g, Accel Z: %.4f g\n",
           accel_x * ACCEL_SCALE, accel_y * ACCEL_SCALE, accel_z * ACCEL_SCALE);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    int spi_handle = gpioSPISetup(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        read_and_print_imu_data(spi_handle);
        usleep(100000); // 100 ms
    }

    gpioSPIClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

