#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6886_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define ACCEL_XOUT_H_REG 0x3B
#define GYRO_XOUT_H_REG 0x43

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t length) {
    uint8_t buffer[length + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, length);

    if (write(fd, buffer, length + 1) != length + 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int verify_sensor(int fd) {
    uint8_t who_am_i;
    if (i2c_read(fd, WHO_AM_I_REG, &who_am_i, 1) != 0) {
        return -1;
    }
    return (who_am_i == 0x86);
}

int initialize_sensor(int fd) {
    uint8_t data = 0x00;
    if (i2c_write(fd, PWR_MGMT_1_REG, &data, 1) != 0) {
        return -1;
    }
    if (i2c_write(fd, ACCEL_CONFIG_REG, &data, 1) != 0) {
        return -1;
    }
    if (i2c_write(fd, GYRO_CONFIG_REG, &data, 1) != 0) {
        return -1;
    }
    return 0;
}

int read_sensor_data(int fd, int16_t *accel_data, int16_t *gyro_data) {
    uint8_t buffer[14];
    int retries = 3;
    while (retries--) {
        if (i2c_read(fd, ACCEL_XOUT_H_REG, buffer, 14) == 0) {
            accel_data[0] = (int16_t)(buffer[0] << 8 | buffer[1]);
            accel_data[1] = (int16_t)(buffer[2] << 8 | buffer[3]);
            accel_data[2] = (int16_t)(buffer[4] << 8 | buffer[5]);
            gyro_data[0] = (int16_t)(buffer[8] << 8 | buffer[9]);
            gyro_data[1] = (int16_t)(buffer[10] << 8 | buffer[11]);
            gyro_data[2] = (int16_t)(buffer[12] << 8 | buffer[13]);
            return 0;
        }
        usleep(1000); // Retry after 1 ms
    }
    return -1;
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    if (!verify_sensor(fd)) {
        fprintf(stderr, "Sensor not detected\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (initialize_sensor(fd) != 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(fd);
        return EXIT_FAILURE;
    }

    int16_t accel_data[3], gyro_data[3];
    while (!stop) {
        if (read_sensor_data(fd, accel_data, gyro_data) == 0) {
            printf("Accel: X=%d Y=%d Z=%d\n", accel_data[0], accel_data[1], accel_data[2]);
            printf("Gyro: X=%d Y=%d Z=%d\n", gyro_data[0], gyro_data[1], gyro_data[2]);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        usleep(50000); // 50 ms
    }

    close(fd);
    return EXIT_SUCCESS;
}

