        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    if (!verify_sensor(fd)) {
        fprintf(stderr, "Sensor not detected\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (initialize_sensor(fd) != 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(fd);
        return EXIT_FAILURE;
    }

    int16_t accel_data[3], gyro_data[3];
    while (!stop) {
        if (read_sensor_data(fd, accel_data, gyro_data) == 0) {
            printf("Accel: X=%d Y=%d Z=%d\n", accel_data[0], accel_data[1], accel_data[2]);
            printf("Gyro: X=%d Y=%d Z=%d\n", gyro_data[0], gyro_data[1], gyro_data[2]);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        usleep(50000); // 50 ms
    }

    close(fd);
    return EXIT_SUCCESS;
}
