        int16_t x, y, z;
        if (gpioI2CReadReg16(I2C_BUS, I2C_ADDR, X_AXIS_DATA_REG, &x) < 0 ||
            gpioI2CReadReg16(I2C_BUS, I2C_ADDR, Y_AXIS_DATA_REG, &y) < 0 ||
            gpioI2CReadReg16(I2C_BUS, I2C_ADDR, Z_AXIS_DATA_REG, &z) < 0) {
