        if (magnitude > IMPACT_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_DURATION_MS);
            gpioWrite(LED_PIN, 0);
            log_impact(magnitude, x, y, z);
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

