#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define WHO_AM_I_VALUE 0x12

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up device\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer configuration\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope configuration\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I, &who_am_i) < 0 || who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Failed to verify sensor presence\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("imu_log.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(file, "timestamp,acc_x,acc_y,acc_z,gyro_x,gyro_y,gyro_z\n");

    while (keep_running) {
        uint8_t accel_data[6];
        uint8_t gyro_data[6];

        if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, 6, accel_data) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, 6, gyro_data) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        int16_t acc_x = (accel_data[0] << 8) | accel_data[1];
        int16_t acc_y = (accel_data[2] << 8) | accel_data[3];
        int16_t acc_z = (accel_data[4] << 8) | accel_data[5];
        int16_t gyro_x = (gyro_data[0] << 8) | gyro_data[1];
        int16_t gyro_y = (gyro_data[2] << 8) | gyro_data[3];
        int16_t gyro_z = (gyro_data[4] << 8) | gyro_data[5];

        fprintf(file, "%ld,%d,%d,%d,%d,%d,%d\n", time(NULL), acc_x, acc_y, acc_z, gyro_x, gyro_y, gyro_z);

        fflush(file);
        usleep(100000); // 100 ms
    }

    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

