#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MMA8451Q_ADDRESS 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x1A
#define OUT_X_MSB_REG 0x01
#define OUT_Y_MSB_REG 0x03
#define OUT_Z_MSB_REG 0x05
#define LED_GPIO 17
#define THRESHOLD 2048 // 2.0g in counts
#define POLL_INTERVAL 100 // ms
#define LED_ON_DURATION 500 // ms

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write_byte_data(uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(uint8_t reg, uint8_t *buffer, size_t length) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(i2c_fd, buffer, length) != length) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int verify_sensor_identity() {
    uint8_t who_am_i;
    if (i2c_read_bytes(WHO_AM_I_REG, &who_am_i, 1) != 0) {
        return -1;
    }
    return (who_am_i == WHO_AM_I_VALUE);
}

int initialize_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int initialize_led() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(led_line, "accel_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    return 0;
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void log_impact() {
    FILE *log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: Impact detected\n", timestamp);
    fclose(log_file);
}

void check_acceleration() {
    uint8_t buffer[6];
    if (i2c_read_bytes(OUT_X_MSB_REG, buffer, 6) != 0) {
        return;
    }

    int16_t x = (buffer[0] << 8) | buffer[1];
    int16_t y = (buffer[2] << 8) | buffer[3];
    int16_t z = (buffer[4] << 8) | buffer[5];

    if (abs(x) > THRESHOLD || abs(y) > THRESHOLD || abs(z) > THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
        usleep(LED_ON_DURATION * 1000);
        gpiod_line_set_value(led_line, 0);
        log_impact();
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (initialize_i2c() != 0 || initialize_led() != 0 || verify_sensor_identity() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (!stop) {
        check_acceleration();
        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

