    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int initialize_led() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(led_line, "accel_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    return 0;
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

void log_impact() {
    FILE *log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "%s: Impact detected\n", timestamp);
    fclose(log_file);
}

void check_acceleration() {
    uint8_t buffer[6];
    if (i2c_read_bytes(OUT_X_MSB_REG, buffer, 6) != 0) {
        return;
    }

    int16_t x = (buffer[0] << 8) | buffer[1];
    int16_t y = (buffer[2] << 8) | buffer[3];
    int16_t z = (buffer[4] << 8) | buffer[5];

    if (abs(x) > THRESHOLD || abs(y) > THRESHOLD || abs(z) > THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
        usleep(LED_ON_DURATION * 1000);
        gpiod_line_set_value(led_line, 0);
        log_impact();
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (initialize_i2c() != 0 || initialize_led() != 0 || verify_sensor_identity() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (!stop) {
        check_acceleration();
        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}
