    int i2c_file;
    FILE *log_file;
    uint8_t buffer[BUFFER_SIZE];
    struct timespec ts;
    char timestamp[20];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_file = open_i2c_device(I2C_DEVICE, I2C_ADDRESS);
    if (i2c_file < 0) {
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen("magnetic_field_log.csv", "a+")) == NULL) {
        perror("Failed to open log file");
        close(i2c_file);
        exit(EXIT_FAILURE);
    }

    // Write CSV header if file is empty
    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    while (keep_running) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

