            int16_t x = (buffer[1] << 8) | buffer[0];
            if (read_i2c_register(i2c_file, REG_Y, buffer, 2) == 0) {
                int16_t y = (buffer[1] << 8) | buffer[0];
                if (read_i2c_register(i2c_file, REG_Z, buffer, 2) == 0) {
                    int16_t z = (buffer[1] << 8) | buffer[0];
                    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
