#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_DEVICE_ID 0xE5
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_BW_RATE 0x2C
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_THRESH_FF 0x0A
#define ADXL345_TIME_FF 0x20
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_DATAX0 0x32

#define GPIO_PIN 17
#define LOG_FILE "freefall_log.csv"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_freefall_event(int fd, int16_t x, int16_t y, int16_t z) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    if (fseek(log, 0, SEEK_SET) == 0) {
        if (ftell(log) == 0) {
            fprintf(log, "Timestamp,X,Y,Z\n");
        }
        fseek(log, 0, SEEK_END);
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm_info = localtime(&tv.tv_sec);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log, "%s.%03ld,%d,%d,%d\n", timestamp, (long)tv.tv_usec / 1000, x, y, z);
    fflush(log);
    fclose(log);
}

int read_i2c_block_data(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int write_i2c_byte_data(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    uint8_t device_id;
    if (read_i2c_block_data(i2c_fd, 0x00, &device_id, 1) < 0 || device_id != ADXL345_DEVICE_ID) {
        fprintf(stderr, "ADXL345 not found or device ID mismatch\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte_data(i2c_fd, ADXL345_POWER_CTL, 0x00) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte_data(i2c_fd, ADXL345_DATA_FORMAT, 0x08) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte_data(i2c_fd, ADXL345_BW_RATE, 0x0A) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte_data(i2c_fd, ADXL345_THRESH_FF, 0x1E) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte_data(i2c_fd, ADXL345_TIME_FF, 0x64) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte_data(i2c_fd, ADXL345_INT_ENABLE, 0x04) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte_data(i2c_fd, ADXL345_INT_MAP, 0x00) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write_i2c_byte_data(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, "ADXL345_INT1") < 0) {
        perror("Failed to request falling edge events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int event_fd = gpiod_line_event_get_fd(line);
    if (event_fd < 0) {
        perror("Failed to get event file descriptor");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t buf[6];
    while (keep_running) {
        int ret = read(event_fd, &ret, sizeof(ret));
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("Failed to read event");
            break;
        }

        uint8_t int_source;
        if (read_i2c_block_data(i2c_fd, ADXL345_INT_SOURCE, &int_source, 1) < 0) {
            break;
        }

        if (int_source & 0x04) {
            if (read_i2c_block_data(i2c_fd, ADXL345_DATAX0, buf, 6) < 0) {
                break;
            }

            int16_t x = (buf[1] << 8) | buf[0];
            int16_t y = (buf[3] << 8) | buf[2];
            int16_t z = (buf[5] << 8) | buf[4];

            log_freefall_event(i2c_fd, x, y, z);
        }
    }

    if (write_i2c_byte_data(i2c_fd, ADXL345_INT_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Failed to disable interrupts\n");
    }

    close(event_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

