#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define LSM6DSR_ADDRESS 0x6A
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0x69
#define CTRL1_XL_REG 0x10
#define CTRL2_G_REG 0x11
#define OUTX_L_G_REG 0x22
#define OUTX_L_XL_REG 0x28
#define OUTSCALE_G 0.061
#define OUTSCALE_XL 0.061
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define ODR 104
#define FALL_DETECTION_WINDOW 1.0

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_motion_data(FILE *file, double timestamp, double ax, double ay, double az, double gx, double gy, double gz) {
    fprintf(file, "%f,%f,%f,%f,%f,%f,%f\n", timestamp, ax, ay, az, gx, gy, gz);
    fflush(file);
}

void configure_sensor() {
    if (gpioWriteReg(LSM6DSR_ADDRESS, CTRL1_XL_REG, 0x60) != 0) {
        fprintf(stderr, "Failed to write CTRL1_XL register\n");
        exit(EXIT_FAILURE);
    }
    if (gpioWriteReg(LSM6DSR_ADDRESS, CTRL2_G_REG, 0x60) != 0) {
        fprintf(stderr, "Failed to write CTRL2_G register\n");
        exit(EXIT_FAILURE);
    }
}

int check_sensor_presence() {
    uint8_t who_am_i;
    if (gpioReadReg(LSM6DSR_ADDRESS, WHO_AM_I_REG, &who_am_i, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    return who_am_i == WHO_AM_I_VALUE;
}

void read_sensor_data(double *ax, double *ay, double *az, double *gx, double *gy, double *gz) {
    uint8_t data[12];
    if (gpioReadReg(LSM6DSR_ADDRESS, OUTX_L_G_REG, data, 12) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        exit(EXIT_FAILURE);
    }

    *gx = (int16_t)(data[1] | (data[0] << 8)) * OUTSCALE_G;
    *gy = (int16_t)(data[3] | (data[2] << 8)) * OUTSCALE_G;
    *gz = (int16_t)(data[5] | (data[4] << 8)) * OUTSCALE_G;
    *ax = (int16_t)(data[7] | (data[6] << 8)) * OUTSCALE_XL;
    *ay = (int16_t)(data[9] | (data[8] << 8)) * OUTSCALE_XL;
    *az = (int16_t)(data[11] | (data[10] << 8)) * OUTSCALE_XL;
}

double calculate_acceleration_magnitude(double ax, double ay, double az) {
    return sqrt(ax * ax + ay * ay + az * az);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (!check_sensor_presence()) {
        fprintf(stderr, "Sensor not present\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    configure_sensor();

    FILE *file = fopen("motion_log.txt", "w");
    if (!file) {
        fprintf(stderr, "Failed to open motion_log.txt\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double last_freefall_time = 0;
    enum { IDLE, FREEFALL, IMPACT } state = IDLE;

    while (keep_running) {
        double ax, ay, az, gx, gy, gz;
        read_sensor_data(&ax, &ay, &az, &gx, &gy, &gz);

        double timestamp = (double)clock() / CLOCKS_PER_SEC;
        log_motion_data(file, timestamp, ax, ay, az, gx, gy, gz);

        double accel_magnitude = calculate_acceleration_magnitude(ax, ay, az);

        switch (state) {
            case IDLE:
                if (accel_magnitude < FREEFALL_THRESHOLD) {
                    state = FREEFALL;
                    last_freefall_time = timestamp;
                }
                break;
            case FREEFALL:
                if (timestamp - last_freefall_time > FALL_DETECTION_WINDOW) {
                    state = IDLE;
                } else if (accel_magnitude > IMPACT_THRESHOLD) {
                    state = IMPACT;
                }
                break;
            case IMPACT:
                state = IDLE;
                break;
        }
    }

    fclose(file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

