#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define REG_X_GYRO_OUT 0x14
#define REG_WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0x3F5A
#define SCALE_FACTOR 0.0305

static int spi_handle;
static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int spi_transfer_16(int handle, unsigned char *tx, unsigned char *rx) {
    int result = pigpio_spi_writeread(handle, tx, 2, rx, 2);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error_string(result));
        return -1;
    }
    return 0;
}

int read_register(int handle, unsigned char reg) {
    unsigned char tx[2] = {reg | 0x80, 0x00};
    unsigned char rx[2] = {0, 0};
    if (spi_transfer_16(handle, tx, rx) < 0) {
        return -1;
    }
    return (rx[0] << 8) | rx[1];
}

int verify_device(int handle) {
    int who_am_i = read_register(handle, REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Unexpected WHO_AM_I value: 0x%04X (expected 0x%04X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    spi_handle = pigpio_open(0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle: %s\n", pigpio_error_string(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pigpio_spi_set_mode(spi_handle, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", pigpio_error_string(pigpio_spi_set_mode(spi_handle, SPI_MODE)));
        pigpio_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pigpio_spi_set_speed_hz(spi_handle, SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", pigpio_error_string(pigpio_spi_set_speed_hz(spi_handle, SPI_SPEED_HZ)));
        pigpio_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (verify_device(spi_handle) < 0) {
        pigpio_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_close(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp, X_GYRO_OUT (deg/sec)\n");

    while (keep_running) {
        int x_gyro_out = read_register(spi_handle, REG_X_GYRO_OUT);
        if (x_gyro_out < 0) {
            fprintf(stderr, "Failed to read X_GYRO_OUT register\n");
            break;
        }

        double x_gyro_deg_sec = x_gyro_out * SCALE_FACTOR;

        fprintf(log_file, "%ld, %.6f\n", (long)time(NULL), x_gyro_deg_sec);
        fflush(log_file);

        usleep(10000); // Sleep for 10 ms
    }

    if (log_file) {
        fclose(log_file);
    }

    if (spi_handle >= 0) {
        pigpio_close(spi_handle);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

