#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define GYRO_ADDRESS 0x69
#define WHO_AM_I 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLE_INTERVAL_MS 10
#define MAX_RETRIES 3
#define SENSITIVITY 8.75
#define SCALE_FACTOR (1.0 / 114.285)

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int i2c_write_with_retries(int pi, int bus, int address, const unsigned char *data, int length) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_i2c_block_data(pi, bus, address, data, length) >= 0) {
            return 0;
        }
        retries++;
        usleep(1000); // Wait 1 ms before retrying
    }
    return -1;
}

int initialize_gyro(int pi, int bus) {
    unsigned char data[1];

    // Check WHO_AM_I register
    if (i2c_read_i2c_block_data(pi, bus, GYRO_ADDRESS, data, 1) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (data[0] != WHO_AM_I_VALUE) {
        fprintf(stderr, "Gyroscope not detected (WHO_AM_I = 0x%02X)\n", data[0]);
        return -1;
    }

    // Configure CTRL_REG1
    data[0] = 0x0F; // Normal mode, all axes enabled
    if (i2c_write_with_retries(pi, bus, GYRO_ADDRESS, data, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4
    data[0] = 0x00; // +-250 dps full-scale range
    if (i2c_write_with_retries(pi, bus, GYRO_ADDRESS, data, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

int main() {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return EXIT_FAILURE;
    }

    int bus = 1;
    if (initialize_gyro(pi, bus) < 0) {
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    FILE *file = fopen("gyro_log.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,X,Y,Z\n");

    struct timespec ts;
    unsigned char data[6];

    signal(SIGINT, handle_signal);

    while (keep_running) {
        if (i2c_read_i2c_block_data(pi, bus, GYRO_ADDRESS, data, 6) < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        int16_t x = (data[0] | (data[1] << 8));
        int16_t y = (data[2] | (data[3] << 8));
        int16_t z = (data[4] | (data[5] << 8));

        double x_dps = x * SENSITIVITY * SCALE_FACTOR;
        double y_dps = y * SENSITIVITY * SCALE_FACTOR;
        double z_dps = z * SENSITIVITY * SCALE_FACTOR;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, x_dps, y_dps, z_dps);

        fflush(file);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(file);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
}

