        int16_t x = (data[0] | (data[1] << 8));
        int16_t y = (data[2] | (data[3] << 8));
        int16_t z = (data[4] | (data[5] << 8));

        double x_dps = x * SENSITIVITY * SCALE_FACTOR;
        double y_dps = y * SENSITIVITY * SCALE_FACTOR;
        double z_dps = z * SENSITIVITY * SCALE_FACTOR;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, x_dps, y_dps, z_dps);

        fflush(file);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(file);
    pigpio_stop(pi);
    return EXIT_SUCCESS;
}
