#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x53
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D
#define SAMPLE_INTERVAL 100 // milliseconds

int i2c_fd = -1;
FILE *log_file = NULL;

void handle_sigint(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int open_i2c_device() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int read_i2c_register(uint8_t reg, uint8_t *data, size_t length) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(i2c_fd, data, length) != length) {
        perror("Failed to read data from I2C device");
        return -1;
    }
    return 0;
}

int16_t combine_bytes(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

void log_acceleration(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (open_i2c_device() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    while (1) {
        uint8_t data[2];
        int16_t x, y, z;

        if (read_i2c_register(REG_X_LSB, data, 2) != 0) {
            fprintf(stderr, "Error reading X-axis data\n");
            continue;
        }
        x = combine_bytes(data[1], data[0]);

        if (read_i2c_register(REG_Y_LSB, data, 2) != 0) {
            fprintf(stderr, "Error reading Y-axis data\n");
            continue;
        }
        y = combine_bytes(data[1], data[0]);

        if (read_i2c_register(REG_Z_LSB, data, 2) != 0) {
            fprintf(stderr, "Error reading Z-axis data\n");
            continue;
        }
        z = combine_bytes(data[1], data[0]);

        log_acceleration(x, y, z);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

