#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define LOG_INTERVAL_MS 50

static volatile sig_atomic_t keep_running = 1;
static gpiod_chip *chip = NULL;
static gpiod_line *line17 = NULL;
static gpiod_line *line27 = NULL;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_error_and_exit(const char *message) {
    perror(message);
    cleanup();
    exit(EXIT_FAILURE);
}

void cleanup() {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct timespec ts;
    struct sigaction sa;

    // Setup signal handling
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error_and_exit("Failed to setup signal handling");
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error_and_exit("Failed to open GPIO chip");
    }

    // Request GPIO17 line
    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        cleanup();
        log_error_and_exit("Failed to get GPIO17 line");
    }
    if (gpiod_line_request_input(line17, "conveyor_sensor_17", GPIOD_LINE_REQ_FLAG_BIAS_PULL_UP) < 0) {
        gpiod_line_release(line17);
        cleanup();
        log_error_and_exit("Failed to request GPIO17 as input");
    }

    // Request GPIO27 line
    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line27) {
        cleanup();
        log_error_and_exit("Failed to get GPIO27 line");
    }
    if (gpiod_line_request_input(line27, "conveyor_sensor_27", GPIOD_LINE_REQ_FLAG_BIAS_PULL_UP) < 0) {
        gpiod_line_release(line27);
        gpiod_line_release(line17);
        cleanup();
        log_error_and_exit("Failed to request GPIO27 as input");
    }

    // Open log file
    log_file = fopen("conveyor_log.txt", "w");
    if (!log_file) {
        cleanup();
        log_error_and_exit("Failed to open log file");
    }

    // Main loop
    while (keep_running) {
        if (gpiod_line_get_value(line17) < 0 || gpiod_line_get_value(line27) < 0) {
            cleanup();
            log_error_and_exit("Failed to read sensor values");
        }

        int sensor17 = gpiod_line_get_value(line17);
        int sensor27 = gpiod_line_get_value(line27);

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            cleanup();
            log_error_and_exit("Failed to get current time");
        }

        // Log timestamp and sensor states
        fprintf(log_file, "%ld.%03ld: Sensor17=%d, Sensor27=%d\n",
                ts.tv_sec, ts.tv_nsec / 1000000, sensor17, sensor27);
        fflush(log_file);

        // Check if both sensors are triggered
        if (sensor17 == 1 && sensor27 == 1) {
            printf("Conveyor halted due to both sensors being triggered.\n");
        }

        // Sleep for the interval
        struct timespec sleep_interval = {0, LOG_INTERVAL_MS * 1000000L};
        nanosleep(&sleep_interval, NULL);
    }

    // Cleanup on exit
    cleanup();
    return 0;
}

