#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0x2A
#define CTRL_REG1 0x2A
#define DATA_REG_START 0x01
#define DATA_REG_COUNT 6

int i2c_fd;
FILE *log_file;

void handle_signal(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_block_data(int fd, uint8_t reg, uint8_t *buffer, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, buffer, length) != length) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    setup_signal_handler();

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t who_am_i;
    if (i2c_read_block_data(i2c_fd, WHO_AM_I_REG, &who_am_i, 1) < 0 || who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Failed to verify sensor identity\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t ctrl_reg1;
    if (i2c_read_block_data(i2c_fd, CTRL_REG1, &ctrl_reg1, 1) < 0) {
        perror("Failed to read CTRL_REG1");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ctrl_reg1 &= ~0x01; // Set to standby mode
    ctrl_reg1 &= ~(0x07 << 3); // Clear data rate bits
    ctrl_reg1 |= (0x02 << 3); // Set data rate to 100 Hz
    if (i2c_write_byte_data(i2c_fd, CTRL_REG1, ctrl_reg1) < 0) {
        perror("Failed to write CTRL_REG1");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ctrl_reg1 |= 0x01; // Set to active mode
    if (i2c_write_byte_data(i2c_fd, CTRL_REG1, ctrl_reg1) < 0) {
        perror("Failed to write CTRL_REG1");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("fall_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
