#define CALIBRATION_OFFSET_X 0
#define CALIBRATION_OFFSET_Y 0
#define CALIBRATION_OFFSET_Z 0
#define CALIBRATION_SCALE_X 1.0
#define CALIBRATION_SCALE_Y 1.0
#define CALIBRATION_SCALE_Z 1.0
#define SENSITIVITY 0.146 // mG/LSB for +-4 gauss
#define MAG_THRESHOLD 800.0 // mG

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t length) {
    uint8_t buffer[length + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, length);
    if (write(fd, buffer, length + 1) != length + 1) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, data, length) != length) {
        perror("I2C read");
        return -1;
    }
    return 0;
}

int initialize_sensor(int fd) {
    uint8_t who_am_i;
    for (int attempt = 0; attempt < 3; ++attempt) {
        if (i2c_read(fd, WHO_AM_I, &who_am_i, 1) == 0 && who_am_i == WHO_AM_I_VALUE) {
            uint8_t ctrl_reg1 = 0x70; // Continuous-conversion mode, 80 Hz ODR, high-performance mode
            uint8_t ctrl_reg4 = 0x0C; // High-performance mode on all axes
            uint8_t ctrl_reg3 = 0x00; // Normal mode
            if (i2c_write(fd, CTRL_REG1, &ctrl_reg1, 1) == 0 &&
                i2c_write(fd, CTRL_REG4, &ctrl_reg4, 1) == 0 &&
                i2c_write(fd, CTRL_REG3, &ctrl_reg3, 1) == 0) {
                return 0;
            }
        }
        usleep(100000); // Wait 100 ms before retrying
    }
    return -1;
}

double calculate_magnitude(double x, double y, double z) {
    return sqrt(x * x + y * y + z * z);
}

int main() {
    int i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("magnetic_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint8_t data[6];
    double x, y, z;
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds

    while (keep_running) {
        if (i2c_read(i2c_fd, OUT_X_L, data, 6) == 0) {
            int16_t raw_x = (int16_t)(data[1] | (data[0] << 8));
            int16_t raw_y = (int16_t)(data[3] | (data[2] << 8));
            int16_t raw_z = (int16_t)(data[5] | (data[4] << 8));

            x = (raw_x + CALIBRATION_OFFSET_X) * CALIBRATION_SCALE_X * SENSITIVITY;
            y = (raw_y + CALIBRATION_OFFSET_Y) * CALIBRATION_SCALE_Y * SENSITIVITY;
            z = (raw_z + CALIBRATION_OFFSET_Z) * CALIBRATION_SCALE_Z * SENSITIVITY;

            fprintf(log_file, "%f,%f,%f\n", x, y, z);
            fflush(log_file);

            double magnitude = calculate_magnitude(x, y, z);
            if (magnitude > MAG_THRESHOLD) {
                fprintf(stderr, "Metal detected: %f mG\n", magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

