#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define RESET_REGISTER 0x1F
#define POWER_CTL_REGISTER 0x2D
#define STATUS_REGISTER 0x04
#define PARTID_REGISTER 0x01
#define XDATA_REGISTER 0x08
#define YDATA_REGISTER 0x0B
#define ZDATA_REGISTER 0x0E
#define PARTID_VALUE 0x1D
#define SENSITIVITY 0.0000039
#define LOG_INTERVAL 100000000 // 100 ms in nanoseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int spi_read(int pi, uint8_t reg, uint8_t *data, int length) {
    uint8_t tx[2] = { (reg | 0x80) & 0xFF, 0x00 };
    int retries = 5;
    while (retries--) {
        if (gpioSPIRead(pi, SPI_CHANNEL, SPI_SPEED, SPI_MODE, 2, tx, data, length) == 0) {
            return 0;
        }
        usleep(1000); // Retry after 1 ms
    }
    return -1;
}

int reset_device(int pi) {
    uint8_t reset_cmd = 0x52;
    if (gpioSPIDataRW(pi, SPI_CHANNEL, &reset_cmd, 1) != 0) {
        return -1;
    }
    usleep(1000); // Wait 1 ms
    return 0;
}

int set_measurement_mode(int pi) {
    uint8_t power_ctl;
    if (spi_read(pi, POWER_CTL_REGISTER, &power_ctl, 1) != 0) {
        return -1;
    }
    power_ctl &= ~0x02; // Clear RUN bit
    if (gpioSPIDataRW(pi, SPI_CHANNEL, &power_ctl, 1) != 0) {
        return -1;
    }

    uint8_t status;
    do {
        if (spi_read(pi, STATUS_REGISTER, &status, 1) != 0) {
            return -1;
        }
    } while (!(status & 0x01)); // Wait for STABLE bit

    power_ctl |= 0x02; // Set RUN bit
    if (gpioSPIDataRW(pi, SPI_CHANNEL, &power_ctl, 1) != 0) {
        return -1;
    }
    return 0;
}

int check_sensor_presence(int pi) {
    uint8_t partid;
    if (spi_read(pi, PARTID_REGISTER, &partid, 1) != 0) {
        return -1;
    }
    return partid == PARTID_VALUE;
}

int read_acceleration(int pi, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (spi_read(pi, XDATA_REGISTER, data, 3) != 0 ||
        spi_read(pi, YDATA_REGISTER, data + 3, 3) != 0 ||
        spi_read(pi, ZDATA_REGISTER, data + 6, 3) != 0) {
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[4] << 8) | data[3]);
    *z = (int16_t)((data[6] << 8) | data[5]);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int pi = 0;
    if (reset_device(pi) != 0) {
        fprintf(stderr, "Failed to reset device\n");
        gpioTerminate();
        return 1;
    }

    if (set_measurement_mode(pi) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        gpioTerminate();
        return 1;
    }

    if (check_sensor_presence(pi) != 0) {
        fprintf(stderr, "Sensor not present\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("vibration_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;
    struct timespec ts;
    while (keep_running) {
        if (read_acceleration(pi, &x, &y, &z) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: X=%d, Y=%d, Z=%d\n",
                    ts.tv_sec, ts.tv_nsec, x, y, z);
        }
        nanosleep((const struct timespec[]){{0, LOG_INTERVAL}}, NULL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

