    FILE *log_file = fopen("vibration_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;
    struct timespec ts;
    while (keep_running) {
        if (read_acceleration(pi, &x, &y, &z) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: X=%d, Y=%d, Z=%d\n",
                    ts.tv_sec, ts.tv_nsec, x, y, z);
        }
        nanosleep((const struct timespec[]){{0, LOG_INTERVAL}}, NULL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}
