#include <time.h>

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_with_timestamp(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_line_open(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to open line 17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "IR_obstacle_sensor") < 0) {
        fprintf(stderr, "Failed to request line 17 as input\n");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_with_timestamp("Sensor monitoring started");

    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read line value\n");
            break;
        }

        if (value == 0) {
            log_with_timestamp("Obstacle detected");
            log_with_timestamp("Self-parking sequence started");
            sleep(2); // Simulate self-parking duration
            log_with_timestamp("Self-parking sequence completed");
        }

        sleep(1);
    }

    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    log_with_timestamp("Sensor monitoring stopped");
    return EXIT_SUCCESS;
}

