This program uses the `libgpiod` library to interact with the GPIO pins on a Raspberry Pi 5. It sets up a signal handler to catch `SIGINT` (Ctrl+C) for a graceful shutdown, opens the GPIO chip and line, requests the line as an input, and polls the sensor every second. If an obstacle is detected, it logs a simulated self-parking sequence. The program ensures all resources are released properly on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO17 17
#define GPIO27 27
#define POLL_INTERVAL_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[2];
    struct gpiod_line_request req[2];
    struct timespec ts;
    int ret;

    // Set up signal handler for clean exit
    signal(SIGINT, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    lines[0] = gpiod_chip_get_line(chip, GPIO17);
    lines[1] = gpiod_chip_get_line(chip, GPIO27);
    if (!lines[0] || !lines[1]) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    req[0].line = lines[0];
    req[0].flags = GPIOD_LINE_REQUEST_INPUT;
    req[1].line = lines[1];
    req[1].flags = GPIOD_LINE_REQUEST_INPUT;

    ret = gpiod_line_request_bulk(req, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        ret = gpiod_line_request_get_values_bulk(req, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO lines: %s\n", strerror(-ret));
            break;
        }

        // Log the status with a timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld - GPIO17: %s, GPIO27: %s\n",
               ts.tv_sec, ts.tv_nsec,
               req[0].values[0] ? "Clear" : "Obstacle",
               req[1].values[0] ? "Clear" : "Obstacle");

        // Poll every 100 ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Release resources
    gpiod_line_release_bulk(req, 2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

