#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define MSC_CTRL 0x24
#define X_RATE 0x04
#define Y_RATE 0x06
#define Z_RATE 0x08
#define SCALE_FACTOR 0.02
#define READ_INTERVAL 100000 // 100 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        return -1;
    }

    uint8_t speed = SPI_SPEED;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(*fd);
        return -1;
    }

    return 0;
}

int cs_init(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!*chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, CS_PIN);
    if (!*line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "spi_cs", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

void cs_activate(struct gpiod_line *line) {
    gpiod_line_set_value(line, 0);
}

void cs_deactivate(struct gpiod_line *line) {
    gpiod_line_set_value(line, 1);
}

int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return 0;
}

int read_register(int fd, struct gpiod_line *line, uint8_t reg) {
    uint8_t tx[3] = {reg | 0x80, 0x00, 0x00};
    uint8_t rx[2] = {0, 0};

    cs_activate(line);
    if (spi_transfer(fd, tx, rx, 3) < 0 || spi_transfer(fd, NULL, rx, 2) < 0) {
        cs_deactivate(line);
        return -1;
    }
    cs_deactivate(line);

    return (int16_t)((rx[0] << 8) | rx[1]);
}

void enable_data_ready_mode(int fd, struct gpiod_line *line) {
    uint8_t tx[3] = {MSC_CTRL, 0x01, 0x00};
    cs_activate(line);
    if (spi_transfer(fd, tx, NULL, 3) < 0) {
        cs_deactivate(line);
        fprintf(stderr, "Failed to enable data ready mode\n");
    }
    cs_deactivate(line);
}

int main() {
    int spi_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler\n");
        return EXIT_FAILURE;
    }

    if (spi_init(&spi_fd) < 0 || cs_init(&chip, &line) < 0) {
        return EXIT_FAILURE;
    }

    enable_data_ready_mode(spi_fd, line);

    while (keep_running) {
        int16_t x_rate = read_register(spi_fd, line, X_RATE);
        int16_t y_rate = read_register(spi_fd, line, Y_RATE);
        int16_t z_rate = read_register(spi_fd, line, Z_RATE);

        if (x_rate < 0 || y_rate < 0 || z_rate < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            break;
        }

        printf("X: %.2f deg/sec, Y: %.2f deg/sec, Z: %.2f deg/sec\n",
               x_rate * SCALE_FACTOR, y_rate * SCALE_FACTOR, z_rate * SCALE_FACTOR);

        usleep(READ_INTERVAL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

