        int16_t gyro_x = (data[1] << 8) | data[0];
        int16_t gyro_y = (data[3] << 8) | data[2];
        int16_t gyro_z = (data[5] << 8) | data[4];
        int16_t accel_x = (data[7] << 8) | data[6];
        int16_t accel_y = (data[9] << 8) | data[8];
        int16_t accel_z = (data[11] << 8) | data[10];

