        double gyro_y_dps = gyro_y * 0.00875;
        double gyro_z_dps = gyro_z * 0.00875;
        double accel_x_g = accel_x * 0.000061;
        double accel_y_g = accel_y * 0.000061;
        double accel_z_g = accel_z * 0.000061;

        printf("Gyro: X=%.3f Y=%.3f Z=%.3f\n", gyro_x_dps, gyro_y_dps, gyro_z_dps);
        printf("Accel: X=%.3f Y=%.3f Z=%.3f\n", accel_x_g, accel_y_g, accel_z_g);

        if (gpioDelay(READ_INTERVAL_MS) < 0) {
            fprintf(stderr, "Failed to delay\n");
            break;
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

