#define FXOS8700_I2C_ADDR 0x1D
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3

#define WHO_AM_I_VALUE 0xC7

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int check_sensor_presence(int pi, int addr) {
    unsigned char who_am_i;
    if (i2c_read_byte_data(pi, addr, FXOS8700_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Sensor not found or incorrect address\n");
        return -1;
    }
    return 0;
}

int configure_sensor(int pi, int addr) {
    unsigned char data;

    // Configure accelerometer
    data = 0x0F; // 12-bit resolution, active mode
    if (i2c_write_byte_data(pi, addr, FXOS8700_CTRL_REG1, data) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }

    data = 0x00; // Normal mode
    if (i2c_write_byte_data(pi, addr, FXOS8700_CTRL_REG2, data) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG2\n");
        return -1;
    }

    // Configure magnetometer
    data = 0x1F; // 16-bit resolution, active mode
    if (i2c_write_byte_data(pi, addr, FXOS8700_M_CTRL_REG1, data) < 0) {
        fprintf(stderr, "Failed to write M_CTRL_REG1\n");
        return -1;
    }

    data = 0x00; // Normal mode
    if (i2c_write_byte_data(pi, addr, FXOS8700_M_CTRL_REG2, data) < 0) {
        fprintf(stderr, "Failed to write M_CTRL_REG2\n");
        return -1;
    }

    return 0;
}

int read_sensor_data(int pi, int addr, unsigned char *data) {
    int retries = 5;
    while (retries--) {
        if (i2c_read_i2c_block_data(pi, addr, FXOS8700_OUT_X_MSB, 12, data) == 12) {
            return 0;
        }
        fprintf(stderr, "I2C read failed, retrying...\n");
        usleep(100000); // 100 ms
    }
    fprintf(stderr, "Failed to read sensor data after retries\n");
    return -1;
}

void log_sensor_data(unsigned char *data) {
    int16_t accel_x = (data[0] << 6) | (data[1] >> 2);
    int16_t accel_y = ((data[1] & 0x03) << 8) | data[2];
    int16_t accel_z = (data[3] << 6) | (data[4] >> 2);

    int16_t mag_x = (data[5] << 8) | data[6];
    int16_t mag_y = (data[7] << 8) | data[8];
    int16_t mag_z = (data[9] << 8) | data[10];

    printf("Accelerometer: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
    printf("Magnetometer: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int pi = 0;
    int i2c_handle = i2cOpen(pi, I2C_BUS, 100000);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (check_sensor_presence(pi, FXOS8700_I2C_ADDR) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(pi, FXOS8700_I2C_ADDR) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    unsigned char data[12];
    while (keep_running) {
        if (read_sensor_data(pi, FXOS8700_I2C_ADDR, data) == 0) {
            log_sensor_data(data);
        }
        usleep(100000); // 100 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

