#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAZ0 0x36
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int open_i2c_device(const char *device, int address) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return file;
}

int read_acceleration(int file, int *data) {
    char buffer[6];
    if (read(file, buffer, 6) != 6) {
        perror("Failed to read from the i2c bus");
        return -1;
    }
    data[0] = (buffer[1] << 8) | buffer[0];
    data[1] = (buffer[3] << 8) | buffer[2];
    data[2] = (buffer[5] << 8) | buffer[4];
    return 0;
}

double calculate_tilt_angle(int x, int y, int z) {
    double x_g = x * 0.0039; // Convert to g
    double y_g = y * 0.0039;
    double z_g = z * 0.0039;
    double tilt_x = atan2(y_g, z_g) * 180.0 / M_PI;
    double tilt_y = atan2(x_g, z_g) * 180.0 / M_PI;
    return fmax(fabs(tilt_x), fabs(tilt_y));
}

void log_tilt_event(double tilt_angle) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    fprintf(log_file, "[%s] Tilt angle: %.2f degrees\n", timestamp, tilt_angle);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);

    int i2c_file = open_i2c_device(I2C_DEVICE, ADXL345_ADDRESS);
    if (i2c_file < 0) {
        return EXIT_FAILURE;
    }

    int data[3];
    while (!stop) {
        if (read_acceleration(i2c_file, data) < 0) {
            fprintf(stderr, "I2C read error, retrying...\n");
            continue;
        }

        double tilt_angle = calculate_tilt_angle(data[0], data[1], data[2]);
        if (tilt_angle > TILT_THRESHOLD) {
            log_tilt_event(tilt_angle);
        }

        usleep(100000); // Sleep for 100 ms
    }

    close(i2c_file);
    return EXIT_SUCCESS;
}

