#include <pigpio.h>

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int validate_threshold(const char *arg) {
    char *endptr;
    long threshold = strtol(arg, &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Invalid threshold: %s\n", arg);
        return -1;
    }
    return (int)threshold;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int threshold = validate_threshold(argv[1]);
    if (threshold == -1) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int high_count = 0;
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        for (int i = 0; i < 5000; i++) {
            if (!keep_running) break;

            if (gpioRead(17) == 1) {
                high_count++;
            }
            usleep(1000); // Sleep for 1 ms
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;

        if (elapsed < 5.0) {
            fprintf(stderr, "Warning: Monitoring window was shorter than expected\n");
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (high_count > threshold) {
            printf("[%s] ALERT: High readings = %d\n", timestamp, high_count);
        } else {
            printf("[%s] Status: High readings = %d\n", timestamp, high_count);
        }

        if (keep_running) {
            sleep(1);
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

