#include <errno.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define LOCK_TIME 5

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line17, *line27;
    struct timespec ts;
    FILE *log_file;
    char buffer[100];
    int ret;
    unsigned int code, input_code;
    time_t now;
    struct tm *tm_info;

    // Initialize random number generator
    srand(time(NULL));

    // Generate a random 6-digit code
    code = (rand() % 900000) + 100000;
    printf("Generated code: %06u\n", code);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get lines for GPIO17 and GPIO27
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line17 || !line27) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines as output, default to LOW
    ret = gpiod_line_request_output(line17, "door_a", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO17: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line27, "door_b", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO27: %s\n", strerror(-ret));
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("access_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!exit_flag) {
        printf("Enter code: ");
        if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
            fprintf(stderr, "Error reading input: %s\n", strerror(errno));
            continue;
        }

        // Remove newline character
        buffer[strcspn(buffer, "\n")] = '\0';

        // Validate input
        if (strlen(buffer) != 6 || sscanf(buffer, "%u", &input_code) != 1) {
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            continue;
        }

        if (input_code == code) {
            // Unlock Door A
            gpiod_line_set_value(line17, 1);
            nanosleep(&ts, NULL);

            // Log access
            now = time(NULL);
            tm_info = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%06u\n",
                    tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday,
                    tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, code);

            // Re-lock Door A after 5 seconds
            gpiod_line_set_value(line17, 0);
            nanosleep(&ts, NULL);

            // Generate new code
            code = (rand() % 900000) + 100000;
            printf("Generated new code: %06u\n", code);
        } else {
            printf("Access denied\n");
        }
    }

    // Clean up
    gpiod_line_set_value(line17, 0);
    gpiod_line_set_value(line27, 0);
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

