#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define ONE_TIME_HIGH_RES_MODE_2 0x21
#define MAX_CONVERSION_TIME_MS 180
#define LOG_FILE "light_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int *fd) {
    *fd = open(device, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    return 0;
}

int set_i2c_address(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }
    return 0;
}

int write_i2c_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }
    return 0;
}

int read_i2c_bytes(int fd, uint8_t *buf, int length) {
    if (read(fd, buf, length) != length) {
        perror("Failed to read from the i2c bus");
        return -1;
    }
    return 0;
}

int calculate_lux(uint16_t raw_value) {
    return (raw_value * 5) / 6;
}

void log_illuminance(int lux) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "Timestamp: %s, Lux: %d\n", timestamp, lux);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    if (open_i2c_device(I2C_DEVICE, &i2c_fd) != 0) {
        return EXIT_FAILURE;
    }

    if (set_i2c_address(i2c_fd, BH1750_ADDR) != 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    while (keep_running) {
        if (write_i2c_byte(i2c_fd, ONE_TIME_HIGH_RES_MODE_2) != 0) {
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        usleep(MAX_CONVERSION_TIME_MS * 1000);

        uint8_t data[2];
        if (read_i2c_bytes(i2c_fd, data, 2) != 0) {
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        uint16_t raw_value = (data[0] << 8) | data[1];
        int lux = calculate_lux(raw_value);
        log_illuminance(lux);

        sleep(5);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

