#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define PWM_PIN 18
#define PORT 12345
#define SECRET "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define PLAY_DURATION 5 // seconds
#define SAMPLE_INTERVAL 20 // ms

static int i2c_handle;
static int pwm_handle;
static int server_socket;
static int client_socket;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void log_frequency(double frequency) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%f\n", frequency);
        fclose(log);
    }
}

double map_to_frequency(int touch_value, int min_value, int max_value) {
    double ratio = (double)(touch_value - min_value) / (max_value - min_value);
    double log_min = log(220);
    double log_max = log(880);
    double log_freq = log_min + ratio * (log_max - log_min);
    return exp(log_freq);
}

void setup_mpr121() {
    // Soft reset
    if (i2c_write_byte_data(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Failed to soft reset MPR121\n");
        exit(EXIT_FAILURE);
    }
    usleep(10000); // Wait for reset

    // Configure electrodes
    if (i2c_write_byte_data(i2c_handle, 0x5E, 0x00) < 0 ||
        i2c_write_byte_data(i2c_handle, 0x5F, 0x00) < 0 ||
        i2c_write_byte_data(i2c_handle, 0x6C, 0x00) < 0 ||
        i2c_write_byte_data(i2c_handle, 0x6D, 0x00) < 0) {
        fprintf(stderr, "Failed to configure electrodes\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    setup_mpr121();

    pwm_handle = pigpioServoHz(PWM_PIN, 440); // Start with a default frequency
    if (pwm_handle < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        fprintf(stderr, "Failed to create socket\n");
