#include <gpiod.h>
#include <math.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LSM303DLHC_ADDRESS 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define PWM_CHIP "pwmchip0"
#define PWM_LINE 0
#define GPIO_LED 17

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    perror(message);
}

int init_i2c(int *fd) {
    *fd = open(I2C_DEVICE, O_RDWR);
    if (*fd < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }

    if (ioctl(*fd, I2C_SLAVE, LSM303DLHC_ADDRESS) < 0) {
        log_error("Failed to set I2C address");
        close(*fd);
        return -1;
    }

    return 0;
}

int init_magnetometer(int fd) {
    uint8_t data = 0x18; // 10 Hz continuous conversion
    if (write(fd, &data, 1) != 1) {
        log_error("Failed to write to CTRL_REG1_M");
        return -1;
    }
    return 0;
}

int read_magnetometer(int fd, int16_t *data) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        log_error("Failed to read magnetometer data");
        return -1;
    }

    data[0] = (int16_t)(buffer[1] << 8 | buffer[0]);
    data[1] = (int16_t)(buffer[3] << 8 | buffer[2]);
    data[2] = (int16_t)(buffer[5] << 8 | buffer[4]);

    return 0;
}

int init_pwm(gpiod_line_handle_t *line) {
    struct gpiod_line_spec spec = {
        .consumer = "led_control",
        .name = "LED PWM",
        .offset = GPIO_LED,
        .flags = GPIOD_LINE_REQUEST_OUTPUT,
    };

    *line = gpiod_line_request_by_spec(PWM_CHIP, &spec);
    if (*line == NULL) {
        log_error("Failed to request PWM line");
        return -1;
    }

    if (gpiod_line_set_active_low(*line)) {
        log_error("Failed to set active low");
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

void set_pwm_duty_cycle(gpiod_line_handle_t line, int duty_cycle) {
    gpiod_line_set_value_with_delay_ns(line, duty_cycle, 1000000);
}

void cleanup(int *fd, gpiod_line_handle_t line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (*fd >= 0) {
        close(*fd);
    }
}

int main() {
    int i2c_fd;
    gpiod_line_handle_t pwm_line;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c(&i2c_fd) < 0 || init_magnetometer(i2c_fd) < 0 || init_pwm(&pwm_line) < 0) {
        cleanup(&i2c_fd, pwm_line);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int16_t mag_data[3];
        if (read_magnetometer(i2c_fd, mag_data) == 0) {
            double z_magnitude = fabs(mag_data[2]);
            int duty_cycle = (int)(z_magnitude / 1000.0 * 100); // Scale to 0-100%
            set_pwm_duty_cycle(pwm_line, duty_cycle);
        }
        usleep(100000); // 100 ms
    }

    cleanup(&i2c_fd, pwm_line);
    return EXIT_SUCCESS;
}

