#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_A 0x70
#define CONFIG_B 0x20
#define MODE_CONTINUOUS 0x00

#define SAMPLE_WINDOW 100
#define READ_INTERVAL 500 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void write_register(int pi, uint8_t reg, uint8_t value) {
    if (i2c_write_byte_data(pi, I2C_ADDR, reg, value) < 0) {
        fprintf(stderr, "I2C write error\n");
        exit(EXIT_FAILURE);
    }
}

void read_registers(int pi, uint8_t reg, uint8_t *buf, int length) {
    if (i2c_read_i2c_block_data(pi, I2C_ADDR, reg, buf, length) < 0) {
        fprintf(stderr, "I2C read error\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pi = I2C_BUS;
    if (gpioI2CSetup(pi, I2C_ADDR) < 0) {
        fprintf(stderr, "I2C setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Configure the HMC5883L
    write_register(pi, 0x00, CONFIG_A);
    write_register(pi, 0x01, CONFIG_B);
    write_register(pi, 0x02, MODE_CONTINUOUS);

    int16_t x_offset = 0, y_offset = 0, z_offset = 0;
    int sample_count = 0;

    while (keep_running) {
        uint8_t buf[6];
        read_registers(pi, 0x03, buf, 6);

        int16_t x_raw = (buf[0] << 8) | buf[1];
        int16_t y_raw = (buf[2] << 8) | buf[3];
        int16_t z_raw = (buf[4] << 8) | buf[5];

        // Update running average for hard-iron offsets
        x_offset = (x_offset * sample_count + x_raw) / (sample_count + 1);
        y_offset = (y_offset * sample_count + y_raw) / (sample_count + 1);
        z_offset = (z_offset * sample_count + z_raw) / (sample_count + 1);

        sample_count = (sample_count + 1) % SAMPLE_WINDOW;

        if (sample_count == 0) {
            // Apply offsets to the latest raw reading
            int16_t x_corrected = x_raw - x_offset;
            int16_t y_corrected = y_raw - y_offset;
            int16_t z_corrected = z_raw - z_offset;

            printf("X: %d, Y: %d, Z: %d\n", x_corrected, y_corrected, z_corrected);
        }

        usleep(READ_INTERVAL * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

