#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define DELAY_NS (500 * 1000 * 1000) // 500 ms in nanoseconds

static struct gpiod_chip *chip;
static struct gpiod_line *line1, *line2;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_gpio() {
    int ret;

    // Request the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    // Request line 1 (GPIO17)
    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        fprintf(stderr, "Failed to get line for GPIO17\n");
        gpiod_chip_close(chip);
        return -1;
    }
    ret = gpiod_line_request_output(line1, "solenoid1", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line for GPIO17: %s\n", gpiod_strerror(ret));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request line 2 (GPIO27)
    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (!line2) {
        fprintf(stderr, "Failed to get line for GPIO27\n");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return -1;
    }
    ret = gpiod_line_request_output(line2, "solenoid2", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line for GPIO27: %s\n", gpiod_strerror(ret));
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set both lines LOW at startup
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);

    return 0;
}

void cleanup_gpio() {
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct sigaction sa;
    struct timespec ts;

    // Setup signal handler for clean exit
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler\n");
        return EXIT_FAILURE;
    }

    // Setup GPIO
    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        // Energize solenoid 1
        gpiod_line_set_value(line1, 1);
        ts.tv_sec = 0;
        ts.tv_nsec = DELAY_NS;
        nanosleep(&ts, NULL);

        // De-energize solenoid 1 and energize solenoid 2
        gpiod_line_set_value(line1, 0);
        gpiod_line_set_value(line2, 1);
        nanosleep(&ts, NULL);

        // De-energize solenoid 2
        gpiod_line_set_value(line2, 0);
    }

    // Cleanup GPIO
    cleanup_gpio();

    return EXIT_SUCCESS;
}

