#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define UART0 "/dev/serial0"
#define UART1 "/dev/serial1"
#define BAUD_RATE B9600
#define TIMEOUT 5000 // 5 seconds
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int setup_serial(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios options;
    if (tcgetattr(fd, &options) != 0) {
        fprintf(stderr, "Error getting termios for %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    if (tcsetattr(fd, TCSANOW, &options) != 0) {
        fprintf(stderr, "Error setting termios for %s: %s\n", device, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_serial(int fd, char *buffer, size_t length) {
    fd_set read_fds;
    struct timeval timeout;
    int bytes_read = 0;

    FD_ZERO(&read_fds);
    FD_SET(fd, &read_fds);

    timeout.tv_sec = TIMEOUT / 1000;
    timeout.tv_usec = (TIMEOUT % 1000) * 1000;

    int ret = select(fd + 1, &read_fds, NULL, NULL, &timeout);
    if (ret < 0) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout reading from serial port\n");
        return -1;
    }

    if (FD_ISSET(fd, &read_fds)) {
        bytes_read = read(fd, buffer, length);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            return -1;
        }
    }

    return bytes_read;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_GPIO_1, PI_OUTPUT) < 0 || gpioSetMode(LOCK_GPIO_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(LOCK_GPIO_1, PI_LOW);
    gpioWrite(LOCK_GPIO_2, PI_LOW);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int uart0_fd = setup_serial(UART0);
    int uart1_fd = setup_serial(UART1);
    if (uart0_fd < 0 || uart1_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char code0[CODE_LENGTH + 1] = {0};
    char code1[CODE_LENGTH + 1] = {0};
    int code0_index = 0;
    int code1_index = 0;

    while (keep_running) {
        char buffer[1];
        int read0 = read_serial(uart0_fd, buffer, 1);
        int read1 = read_serial(uart1_fd, buffer, 1);

        if (read0 > 0 && isdigit(buffer[0])) {
            code0[code0_index++] = buffer[0];
            if (code0_index == CODE_LENGTH) {
                code0[code0_index] = '\0';
                code0_index = 0;
            }
        } else {
            code0_index = 0;
        }

        if (read1 > 0 && isdigit(buffer[0])) {
            code1[code1_index++] = buffer[0];
            if (code1_index == CODE_LENGTH) {
                code1[code1_index] = '\0';
                code1_index = 0;
            }
        } else {
            code1_index = 0;
        }

        if (strlen(code0) == CODE_LENGTH && strlen(code1) == CODE_LENGTH) {
            if (strncmp(code0, EXPECTED_CODE, CODE_LENGTH) == 0 &&
                strncmp(code1, EXPECTED_CODE, CODE_LENGTH) == 0) {
                if (gpioWrite(LOCK_GPIO_1, PI_HIGH) < 0 || gpioWrite(LOCK_GPIO_2, PI_HIGH) < 0) {
                    fprintf(stderr, "Failed to unlock doors\n");
                } else {
                    sleep(2);
                    if (gpioWrite(LOCK_GPIO_1, PI_LOW) < 0 || gpioWrite(LOCK_GPIO_2, PI_LOW) < 0) {
                        fprintf(stderr, "Failed to lock doors\n");
                    }
                }
                code0[0] = '\0';
                code1[0] = '\0';
            }
        }
    }

    gpioWrite(LOCK_GPIO_1, PI_LOW);
    gpioWrite(LOCK_GPIO_2, PI_LOW);

    close(uart0_fd);
    close(uart1_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

