#include <gpiod.h>
#include <syslog.h>
#include <time.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define PIR_CHIP "gpiochip0"
#define RELAY_CHIP "gpiochip0"
#define PIR_LINE_NAME "pir"
#define RELAY_LINE_NAME "relay"
#define POLL_INTERVAL 50 // milliseconds
#define STRIKE_DURATION 1000 // milliseconds
#define FAILSAFE_DURATION 10000 // milliseconds

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_and_exit(const char *message, int status) {
    syslog(LOG_INFO, "%s", message);
    if (pir_line) gpiod_line_release(pir_line);
    if (relay_line) gpiod_line_release(relay_line);
    if (chip) gpiod_chip_close(chip);
    closelog();
    exit(status);
}

int main() {
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting door strike program");

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        log_and_exit("Failed to set signal handlers", EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        log_and_exit("Failed to open PIR chip", EXIT_FAILURE);
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_and_exit("Failed to get PIR line", EXIT_FAILURE);
    }

    if (gpiod_line_request_input(pir_line, PIR_LINE_NAME, 0) < 0) {
        log_and_exit("Failed to request PIR line as input", EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_name(RELAY_CHIP);
    if (!chip) {
        log_and_exit("Failed to open RELAY chip", EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_and_exit("Failed to get RELAY line", EXIT_FAILURE);
    }

    if (gpiod_line_request_output(relay_line, RELAY_LINE_NAME, 0) < 0) {
        log_and_exit("Failed to request RELAY line as output", EXIT_FAILURE);
    }

    gpiod_line_set_value(relay_line, 0); // Ensure relay is off initially

    time_t last_motion_time = 0;
    time_t motion_start_time = 0;

    while (keep_running) {
        int value = gpiod_line_get_value(pir_line);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor value");
            continue;
        }

        if (value) {
            if (motion_start_time == 0) {
                motion_start_time = time(NULL);
                syslog(LOG_INFO, "Motion detected");
            }

            if (difftime(time(NULL), motion_start_time) > FAILSAFE_DURATION) {
                gpiod_line_set_value(relay_line, 0);
                syslog(LOG_WARNING, "PIR sensor stuck HIGH, potential malfunction");
                motion_start_time = 0;
            } else {
                gpiod_line_set_value(relay_line, 1);
                syslog(LOG_INFO, "Relay energized");
                sleep(1);
                gpiod_line_set_value(relay_line, 0);
                syslog(LOG_INFO, "Relay de-energized");
            }
        } else {
            motion_start_time = 0;
        }

        last_motion_time = time(NULL);
        usleep(POLL_INTERVAL * 1000);
    }

    gpiod_line_set_value(relay_line, 0); // Ensure relay is off on shutdown
    syslog(LOG_INFO, "Shutting down");

    if (pir_line) gpiod_line_release(pir_line);
    if (relay_line) gpiod_line_release(relay_line);
    if (chip) gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

