#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22

#define RELAY_ON 1
#define RELAY_OFF 0

#define RELAY_ON_TIME 300000000 // 300 seconds in nanoseconds
#define PAUSE_TIME 60000000    // 60 seconds in nanoseconds

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

void log_syslog(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void activate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, RELAY_ON) != 0) {
        log_syslog("Failed to activate relay");
        exit(EXIT_FAILURE);
    }
    char log_message[100];
    snprintf(log_message, sizeof(log_message), "Relay %d activated", relay_pin);
    log_syslog(log_message);
}

void deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, RELAY_OFF) != 0) {
        log_syslog("Failed to deactivate relay");
        exit(EXIT_FAILURE);
    }
    char log_message[100];
    snprintf(log_message, sizeof(log_message), "Relay %d deactivated", relay_pin);
    log_syslog(log_message);
}

void timer_callback(int timer, unsigned int unused) {
    static int current_relay = 0;
    static int state = 0; // 0: activate, 1: wait, 2: deactivate

    switch (state) {
        case 0: // Activate relay
            deactivate_relay(current_relay);
            activate_relay(current_relay);
            gpioSetTimerFuncEx(timer, RELAY_ON_TIME, timer_callback, 0);
            state = 1;
            break;
        case 1: // Wait
            gpioSetTimerFuncEx(timer, PAUSE_TIME, timer_callback, 0);
            state = 2;
            break;
        case 2: // Deactivate relay
            deactivate_relay(current_relay);
            current_relay = (current_relay + 1) % 4;
            state = 0;
            break;
    }
}

int main() {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_syslog("Failed to initialize GPIO");
        closelog();
        exit(EXIT_FAILURE);
    }

    int relays[] = {RELAY1, RELAY2, RELAY3, RELAY4};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(relays[i], PI_OUTPUT) != 0) {
            log_syslog("Failed to set GPIO mode");
            gpioTerminate();
            closelog();
            exit(EXIT_FAILURE);
        }
        deactivate_relay(relays[i]);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetTimerFuncEx(0, 0, timer_callback, 0);

    while (!stop_flag) {
        sleep(1);
    }

    for (int i = 0; i < 4; i++) {
        deactivate_relay(relays[i]);
    }

    gpioTerminate();
    closelog();

    return 0;
}

