#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <errno.h>
#include <stdint.h>
#include <sys/timerfd.h>
#include <sys/epoll.h>
#include <linux/limits.h>

#define MPU6050_I2C_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define ACCEL_SCALE 16384.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 100

static int i2c_fd = -1;
static int timer_fd = -1;
static int epoll_fd = -1;
static int sysfs_fd = -1;
static volatile sig_atomic_t stop = 0;
static float accel_buffer[BUFFER_SIZE][3];
static int buffer_index = 0;

void handle_signal(int sig) {
    stop = 1;
}

void write_sysfs(const char *path, const char *data) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open sysfs file");
        return;
    }
    if (write(fd, data, strlen(data)) < 0) {
        perror("Failed to write to sysfs file");
    }
    close(fd);
}

void read_acceleration(float *x, float *y, float *z) {
    uint8_t buffer[6];
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Failed to read from MPU6050");
        exit(EXIT_FAILURE);
    }
    *x = ((int16_t)(buffer[0] << 8 | buffer[1])) / ACCEL_SCALE;
    *y = ((int16_t)(buffer[2] << 8 | buffer[3])) / ACCEL_SCALE;
    *z = ((int16_t)(buffer[4] << 8 | buffer[5])) / ACCEL_SCALE;
}

void init_mpu6050() {
    uint8_t data = 0x00;
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to MPU6050");
        exit(EXIT_FAILURE);
    }
    data = 0x00;
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to MPU6050");
        exit(EXIT_FAILURE);
    }
    data = 0x00;
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write to MPU6050");
        exit(EXIT_FAILURE);
    }
}

void init_timer() {
    struct itimerspec its;
    timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (timer_fd < 0) {
        perror("Failed to create timer");
        exit(EXIT_FAILURE);
    }
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10ms
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10ms
    if (timerfd_settime(timer_fd, 0, &its, NULL) < 0) {
        perror("Failed to set timer");
        exit(EXIT_FAILURE);
    }
}

void init_sysfs() {
    char path[PATH_MAX];
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
    sysfs_fd = open(path, O_WRONLY | O_CREAT, 0666);
    if (sysfs_fd < 0) {
        perror("Failed to create sysfs file");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (timer_fd >= 0) {
        close(timer_fd);
    }
    if (sysfs_fd >= 0) {
        close(sysfs_fd);
    }
    if (epoll_fd >= 0) {
        close(epoll_fd);
    }
}

void log_acceleration(float x, float y, float z) {
    accel_buffer[buffer_index][0] = x;
    accel_buffer[buffer_index][1] = y;
    accel_buffer[buffer_index][2] = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%f %f %f\n", x, y, z);
    write_sysfs("/sys/kernel/mpu6050_accel/latest", buffer);
}

void timer_callback(int signum) {
    (void)signum;
    float x, y, z;
    read_acceleration(&x, &y, &z);
    log_acceleration(x, y, z);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    init_mpu6050();
    init_timer();
    init_sysfs();

    struct epoll_event ev, events[1];
    epoll_fd = epoll_create1(0);
    if (epoll_fd < 0) {
        perror("Failed to create epoll");
        cleanup();
        exit(EXIT_FAILURE);
    }

    ev.events = EPOLLIN;
    ev.data.fd = timer_fd;
    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, timer_fd, &ev) < 0) {
        perror("Failed to add timer to epoll");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (!stop) {
        int nfds = epoll_wait(epoll_fd, events, 1, -1);
        if (nfds < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("epoll_wait");
            break;
        }
        if (events[0].data.fd == timer_fd) {
            uint64_t expirations;
