#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>
#include <unistd.h>
#include <stdbool.h>

#define NUM_RELAYS 4
#define GPIO_PINS {18, 23, 24, 25}
#define PRIME_INTERVALS {2, 3, 5, 7}

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];
static bool running = true;

void handle_signal(int sig) {
    running = false;
}

void cleanup() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PINS[i]);
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_output(lines[i], "relay", 0) < 0) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", GPIO_PINS[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct timespec last_time;
    clock_gettime(CLOCK_MONOTONIC, &last_time);

    while (running) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        for (int i = 0; i < NUM_RELAYS; i++) {
            if (current_time.tv_sec - last_time.tv_sec >= PRIME_INTERVALS[i]) {
                int value = gpiod_line_get_value(lines[i]) == 0 ? 1 : 0;
                if (gpiod_line_set_value(lines[i], value) < 0) {
                    fprintf(stderr, "Failed to set value for GPIO %d\n", GPIO_PINS[i]);
                }
                last_time.tv_sec = current_time.tv_sec;
            }
        }

        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    // Ensure all relays are turned off on exit
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to turn off GPIO %d\n", GPIO_PINS[i]);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

