#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define POLL_INTERVAL 100 // milliseconds
#define RELAY_ON_TIME 3000 // milliseconds
#define DEBOUNCE_TIME 5000 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_timestamp(const char *filename) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = '\0'; // Remove newline

    fprintf(file, "%s\n", timestamp);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SOUND_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize relay pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    unsigned long last_activation_time = 0;
    unsigned long last_debounce_time = 0;

    while (keep_running) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN);

        if (sound_detected && (gpioTickDiff(last_debounce_time) > DEBOUNCE_TIME)) {
            unsigned long current_time = gpioTick();
            if (gpioTickDiff(last_activation_time) > RELAY_ON_TIME) {
                if (gpioWrite(RELAY_PIN, 1) < 0) {
                    fprintf(stderr, "Failed to activate relay\n");
                } else {
                    log_timestamp("alarm_log.txt");
                    last_activation_time = current_time;
                }
            }
            last_debounce_time = current_time;
        }

        if (gpioTickDiff(last_activation_time) > RELAY_ON_TIME) {
            if (gpioWrite(RELAY_PIN, 0) < 0) {
                fprintf(stderr, "Failed to deactivate relay\n");
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to deactivate relay on exit\n");
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

