#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define GYRO_XOUT_H_REG 0x43
#define GYRO_SENSITIVITY 131.0
#define THRESHOLD 50.0
#define BUFFER_SIZE 100

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void error_exit(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        error_exit("Failed to write to I2C device");
    }
}

uint8_t i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        error_exit("Failed to write register address to I2C device");
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        error_exit("Failed to read from I2C device");
    }
    return value;
}

void i2c_read_bytes(int fd, uint8_t reg, uint8_t *buffer, size_t length) {
    if (write(fd, &reg, 1) != 1) {
        error_exit("Failed to write register address to I2C device");
    }
    if (read(fd, buffer, length) != length) {
        error_exit("Failed to read from I2C device");
    }
}

void initialize_mpu6050(int fd) {
    uint8_t who_am_i = i2c_read_byte(fd, WHO_AM_I_REG);
    if (who_am_i != 0x68) {
        error_exit("MPU6050 not found");
    }

    i2c_write_byte(fd, PWR_MGMT_1_REG, 0x00); // Wake up the MPU6050
}

void read_gyroscope_data(int fd, float *gx, float *gy, float *gz) {
    uint8_t buffer[6];
    i2c_read_bytes(fd, GYRO_XOUT_H_REG, buffer, 6);

    int16_t raw_x = (buffer[0] << 8) | buffer[1];
    int16_t raw_y = (buffer[2] << 8) | buffer[3];
    int16_t raw_z = (buffer[4] << 8) | buffer[5];

    *gx = raw_x / GYRO_SENSITIVITY;
    *gy = raw_y / GYRO_SENSITIVITY;
    *gz = raw_z / GYRO_SENSITIVITY;
}

void callback_function() {
    printf("Threshold exceeded!\n");
}

int main() {
    signal(SIGINT, handle_sigint);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        error_exit("Failed to open I2C device");
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        close(fd);
        error_exit("Failed to set I2C address");
    }

    initialize_mpu6050(fd);

    float buffer[BUFFER_SIZE][3];
    int buffer_index = 0;

    while (keep_running) {
        float gx, gy, gz;
        read_gyroscope_data(fd, &gx, &gy, &gz);

        buffer[buffer_index][0] = gx;
        buffer[buffer_index][1] = gy;
        buffer[buffer_index][2] = gz;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        float magnitude = sqrt(gx * gx + gy * gy + gz * gz);
        if (magnitude > THRESHOLD) {
            callback_function();
        }

        usleep(10000); // 10ms delay
    }

    close(fd);
    return 0;
}

