    int16_t raw_y = (buffer[2] << 8) | buffer[3];
    int16_t raw_z = (buffer[4] << 8) | buffer[5];

    *gx = raw_x / GYRO_SENSITIVITY;
    *gy = raw_y / GYRO_SENSITIVITY;
    *gz = raw_z / GYRO_SENSITIVITY;
}

void callback_function() {
    printf("Threshold exceeded!\n");
}

int main() {
    signal(SIGINT, handle_sigint);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        error_exit("Failed to open I2C device");
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        close(fd);
        error_exit("Failed to set I2C address");
    }

    initialize_mpu6050(fd);

    float buffer[BUFFER_SIZE][3];
    int buffer_index = 0;

    while (keep_running) {
        float gx, gy, gz;
        read_gyroscope_data(fd, &gx, &gy, &gz);

        buffer[buffer_index][0] = gx;
        buffer[buffer_index][1] = gy;
        buffer[buffer_index][2] = gz;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        float magnitude = sqrt(gx * gx + gy * gy + gz * gz);
        if (magnitude > THRESHOLD) {
            callback_function();
        }

        usleep(10000); // 10ms delay
    }

    close(fd);
    return 0;
}
