#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define SERIAL_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define READ_TIMEOUT 1000
#define READ_INTERVAL 100
#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define READ_COMMAND_SIZE 9
#define READ_RESPONSE_SIZE 9
#define LOG_INTERVAL 5000

static int pi = -1;
static int serial_fd = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

void log_error(const char *message) {
    if (error_log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(error_log_file, "[%s] %s\n", time_str, message);
        fflush(error_log_file);
    }
}

void handle_signal(int sig) {
    if (serial_fd != -1) {
        serClose(serial_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (error_log_file) {
        fclose(error_log_file);
    }
    if (pi != -1) {
        gpioTerminate(pi);
    }
    exit(EXIT_SUCCESS);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int open_serial_port() {
    serial_fd = serOpen(SERIAL_DEVICE, BAUD_RATE, 0);
    if (serial_fd < 0) {
        log_error("Failed to open serial port");
        return -1;
    }
    return 0;
}

int send_read_command() {
    if (serWrite(serial_fd, READ_COMMAND, READ_COMMAND_SIZE) != READ_COMMAND_SIZE) {
        log_error("Failed to send read command");
        return -1;
    }
    usleep(READ_INTERVAL * 1000);
    return 0;
}

int read_response(uint8_t *response) {
    int total_bytes = 0;
    int start_time = millis();
    while (total_bytes < READ_RESPONSE_SIZE) {
        if (millis() - start_time > READ_TIMEOUT) {
            log_error("Read timeout");
            return -1;
        }
        if (serDataAvailable(serial_fd) >= (READ_RESPONSE_SIZE - total_bytes)) {
            int bytes_read = serRead(serial_fd, response + total_bytes, READ_RESPONSE_SIZE - total_bytes);
            if (bytes_read <= 0) {
                log_error("Failed to read response");
                return -1;
            }
            total_bytes += bytes_read;
        }
        usleep(READ_INTERVAL * 1000);
    }
    return 0;
}

int validate_checksum(uint8_t *response) {
    uint8_t checksum = 0;
    for (int i = 1; i < 8; i++) {
        checksum += response[i];
    }
    checksum = (~checksum + 1) & 0xFF;
    return (checksum == response[8]);
}

int extract_co2(uint8_t *response, int *co2) {
    *co2 = (response[2] << 8) | response[3];
    return 0;
}

void log_co2(int co2, int error) {
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "{\"timestamp\": \"%s.%06ld\", \"ppm\": %d, \"error\": %d}\n",
                time_str, tv.tv_usec, co2, error);
        fflush(log_file);
    }
    printf("{\"timestamp\": \"%s.%06ld\", \"ppm\": %d, \"error\": %d}\n",
           time_str, tv.tv_usec, co2, error);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }
    pi = gpioInitialise();

    if (open_serial_port() != 0) {
        gpioTerminate(pi);
        return EXIT_FAILURE;
    }

    log_file = fopen("co2_log.json", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        serClose(serial_fd);
        gpioTerminate(pi);
        return EXIT_FAILURE;
    }

    error_log_file = fopen("co2_error.log", "a");
    if (!error_log_file) {
        log_error("Failed to open error log file");
        fclose(log_file);
        serClose(serial_fd);
        gpioTerminate(pi);
        return EXIT_FAILURE;
    }

    setup_signal_handlers();

    while (1) {
        uint8_t response[READ_RESPONSE_SIZE];
        int co2 = 0;
        int error = 0;

        if (send_read_command() != 0) {
            error = 1;
        } else if (read_response(response) != 0) {
            error = 1;
        } else if (!validate_checksum(response)) {
            log_error("Checksum mismatch");
            error = 1;
        } else if (extract_co2(response, &co2) != 0) {
            error = 1;
        }

        log_co2(co2, error);

        usleep(LOG_INTERVAL * 1000);
    }

    if (serial_fd != -1) {
        serClose(serial_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (error_log_file) {
        fclose(error_log_file);
    }
    if (pi != -1) {
        gpioTerminate(pi);
    }

    return EXIT_SUCCESS;
}

