#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_START 0x03
#define GPIO_PIN 17
#define TARGET_HEADING 90.0
#define COMPENSATION_X 100
#define COMPENSATION_Y -50
#define DEVIATION_THRESHOLD 10.0
#define SAMPLE_INTERVAL 100
#define BUFFER_SIZE 100

volatile sig_atomic_t keep_running = 1;
int i2c_handle;
int buffer[BUFFER_SIZE];
int buffer_index = 0;

void signal_handler(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void write_i2c_register(int reg, int value) {
    if (i2c_write_i2c_block_data(i2c_handle, reg, &value, 1) < 0) {
        log_error("Failed to write I2C register");
    }
}

int read_i2c_data(int reg, int *data, int length) {
    if (i2c_read_i2c_block_data(i2c_handle, reg, data, length) < 0) {
        log_error("Failed to read I2C data");
        return -1;
    }
    return 0;
}

double calculate_heading(int x, int z, int y) {
    double heading = atan2((double)y, (double)x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

void setup_sensor() {
    write_i2c_register(CONFIG_A, 0x70);
    write_i2c_register(CONFIG_B, 0x20);
    write_i2c_register(MODE, 0x00);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    setup_sensor();

    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    while (keep_running) {
        int data[6];
        if (read_i2c_data(DATA_START, data, 6) == 0) {
            int x = (data[0] << 8) | data[1];
            int z = (data[2] << 8) | data[3];
            int y = (data[4] << 8) | data[5];

            x += COMPENSATION_X;
            y += COMPENSATION_Y;

            double heading = calculate_heading(x, z, y);
            buffer[buffer_index] = (int)heading;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            double deviation = fabs(heading - TARGET_HEADING);
            gpioWrite(GPIO_PIN, deviation > DEVIATION_THRESHOLD ? PI_HIGH : PI_LOW);

            printf("Heading: %.2f\n", heading);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

