#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "lighting_log.txt"
#define RED_RELAY 17
#define GREEN_RELAY 27
#define BLUE_RELAY 22

static int i2c_fd = -1;
static int log_fd = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *red_line, *green_line, *blue_line;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

void handle_signal(int sig) {
    cleanup();
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
    }

    red_line = gpiod_chip_get_line(chip, RED_RELAY);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY);
    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY);

    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        cleanup();
    }

    if (gpiod_line_request_output(red_line, "red_relay", 0) < 0 ||
        gpiod_line_request_output(green_line, "green_relay", 0) < 0 ||
        gpiod_line_request_output(blue_line, "blue_relay", 0) < 0) {
        perror("Failed to request GPIO lines");
        cleanup();
    }
}

void setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup();
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C address");
        cleanup();
    }

    uint8_t mode = BH1750_CONT_HIGH_RES_MODE;
    if (write(i2c_fd, &mode, 1) != 1) {
        perror("Failed to write to I2C bus");
        cleanup();
    }
    usleep(120000); // Wait for the first conversion
}

void log_data(time_t timestamp, float lux, int red, int green, int blue) {
    if (log_fd == -1) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd < 0) {
            perror("Failed to open log file");
            cleanup();
        }
    }

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%ld, %.2f, %d, %d, %d\n", timestamp, lux, red, green, blue);
    if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
        perror("Failed to write to log file");
    }
}

void control_relays(float lux) {
    int red = 0, green = 0, blue = 0;

    if (lux < 50) {
        red = 1;
    } else if (lux < 150) {
        green = 1;
    } else if (lux < 300) {
        blue = 1;
    } else {
        red = green = blue = 1;
    }

    gpiod_line_set_value(red_line, red);
    gpiod_line_set_value(green_line, green);
    gpiod_line_set_value(blue_line, blue);
}

int read_lux() {
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C bus");
        return -1;
    }

    uint16_t raw = (data[0] << 8) | data[1];
    return raw / 1.2;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_i2c();

    while (1) {
        int raw_lux = read_lux();
        if (raw_lux < 0) {
            cleanup();
        }

        float lux = raw_lux;
        time_t timestamp = time(NULL);

        control_relays(lux);
        log_data(timestamp, lux, gpiod_line_get_value(red_line), gpiod_line_get_value(green_line), gpiod_line_get_value(blue_line));

        sleep(1);
    }

    cleanup();
    return 0;
}
