#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int map_distance_to_pwm(int distance) {
    if (distance < 10) return PWM_RANGE;
    if (distance > 100) return 0;
    return (PWM_RANGE * (100 - distance)) / 90;
}

void control_motor(int in1, int in2, int distance) {
    int pwm_value = map_distance_to_pwm(distance);
    if (distance < 50) {
        gpioWrite(in1, 1);
        gpioPWM(in2, pwm_value);
    } else {
        gpioWrite(in1, 0);
        gpioPWM(in2, pwm_value);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_motor_a = atoi(argv[1]);
    int distance_motor_b = atoi(argv[2]);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    gpioPWMrange(PWM_RANGE);
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    while (keep_running) {
        control_motor(MOTOR_A_IN1, MOTOR_A_IN2, distance_motor_a);
        control_motor(MOTOR_B_IN3, MOTOR_B_IN4, distance_motor_b);
        usleep(100000); // 100 ms
    }

    // Stop motors
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioPWM(MOTOR_A_IN2, 0);
    gpioPWM(MOTOR_B_IN4, 0);

    gpioTerminate();
    return EXIT_SUCCESS;
}

