    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int init_mpu6050(int fd) {
    uint8_t data[2];
    data[0] = 0x6B; // PWR_MGMT_1 register
    data[1] = 0;    // Set to zero to wake up the MPU-6050
    if (write(fd, data, 2) != 2) {
        perror("Failed to write to PWR_MGMT_1 register");
        return -1;
    }

    return 0;
}

int read_accel_gyro(int fd, int16_t *accel, int16_t *gyro) {
    uint8_t buf[14];
    if (read_i2c_block_data(fd, 0x3B, buf, 14) < 0) {
        return -1;
    }

    accel[0] = (buf[0] << 8) | buf[1];
    accel[1] = (buf[2] << 8) | buf[3];
    accel[2] = (buf[4] << 8) | buf[5];
    gyro[0] = (buf[8] << 8) | buf[9];
    gyro[1] = (buf[10] << 8) | buf[11];
    gyro[2] = (buf[12] << 8) | buf[13];

    return 0;
}

int init_pwm() {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/%s/%s/enable", PWM_CHIP, PWM_DEVICE);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM enable file");
        return -1;
    }
    if (write(fd, "1", 1) != 1) {
        perror("Failed to enable PWM");
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/pwm/%s/%s/duty_cycle", PWM_CHIP, PWM_DEVICE);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM duty cycle file");
        return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/pwm/%s/%s/period", PWM_CHIP, PWM_DEVICE);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM period file");
        return -1;
    }
    if (write(fd, "20000000", 9) != 9) { // 20ms period
        perror("Failed to set PWM period");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

int set_pwm_duty_cycle(int duty_cycle) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/class/pwm/%s/%s/duty_cycle", PWM_CHIP, PWM_DEVICE);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM duty cycle file");
        return -1;
    }
    char buffer[12];
    snprintf(buffer, sizeof(buffer), "%d", duty_cycle);
    if (write(fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("Failed to set PWM duty cycle");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

void log_data(int pitch, int roll, int servo_position) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log, "%s,%d,%d,%d\n", timestamp, pitch, roll, servo_position);
    fclose(log);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = -1;
    for (int retries = 0; retries < MAX_RETRIES; ++retries) {
        i2c_fd = open_i2c_device(I2C_DEVICE, MPU6050_ADDR);
        if (i2c_fd >= 0) {
            break;
        }
        usleep(RETRY_DELAY * (1 << retries)); // Exponential backoff
    }

    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050 after %d retries\n", MAX_RETRIES);
        return EXIT_FAILURE;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_pwm() < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int16_t accel[3], gyro[3];
    int servo_position = 1500000; // Initial duty cycle (50% of 20ms period)

    while (!stop) {
        if (read_accel_gyro(i2c_fd, accel, gyro) < 0) {
            fprintf(stderr, "Failed to read from MPU-6050\n");
            break;
        }

        // Simple pitch and roll calculation (not calibrated)
        int pitch = accel[0];
        int roll = accel[1];

        // Adjust servo position based on roll
        if (roll > 1000) {
            servo_position += 10000;
        } else if (roll < -1000) {
            servo_position -= 10000;
        }

        // Clamp servo position
        if (servo_position < 1000000) {
            servo_position = 1000000;
        } else if (servo_position > 2000000) {
            servo_position = 2000000;
        }

        if (set_pwm_duty_cycle(servo_position) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        log_data(pitch, roll, servo_position);
        usleep(100000); // 100ms delay
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}
