#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define TRANSITION_TIME 1800 // 30 minutes in seconds

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define GPIO22 22

#define NUM_RELAYS 4
#define MAX_SCHEDULE_ENTRIES 1440 // Max entries for a 24-hour schedule

typedef struct {
    time_t time;
    int relay;
    int state;
} ScheduleEntry;

ScheduleEntry schedule[MAX_SCHEDULE_ENTRIES];
int schedule_count = 0;
int pi = -1;

void handle_signal(int sig) {
    if (pi >= 0) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpioPWMStop(pi, i + 4);
            gpioWrite(i + 4, 0);
        }
        gpioTerminate(pi);
    }
    exit(0);
}

int read_schedule(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening schedule file: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%2d:%2d:%2d,%d,%s",
                   &schedule[schedule_count].time.tm_hour,
                   &schedule[schedule_count].time.tm_min,
                   &schedule[schedule_count].time.tm_sec,
                   &schedule[schedule_count].relay,
                   line + strlen(line) - 2) == 5) {
            schedule[schedule_count].time.tm_year = 120; // Year 2020
            schedule[schedule_count].time.tm_mon = 0;    // January
            schedule[schedule_count].time.tm_mday = 1;   // 1st day
            schedule[schedule_count].time = mktime(&schedule[schedule_count].time);
            schedule[schedule_count].state = strcmp(line + strlen(line) - 2, "on") == 0 ? 1 : 0;
            schedule_count++;
        } else {
            fprintf(stderr, "Invalid schedule entry: %s", line);
        }
    }

    fclose(file);
    return 0;
}

void update_lights() {
    time_t now = time(NULL);
    struct tm *current_time = localtime(&now);

    for (int i = 0; i < schedule_count; i++) {
        if (difftime(now, schedule[i].time) >= 0 && difftime(now, schedule[i].time) < TRANSITION_TIME) {
            int elapsed = difftime(now, schedule[i].time);
            int duty_cycle = (schedule[i].state * PWM_RANGE * elapsed) / TRANSITION_TIME;

            if (gpioPWMSetFreq(pi, schedule[i].relay + 3, PWM_FREQUENCY) < 0) {
                fprintf(stderr, "Error setting PWM frequency: %s\n", strerror(errno));
                continue;
            }

            if (gpioPWM(duty_cycle, schedule[i].relay + 3) < 0) {
                fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
            }
        } else if (difftime(now, schedule[i].time) >= TRANSITION_TIME) {
            gpioWrite(schedule[i].relay + 3, schedule[i].state);
            gpioPWMStop(pi, schedule[i].relay + 3);
        }
    }
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(pi, i + 4, PI_OUTPUT) < 0) {
            fprintf(stderr, "Error setting GPIO mode: %s\n", strerror(errno));
            pigpio_stop(pi);
            return EXIT_FAILURE;
        }
    }

    if (read_schedule("lighting_schedule.txt") != 0) {
        pigpio_stop(pi);
        return EXIT_FAILURE;
    }

    while (1) {
        update_lights();
        sleep(1);
    }

    // This point is never reached due to the infinite loop
    pigpio_stop(pi);
    return EXIT_SUCCESS;
}

