#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 30
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define MEASUREMENT_INTERVAL_MS 60
#define TIMEOUT_US 30000

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
    gpioWrite(BUZZER_PIN, 0);
    printf("SIGINT received, shutting down...\n");
}

double measure_distance() {
    if (gpioTrigger(TRIGGER_PIN, 10) < 0) {
        fprintf(stderr, "Failed to trigger ultrasonic sensor\n");
        return -1;
    }

    unsigned long start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTickDiff(start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo\n");
            return -1;
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTickDiff(start_tick) > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            return -1;
        }
    }

    unsigned long pulse_width_us = gpioTickDiff(start_tick);
    double distance_cm = pulse_width_us / 58.0;
    return distance_cm;
}

int map_distance_to_frequency(double distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM) distance_cm = MIN_DISTANCE_CM;
    if (distance_cm > MAX_DISTANCE_CM) distance_cm = MAX_DISTANCE_CM;

    double frequency_hz = MIN_FREQUENCY_HZ + (distance_cm - MIN_DISTANCE_CM) *
                          (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    return (int)frequency_hz;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        double distance_cm = measure_distance();
        if (distance_cm < 0) {
            fprintf(stderr, "Error measuring distance\n");
            usleep(MEASUREMENT_INTERVAL_MS * 1000);
            continue;
        }

        int frequency_hz = map_distance_to_frequency(distance_cm);
        if (gpioPWM(BUZZER_PIN, frequency_hz) < 0) {
            fprintf(stderr, "Failed to set PWM frequency\n");
        }

        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
    printf("Program terminated\n");
    return 0;
}

