        cleanup(RED_PIN, GREEN_PIN, BLUE_PIN);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    double t = 0.0;
    double dt = 0.01;

    while (keep_running) {
        double proximity = (sin(t) + 1.0) / 2.0; // Simulated proximity value between 0.0 and 1.0

        int red_value = (int)(255 * (1.0 - proximity));
        int green_value = (int)(255 * proximity);
        int blue_value = 0;

        if (gpioPWM(RED_PIN, red_value) < 0 ||
            gpioPWM(GREEN_PIN, green_value) < 0 ||
            gpioPWM(BLUE_PIN, blue_value) < 0) {
            fprintf(stderr, "Failed to set PWM value\n");
            cleanup(RED_PIN, GREEN_PIN, BLUE_PIN);
            return EXIT_FAILURE;
        }

        t += dt;
        usleep(10000); // Sleep for 10ms
    }

