volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write_byte_data(int file, uint8_t reg, uint8_t data) {
    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    uint8_t buffer[2] = {reg, data};
    if (write(file, buffer, 2) != 2) {
        perror("Failed to write to the device");
        return -1;
    }

    return 0;
}

int i2c_read_block_data(int file, uint8_t reg, uint8_t *data, size_t length) {
    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(file, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(file, data, length) != length) {
        perror("Failed to read from the device");
        return -1;
    }

    return 0;
}

int16_t convert_to_int16(uint8_t high, uint8_t low) {
    return (int16_t)((high << 8) | low);
}

double convert_to_degrees_per_second(int16_t raw_value) {
    return raw_value / 131.0;
}

