    int file;
    uint8_t data[6];
    struct timespec ts;
    FILE *log_file;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    file = open(I2C_DEVICE, O_RDWR);
    if (file < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (i2c_write_byte_data(file, PWR_MGMT_1, 0x00) < 0) {
        close(file);
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(file);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (i2c_read_block_data(file, GYRO_XOUT_H, data, 6) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            break;
        }

        int16_t x_raw = convert_to_int16(data[0], data[1]);
        int16_t y_raw = convert_to_int16(data[2], data[3]);
        int16_t z_raw = convert_to_int16(data[4], data[5]);

        double x_dps = convert_to_degrees_per_second(x_raw);
        double y_dps = convert_to_degrees_per_second(y_raw);
        double z_dps = convert_to_degrees_per_second(z_raw);

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: x: %.2f, y: %.2f, z: %.2f\n",
                ts.tv_sec, ts.tv_nsec, x_dps, y_dps, z_dps);
        fflush(log_file);

        usleep(100000); // Sleep for 100 ms
    }

    fclose(log_file);
    close(file);

    return EXIT_SUCCESS;
}

