    stop_flag = 1;
}

void button_isr_handler(unsigned gpio, unsigned level, uint32_t tick, void *userdata) {
    if (level == 0 && !debounce_flag) {
        debounce_flag = 1;
        play_flag = !play_flag;
    }
}

void play_melody() {
    for (size_t i = 0; i < melody_length; ++i) {
        if (stop_flag) {
            break;
        }
        if (melody[i] == 0) {
            usleep(note_durations[i] * 1000);
        } else {
            if (gpioHardwarePWM(BUZZER_PIN, PWM_FREQUENCY, PWM_DUTY_CYCLE, melody[i]) < 0) {
                fprintf(stderr, "Failed to set PWM frequency\n");
                exit(EXIT_FAILURE);
            }
            usleep(note_durations[i] * 1000);
            gpioHardwarePWM(BUZZER_PIN, 0, 0, 0); // Stop PWM
        }
    }
}

