        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, GPIO_INTR_FALLING, button_isr_handler, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop_flag) {
        if (play_flag && !debounce_flag) {
            play_melody();
            play_flag = 0;
        }
        if (debounce_flag) {
            usleep(DEBOUNCE_MS * 1000);
            debounce_flag = 0;
        }
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0, 0); // Ensure PWM is stopped
    gpioTerminate();

    return EXIT_SUCCESS;
}

