#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEFAULT_TIMEOUT 1000
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

void log_event(FILE *log_file, int value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (fprintf(log_file, "%s %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
    if (fsync(fileno(log_file)) < 0) {
        fprintf(stderr, "Error fsyncing log file: %s\n", strerror(errno));
    }
}

void print_earthquake_alert(time_t now) {
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    printf("EARTHQUAKE ALERT at %s\n", timestamp);
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int timeout = DEFAULT_TIMEOUT;
    int value;
    int high_count = 0;
    int event_values[WINDOW_SIZE] = {0};
    int event_index = 0;
    FILE *log_file;

    if (argc > 1) {
        timeout = atoi(argv[1]);
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "vibration_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        if (gpiod_line_event_wait(line, timeout) < 0) {
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            break;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            break;
        }

        value = gpiod_line_event_value(&event);
        log_event(log_file, value);

        event_values[event_index] = value;
        event_index = (event_index + 1) % WINDOW_SIZE;

        high_count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (event_values[i] == 1) {
                high_count++;
            }
        }

        if (high_count >= 3) {
            time_t now = time(NULL);
            print_earthquake_alert(now);
        }
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

