#define I2C_DEVICE "/dev/i2c-1"
#define LSM303_ADDRESS 0x1E
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define REG_OUT_X_H_M 0x03
#define REG_OUT_X_L_M 0x04
#define REG_OUT_Z_H_M 0x05
#define REG_OUT_Z_L_M 0x06
#define REG_OUT_Y_H_M 0x07
#define REG_OUT_Y_L_M 0x08

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (ioctl(fd, I2C_SLAVE, LSM303_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to the i2c bus");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, LSM303_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
