#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_MS 200

volatile int relay_state = 0;
volatile int last_touch_time = 0;
volatile sig_atomic_t terminate = 0;

void log_relay_state(const char *state) {
    FILE *file = fopen("relay_log.json", "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening relay_log.json\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "\"%Y-%m-%dT%H:%M:%SZ\"", tm_info);

    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "{\"timestamp\":%s,\"relay_state\":\"%s\"}\n", timestamp, state);

    if (fputs(log_entry, file) == EOF) {
        fprintf(stderr, "Error writing to relay_log.json\n");
    }

    fclose(file);
}

void touch_callback(int gpio, unsigned level, uint32_t tick) {
    uint32_t current_time = pigpio_get_current_tick();
    uint32_t elapsed_time = pigpio_tickDiff(current_time, last_touch_time);

    if (elapsed_time > DEBOUNCE_MS) {
        last_touch_time = current_time;

        relay_state = !relay_state;
        if (relay_state) {
            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Error toggling relay ON\n");
            }
            log_relay_state("ON");
        } else {
            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Error toggling relay OFF\n");
            }
            log_relay_state("OFF");
        }
    }
}

void handle_sigint(int sig) {
    terminate = 1;
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error turning relay OFF on SIGINT\n");
    }
    log_relay_state("OFF");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode for TOUCH_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor for TOUCH_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TOUCH_PIN, EDGE_RISING, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for TOUCH_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!terminate) {
        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

