#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_RELAY_COUNT 4
#define GPIO_RELAY_PINS {17, 23, 24, 25}
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME 5
#define RELAY_OFF_TIME 1
#define LOG_FILE "irrigation_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[GPIO_RELAY_COUNT] = {NULL};
static FILE *log_file = NULL;
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void log_activation(int relay, int moisture) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (fprintf(log_file, "[%s] Relay %d activated, Moisture: %d\n", timestamp, relay, moisture) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

void setup_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_RELAY_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_RELAY_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", GPIO_RELAY_PINS[i], strerror(errno));
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(lines[i], "relay", 1) < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", GPIO_RELAY_PINS[i], strerror(gpiod_strerror(gpiod_line_request_output(lines[i], "relay", 1))));
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpio() {
    for (int i = 0; i < GPIO_RELAY_COUNT; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

void deactivate_all_relays() {
    for (int i = 0; i < GPIO_RELAY_COUNT; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    setup_gpio();

    while (!stop) {
        int moisture = rand() % 101;
        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < GPIO_RELAY_COUNT; i++) {
                if (gpiod_line_set_value(lines[i], 0) < 0) {
                    fprintf(stderr, "Error setting line %d to 0: %s\n", GPIO_RELAY_PINS[i], strerror(errno));
                    continue;
                }
                log_activation(i + 1, moisture);
                sleep(RELAY_ON_TIME);

                if (gpiod_line_set_value(lines[i], 1) < 0) {
                    fprintf(stderr, "Error setting line %d to 1: %s\n", GPIO_RELAY_PINS[i], strerror(errno));
                }
                sleep(RELAY_OFF_TIME);
            }
        }
        sleep(10);
    }

    deactivate_all_relays();
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

