#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18
#define RETRY_LIMIT 3
#define RETRY_DELAY_MS 100
#define VALVE_OPEN_PULSE 1500
#define VALVE_CLOSED_PULSE 500
#define NOZZLE_PULSES {500, 750, 1500, 2250, 2500}
#define WATERING_DURATION 5
#define CYCLE_DELAY 5

volatile sig_atomic_t stop_requested = 0;

void handle_signal(int sig) {
    stop_requested = 1;
}

int gpio_servo_retry(int gpio, int pulse, int retries) {
    for (int attempt = 0; attempt < retries; ++attempt) {
        if (gpioServo(gpio, pulse) == 0) {
            return 0;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int moisture_values[] = {20, 40, 60, 80, 100};
    int num_values = sizeof(moisture_values) / sizeof(moisture_values[0]);

    for (int i = 0; i < num_values && !stop_requested; ++i) {
        int moisture = moisture_values[i];
        printf("Moisture reading: %d\n", moisture);

        if (moisture < 50) {
            if (gpio_servo_retry(VALVE_GPIO, VALVE_OPEN_PULSE, RETRY_LIMIT) != 0) {
                fprintf(stderr, "Critical: Failed to open valve\n");
                break;
            }

            int nozzle_pulses[] = NOZZLE_PULSES;
            for (int j = 0; j < 5 && !stop_requested; ++j) {
                if (gpio_servo_retry(NOZZLE_GPIO, nozzle_pulses[j], RETRY_LIMIT) != 0) {
                    fprintf(stderr, "Error: Failed to set nozzle to %d degrees\n", j * 45);
                    continue;
                }
                sleep(2);
            }

