#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_DEVICE "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int i2c_write_byte_data(int fd, uint8_t reg, uint8_t data) {
    uint8_t buffer[2] = {reg, data};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int length) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, buf, length) != length) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int main() {
    int i2c_fd;
    uint8_t data[6];
    FILE *log_file;
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte_data(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,x,y,z\n");

    while (!stop) {
        if (i2c_read_bytes(i2c_fd, GYRO_XOUT_H, data, 6) < 0) {
            close(i2c_fd);
            fclose(log_file);
            return EXIT_FAILURE;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        double x_deg_s = x / GYRO_SENSITIVITY;
        double y_deg_s = y / GYRO_SENSITIVITY;
        double z_deg_s = z / GYRO_SENSITIVITY;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, x_deg_s, y_deg_s, z_deg_s);
        fflush(log_file);

        usleep(100000); // Sleep for 100ms to achieve 10Hz sampling rate
    }

    close(i2c_fd);
    fclose(log_file);
    return EXIT_SUCCESS;
}

