#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define DEBOUNCE_DELAY 200 // milliseconds
#define STEP_DELAY 3 // milliseconds
#define STEPS_PER_ROTATION 512

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    printf("SIGINT received, de-energizing coils and exiting.\n");
}

void rotate_motor(int steps, int direction) {
    int sequence[8] = {1, 3, 2, 6, 4, 12, 8, 9};
    int step_count = 0;

    for (int i = 0; i < steps; i++) {
        for (int j = 0; j < 8; j++) {
            int step = sequence[(direction == 1) ? j : (7 - j)];
            gpioWrite(IN1, (step & 1) ? 1 : 0);
            gpioWrite(IN2, (step & 2) ? 1 : 0);
            gpioWrite(IN3, (step & 4) ? 1 : 0);
            gpioWrite(IN4, (step & 8) ? 1 : 0);

            if (gpioWrite(IN1, (step & 1) ? 1 : 0) != 0 ||
                gpioWrite(IN2, (step & 2) ? 1 : 0) != 0 ||
                gpioWrite(IN3, (step & 4) ? 1 : 0) != 0 ||
                gpioWrite(IN4, (step & 8) ? 1 : 0) != 0) {
                fprintf(stderr, "Error writing to GPIO\n");
                exit(EXIT_FAILURE);
            }

            usleep(STEP_DELAY * 1000);
            step_count++;
        }
    }

    // De-energize coils
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting GPIO mode or pull-up/down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_lock_state = 1;
    int last_unlock_state = 1;

    while (keep_running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state == 0 && last_lock_state == 1) {
            printf("Lock button pressed\n");
            usleep(DEBOUNCE_DELAY * 1000);
            rotate_motor(STEPS_PER_ROTATION, 1);
            printf("Locked\n");
        }

        if (unlock_state == 0 && last_unlock_state == 1) {
            printf("Unlock button pressed\n");
            usleep(DEBOUNCE_DELAY * 1000);
            rotate_motor(STEPS_PER_ROTATION, -1);
            printf("Unlocked\n");
        }

        last_lock_state = lock_state;
        last_unlock_state = unlock_state;

        usleep(10000); // Polling delay
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

