#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define TRIGGER_PIN 0
#define ECHO_PIN 0
#define TIMEOUT_MS 50
#define PULSE_WIDTH_US 10
#define SPEED_OF_SOUND_CM_US 0.01715
#define MEASURE_INTERVAL_MS 1000
#define GUARD_INTERVAL_MS 60

static int fd_log;
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;

void cleanup(int signum) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (fd_log != -1) {
        close(fd_log);
    }
    exit(0);
}

int main() {
    struct timespec start, end;
    long duration_us;
    int distance_cm;
    int ret;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    fd_log = open("distance_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd_log == -1) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup(0);
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_GPIO);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        cleanup(0);
    }
    if (gpiod_line_request(trigger_line, "trigger", GPIOD_OUT) < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        cleanup(0);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_GPIO);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        cleanup(0);
    }
    if (gpiod_line_request(echo_line, "echo", GPIOD_IN) < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        cleanup(0);
    }

    while (1) {
        // Generate 10us pulse on trigger
        gpiod_line_set_value(trigger_line, 1);
        nanosleep((const struct timespec[]){{0, PULSE_WIDTH_US * 1000}}, NULL);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo to go high
        ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_RISING, TIMEOUT_MS * 1000);
        if (ret < 0) {
            fprintf(stderr, "Timeout waiting for echo to rise\n");
            fprintf(fd_log, "-1\n");
            continue;
        }

        // Measure duration of echo high
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            perror("Failed to get start time");
            fprintf(fd_log, "-1\n");
            continue;
        }

        ret = gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_FALLING, TIMEOUT_MS * 1000);
        if (ret < 0) {
            fprintf(stderr, "Timeout waiting for echo to fall\n");
            fprintf(fd_log, "-1\n");
            continue;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("Failed to get end time");
            fprintf(fd_log, "-1\n");
            continue;
        }

        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        distance_cm = (int)(duration_us * SPEED_OF_SOUND_CM_US);

        fprintf(fd_log, "%d\n", distance_cm);

        // Guard interval
        usleep(GUARD_INTERVAL_MS * 1000);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

