#define DISTANCE_THRESHOLD 50

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int write_register(int i2c_handle, uint8_t reg, uint8_t value) {
    int result = i2c_write_byte_data(i2c_handle, VL53L1X_I2C_ADDR, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, pi_error_string(result));
    }
    return result;
}

int read_register(int i2c_handle, uint8_t reg, uint8_t *value) {
    int result = i2c_read_byte_data(i2c_handle, VL53L1X_I2C_ADDR, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, pi_error_string(result));
    }
    return result;
}

int read_distance(int i2c_handle, uint16_t *distance) {
    uint8_t msb, lsb;
    int result = read_register(i2c_handle, 0x0096, &msb);
    if (result < 0) return result;
    result = read_register(i2c_handle, 0x0097, &lsb);
    if (result < 0) return result;
    *distance = (msb << 8) | lsb;
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pi_error_string(gpioInitialise()));
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = i2cOpen(VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pi_error_string(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0 || gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", pi_error_string(gpioInitialise()));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, 0x0000, 0x00) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, 0x0080, 0x01) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint8_t interrupt_status;
        if (read_register(i2c_handle, 0x0044, &interrupt_status) < 0) {
            fprintf(stderr, "Error checking interrupt status\n");
            break;
        }

        if (interrupt_status & 0x02) { // Data ready
            uint16_t distance;
            if (read_distance(i2c_handle, &distance) < 0) {
                fprintf(stderr, "Error reading distance\n");
                break;
            }
            printf("Distance: %u cm\n", distance);

            if (distance <= DISTANCE_THRESHOLD) {
                gpioWrite(RELAY_GPIO, 1);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

