#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

int i2c_fd = -1;
volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void i2c_write_byte_data(int reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
}

int i2c_read_bytes_data(int reg, uint8_t *buffer, size_t length) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(i2c_fd, buffer, length) != length) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

void init_mpu6050() {
    // Wake up the MPU-6050
    i2c_write_byte_data(PWR_MGMT_1, 0x00);

    // Set gyroscope full-scale range to ±250 dps
    i2c_write_byte_data(GYRO_CONFIG, 0x00);
}

void read_gyroscope(float *gx, float *gy, float *gz) {
    uint8_t buffer[6];
    if (i2c_read_bytes_data(GYRO_XOUT_H, buffer, 6) != 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        exit(EXIT_FAILURE);
    }

    // Convert raw data to degrees per second
    *gx = (int16_t)((buffer[0] << 8) | buffer[1]) / GYRO_SENSITIVITY;
    *gy = (int16_t)((buffer[2] << 8) | buffer[3]) / GYRO_SENSITIVITY;
    *gz = (int16_t)((buffer[4] << 8) | buffer[5]) / GYRO_SENSITIVITY;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    init_mpu6050();

    float gx, gy, gz;
    while (keep_running) {
        read_gyroscope(&gx, &gy, &gz);
        printf("Gyroscope: x = %.2f dps, y = %.2f dps, z = %.2f dps\n", gx, gy, gz);
        usleep(100000); // 100 ms delay
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

