#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_COUNT 4
#define GPIO_LINE_NAMES { "GPIO17", "GPIO18", "GPIO27", "GPIO22" }
#define GPIO_LINE_NUMBERS { 17, 18, 27, 22 }
#define POLL_INTERVAL 60
#define WATERING_INTERVAL 86400
#define WATERING_DURATION 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[GPIO_LINE_COUNT] = { NULL };
static volatile sig_atomic_t stop = 0;

void log_watering_time() {
    FILE *log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[20];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    if (fprintf(log_file, "Watering started at %s\n", buffer) < 0) {
        perror("Failed to write to log file");
    }

    fclose(log_file);
}

void handle_signal(int sig) {
    stop = 1;
}

void cleanup() {
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct timespec ts = { .tv_sec = WATERING_INTERVAL, .tv_nsec = 0 };
    struct timespec ts_poll = { .tv_sec = POLL_INTERVAL, .tv_nsec = 0 };

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINE_NUMBERS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", GPIO_LINE_NUMBERS[i]);
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_output(lines[i], "relay_control", 1)) {
            fprintf(stderr, "Failed to request line %d as output\n", GPIO_LINE_NUMBERS[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_set_value(lines[i], 1);
    }

    while (!stop) {
        nanosleep(&ts_poll, NULL);

        if (stop) break;

        log_watering_time();

        for (int i = 0; i < GPIO_LINE_COUNT; i++) {
            gpiod_line_set_value(lines[i], 0);
            nanosleep(&ts, NULL);
            gpiod_line_set_value(lines[i], 1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

