        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fclose(log_file);
    }
}

void handle_signal(int signal) {
    keep_running = 0;
}

int setup_gpio_and_pwm(int gpio, int *pwm_handle) {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialise GPIO");
        return -1;
    }

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO mode");
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(gpio, *pwm_handle, 0) < 0) {
        log_event("Failed to initialise PWM");
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup(int *pwm_handles, int num_gpios) {
    for (int i = 0; i < num_gpios; i++) {
        gpioPWM(17 + i, pwm_handles[i], 0);
    }
    gpioTerminate();
    log_event("Cleaned up resources and terminated GPIO");
}

int main() {
    int gpio_pins[] = {17, 18, 27, 22};
    int num_gpios = sizeof(gpio_pins) / sizeof(gpio_pins[0]);
    int pwm_handles[num_gpios];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    for (int i = 0; i < num_gpios; i++) {
        if (setup_gpio_and_pwm(gpio_pins[i], &pwm_handles[i]) < 0) {
            cleanup(pwm_handles, num_gpios);
            return EXIT_FAILURE;
        }
    }

    log_event("Started sunrise simulation");

    for (int step = 0; step <= TOTAL_STEPS && keep_running; step++) {
        for (int i = 0; i < num_gpios; i++) {
            if (gpioPWM(gpio_pins[i], pwm_handles[i], step) < 0) {
                log_event("Failed to set PWM duty cycle");
                cleanup(pwm_handles, num_gpios);
                return EXIT_FAILURE;
            }
        }
        log_event("Updated PWM duty cycle");
        gpioDelay(STEP_DELAY);
    }

    log_event("Completed sunrise simulation");

    cleanup(pwm_handles, num_gpios);
    return EXIT_SUCCESS;
}
