#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43
#define LED_PIN 17
#define BUFFER_SIZE 100
#define THRESHOLD 250

typedef struct {
    double timestamp;
    double x, y, z;
} GyroData;

GyroData buffer[BUFFER_SIZE];
int buffer_index = 0;
int i2c_handle;
int reinit_attempts = 0;

void signal_handler(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    exit(0);
}

int init_i2c() {
    i2c_handle = i2c_open(1, MPU6050_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    if (i2c_write_byte_data(i2c_handle, PWR_MGMT_1, 0x00) < 0 ||
        i2c_write_byte_data(i2c_handle, SMPLRT_DIV, 0x07) < 0 ||
        i2c_write_byte_data(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        i2c_close(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    uint8_t who_am_i;
    if (i2c_read_byte_data(i2c_handle, WHO_AM_I, &who_am_i) < 0 || who_am_i != 0x68) {
        i2c_close(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

void read_gyro_data() {
    uint8_t data[6];
    if (i2c_read_i2c_block_data(i2c_handle, GYRO_XOUT_H, 6, data) < 0) {
        if (reinit_attempts < 3) {
            reinit_attempts++;
            if (init_i2c() == 0) {
                read_gyro_data();
                return;
            }
        }
        fprintf(stderr, "Failed to read gyroscope data\n");
        exit(1);
    }

    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];

    double x_deg_s = x / 131.0;
    double y_deg_s = y / 131.0;
    double z_deg_s = z / 131.0;

    buffer[buffer_index].timestamp = (double)clock() / CLOCKS_PER_SEC;
    buffer[buffer_index].x = x_deg_s;
    buffer[buffer_index].y = y_deg_s;
    buffer[buffer_index].z = z_deg_s;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    int led_state = 0;
    if (fabs(x_deg_s) > THRESHOLD || fabs(y_deg_s) > THRESHOLD || fabs(z_deg_s) > THRESHOLD) {
        led_state = 1;
    }
    gpioWrite(LED_PIN, led_state);
}

