#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <syslog.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define GYRO_SCALE_FACTOR 131.0
#define GYRO_REG_START 0x43
#define GYRO_REG_COUNT 6
#define RETRY_LIMIT 3
#define LOG_FILE "gyro_log.txt"

static int spidev_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;

void cleanup() {
    if (spidev_fd != -1) {
        close(spidev_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    syslog(LOG_INFO, "Cleaned up resources and exiting.");
}

void handle_signal(int sig) {
    cleanup();
    exit(0);
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

int setup_spi() {
    spidev_fd = open(SPI_DEVICE, O_RDWR);
    if (spidev_fd < 0) {
        log_error("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spidev_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        log_error("Failed to set SPI mode");
        close(spidev_fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spidev_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        log_error("Failed to set SPI bits per word");
        close(spidev_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spidev_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        log_error("Failed to set SPI speed");
        close(spidev_fd);
        return -1;
    }

    return 0;
}

int setup_gpio() {
    gpio_chip = gpiod_chip_open(GPIO_CHIP);
    if (!gpio_chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE_OFFSET);
    if (!cs_line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "cs", 1) < 0) {
        log_error("Failed to request GPIO line");
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int read_gyro_data(uint8_t *buffer) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)buffer,
        .rx_buf = (unsigned long)buffer,
        .len = GYRO_REG_COUNT,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    gpiod_line_set_value(cs_line, 0); // Assert CS LOW

    int ret = ioctl(spidev_fd, SPI_IOC_MESSAGE(1), &tr);
    gpiod_line_set_value(cs_line, 1); // Deassert CS HIGH

    if (ret < 0) {
        log_error("SPI transfer failed");
        return -1;
    }

    return 0;
}

void convert_and_log_data(uint8_t *buffer) {
    int16_t x_rate = (int16_t)(buffer[0] << 8 | buffer[1]);
    int16_t y_rate = (int16_t)(buffer[2] << 8 | buffer[3]);
    int16_t z_rate = (int16_t)(buffer[4] << 8 | buffer[5]);

    double x_rate_dps = x_rate / GYRO_SCALE_FACTOR;
    double y_rate_dps = y_rate / GYRO_SCALE_FACTOR;
    double z_rate_dps = z_rate / GYRO_SCALE_FACTOR;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02dT%02d:%02d:%02d.%09ld",
             ts.tv_sec / 86400 + 1970, (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60,
             ts.tv_sec % 60, ts.tv_nsec / 1000000, (ts.tv_nsec / 1000) % 1000);

    if (fprintf(log_file, "%s,%f,%f,%f\n", timestamp, x_rate_dps, y_rate_dps, z_rate_dps) < 0) {
        log_error("Failed to write to log file");
    }
}

int main() {
    openlog("gyro_reader", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_spi() < 0 || setup_gpio() < 0) {
        cleanup();
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    uint8_t buffer[GYRO_REG_COUNT];
    buffer[0] = GYRO_REG_START;

    while (1) {
        int retries = 0;
        while (retries < RETRY_LIMIT) {
            if (read_gyro_data(buffer) == 0) {
                convert_and_log_data(buffer);
                break;
            }
            retries++;
        }

        if (retries == RETRY_LIMIT) {
            log_error("Persistent SPI communication failure");
        }

        usleep(10000); // Sleep for 10 ms
    }

    cleanup();
    closelog();
    return 0;
}

