#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <time.h>
#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define LED_PIN 21
#define I2C_BUS 1

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void log_tilt(const char *filename, double roll, double pitch) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioI2COpen(I2C_BUS, MPU6050_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWriteReg8(MPU6050_ADDRESS, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050.\n");
        gpioI2CClose(MPU6050_ADDRESS);
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWriteReg8(MPU6050_ADDRESS, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range.\n");
        gpioI2CClose(MPU6050_ADDRESS);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);

    while (keep_running) {
        int16_t raw_data[3];
        if (gpioI2CReadReg8(MPU6050_ADDRESS, ACCEL_XOUT_H, (uint8_t *)raw_data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        } else {
            int16_t x = (raw_data[0] << 8) | raw_data[1];
            int16_t y = (raw_data[2] << 8) | raw_data[3];
            int16_t z = (raw_data[4] << 8) | raw_data[5];

            double roll = atan2((double)y, (double)z) * 180.0 / M_PI;
            double pitch = atan2(-(double)x, sqrt((double)y * (double)y + (double)z * (double)z)) * 180.0 / M_PI;

            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

            log_tilt("tilt_log.txt", roll, pitch);

            if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
                gpioWrite(LED_PIN, PI_HIGH);
            } else {
                gpioWrite(LED_PIN, PI_LOW);
            }
        }

        gpioDelay(100);
    }

    gpioWrite(LED_PIN, PI_LOW);
    gpioI2CClose(MPU6050_ADDRESS);
    gpioTerminate();

    return 0;
}

