#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_LED 17
#define RETRY_LIMIT 3
#define RETRY_DELAY 10

static int i2c_fd = -1;
static int gpio_fd = -1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd != -1) {
        gpiod_line_set_value(gpio_fd, 0);
        gpiod_line_release(gpio_fd);
    }
    exit(0);
}

int i2c_write_read(int fd, uint8_t reg, uint8_t *data, size_t length) {
    uint8_t buffer[3];
    buffer[0] = reg;
    for (size_t i = 0; i < length; i++) {
        buffer[i + 1] = data[i];
    }

    if (write(fd, buffer, length + 1) != length + 1) {
        return -1;
    }

    if (read(fd, data, length) != length) {
        return -1;
    }

    return 0;
}

int read_sensor_value(int fd, uint8_t reg, uint16_t *value) {
    uint8_t data[2];
    int retries = 0;

    while (retries < RETRY_LIMIT) {
        if (i2c_write_read(fd, reg, data, 2) == 0) {
            *value = (data[0] | (data[1] << 8));
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY * 1000);
    }

    return -1;
}

void log_reading(uint16_t ambient_light, uint16_t proximity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity);
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd == -1) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int line = gpiod_chip_get_line(gpio_fd, GPIO_LED);
    if (line < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "presence_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t ambient_light = 0;
        uint16_t proximity = 0;

        if (read_sensor_value(i2c_fd, AMBIENT_LIGHT_REG, &ambient_light) == 0 &&
            read_sensor_value(i2c_fd, PROXIMITY_REG, &proximity) == 0) {
            log_reading(ambient_light, proximity);
            gpiod_line_set_value(line, proximity > 100);
        } else {
            fprintf(stderr, "I2C communication error\n");
        }

        usleep(100000); // 100 ms
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

