#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17
#define ALERT_DURATION 2000 // milliseconds
#define SEISMIC_THRESHOLD 500 // milliseconds

volatile sig_atomic_t running = 1;
FILE *log_file = NULL;
int sensor1_high_time = 0;
int sensor2_high_time = 0;

void log_seismic_event() {
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file);
    }
}

void handle_signal(int signal) {
    running = 0;
    if (log_file) {
        fclose(log_file);
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(ALERT_PIN, LOW);
        gpioTerminate();
    }
    exit(0);
}

void sensor_callback(int gpio, int level, uint32_t tick) {
    if (gpio == SENSOR1_PIN) {
        if (level == HIGH) {
            sensor1_high_time = pigpioGetTick();
        } else {
            sensor1_high_time = 0;
        }
    } else if (gpio == SENSOR2_PIN) {
        if (level == HIGH) {
            sensor2_high_time = pigpioGetTick();
        } else {
            sensor2_high_time = 0;
        }
    }

    if (sensor1_high_time && sensor2_high_time) {
        uint32_t current_time = pigpioGetTick();
        if ((current_time - sensor1_high_time) >= SEISMIC_THRESHOLD &&
            (current_time - sensor2_high_time) >= SEISMIC_THRESHOLD) {
            gpioWrite(ALERT_PIN, HIGH);
            log_seismic_event();
            gpioDelay(ALERT_DURATION);
            gpioWrite(ALERT_PIN, LOW);
            sensor1_high_time = 0;
            sensor2_high_time = 0;
        }
    }
}

