        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0 ||
