        gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-up/down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioCallback(piCallbackBothEdges, SENSOR1_PIN, sensor_callback) < 0 ||
        gpioCallback(piCallbackBothEdges, SENSOR2_PIN, sensor_callback) < 0) {
        fprintf(stderr, "Failed to register callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        gpioSleep(100); // Sleep for 100 milliseconds
    }

    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(ALERT_PIN, LOW);
    gpioTerminate();
    return 0;
}

