#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <pthread.h>

#define SPI_CHANNEL 0
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define CE_PIN 8
#define LED_PIN 17
#define BUFFER_SIZE 100
#define THRESHOLD_DEG_PER_SEC 20.0
#define GYRO_SENSITIVITY 200.0

typedef struct {
    double timestamp;
    int16_t rate_x;
} GyroData;

typedef struct {
    GyroData buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t lock;
} CircularBuffer;

CircularBuffer gyroBuffer;
volatile sig_atomic_t keepRunning = 1;

void signalHandler(int signal) {
    keepRunning = 0;
}

int16_t readGyroX(int pi) {
    uint8_t address = 0x02 | 0x80; // Set MSB for read
    uint8_t data[3] = {0};

    if (gpioSPIDataRW(pi, SPI_CHANNEL, address, 1, data, 2) < 0) {
        fprintf(stderr, "SPI read error\n");
        return 0;
    }

    int16_t rate_x = (data[0] << 8) | data[1];
    if (rate_x & 0x8000) { // Convert two's complement
        rate_x |= 0xFFFF0000;
    }
    return rate_x;
}

void* gyroReader(void* arg) {
    int pi = *(int*)arg;
    double timestamp;
    int16_t rate_x;
    double rate_x_deg_per_sec;
    int led_state = 0;

    while (keepRunning) {
        rate_x = readGyroX(pi);
        rate_x_deg_per_sec = rate_x / GYRO_SENSITIVITY;

        clock_gettime(CLOCK_MONOTONIC, (struct timespec*)&timestamp);

        pthread_mutex_lock(&gyroBuffer.lock);
        gyroBuffer.buffer[gyroBuffer.head].timestamp = timestamp;
        gyroBuffer.buffer[gyroBuffer.head].rate_x = rate_x;
        gyroBuffer.head = (gyroBuffer.head + 1) % BUFFER_SIZE;
        if (gyroBuffer.count < BUFFER_SIZE) {
            gyroBuffer.count++;
        } else {
            gyroBuffer.head = (gyroBuffer.head + 1) % BUFFER_SIZE;
        }
        pthread_mutex_unlock(&gyroBuffer.lock);

        if (fabs(rate_x_deg_per_sec) > THRESHOLD_DEG_PER_SEC) {
            if (!led_state) {
                gpioWrite(pi, LED_PIN, 1);
                led_state = 1;
            }
        } else {
            if (led_state) {
                gpioWrite(pi, LED_PIN, 0);
                led_state = 0;
            }
        }

        usleep(10000); // 10 ms delay
    }

    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    if (gpioSetMode(CE_PIN, PI_OUTPUT) < 0 || gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSPISetup(SPI_CHANNEL, SPI_SPEED_HZ, SPI_MODE) < 0) {
        fprintf(stderr, "SPI setup failed\n");
        gpioTerminate();
        return 1;
    }

    pthread_mutex_init(&gyroBuffer.lock, NULL);
    gyroBuffer.head = 0;
    gyroBuffer.count = 0;

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    pthread_t readerThread;
    int pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Pigpio initialization failed\n");
        gpioTerminate();
        return 1;
    }

    if (pthread_create(&readerThread, NULL, gyroReader, &pi) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        gpioTerminate();
        return 1;
    }

    pthread_join(readerThread, NULL);

    gpioSPIClose(pi);
    gpioTerminate();

    return 0;
}

