#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define PWM_FREQUENCY 100
#define PWM_RANGE 255

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void cleanup(int gpio17, int gpio18, int gpio27) {
    gpioPWM(gpio17, 0);
    gpioPWM(gpio18, 0);
    gpioPWM(gpio27, 0);
    gpioTerminate();
    printf("Cleanup complete. All lamps turned off.\n");
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_in_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int fade_duration = atoi(argv[1]);
    if (fade_duration < 1 || fade_duration > 3600) {
        fprintf(stderr, "Fade duration must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int gpio17 = GPIO17;
    int gpio18 = GPIO18;
    int gpio27 = GPIO27;

    if (gpioSetMode(gpio17, PI_OUTPUT) < 0 ||
        gpioSetMode(gpio18, PI_OUTPUT) < 0 ||
        gpioSetMode(gpio27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes.\n");
        cleanup(gpio17, gpio18, gpio27);
        return EXIT_FAILURE;
    }

    if (gpioPWMrange(gpio17, PWM_RANGE) < 0 ||
        gpioPWMrange(gpio18, PWM_RANGE) < 0 ||
        gpioPWMrange(gpio27, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range.\n");
        cleanup(gpio17, gpio18, gpio27);
        return EXIT_FAILURE;
    }

