            return EXIT_FAILURE;
        }

        if (gpiod_line_request_output(lines[i], line_names[i], line_flags[i]) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for %s\n", line_names[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        // Red
        gpiod_line_set_value(lines[RED_PIN], 0);
        gpiod_line_set_value(lines[YELLOW_PIN], 1);
        gpiod_line_set_value(lines[GREEN_PIN], 1);
        gpiod_line_set_value(lines[BLUE_PIN], 1);
