        sleep(10);

        // Red + Yellow
        gpiod_line_set_value(lines[RED_PIN], 0);
        gpiod_line_set_value(lines[YELLOW_PIN], 0);
        printf("State: Red + Yellow\n");
        sleep(2);

        // Green
        gpiod_line_set_value(lines[RED_PIN], 1);
        gpiod_line_set_value(lines[YELLOW_PIN], 1);
        gpiod_line_set_value(lines[GREEN_PIN], 0);
        gpiod_line_set_value(lines[BLUE_PIN], 1);
        printf("State: Green\n");
        sleep(10);

        // Yellow
        gpiod_line_set_value(lines[RED_PIN], 1);
        gpiod_line_set_value(lines[YELLOW_PIN], 0);
        gpiod_line_set_value(lines[GREEN_PIN], 1);
        gpiod_line_set_value(lines[BLUE_PIN], 1);
        printf("State: Yellow\n");
        sleep(3);
    }

    // Release resources
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

