#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define LOG_FILE "touch_relay.log"

volatile sig_atomic_t keep_running = 1;

void log_error(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log, "[%s] %s\n", timestamp, message);
        fclose(log);
    }
}

void handle_signal(int sig) {
    keep_running = 0;
}

void configure_mpr121(int i2c_handle) {
    if (i2c_write_byte_data(i2c_handle, I2C_ADDR, 0x80, 0x63) != 0 ||
        i2c_write_byte_data(i2c_handle, I2C_ADDR, 0x5E, 0x00) != 0 ||
        i2c_write_byte_data(i2c_handle, I2C_ADDR, 0x5D, 0x01) != 0 ||
        i2c_write_byte_data(i2c_handle, I2C_ADDR, 0x41, 0x0A) != 0 ||
        i2c_write_byte_data(i2c_handle, I2C_ADDR, 0x42, 0x08) != 0 ||
        i2c_write_byte_data(i2c_handle, I2C_ADDR, 0x5B, 0x21) != 0 ||
        i2c_write_byte_data(i2c_handle, I2C_ADDR, 0x5C, 0x0D) != 0 ||
        i2c_write_byte_data(i2c_handle, I2C_ADDR, 0x5E, 0x0D) != 0) {
        log_error("Failed to configure MPR121");
        exit(EXIT_FAILURE);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, PI_LOW) != 0) {
        log_error("Failed to set relay GPIO to LOW");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    configure_mpr121(i2c_handle);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int relay_state = 0;
    int last_touch_state = 0;
    int touch_state = 0;
    int debounce_counter = 0;

    while (keep_running) {
        int lsb = i2c_read_byte_data(i2c_handle, I2C_ADDR, 0x00);
        int msb = i2c_read_byte_data(i2c_handle, I2C_ADDR, 0x01);

        if (lsb < 0 || msb < 0) {
            log_error("Failed to read touch status");
            break;
        }

        touch_state = (msb << 8) | lsb;
        int current_touch = touch_state & 0x01;

        if (current_touch != last_touch_state) {
            debounce_counter = 0;
        } else if (debounce_counter < 10) {
            debounce_counter++;
        }

        if (debounce_counter == 10) {
            if (current_touch && !last_touch_state) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state ? PI_HIGH : PI_LOW) != 0) {
                    log_error("Failed to toggle relay GPIO");
                }
            }
        }

        last_touch_state = current_touch;
        usleep(10000); // 10 ms delay
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

