#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define DEBOUNCE_INTERVAL_MS 50
#define DEBOUNCE_READS 3

static int flame_fd, buzzer_fd, led_fd, log_fd;
static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *message) {
    if (log_fd < 0) {
        fprintf(stderr, "Log file not open\n");
        return;
    }
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
    dprintf(log_fd, "[%s] %s\n", timestamp, message);
}

void cleanup() {
    if (flame_fd >= 0) {
        gpiod_line_release(flame_fd);
    }
    if (buzzer_fd >= 0) {
        gpiod_line_release(buzzer_fd);
    }
    if (led_fd >= 0) {
        gpiod_line_release(led_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
}

int main() {
    struct gpiod_line *flame_line, *buzzer_line, *led_line;
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("Failed to get flame sensor line");
        cleanup();
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(flame_line);
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(flame_line, "flame_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (ret < 0) {
        perror("Failed to request flame sensor line as input");
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret < 0) {
        perror("Failed to request buzzer line as output");
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        cleanup();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        cleanup();
        return EXIT_FAILURE;
    }

    flame_fd = gpiod_line_get_fd(flame_line);
    buzzer_fd = gpiod_line_get_fd(buzzer_line);
    led_fd = gpiod_line_get_fd(led_line);

    log_fd = open("flame_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int flame_detected = 0;
        for (int i = 0; i < DEBOUNCE_READS; i++) {
            int value;
            ret = read(flame_fd, &value, sizeof(value));
            if (ret < 0) {
                perror("Failed to read flame sensor value");
                cleanup();
                return EXIT_FAILURE;
            }
            if (value == 0) { // Active low
                flame_detected++;
            }
            usleep(DEBOUNCE_INTERVAL_MS * 1000);
        }

        if (flame_detected == DEBOUNCE_READS) {
            if (gpiod_line_set_value(buzzer_fd, 1) < 0) {
                perror("Failed to activate buzzer");
            }
            if (gpiod_line_set_value(led_fd, 1) < 0) {
                perror("Failed to activate LED");
            }
            log_event("Flame Detected");
        } else {
            if (gpiod_line_set_value(buzzer_fd, 0) < 0) {
                perror("Failed to deactivate buzzer");
            }
            if (gpiod_line_set_value(led_fd, 0) < 0) {
                perror("Failed to deactivate LED");
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}
