#define GPIO_SOLENOID1 17
#define GPIO_SOLENOID2 27
#define DISPENSE_DURATION_MS 1000
#define DISPENSE_INTERVAL_MS 5000

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    keep_running = 0;
}

int log_dispense_event(const char *solenoid1, const char *solenoid2, int duration) {
    FILE *log_file = fopen("dispense_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "[%s] Solenoid1: %s, Solenoid2: %s, Duration: %d ms\n",
            timestamp, solenoid1, solenoid2, duration);

    fclose(log_file);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    signal(SIGINT, sigint_handler);

    if (gpioSetMode(GPIO_SOLENOID1, PI_OUTPUT) < 0 || gpioSetMode(GPIO_SOLENOID2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return -1;
    }

    while (keep_running) {
        // Activate solenoid 1
        gpioWrite(GPIO_SOLENOID1, PI_HIGH);
        gpioDelay((DISPENSE_DURATION_MS / 2) * 1000);

        // Activate solenoid 2
        gpioWrite(GPIO_SOLENOID1, PI_LOW);
        gpioWrite(GPIO_SOLENOID2, PI_HIGH);
        gpioDelay((DISPENSE_DURATION_MS / 2) * 1000);

        // Deactivate both solenoids
        gpioWrite(GPIO_SOLENOID2, PI_LOW);

        // Log the dispense event
        if (log_dispense_event("ON", "ON", DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Failed to log dispense event\n");
        }

        // Wait for the next cycle
        gpioDelay(DISPENSE_INTERVAL_MS * 1000);
    }

    // Cleanup
    gpioWrite(GPIO_SOLENOID1, PI_LOW);
    gpioWrite(GPIO_SOLENOID2, PI_LOW);
    gpioTerminate();

    return 0;
}

