#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25
#define LOG_FILE "balance_log.txt"

volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        exit(1);
    }
    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}

void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
}

void set_motor_speed(int forward_pin, int backward_pin, int speed) {
    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(forward_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(backward_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    float Kp = 1.0, Ki = 0.01, Kd = 0.1;
    float prev_error = 0.0, integral = 0.0;
    time_t rawtime;
    struct tm *timeinfo;

    while (!stop) {
        float tilt_error = ((float)rand() / RAND_MAX) * 20.0 - 10.0;
        float distance = ((float)rand() / RAND_MAX) * 398.0 + 2.0;

        integral += tilt_error;
        float derivative = tilt_error - prev_error;
        float output = Kp * tilt_error + Ki * integral + Kd * derivative;
        prev_error = tilt_error;

        int motor_a_speed = (int)output;
        int motor_b_speed = (int)output;

        if (distance < 20.0) {
            motor_a_speed = -127;
            motor_b_speed = -127;
        }

        motor_a_speed = motor_a_speed > 255 ? 255 : (motor_a_speed < -255 ? -255 : motor_a_speed);
        motor_b_speed = motor_b_speed > 255 ? 255 : (motor_b_speed < -255 ? -255 : motor_b_speed);

        set_motor_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, motor_a_speed);
        set_motor_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, motor_b_speed);

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "%s, %.2f, %.2f, %d, %d",
                 timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);

        log_message(log_entry);

        gpioDelay(50);
    }

    stop_motors();
    gpioTerminate();
    return 0;
}

