#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_SENSOR_PIN 4
#define DEBOUNCE_DELAY 50 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up signal handling for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handling\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0 ||
        gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure GPIO pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch_state = 0;
    int current_touch_state = 0;

    while (keep_running) {
        current_touch_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_touch_state != last_touch_state) {
            if (current_touch_state == 1) {
                usleep(DEBOUNCE_DELAY * 1000); // Debounce delay
                current_touch_state = gpioRead(TOUCH_SENSOR_PIN);
                if (current_touch_state == 1) {
                    relay_state = !relay_state;
                    gpioWrite(RELAY_PIN, relay_state);
                }
            }
            last_touch_state = current_touch_state;
        }

        usleep(10000); // Polling delay
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

