#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27
#define PWM_FREQUENCY 1000
#define SAMPLE_RATE 8000
#define SAMPLE_SIZE 1024
#define DEFAULT_SENSITIVITY 1.0

static volatile sig_atomic_t keep_running = 1;
static double sensitivity = DEFAULT_SENSITIVITY;

void handle_signal(int sig) {
    keep_running = 0;
}

double compute_rms(const short *samples, int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / num_samples);
}

void map_amplitude_to_color(double amplitude, int *red, int *green, int *blue) {
    double normalized = amplitude / sensitivity;
    if (normalized < 0.5) {
        *red = 0;
        *green = (int)(255 * (2 * normalized));
        *blue = (int)(255 * (1 - 2 * normalized));
    } else {
        *red = (int)(255 * (2 * (normalized - 0.5)));
        *green = (int)(255 * (1 - 2 * (normalized - 0.5)));
        *blue = 0;
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO_RED, PI_OUTPUT);
    gpioSetMode(GPIO_GREEN, PI_OUTPUT);
    gpioSetMode(GPIO_BLUE, PI_OUTPUT);
    gpioPWM(GPIO_RED, 0);
    gpioPWM(GPIO_GREEN, 0);
    gpioPWM(GPIO_BLUE, 0);
}

void cleanup_gpio() {
    gpioPWM(GPIO_RED, 0);
    gpioPWM(GPIO_GREEN, 0);
    gpioPWM(GPIO_BLUE, 0);
    gpioTerminate();
}

#ifdef ALSA_AVAILABLE
void setup_alsa(snd_pcm_t **capture_handle) {
    int err;
    snd_pcm_hw_params_t *hw_params;
    snd_pcm_uframes_t frames;

    if ((err = snd_pcm_open(capture_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Failed to open ALSA capture device: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_malloc(&hw_params)) < 0) {
        fprintf(stderr, "Failed to allocate hardware parameters: %s\n", snd_strerror(err));
