#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define POWER_ON_RGBC_ENABLE 0x03
#define INTEGRATION_TIME 0xD5
#define CLEAR_LOW 0x14
#define CLEAR_HIGH 0x15
#define RED_LOW 0x16
#define RED_HIGH 0x17
#define GREEN_LOW 0x18
#define GREEN_HIGH 0x19
#define BLUE_LOW 0x1A
#define BLUE_HIGH 0x1B

static int i2c_handle = -1;
static FILE *file = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

void write_i2c_byte(int reg, uint8_t value) {
    if (i2c_write_byte_data(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X\n", reg);
    }
}

void read_i2c_bytes(int reg, uint8_t *buffer, int length) {
    if (i2c_read_i2c_block_data(i2c_handle, reg, length, buffer) < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X\n", reg);
        for (int i = 0; i < length; i++) {
            buffer[i] = 0;
        }
    }
}

void initialize_sensor() {
    write_i2c_byte(0x80, POWER_ON_RGBC_ENABLE);
    write_i2c_byte(0x81, INTEGRATION_TIME);
}

void log_data(int clear, int red, int green, int blue) {
    time_t now = time(NULL);
    fprintf(file, "%ld,%d,%d,%d,%d\n", now, clear, red, green, blue);
    fflush(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    file = fopen("color_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(file, "timestamp,clear,red,green,blue\n");
    fflush(file);

    initialize_sensor();

    while (keep_running) {
        uint8_t buffer[8];
        read_i2c_bytes(CLEAR_LOW, buffer, 8);

        int clear = (buffer[1] << 8) | buffer[0];
        int red = (buffer[3] << 8) | buffer[2];
        int green = (buffer[5] << 8) | buffer[4];
        int blue = (buffer[7] << 8) | buffer[6];

        log_data(clear, red, green, blue);

        gpioDelay(500000); // 500 ms delay
    }

    if (file) {
        fclose(file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

