#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 51840

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];
static int relay_pins[NUM_RELAYS] = {17, 27, 22, 23};
static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

void setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_line_get(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", relay_pins[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(lines[i], "relay", GPIOD_LINE_REQUEST_DIRECTIONS_BOTH) < 0) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", relay_pins[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpio() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], 1); // Turn off relay (active-low)
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

void simulate_phase(int duration, int start_duty, int end_duty, int step) {
    int duty = start_duty;
    int step_duration = duration / (abs(end_duty - start_duty) / step);

    while (duration > 0 && !stop) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], duty == 0 ? 1 : 0);
        }

        usleep(step_duration * 1000); // Convert to microseconds

        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], duty == 0 ? 1 : 0);
        }

        usleep(step_duration * 1000); // Convert to microseconds

        duration -= 2 * step_duration / 1000000; // Convert to seconds
        duty += (end_duty - start_duty) / (abs(end_duty - start_duty) / step);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (!stop) {
        simulate_phase(SUNRISE_DURATION, 0, 100, 1);
        simulate_phase(DAYTIME_DURATION, 100, 100, 0);
        simulate_phase(SUNSET_DURATION, 100, 0, 1);
        simulate_phase(NIGHTTIME_DURATION, 0, 0, 0);
    }

    cleanup_gpio();
    return 0;
}

