#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG 0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43
#define SAMPLE_RATE_DIVIDER 0x07
#define GYRO_FULL_SCALE_RANGE 0x00
#define GYRO_SENSITIVITY 131.0
#define I2C_BUS 1
#define LOG_FILE "gyro_log.csv"

volatile sig_atomic_t keep_running = 1;
FILE *log_file = NULL;
int i2c_handle = -1;

void signal_handler(int signum) {
    keep_running = 0;
}

void init_sensor() {
    if (i2cWriteByteData(i2c_handle, MPU6050_ADDRESS, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6050\n");
        return;
    }
    if (i2cWriteByteData(i2c_handle, MPU6050_ADDRESS, MPU6050_SMPLRT_DIV, SAMPLE_RATE_DIVIDER) < 0) {
        fprintf(stderr, "Failed to set sample rate divider\n");
        return;
    }
    if (i2cWriteByteData(i2c_handle, MPU6050_ADDRESS, MPU6050_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set DLPF configuration\n");
        return;
    }
    if (i2cWriteByteData(i2c_handle, MPU6050_ADDRESS, MPU6050_GYRO_CONFIG, GYRO_FULL_SCALE_RANGE) < 0) {
        fprintf(stderr, "Failed to set gyroscope full-scale range\n");
        return;
    }
}

int read_gyro(int *x, int *y, int *z) {
    unsigned char data[6];
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_ADDRESS, MPU6050_GYRO_XOUT_H, data, 6) < 0) {
        return -1;
    }
    *x = (data[0] << 8) | data[1];
    *y = (data[2] << 8) | data[3];
    *z = (data[4] << 8) | data[5];
    return 0;
}

void log_data(int x, int y, int z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;
    fprintf(log_file, "%f,%f,%f,%f\n", timestamp, x / GYRO_SENSITIVITY, y / GYRO_SENSITIVITY, z / GYRO_SENSITIVITY);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    init_sensor();

    while (keep_running) {
        int x, y, z;
        int retries = 3;
        while (retries-- > 0) {
            if (read_gyro(&x, &y, &z) == 0) {
                log_data(x, y, z);
                break;
            }
            init_sensor();
        }
        if (retries < 0) {
            fprintf(stderr, "Failed to read gyroscope data after 3 attempts\n");
        }
        usleep(10000); // 10 ms interval
    }

    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

