#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_PIN_1 4
#define RELAY_PIN_2 17
#define RELAY_PIN_3 27
#define RELAY_PIN_4 22

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"

int relay_pins[NUM_RELAYS] = {RELAY_PIN_1, RELAY_PIN_2, RELAY_PIN_3, RELAY_PIN_4};
int pi;
FILE *log_file;

void cleanup(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (pi >= 0) {
        gpioTerminate(pi);
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1); // Deactivate all relays
    }
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    pi = gpioInitialise();

    if (signal(SIGINT, cleanup) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler\n");
        cleanup(1);
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(1);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode for pin %d\n", relay_pins[i]);
            cleanup(1);
        }
        if (gpioWrite(relay_pins[i], 1) < 0) { // Ensure all relays are deactivated initially
            fprintf(stderr, "Failed to write to GPIO pin %d\n", relay_pins[i]);
            cleanup(1);
        }
    }

    srand(time(NULL));

    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            int moisture_level = rand() % 101;
            int relay_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;

            if (gpioWrite(relay_pins[i], relay_state) < 0) {
                fprintf(stderr, "Failed to write to GPIO pin %d\n", relay_pins[i]);
                cleanup(1);
            }

            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "Time: %s, Zone: %d, Moisture: %d, Relay State: %d\n",
                    time_str, i + 1, moisture_level, relay_state);
            fflush(log_file);
        }

        sleep(5);
    }

    cleanup(0);
    return 0;
}

