#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define ADXL345_I2C_ADDR 0x53
#define DATA_FORMAT_REG 0x31
#define POWER_CTL_REG   0x2D
#define DATAX0_REG      0x32
#define FREEFALL_THRESHOLD 0.2
#define SCALE_FACTOR 256.0
#define GPIO_PIN 27
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define FREEFALL_DURATION 500000 // 0.5 seconds in microseconds
#define ALARM_DURATION 5000000 // 5 seconds in microseconds

volatile sig_atomic_t keep_running = 1;

void sigint_handler(int sig) {
    keep_running = 0;
}

void log_freefall_event(double x, double y, double z) {
    FILE *log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (gpioI2CSetup(1, ADXL345_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWriteReg8(1, DATA_FORMAT_REG, 0x0B) < 0) {
        fprintf(stderr, "Failed to write to DATA_FORMAT register\n");
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWriteReg8(1, POWER_CTL_REG, 0x08) < 0) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(GPIO_PIN, PI_LOW);

    while (keep_running) {
