#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400
#define MAX_PULSE_WIDTH_US 23200
#define TIMEOUT_US 100000
#define TRIGGER_INTERVAL_MS 200

static volatile unsigned long start_tick = 0;
static volatile unsigned long end_tick = 0;
static volatile int valid_measurement = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static int pigpio_initialized = 0;

void handle_sigint(int sig) {
    if (pigpio_initialized) {
        gpioCancel(ECHO_PIN);
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&mutex);
    exit(0);
}

void rising_edge_callback(int gpio, unsigned level, uint32_t tick) {
    if (gpio == ECHO_PIN && level == 1) {
        pthread_mutex_lock(&mutex);
        start_tick = tick;
        valid_measurement = 1;
        pthread_mutex_unlock(&mutex);
    }
}

void falling_edge_callback(int gpio, unsigned level, uint32_t tick) {
    if (gpio == ECHO_PIN && level == 0) {
        pthread_mutex_lock(&mutex);
        end_tick = tick;
        pthread_mutex_unlock(&mutex);
    }
}

void measure_distance() {
    gpioTrigger(TRIG_PIN, 0, 10);
    usleep(TRIGGER_INTERVAL_MS * 1000);
}

void log_distance(unsigned long pulse_width_us) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    double distance_cm = pulse_width_us * 0.0343 / 2.0;

    pthread_mutex_lock(&mutex);
    if (valid_measurement && pulse_width_us <= MAX_PULSE_WIDTH_US) {
        fprintf(log_file, "%lld,%f\n", timestamp_ns, distance_cm);
        fflush(log_file);
    }
    valid_measurement = 0;
    pthread_mutex_unlock(&mutex);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioCallback(ECHO_PIN, EITHER_EDGE, rising_edge_callback) < 0 ||
        gpioCallback(ECHO_PIN, EITHER_EDGE, falling_edge_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO callbacks\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        measure_distance();

        unsigned long pulse_width_us = 0;
        pthread_mutex_lock(&mutex);
        if (valid_measurement) {
            if (end_tick >= start_tick) {
                pulse_width_us = (end_tick - start_tick) * gpioTickPerUs();
            } else {
                pulse_width_us = ((0xFFFFFFFF - start_tick) + end_tick + 1) * gpioTickPerUs();
            }
        }
        pthread_mutex_unlock(&mutex);

        if (pulse_width_us > TIMEOUT_US) {
            valid_measurement = 0;
        } else {
            log_distance(pulse_width_us);
        }
    }

    return 0;
}

