#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define Buzzer_GPIO 17

#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int read_i2c_word(int pi, int addr, int reg, int *value) {
    int retries = 3;
    while (retries--) {
        if (i2c_read_i2c_block_data(pi, addr, reg, 2, (unsigned char *)value) == 2) {
            *value = ((*value) << 8) | (*(value + 1));
            return 0;
        }
        usleep(1000); // Wait 1ms before retrying
    }
    return -1;
}

int write_i2c_byte(int pi, int addr, int reg, int value) {
    return i2c_write_i2c_block_data(pi, addr, reg, 1, (unsigned char *)&value);
}

int main(int argc, char *argv[]) {
    int pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        pigpio_stop(pi);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (write_i2c_byte(pi, I2C_ADDR, CTRL_REG1, 0x77) < 0 ||
        write_i2c_byte(pi, I2C_ADDR, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to configure LIS3DH\n");
        gpioTerminate();
        pigpio_stop(pi);
        return 1;
    }

    double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    double impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    int buzzer_state = 0;
    int x, y, z;
    double magnitude;

    while (keep_running) {
        int x_raw, y_raw, z_raw;

        if (read_i2c_word(pi, I2C_ADDR, OUT_X_L, &x_raw) < 0 ||
            read_i2c_word(pi, I2C_ADDR, OUT_X_L + 2, &y_raw) < 0 ||
            read_i2c_word(pi, I2C_ADDR, OUT_X_L + 4, &z_raw) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            break;
        }

        x = x_raw;
        y = y_raw;
        z = z_raw;

        magnitude = sqrt(x * x + y * y + z * z) / 16384.0;

        if (magnitude < freefall_threshold) {
            printf("Freefall detected: %f g\n", magnitude);
        } else if (magnitude > impact_threshold) {
            printf("Impact detected: %f g\n", magnitude);
            if (!buzzer_state) {
                gpioSetMode(Buzzer_GPIO, PI_OUTPUT);
                gpioWrite(Buzzer_GPIO, 1);
                buzzer_state = 1;
            }
        } else {
            if (buzzer_state) {
                gpioWrite(Buzzer_GPIO, 0);
                buzzer_state = 0;
            }
        }

        usleep(10000); // 10ms delay for 100Hz data rate
    }

    if (buzzer_state) {
        gpioWrite(Buzzer_GPIO, 0);
    }

    gpioTerminate();
    pigpio_stop(pi);
    return 0;
}

