#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_Y_L 0x2A
#define OUT_Z_L 0x2C

static int i2c_handle = -1;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;

void cleanup_and_exit(int status) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(status);
}

void signal_handler(int sig) {
    cleanup_and_exit(0);
}

void log_high_acceleration(float x, float y, float z) {
    FILE *log_file = fopen("/var/log/high_acceleration.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] High acceleration detected: X=%.4f, Y=%.4f, Z=%.4f\n", timestamp, x, y, z);
        fclose(log_file);
    }
    system("sudo shutdown -h now");
}

int read_acceleration(int *x, int *y, int *z) {
    int data[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, data, 6) != 6) {
        return -1;
    }
    *x = (data[1] << 8) | data[0];
    *y = (data[3] << 8) | data[2];
    *z = (data[5] << 8) | data[4];
    return 0;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X\n", i2c_address);
                    cleanup_and_exit(1);
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold: %f\n", threshold);
                    cleanup_and_exit(1);
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a hex_address] [-t threshold]\n", argv[0]);
                cleanup_and_exit(1);
        }
    }

    i2c_handle = i2cOpen(1, i2c_address);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        cleanup_and_exit(1);
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) != 0 ||
        i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) != 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        cleanup_and_exit(1);
    }

    while (1) {
        int x_raw, y_raw, z_raw;
        if (read_acceleration(&x_raw, &y_raw, &z_raw) == 0) {
            float x = (x_raw >> 4) * 0.0009765625;
            float y = (y_raw >> 4) * 0.0009765625;
            float z = (z_raw >> 4) * 0.0009765625;

            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                log_high_acceleration(x, y, z);
            }
        }
        usleep(100000); // 100 ms
    }

    cleanup_and_exit(0);
}

