#include <stdbool.h>

#define LEFT_PIN 4
#define CENTER_PIN 17
#define RIGHT_PIN 27
#define ALERT_PIN 22
#define POLL_INTERVAL 10 // milliseconds
#define BUFFER_SIZE 5
#define ALERT_THRESHOLD 5
#define ALERT_DURATION 2 // seconds

static volatile bool running = true;
static gpiod_chip *chip;
static gpiod_line *left_line, *center_line, *right_line, *alert_line;
static int center_no_line_count = 0;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;

void handle_signal(int sig) {
    running = false;
}

void log_reading(int left, int center, int right) {
    buffer[buffer_index] = (left << 2) | (center << 1) | right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

void check_alert_condition() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if ((buffer[i] & 0x02) == 0) { // Check if center is 'no line'
            center_no_line_count++;
        } else {
            center_no_line_count = 0;
        }
    }

    if (center_no_line_count >= ALERT_THRESHOLD) {
        gpiod_line_request_set_value(alert_line, 1);
        sleep(ALERT_DURATION);
        gpiod_line_request_set_value(alert_line, 0);
        center_no_line_count = 0;
    }
}

void line_following_logic(int left, int center, int right) {
    if (center == 0) {
        // Move forward
        printf("Moving forward\n");
    } else if (left == 0) {
        // Turn left
        printf("Turning left\n");
    } else if (right == 0) {
        // Turn right
        printf("Turning right\n");
    } else {
        // Stop
        printf("Stopping\n");
    }
}

void cleanup() {
    if (left_line) gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line) gpiod_line_release(right_line);
    if (alert_line) gpiod_line_release(alert_line);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);

    if (!left_line || !center_line || !right_line || !alert_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(left_line, "left_sensor", GPIOD_LINE_REQ_EV_NONE) < 0 ||
        gpiod_line_request_input(center_line, "center_sensor", GPIOD_LINE_REQ_EV_NONE) < 0 ||
        gpiod_line_request_input(right_line, "right_sensor", GPIOD_LINE_REQ_EV_NONE) < 0 ||
        gpiod_line_request_output(alert_line, "alert", 0, GPIOD_LINE_REQ_DIRECTIONS_NONE) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int left = gpiod_line_get_value(left_line);
        int center = gpiod_line_get_value(center_line);
        int right = gpiod_line_get_value(right_line);

        log_reading(left, center, right);
        check_alert_condition();
        line_following_logic(left, center, right);

        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

