#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD 500  // 5.0 mT * 100
#define POLL_ATTEMPTS 50
#define SAMPLE_INTERVAL 100  // 100 ms

volatile sig_atomic_t keep_running = 1;

void log_event(const char *event) {
    FILE *file = fopen("magnetic_events.txt", "a");
    if (file) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(file, "[%s] %s\n", timestamp, event);
        fclose(file);
    }
}

void sigint_handler(int sig) {
    keep_running = 0;
    log_event("SIGINT received, shutting down.");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode.\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        log_event("Failed to open I2C bus.");
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        if (i2cWriteByteData(i2c_handle, 0xC1, 0x01) < 0) {
            fprintf(stderr, "Failed to start conversion: %s\n", strerror(errno));
            log_event("Failed to start conversion.");
            gpioWrite(RELAY_GPIO, PI_LOW);
            continue;
        }

        int attempts = 0;
        while (attempts < POLL_ATTEMPTS) {
            int status = i2cReadByteData(i2c_handle, 0xC1);
            if (status < 0) {
                fprintf(stderr, "Failed to read status: %s\n", strerror(errno));
                log_event("Failed to read status.");
                gpioWrite(RELAY_GPIO, PI_LOW);
                break;
            }

            if (status == 0x00) {
                break;
            }
            attempts++;
        }

        if (attempts == POLL_ATTEMPTS) {
            fprintf(stderr, "Timeout waiting for conversion.\n");
            log_event("Timeout waiting for conversion.");
            gpioWrite(RELAY_GPIO, PI_LOW);
            continue;
        }

        int lsb = i2cReadByteData(i2c_handle, 0xC0);
        if (lsb < 0) {
            fprintf(stderr, "Failed to read LSB: %s\n", strerror(errno));
            log_event("Failed to read LSB.");
            gpioWrite(RELAY_GPIO, PI_LOW);
            continue;
        }

        int msb = i2cReadByteData(i2c_handle, 0xC1);
        if (msb < 0) {
            fprintf(stderr, "Failed to read MSB: %s\n", strerror(errno));
            log_event("Failed to read MSB.");
            gpioWrite(RELAY_GPIO, PI_LOW);
            continue;
        }

        int16_t field_raw = (msb << 8) | lsb;
        int field_mT_x100 = field_raw * 25 / 1000;

        char event[100];
        snprintf(event, sizeof(event), "Field reading: %d mT", field_mT_x100 / 100);
        log_event(event);

        if (field_mT_x100 > FIELD_THRESHOLD) {
            gpioWrite(RELAY_GPIO, PI_HIGH);
            log_event("Relay activated.");
        } else {
            gpioWrite(RELAY_GPIO, PI_LOW);
