#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 256

int server_fd, client_fd;
FILE *log_file;
volatile sig_atomic_t keep_running = 1;

void log_event(const char *event) {
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fflush(log_file);
    }
}

void handle_signal(int sig) {
    keep_running = 0;
}

void cleanup() {
    if (client_fd != -1) {
        close(client_fd);
    }
    if (server_fd != -1) {
        close(server_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        cleanup();
        return EXIT_FAILURE;
    }

    // Bind socket
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return EXIT_FAILURE;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            if (errno == EINTR) {
                continue; // Interrupted by signal
            }
            perror("accept failed");
            break;
        }

        char buffer[BUFFER_SIZE] = {0};
        ssize_t bytes_read = read(client_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read < 0) {
            perror("read failed");
        } else {
            buffer[bytes_read] = '\0';
            char *command = strtok(buffer, " \t\n");
            if (command) {
                if (strcasecmp(command, "ON") == 0) {
                    gpioWrite(GPIO_PIN, 1);
                    log_event("Relay turned ON");
                } else if (strcasecmp(command, "OFF") == 0) {
                    gpioWrite(GPIO_PIN, 0);
                    log_event("Relay turned OFF");
                } else {
                    log_event("Invalid command received");
                }
            }
        }
        close(client_fd);
    }

    cleanup();
    return EXIT_SUCCESS;
}

