#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define GPIO_RELAY 18
#define POLL_INTERVAL_MS 100
#define SCALE_FACTOR 1.0 / 1500.0
#define FLOW_THRESHOLD 5.0

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int sig) {
    stop_flag = 1;
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_RELAY, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO relay\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c1 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c2 < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 2\n");
        i2cClose(i2c1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t start_cmd[] = {0x36, 0x08};
    if (i2cWrite(i2c1, start_cmd, 2) != 0 || i2cWrite(i2c2, start_cmd, 2) != 0) {
        fprintf(stderr, "Failed to send start command to sensors\n");
        i2cClose(i2c1);
        i2cClose(i2c2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c1);
        i2cClose(i2c2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        uint8_t data1[3], data2[3];
        if (i2cRead(i2c1, data1, 3) == 3 && crc8(data1, 2) == data1[2]) {
            int16_t raw1 = (data1[0] << 8) | data1[1];
            double flow1 = raw1 * SCALE_FACTOR;
            if (fprintf(log_file, "%lu ms: Sensor 1: %f ml/min\n", (unsigned long)time(NULL) * 1000, flow1) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
            }
        } else {
            fprintf(stderr, "Read error or CRC mismatch on sensor 1\n");
        }

        if (i2cRead(i2c2, data2, 3) == 3 && crc8(data2, 2) == data2[2]) {
            int16_t raw2 = (data2[0] << 8) | data2[1];
            double flow2 = raw2 * SCALE_FACTOR;
            if (fprintf(log_file, "%lu ms: Sensor 2: %f ml/min\n", (unsigned long)time(NULL) * 1000, flow2) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
            }
        } else {
            fprintf(stderr, "Read error or CRC mismatch on sensor 2\n");
        }

        fflush(log_file);

        if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
            if (gpioWrite(GPIO_RELAY, 1) < 0) {
                fprintf(stderr, "Failed to energize relay\n");
            }
        } else {
            if (gpioWrite(GPIO_RELAY, 0) < 0) {
                fprintf(stderr, "Failed to de-energize relay\n");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    if (gpioWrite(GPIO_RELAY, 0) < 0) {
        fprintf(stderr, "Failed to de-energize relay on shutdown\n");
    }

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Failed to close log file\n");
    }

    if (i2cClose(i2c1) < 0) {
        fprintf(stderr, "Failed to close I2C handle for sensor 1\n");
    }

    if (i2cClose(i2c2) < 0) {
        fprintf(stderr, "Failed to close I2C handle for sensor 2\n");
    }

    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
    }

    printf("Shutdown complete\n");
    return EXIT_SUCCESS;
}

