#include <pigpio.h>
#include <signal.h>
#include <stdlib.h>
#include <unistd.h>
#include <syslog.h>
#include <stdio.h>

#define RAIN_SENSOR_PIN 17
#define ENA_PIN 22
#define IN1_PIN 23
#define IN2_PIN 24
#define POLL_INTERVAL 200000 // 200 ms in microseconds
#define MOTOR_RUN_TIME 5000000 // 5 seconds in microseconds
#define DRY_THRESHOLD 3

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_message(int priority, const char *message) {
    syslog(priority, "rain_window: %s", message);
}

int main() {
    int rain_sensor_value = 1;
    int dry_count = 0;
    int last_rain_sensor_value = 1;
    int motor_running = 0;

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialize GPIO");
        return EXIT_FAILURE;
    }

    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);
    log_message(LOG_INFO, "Startup");

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0 ||
        gpioSetMode(ENA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(IN2_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set GPIO modes or pull-up");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        rain_sensor_value = gpioRead(RAIN_SENSOR_PIN);

        if (rain_sensor_value == 0 && last_rain_sensor_value == 1) {
            if (!motor_running) {
                log_message(LOG_INFO, "Rain detected, starting motor");
                if (gpioWrite(ENA_PIN, 1) < 0 || gpioWrite(IN1_PIN, 1) < 0 || gpioWrite(IN2_PIN, 0) < 0) {
                    log_message(LOG_WARNING, "Failed to start motor");
                } else {
                    motor_running = 1;
                    gpioDelay(MOTOR_RUN_TIME);
                    if (gpioWrite(ENA_PIN, 0) < 0 || gpioWrite(IN1_PIN, 0) < 0 || gpioWrite(IN2_PIN, 0) < 0) {
                        log_message(LOG_WARNING, "Failed to stop motor");
                    } else {
                        log_message(LOG_INFO, "Motor stopped");
                    }
                    motor_running = 0;
                    dry_count = 0;
                }
            }
        } else if (rain_sensor_value == 1) {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD) {
                dry_count = 0;
            }
        } else {
            dry_count = 0;
        }

        last_rain_sensor_value = rain_sensor_value;
        gpioDelay(POLL_INTERVAL);
