    int rain_sensor_value = 1;
    int dry_count = 0;
    int last_rain_sensor_value = 1;
    int motor_running = 0;

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialize GPIO");
        return EXIT_FAILURE;
    }

