        gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0 ||
        gpioSetMode(ENA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(IN2_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set GPIO modes or pull-up");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

