#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_SENSOR_PIN 4
#define FLOODLIGHT_PIN 17
#define POLL_INTERVAL 100 // milliseconds
#define FLOODLIGHT_DURATION 60000 // milliseconds (60 seconds)

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_event(const char *event, int duration) {
    FILE *log_file = fopen("security_log.txt", "a");
    if (log_file == NULL) {
        gpioWrite(FLOODLIGHT_PIN, 0);
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    if (strcmp(event, "activation") == 0) {
        fprintf(log_file, "%s: Motion detected\n", timestamp);
    } else {
        fprintf(log_file, "%s: Floodlight turned off, duration: %d seconds\n", timestamp, duration);
    }

    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(FLOODLIGHT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set floodlight to off\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = 0;
    int current_state = 0;
    int floodlight_on = 0;
    time_t floodlight_start_time = 0;

    while (keep_running) {
        current_state = gpioRead(PIR_SENSOR_PIN);
        if (current_state != last_state && current_state == 1) {
            // Rising edge detected
            if (!floodlight_on) {
                if (gpioWrite(FLOODLIGHT_PIN, 1) < 0) {
                    fprintf(stderr, "Failed to turn on floodlight\n");
                    gpioTerminate();
                    return 1;
                }
                floodlight_on = 1;
                floodlight_start_time = time(NULL);
                log_event("activation", 0);
            }
        }

        if (floodlight_on && (time(NULL) - floodlight_start_time) * 1000 >= FLOODLIGHT_DURATION) {
            if (gpioWrite(FLOODLIGHT_PIN, 0) < 0) {
                fprintf(stderr, "Failed to turn off floodlight\n");
                gpioTerminate();
                return 1;
            }
            floodlight_on = 0;
            log_event("deactivation", (int)(time(NULL) - floodlight_start_time));
        }

        last_state = current_state;
        usleep(POLL_INTERVAL * 1000);
    }

    // Ensure floodlight is off on exit
    if (floodlight_on) {
        if (gpioWrite(FLOODLIGHT_PIN, 0) < 0) {
            fprintf(stderr, "Failed to turn off floodlight on exit\n");
        }
        log_event("deactivation", (int)(time(NULL) - floodlight_start_time));
    }

    gpioTerminate();
    return 0;
}

