#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A

#define MPR121_SOFT_RESET 0x80
#define MPR121_MHDR 0x5B
#define MPR121_NHDR 0x5C
#define MPR121_NCLR 0x5D
#define MPR121_FDL 0x5E
#define MPR121_TOUCH_STATUS 0x00
#define MPR121_ELE_CFG 0x5E
#define MPR121_FSC 0x2A
#define MPR121_TCH 0x01
#define MPR121_ELE0 0x00

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    return 0;
}

int init_i2c() {
    if (i2cOpen(I2C_BUS, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }
    return 0;
}

int mpr121_write_register(uint8_t reg, uint16_t value) {
    if (i2cWriteReg16(I2C_BUS, MPR121_ADDR, reg, value) < 0) {
        fprintf(stderr, "Failed to write to MPR121 register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int mpr121_read_register(uint8_t reg, uint16_t *value) {
    if (i2cReadReg16(I2C_BUS, MPR121_ADDR, reg, value) < 0) {
        fprintf(stderr, "Failed to read from MPR121 register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int mpr121_init() {
    if (mpr121_write_register(MPR121_SOFT_RESET, 0x63) < 0) return -1;
    usleep(10000); // Wait for reset

    if (mpr121_write_register(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_register(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_register(MPR121_FDL, 0x00) < 0) return -1;
    if (mpr121_write_register(MPR121_ELE_CFG, 0x0C) < 0) return -1;
    if (mpr121_write_register(MPR121_FSC, 0x10) < 0) return -1;

    uint16_t auto_config = 0x0C5B;
    if (mpr121_write_register(0x7B, auto_config) < 0) return -1;
    if (mpr121_write_register(0x7C, auto_config) < 0) return -1;
    if (mpr121_write_register(0x7D, auto_config) < 0) return -1;

    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio() < 0) goto cleanup;
    if (init_i2c() < 0) goto cleanup;

    if (mpr121_init() < 0) goto cleanup;

    uint16_t touch_status;
    uint16_t last_touch_status = 0;
    int relay_state = 0;

    while (keep_running) {
        if (mpr121_read_register(MPR121_TOUCH_STATUS, &touch_status) < 0) {
            fprintf(stderr, "Error reading touch status\n");
            break;
        }

        if ((touch_status & (1 << MPR121_ELE0)) && !(last_touch_status & (1 << MPR121_ELE0))) {
            relay_state = !relay_state;
            gpioWrite(RELAY_GPIO, relay_state);
            usleep(200000); // Debounce delay
        }

        last_touch_status = touch_status;
        usleep(10000); // Polling delay
    }

cleanup:
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
    i2cClose(I2C_BUS);
    return 0;
}

