#include <netinet/in.h>
#include <arpa/inet.h>

#define SERVO_GPIO 17
#define PIR_GPIO 4
#define SERVO_PWM_FREQ 50
#define SERVO_MIN_PULSE_WIDTH 1
#define SERVO_MAX_PULSE_WIDTH 2
#define TCP_PORT 5000
#define LOG_FILE "security.log"

static int servo_line = -1;
static int pir_line = -1;
static int server_socket = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t keep_running = 1;

void log_message(const char *format, ...) {
    va_list args;
    char buffer[1024];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", tm_info);

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    syslog(LOG_USER | LOG_INFO, "%s %s", time_str, buffer);
    fprintf(log_file, "%s %s\n", time_str, buffer);
    fflush(log_file);
}

void handle_signal(int sig) {
    keep_running = 0;
}

void *servo_control_thread(void *arg) {
    int pulse_width = SERVO_MIN_PULSE_WIDTH;
    while (keep_running) {
        gpiod_line_set_value(servo_line, pulse_width);
        usleep(1000000 / SERVO_PWM_FREQ);
        gpiod_line_set_value(servo_line, 0);
        usleep(1000000 / SERVO_PWM_FREQ);
    }
    return NULL;
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, SERVO_GPIO);
    if (!line) {
        log_message("Failed to get servo line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    servo_line = gpiod_line_request_output(line, "servo_control", 0);
    if (servo_line < 0) {
        log_message("Failed to request servo line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!line) {
        log_message("Failed to get PIR line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    pir_line = gpiod_line_request_input(line, "pir_sensor", GPIOD_LINE_REQ_EV_BOTH_EDGES);
    if (pir_line < 0) {
        log_message("Failed to request PIR line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_close(chip);
}

void setup_socket() {
    struct sockaddr_in server_addr;

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        log_message("Failed to create socket: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message("Failed to set socket options: %s", strerror(errno));
        close(server_socket);
        exit(EXIT_FAILURE);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(TCP_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
