            }
            log_message("Failed to accept client: %s", strerror(errno));
            break;
        }
        handle_client(client_socket);
    }

    keep_running = 0;
    pthread_join(servo_thread, NULL);
    gpiod_line_release(servo_line);
    gpiod_line_release(pir_line);
    close(server_socket);
    fclose(log_file);
    closelog();

    return 0;
}

