#define RELAY_PIN 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL 2

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
