int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return -1;
    }
    gpioWrite(RELAY_PIN, PI_LOW);
    return 0;
}

int open_i2c() {
    int i2c_handle = i2cOpen(1, BH1750_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }
    return i2c_handle;
}

int write_i2c(int i2c_handle, unsigned char command) {
    if (i2cWriteByte(i2c_handle, command) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }
    return 0;
}

int read_lux(int i2c_handle, unsigned short *lux) {
    unsigned char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }
    *lux = (data[0] << 8) | data[1];
    return 0;
}

int log_data(FILE *log_file, unsigned short lux) {
    time_t now = time(NULL);
    if (fprintf(log_file, "%s: %u lux\n", ctime(&now), lux) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() < 0) {
        goto cleanup;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    int i2c_handle = open_i2c();
    if (i2c_handle < 0) {
        goto cleanup;
    }

    while (keep_running) {
        if (write_i2c(i2c_handle, BH1750_ONE_TIME_HIGH_RES_MODE) < 0) {
            fprintf(stderr, "I2C write error, retrying...\n");
            usleep(100000); // 100 ms
            continue;
        }

        usleep(120000); // 120 ms

        unsigned short lux;
        if (read_lux(i2c_handle, &lux) < 0) {
            fprintf(stderr, "I2C read error, retrying...\n");
            usleep(100000); // 100 ms
            continue;
        }

        lux /= 1.2;

        if (log_data(log_file, lux) < 0) {
            goto cleanup;
        }

        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_PIN, PI_HIGH);
        } else {
            gpioWrite(RELAY_PIN, PI_LOW);
        }

        usleep(SAMPLE_INTERVAL * 1000000); // 2 seconds
    }

cleanup:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    return 0;
}

