#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <gpiod.h>
#include <string.h>

#define DOUT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 25
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 2280
#define DEFAULT_DURATION 200
#define POLL_INTERVAL 500
#define MAX_RETRIES 3
#define READ_BITS 24
#define CHANNEL_A_GAIN_128 0x01

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_hx711(gpiod_chip *chip, gpiod_line *dout, gpiod_line *sck, int *value) {
    uint64_t dout_value;
    uint64_t sck_value;
    int bit;
    int i;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (gpiod_line_get_value(dout, &dout_value) < 0) {
            syslog(LOG_ERR, "Failed to read DOUT value");
            return -1;
        }

        if (dout_value != 0) {
            usleep(1000); // Wait for 1 ms
            retries++;
            continue;
        }

        *value = 0;
        for (i = 0; i < READ_BITS; i++) {
            if (gpiod_line_get_value(dout, &dout_value) < 0) {
                syslog(LOG_ERR, "Failed to read DOUT value");
                return -1;
            }

            *value = (*value << 1) | dout_value;

            sck_value = 1;
            if (gpiod_line_set_value(sck, sck_value) < 0) {
                syslog(LOG_ERR, "Failed to set SCK value");
                return -1;
            }
            usleep(1); // Short delay
            sck_value = 0;
            if (gpiod_line_set_value(sck, sck_value) < 0) {
                syslog(LOG_ERR, "Failed to set SCK value");
                return -1;
            }
        }

        // Send one additional clock pulse to select Channel A / Gain 128
        sck_value = 1;
        if (gpiod_line_set_value(sck, sck_value) < 0) {
            syslog(LOG_ERR, "Failed to set SCK value");
            return -1;
        }
        usleep(1);
        sck_value = 0;
        if (gpiod_line_set_value(sck, sck_value) < 0) {
            syslog(LOG_ERR, "Failed to set SCK value");
            return -1;
        }

        // Convert to signed 32-bit integer
        if (*value & (1 << (READ_BITS - 1))) {
            *value |= ~((1 << READ_BITS) - 1);
        }

        return 0;
    }

    syslog(LOG_ERR, "DOUT did not go LOW within timeout");
    return -1;
}

int main(int argc, char *argv[]) {
    gpiod_chip *chip;
    gpiod_line *dout, *sck, *solenoid;
    int threshold = DEFAULT_THRESHOLD;
    int scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    int value, raw_value;
    int tare_offset = 0;
    int weight;
    int i;

    // Parse command-line arguments
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--threshold") == 0 && i + 1 < argc) {
            threshold = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            scale = atoi(argv[++i]);
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            duration = atoi(argv[++i]);
        }
    }

    // Open syslog
    openlog("hx711_reader", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting HX711 reader");

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    // Open DOUT line
    dout = gpiod_chip_get_line(chip, DOUT_PIN);
    if (!dout) {
        syslog(LOG_ERR, "Failed to get DOUT line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(dout, "dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT line as input");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    // Open SCK line
    sck = gpiod_chip_get_line(chip, SCK_PIN);
    if (!sck) {
        syslog(LOG_ERR, "Failed to get SCK line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
