int read_hx711(gpiod_chip *chip, gpiod_line *dout, gpiod_line *sck, int *value) {
    uint64_t dout_value;
    uint64_t sck_value;
    int bit;
    int i;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (gpiod_line_get_value(dout, &dout_value) < 0) {
            syslog(LOG_ERR, "Failed to read DOUT value");
            return -1;
        }

        if (dout_value != 0) {
            usleep(1000); // Wait for 1 ms
            retries++;
            continue;
        }

        *value = 0;
        for (i = 0; i < READ_BITS; i++) {
            if (gpiod_line_get_value(dout, &dout_value) < 0) {
                syslog(LOG_ERR, "Failed to read DOUT value");
                return -1;
            }

            *value = (*value << 1) | dout_value;

            sck_value = 1;
            if (gpiod_line_set_value(sck, sck_value) < 0) {
                syslog(LOG_ERR, "Failed to set SCK value");
                return -1;
