#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static int keep_running = 1;
static mosquitto *mosq = NULL;
static int gpio_handle;

void log_message(int level, const char *message) {
    syslog(level, "mqtt_relay: %s", message);
}

void on_connect(struct mosquitto *mosq, void *obj, int result) {
    if (result == 0) {
        log_message(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_message(LOG_ERR, "Connection failed with result code %d", result);
    }
}

void on_disconnect(struct mosquitto *mosq, void *obj, int result) {
    log_message(LOG_INFO, "Disconnected from MQTT broker with result code %d", result);
    if (keep_running) {
        sleep(5);
        mosquitto_reconnect(mosq);
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        log_message(LOG_INFO, "Received message: %s", payload);

        if (strcmp(payload, "ON") == 0) {
            gpioWrite(gpio_handle, 1);
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(gpio_handle, 0);
        } else {
            log_message(LOG_ERR, "Invalid payload: %s", payload);
        }
    } else {
        log_message(LOG_ERR, "Received empty payload");
    }
}

void on_log(struct mosquitto *mosq, void *obj, int level, const char *str) {
    log_message(LOG_INFO, str);
}

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialize pigpio");
        closelog();
        return EXIT_FAILURE;
    }

    gpio_handle = gpioOpen(0);
    if (gpio_handle < 0) {
        log_message(LOG_ERR, "Failed to open GPIO handle");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set GPIO mode");
        gpioClose(gpio_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioWrite(GPIO_PIN, 0);

    mosquitto_lib_init();
    mosq = mosquitto_new("relay_controller_1", 1, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto instance");
        gpioClose(gpio_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_log_callback_set(mosq, on_log);

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker, return code %d", rc);
    }

    while (keep_running) {
        int loop_rc = mosquitto_loop(mosq, -1, 1);
        if (loop_rc) {
            log_message(LOG_ERR, "mosquitto_loop returned error code %d", loop_rc);
            mosquitto_destroy(mosq);
            mosquitto_reconnect(mosq);
            mosq = mosquitto_new("relay_controller_1", 1, NULL);
            if (!mosq) {
                log_message(LOG_ERR, "Failed to recreate mosquitto instance");
                break;
            }
            mosquitto_connect_callback_set(mosq, on_connect);
            mosquitto_disconnect_callback_set(mosq, on_disconnect);
            mosquitto_message_callback_set(mosq, on_message);
            mosquitto_log_callback_set(mosq, on_log);
            mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
        }
    }

    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    gpioWrite(GPIO_PIN, 0);
    gpioClose(gpio_handle);
    gpioTerminate();

    closelog();
    return EXIT_SUCCESS;
}

