#define PWM_FREQUENCY 50
#define PWM_RANGE 2500
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

int main() {
    const int gpio_pins[] = {7, 8, 9, 10, 11};
    const int pulse_widths[] = {1000, 1500, 2000, 500, 2500};
    const int num_servos = sizeof(gpio_pins) / sizeof(gpio_pins[0]);
    int pigpio_status;

    // Initialize pigpio library
    pigpio_status = pigpio_start(NULL, NULL);
    if (pigpio_status != 0) {
        fprintf(stderr, "Failed to start pigpio: %d\n", pigpio_status);
        return EXIT_FAILURE;
    }

    // Set PWM frequency and range for each servo
    for (int i = 0; i < num_servos; i++) {
        pigpio_status = pigpio_set_mode(gpio_pins[i], PI_OUTPUT);
        if (pigpio_status != 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d: %d\n", gpio_pins[i], pigpio_status);
            pigpio_stop();
            return EXIT_FAILURE;
        }

        pigpio_status = pigpio_set_PWM_frequency(gpio_pins[i], PWM_FREQUENCY);
        if (pigpio_status != 0) {
            fprintf(stderr, "Failed to set PWM frequency for GPIO %d: %d\n", gpio_pins[i], pigpio_status);
            pigpio_stop();
            return EXIT_FAILURE;
        }

        pigpio_status = pigpio_set_PWM_range(gpio_pins[i], PWM_RANGE);
        if (pigpio_status != 0) {
            fprintf(stderr, "Failed to set PWM range for GPIO %d: %d\n", gpio_pins[i], pigpio_status);
            pigpio_stop();
            return EXIT_FAILURE;
        }
    }

    // Set pulse widths for each servo
    for (int i = 0; i < num_servos; i++) {
        pigpio_status = pigpio_set_servo_pulsewidth(gpio_pins[i], pulse_widths[i]);
        if (pigpio_status != 0) {
            fprintf(stderr, "Failed to set pulse width for GPIO %d: %d\n", gpio_pins[i], pigpio_status);
            pigpio_stop();
            return EXIT_FAILURE;
        }
    }

    // Hold the signals for 3 seconds
    sleep(3);

    // Cleanly stop PWM and release resources
    for (int i = 0; i < num_servos; i++) {
        pigpio_set_servo_pulsewidth(gpio_pins[i], 0);
    }

    pigpio_stop();
    return EXIT_SUCCESS;
}

