            pigpio_stop();
            return EXIT_FAILURE;
        }
    }

    // Hold the signals for 3 seconds
    sleep(3);

    // Cleanly stop PWM and release resources
    for (int i = 0; i < num_servos; i++) {
        pigpio_set_servo_pulsewidth(gpio_pins[i], 0);
    }

    pigpio_stop();
    return EXIT_SUCCESS;
}
```

This code initializes the pigpio library, sets up PWM for each GPIO pin connected to a servo, applies the specified pulse widths, holds the signals for 3 seconds, and then stops the PWM and releases resources. Make sure to compile with `-lpigpio` and run with appropriate permissions.

