#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>

#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

#define PWM_FREQUENCY 10000
#define CONTROL_PERIOD 100
#define TICKS_PER_REVOLUTION 64
#define TARGET_RPM 50
#define KP 0.5
#define KI 0.05
#define MAX_PWM 255
#define MIN_PWM 0
#define STALL_THRESHOLD 2

atomic_int encoder_a_ticks = 0;
atomic_int encoder_b_ticks = 0;
atomic_int last_a_ticks = 0;
atomic_int last_b_ticks = 0;
atomic_int pwm_a = 0;
atomic_int pwm_b = 0;
atomic_int integral_a = 0;
atomic_int integral_b = 0;
atomic_int last_control_time = 0;
atomic_int stall_time_a = 0;
atomic_int stall_time_b = 0;

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void encoder_callback_a(int level, uint32_t tick, void *userdata) {
    static int last_level = 0;
    int current_level = level;
    if (last_level == 0 && current_level == 1) {
        atomic_fetch_add(&encoder_a_ticks, 1);
    }
    last_level = current_level;
}

void encoder_callback_b(int level, uint32_t tick, void *userdata) {
    static int last_level = 0;
    int current_level = level;
    if (last_level == 0 && current_level == 1) {
        atomic_fetch_add(&encoder_b_ticks, 1);
    }
    last_level = current_level;
}

void control_loop() {
    int current_time = millis();
    int dt = current_time - atomic_load(&last_control_time);
    if (dt < CONTROL_PERIOD) {
        usleep((CONTROL_PERIOD - dt) * 1000);
    }

    int a_ticks = atomic_load(&encoder_a_ticks);
    int b_ticks = atomic_load(&encoder_b_ticks);

    int a_error = TARGET_RPM - (a_ticks * 60.0 / TICKS_PER_REVOLUTION);
    int b_error = TARGET_RPM - (b_ticks * 60.0 / TICKS_PER_REVOLUTION);

    atomic_fetch_add(&integral_a, a_error);
    atomic_fetch_add(&integral_b, b_error);

    int control_a = KP * a_error + KI * atomic_load(&integral_a);
    int control_b = KP * b_error + KI * atomic_load(&integral_b);

    control_a = control_a > MAX_PWM ? MAX_PWM : (control_a < MIN_PWM ? MIN_PWM : control_a);
    control_b = control_b > MAX_PWM ? MAX_PWM : (control_b < MIN_PWM ? MIN_PWM : control_b);

    atomic_store(&pwm_a, control_a);
    atomic_store(&pwm_b, control_b);

    if (a_ticks == atomic_load(&last_a_ticks)) {
        atomic_fetch_add(&stall_time_a, dt);
    } else {
        atomic_store(&stall_time_a, 0);
        atomic_store(&last_a_ticks, a_ticks);
    }

    if (b_ticks == atomic_load(&last_b_ticks)) {
        atomic_fetch_add(&stall_time_b, dt);
    } else {
        atomic_store(&stall_time_b, 0);
        atomic_store(&last_b_ticks, b_ticks);
    }

    if (atomic_load(&stall_time_a) > STALL_THRESHOLD * 1000) {
        printf("Warning: Motor A is stalled!\n");
    }

    if (atomic_load(&stall_time_b) > STALL_THRESHOLD * 1000) {
        printf("Warning: Motor B is stalled!\n");
    }

    printf("Motor A RPM: %d, PWM: %d\n", a_ticks * 60 / TICKS_PER_REVOLUTION, atomic_load(&pwm_a));
    printf("Motor B RPM: %d, PWM: %d\n", b_ticks * 60 / TICKS_PER_REVOLUTION, atomic_load(&pwm_b));

    atomic_store(&last_control_time, current_time);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ENCODER_A_A_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(ENCODER_A_A_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_A_B_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_A_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_B_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down resistors\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(ENCODER_A_A_PIN, encoder_callback_a, NULL) < 0 ||
        gpioSetAlertFunc(ENCODER_A_B_PIN, encoder_callback_b, NULL) < 0 ||
        gpioSetAlertFunc(ENCODER_B_A_PIN, encoder_callback_a, NULL) < 0 ||
        gpioSetAlertFunc(ENCODER_B_B_PIN, encoder_callback_b, NULL) < 0) {
        fprintf(stderr, "Failed to set alert functions\n");
        gpioTerminate();
        return 1;
    }

    if (gpioPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        control_loop();
    }

    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
    gpioTerminate();
    return 0;
}

