#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE_2 0x21
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define POLL_INTERVAL 5
#define I2C_BUS 1
#define LOG_FILE "chicken_coop_log.txt"

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int read_lux(int i2c_handle) {
    unsigned char buffer[2];
    if (i2c_write(i2c_handle, BH1750_ADDR, &BH1750_ONE_TIME_HIGH_RES_MODE_2, 1) < 0) {
        fprintf(stderr, "Failed to write to BH1750\n");
        return -1;
    }
    usleep(180000); // Wait 180 ms
    if (i2c_read(i2c_handle, BH1750_ADDR, buffer, 2) < 0) {
        fprintf(stderr, "Failed to read from BH1750\n");
        return -1;
    }
    int raw_lux = (buffer[0] << 8) | buffer[1];
    return raw_lux / 1.2;
}

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s: %s\n", time_str, event);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int relay_state = 0;
    int last_lux = -1;

    while (keep_running) {
        int lux = read_lux(i2c_handle);
        if (lux < 0) {
            log_event("Sensor error, turning off relay");
            relay_state = 0;
            gpioWrite(RELAY_GPIO, relay_state);
            continue;
        }

        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Lux = %d, Relay = %s", lux, relay_state ? "ON" : "OFF");
        log_event(log_buffer);

        if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
            relay_state = 1;
            gpioWrite(RELAY_GPIO, relay_state);
            log_event("Relay turned ON");
        } else if (lux > LUX_THRESHOLD_DAWN && relay_state == 1) {
            relay_state = 0;
            gpioWrite(RELAY_GPIO, relay_state);
            log_event("Relay turned OFF");
        }

        last_lux = lux;
        sleep(POLL_INTERVAL);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

