#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_DELAY 50
#define SLEEP_INTERVAL 10

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", tm_info);
    printf("%s Relay is %s\n", buffer, state ? "ON" : "OFF");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to LOW\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int relay_state = 0;
    int last_touch_state = 0;
    int current_touch_state = 0;

    while (keep_running) {
        last_touch_state = current_touch_state;
        current_touch_state = gpioRead(TOUCH_PIN);

        if (current_touch_state == 1 && last_touch_state == 0) {
            usleep(DEBOUNCE_DELAY * 1000);

            if (gpioRead(TOUCH_PIN) == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) < 0) {
                    fprintf(stderr, "Failed to toggle GPIO %d\n", RELAY_PIN);
                } else {
                    log_relay_state(relay_state);
                }

                while (gpioRead(TOUCH_PIN) == 1) {
                    usleep(1000);
                }
            }
        }

        usleep(SLEEP_INTERVAL * 1000);
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to LOW on exit\n", RELAY_PIN);
    } else {
        log_relay_state(0);
    }

    gpioTerminate();
    printf("Exiting gracefully\n");
    return EXIT_SUCCESS;
}

