#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT 1000

volatile int running = 1;
volatile int pulse_count = 0;
volatile int solenoid_state = 1; // 1 for open, 0 for closed
pthread_mutex_t pulse_mutex;
FILE *log_file;

void log_event(const char *event) {
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(log_file, "[%s] %s\n", timestamp, event);
        fflush(log_file);
    }
}

void handle_signal(int sig) {
    log_event("Received termination signal");
    solenoid_state = 1;
    gpioWrite(SOLENOID_PIN, solenoid_state);
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(sig);
}

void flow_sensor_isr(int gpio, uint32_t level, uint32_t tick) {
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

void *monitor_flow_rate(void *arg) {
    while (running) {
        sleep(1);

        pthread_mutex_lock(&pulse_mutex);
        double lpm = (pulse_count / PULSES_PER_LITER) * 60.0;
        char log_buffer[128];
        snprintf(log_buffer, sizeof(log_buffer), "LPM: %.2f", lpm);
        log_event(log_buffer);
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
            solenoid_state = 0;
            gpioWrite(SOLENOID_PIN, solenoid_state);
            log_event("Solenoid closed");
        } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
            solenoid_state = 1;
            gpioWrite(SOLENOID_PIN, solenoid_state);
            log_event("Solenoid opened");
        }
    }
    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for flow sensor\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for solenoid\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SOLENOID_PIN, solenoid_state) < 0) {
        fprintf(stderr, "Failed to set initial solenoid state\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, flow_sensor_isr, GPIO_INTR_RISING) < 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        gpioTerminate();
        return 1;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    pthread_t flow_thread;
    if (pthread_create(&flow_thread, NULL, monitor_flow_rate, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    pthread_join(flow_thread, NULL);

    handle_signal(0);
    return 0;
}

