#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <json-c/json.h>

#define DEFAULT_CALIBRATION_FACTOR 1000
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define SERVO_MIN_PULSEWIDTH 1000
#define SERVO_MAX_PULSEWIDTH 2000
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define MAX_ATTEMPTS 1000
#define CLOCK_PULSE_WIDTH 1

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int read_config(const char *filename, int *calibration_factor, char *server_ip, int *server_port) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        *calibration_factor = DEFAULT_CALIBRATION_FACTOR;
        strcpy(server_ip, DEFAULT_SERVER_IP);
        *server_port = DEFAULT_SERVER_PORT;
        return 0;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (strncmp(line, "calibration_factor=", 19) == 0) {
            *calibration_factor = atoi(line + 19);
        } else if (strncmp(line, "server_ip=", 10) == 0) {
            strcpy(server_ip, line + 10);
        } else if (strncmp(line, "server_port=", 12) == 0) {
            *server_port = atoi(line + 12);
        }
    }

    fclose(file);
    return 1;
}

int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void cleanup_pigpio() {
    gpioTerminate();
}

int read_hx711(int *value) {
    int count = 0;
    int result = 0;
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioWrite(SCK_PIN, 0);

    // Wait for the DATA pin to go LOW
    while (gpioRead(DATA_PIN) == 1 && count < MAX_ATTEMPTS) {
        count++;
        usleep(1);
    }
    if (count >= MAX_ATTEMPTS) {
        fprintf(stderr, "HX711 timeout: DATA pin not ready\n");
        return -1;
    }

    // Read 24 bits from the HX711
    for (int i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        usleep(CLOCK_PULSE_WIDTH);
        gpioWrite(SCK_PIN, 0);
        result = (result << 1) | gpioRead(DATA_PIN);
    }

    // Read the 25th bit (gain)
    gpioWrite(SCK_PIN, 1);
    usleep(CLOCK_PULSE_WIDTH);
    gpioWrite(SCK_PIN, 0);

    // Send 128 pulses to reset the HX711
    for (int i = 0; i < 128; i++) {
        gpioWrite(SCK_PIN, 1);
        usleep(CLOCK_PULSE_WIDTH);
        gpioWrite(SCK_PIN, 0);
    }

    *value = result;
    return 0;
}

int map_weight_to_pulsewidth(int weight, int calibration_factor, int *pulsewidth) {
    int raw_value = weight * calibration_factor;
    *pulsewidth = SERVO_MIN_PULSEWIDTH + (raw_value * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH) / 1000000);
    if (*pulsewidth < SERVO_MIN_PULSEWIDTH) *pulsewidth = SERVO_MIN_PULSEWIDTH;
    if (*pulsewidth > SERVO_MAX_PULSEWIDTH) *pulsewidth = SERVO_MAX_PULSEWIDTH;
    return 0;
}

int control_servo(int pulsewidth) {
    if (gpioServo(SERVO_PIN, pulsewidth) < 0) {
        fprintf(stderr, "Failed to control servo: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int log_event(const char *target_weight, const char *actual_weight, const char *error_message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    json_object *jobj = json_object_new_object();
    json_object *jtarget_weight = json_object_new_string(target_weight);
    json_object *jactual_weight = json_object_new_string(actual_weight);
    json_object *jtime = json_object_new_string(time_str);
    json_object *jerror_message = json_object_new_string(error_message);

    json_object_object_add(jobj, "time", jtime);
    json_object_object_add(jobj, "target_weight", jtarget_weight);
    json_object_object_add(jobj, "actual_weight", jactual_weight);
    json_object_object_add(jobj, "error_message", jerror_message);

    fprintf(file, "%s\n", json_object_to_json_string(jobj));
    fclose(file);

    json_object_put(jobj);
    return 0;
}

int main() {
    int calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    char server_ip[16] = DEFAULT_SERVER_IP;
    int server_port = DEFAULT_SERVER_PORT;

    if (!read_config(CONFIG_FILE, &calibration_factor, server_ip, &server_port)) {
        fprintf(stderr, "Using default configuration\n");
    }

    if (initialize_pigpio() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Failed to create socket: %s\n", strerror(errno));
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(server_ip);
    server_addr.sin_port = htons(server_port);

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket: %s\n", strerror(errno));
        close(sockfd);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    if (listen(sockfd, 5) < 0) {
        fprintf(stderr, "Failed to listen on socket: %s\n", strerror(errno));
        close(sockfd);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_sock = accept(sockfd, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            fprintf(stderr, "Failed to accept client: %s\n", strerror(errno));
            continue;
        }

        char buffer[256];
        int bytes_received = recv(client_sock, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            fprintf(stderr, "Failed to receive data: %s\n", strerror(errno));
            close(client_sock);
            continue;
        }
        buffer[bytes_received] = '\0';

        int target_weight = atoi(buffer);
        int pulsewidth;
        if (map_weight_to_pulsewidth(target_weight, calibration_factor, &pulsewidth) < 0) {
            log_event(buffer, "N/A", "Failed to map weight to pulsewidth");
            close(client_sock);
            continue;
        }

        if (control_servo(pulsewidth) < 0) {
            log_event(buffer, "N/A", "Failed to control servo");
            close(client_sock);
            continue;
        }

        usleep(1000000); // Wait 1 second for stabilization

        int actual_weight;
        if (read_hx711(&actual_weight) < 0) {
            log_event(buffer, "N/A", "HX711 read error");
            close(client_sock);
            continue;
        }

        char actual_weight_str[32];
        snprintf(actual_weight_str, sizeof(actual_weight_str), "%d", actual_weight);

        if (send(client_sock, actual_weight_str, strlen(actual_weight_str), 0) < 0) {
            fprintf(stderr, "Failed to send data: %s\n", strerror(errno));
        }

        log_event(buffer, actual_weight_str, "Success");

        close(client_sock);
    }

    close(sockfd);
    cleanup_pigpio();
    return EXIT_SUCCESS;
}

