    int calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    char server_ip[16] = DEFAULT_SERVER_IP;
    int server_port = DEFAULT_SERVER_PORT;

    if (!read_config(CONFIG_FILE, &calibration_factor, server_ip, &server_port)) {
        fprintf(stderr, "Using default configuration\n");
    }

    if (initialize_pigpio() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Failed to create socket: %s\n", strerror(errno));
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(server_ip);
    server_addr.sin_port = htons(server_port);

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket: %s\n", strerror(errno));
        close(sockfd);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    if (listen(sockfd, 5) < 0) {
        fprintf(stderr, "Failed to listen on socket: %s\n", strerror(errno));
        close(sockfd);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_sock = accept(sockfd, (struct sockaddr *)&client_addr, &client_len);
        if (client_sock < 0) {
            fprintf(stderr, "Failed to accept client: %s\n", strerror(errno));
            continue;
        }

        char buffer[256];
        int bytes_received = recv(client_sock, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            fprintf(stderr, "Failed to receive data: %s\n", strerror(errno));
            close(client_sock);
            continue;
        }
        buffer[bytes_received] = '\0';

        int target_weight = atoi(buffer);
        int pulsewidth;
        if (map_weight_to_pulsewidth(target_weight, calibration_factor, &pulsewidth) < 0) {
            log_event(buffer, "N/A", "Failed to map weight to pulsewidth");
            close(client_sock);
            continue;
        }

        if (control_servo(pulsewidth) < 0) {
            log_event(buffer, "N/A", "Failed to control servo");
            close(client_sock);
            continue;
        }

        usleep(1000000); // Wait 1 second for stabilization

        int actual_weight;
        if (read_hx711(&actual_weight) < 0) {
            log_event(buffer, "N/A", "HX711 read error");
            close(client_sock);
            continue;
        }

        char actual_weight_str[32];
        snprintf(actual_weight_str, sizeof(actual_weight_str), "%d", actual_weight);

        if (send(client_sock, actual_weight_str, strlen(actual_weight_str), 0) < 0) {
            fprintf(stderr, "Failed to send data: %s\n", strerror(errno));
        }

        log_event(buffer, actual_weight_str, "Success");

        close(client_sock);
    }

    close(sockfd);
    cleanup_pigpio();
    return EXIT_SUCCESS;
}
