#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEFAULT_DEBOUNCE_MS 50

volatile sig_atomic_t keep_running = 1;
int debounce_ms = DEFAULT_DEBOUNCE_MS;
int relay_state = 0;

void handle_signal(int signal) {
    keep_running = 0;
}

void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s Relay: %s\n", buffer, state ? "ON" : "OFF");
}

void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    log_relay_state(relay_state);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TOUCH_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set touch GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set relay GPIO to LOW\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (argc == 3 && strcmp(argv[1], "-d") == 0) {
        debounce_ms = atoi(argv[2]);
    }

    setup_gpio();

    int last_touch_state = 0;
    int stable_touch_state = 0;
    int debounce_counter = 0;

    while (keep_running) {
        int current_touch_state = gpioRead(TOUCH_GPIO);

        if (current_touch_state != last_touch_state) {
            debounce_counter = 0;
        } else {
            debounce_counter++;
            if (debounce_counter >= debounce_ms / 10) {
                if (stable_touch_state != current_touch_state) {
                    stable_touch_state = current_touch_state;
                    if (stable_touch_state == 1 && last_touch_state == 0) {
                        toggle_relay();
                    }
                }
            }
        }

        last_touch_state = current_touch_state;
        usleep(10000); // 10 ms sleep
    }

    // Ensure relay is off on exit
    gpioWrite(RELAY_GPIO, 0);
    log_relay_state(0);

    gpioTerminate();
    return 0;
}

