#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <termios.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define PWM_FREQUENCY 50
#define CENTER_PULSE_WIDTH 1500
#define ANGLE_INCREMENT 10

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int set_raw_mode(int fd) {
    struct termios oldt, newt;
    if (tcgetattr(fd, &oldt) != 0) {
        perror("tcgetattr");
        return -1;
    }

    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(fd, TCSANOW, &newt) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

void restore_terminal(int fd, struct termios oldt) {
    if (tcsetattr(fd, TCSANOW, &oldt) != 0) {
        perror("tcsetattr");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    struct termios oldt;
    if (set_raw_mode(STDIN_FILENO) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcgetattr(STDIN_FILENO, &oldt) != 0) {
        perror("tcgetattr");
        restore_terminal(STDIN_FILENO, oldt);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    int current_angle = 90;
    int pulse_width = CENTER_PULSE_WIDTH;

    gpioServo(SERVO_PIN, pulse_width);

    while (keep_running) {
        int ch = getchar();
        if (ch == '+') {
            current_angle += ANGLE_INCREMENT;
            if (current_angle > 180) current_angle = 180;
        } else if (ch == '-') {
            current_angle -= ANGLE_INCREMENT;
            if (current_angle < 0) current_angle = 0;
        } else if (ch == 'q') {
            break;
        }

        pulse_width = MIN_PULSE_WIDTH + (current_angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180);
        if (pulse_width < MIN_PULSE_WIDTH) pulse_width = MIN_PULSE_WIDTH;
        if (pulse_width > MAX_PULSE_WIDTH) pulse_width = MAX_PULSE_WIDTH;

        gpioServo(SERVO_PIN, pulse_width);
        printf("Current angle: %d°\n", current_angle);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    restore_terminal(STDIN_FILENO, oldt);

    return EXIT_SUCCESS;
}

