#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t keep_running = 1;
static int pulse_count = 0;
static int line = -1;
static int chip = -1;
static FILE *log_file = NULL;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_rpm(double rpm) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file);
}

void print_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int main() {
    struct gpiod_line_event event;
    struct gpiod_line_request req;
    struct timespec start_time, current_time;
    double elapsed_time;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip < 0) {
        print_error("Failed to open GPIO chip");
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line < 0) {
        print_error("Failed to get GPIO line");
    }

    memset(&req, 0, sizeof(req));
    req.line = line;
    req.consumer_label = "conveyor_belt_monitor";
    req.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request_input_flags(&req) < 0) {
        print_error("Failed to request GPIO line as input");
    }

    log_file = fopen("motor_rpm.log", "a");
    if (!log_file) {
        print_error("Failed to open log file");
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (keep_running) {
        if (gpiod_line_event_wait(line, DEBOUNCE_MS, &event) == 0) {
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                pulse_count++;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (elapsed_time >= SAMPLE_INTERVAL) {
            double rpm = (pulse_count / SAMPLE_INTERVAL) * 60.0;
            printf("Current RPM: %.2f\n", rpm);
            log_rpm(rpm);

            pulse_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }
    }

    if (line >= 0) {
        gpiod_line_release(line);
    }

    if (chip >= 0) {
        gpiod_chip_close(chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

