#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_SENSOR_GPIO 4
#define POLL_INTERVAL_MS 50
#define TOUCH_HOLD_TIME_MS 10000

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0 || gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set relay OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int touch_state = 0;
    int last_touch_state = 0;
    unsigned long last_touch_time = 0;

    while (!exit_flag) {
        int current_touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (current_touch_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading touch sensor GPIO\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (current_touch_state != last_touch_state) {
            last_touch_time = gpioTick();
            last_touch_state = current_touch_state;
        }

        if (current_touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            relay_state = !relay_state;
            if (relay_state) {
                if (gpioWrite(RELAY_GPIO, 1) < 0) {
                    fprintf(stderr, "Failed to set relay ON\n");
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            } else {
                if (gpioWrite(RELAY_GPIO, 0) < 0) {
                    fprintf(stderr, "Failed to set relay OFF\n");
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            }
        }

        if (current_touch_state == 1 && (gpioTick() - last_touch_time) > (TOUCH_HOLD_TIME_MS * 1000 / POLL_INTERVAL_MS)) {
            // Touch held for too long
            if (gpioWrite(RELAY_GPIO, 0) < 0) {
                fprintf(stderr, "Failed to set relay OFF\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            relay_state = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set relay OFF during cleanup\n");
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

