    if (log_file) {
        fclose(log_file);
    }
    gpioPWM(GPIO_PWM, 0);
    gpioWrite(GPIO_ENABLE, 0);
    gpioTerminate();
}

void control_loop() {
    int pwm_value = 0;
    double flow_rate = 0.0;
    uint32_t start_time = millis();

    while (keep_running) {
        uint32_t current_time = millis();
        if (current_time - start_time >= SAMPLE_INTERVAL_MS) {
            flow_rate = (pulse_count / PULSES_PER_LITER) * 60000.0 / SAMPLE_INTERVAL_MS;
            double error = target_flow_rate - flow_rate;
            pwm_value = (int)(pwm_value + KP * error);
            pwm_value = pwm_value < 0 ? 0 : (pwm_value > 255 ? 255 : pwm_value);

            fprintf(log_file, "%lu,%.2f,%.2f,%d\n", current_time, flow_rate, target_flow_rate, pwm_value);
            fflush(log_file);

            gpioPWM(GPIO_PWM, pwm_value);
            pulse_count = 0;
            start_time = current_time;
        }
        usleep(1000); // Sleep for 1 ms
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3 || strcmp(argv[1], "-t") != 0) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr;
    target_flow_rate = strtod(argv[2], &endptr);
    if (*endptr != '\0' || target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_logging();

    control_loop();

    cleanup();
    return EXIT_SUCCESS;
}

