#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

#define RFID_SPI_CHANNEL 0
#define RFID_SPI_SPEED 100000
#define RFID_TAG_LENGTH 10
#define RFID_VALID_TAG {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}
#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define BUTTON_GPIO 22
#define DEBOUNCE_MS 50
#define LOCK_TIME_MS 5000

static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

void log_access(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
}

void handle_signal(int signal) {
    terminate = 1;
}

void release_locks() {
    gpioWrite(LOCK_GPIO_1, 1);
    gpioWrite(LOCK_GPIO_2, 1);
}

void close_resources() {
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    release_locks();
    gpioTerminate();
}

int read_rfid_tag(unsigned char *tag) {
    if (spi_fd == -1) {
        return -1;
    }

    unsigned char tx[RFID_TAG_LENGTH] = {0};
    unsigned char rx[RFID_TAG_LENGTH] = {0};

    if (spiXfer(spi_fd, tx, rx, RFID_TAG_LENGTH) != RFID_TAG_LENGTH) {
        return -1;
    }

    for (int i = 0; i < RFID_TAG_LENGTH; i++) {
        if (rx[i] != 0) {
            memcpy(tag, rx, RFID_TAG_LENGTH);
            return 0;
        }
    }

    return -1;
}

int check_valid_tag(unsigned char *tag) {
    return memcmp(tag, RFID_VALID_TAG, RFID_TAG_LENGTH) == 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((log_file = fopen("/var/log/door_access.log", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if ((spi_fd = spiOpen(RFID_SPI_CHANNEL, RFID_SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LOCK_GPIO_1, PI_OUTPUT);
    gpioSetMode(LOCK_GPIO_2, PI_OUTPUT);
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    gpioWrite(LOCK_GPIO_1, 1);
    gpioWrite(LOCK_GPIO_2, 1);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    unsigned char rfid_tag[RFID_TAG_LENGTH];
    int valid_tag = 0;
    int button_pressed = 0;

    while (!terminate) {
        if (!valid_tag) {
            if (read_rfid_tag(rfid_tag) == 0) {
                if (check_valid_tag(rfid_tag)) {
                    valid_tag = 1;
                    log_access("Valid RFID tag detected");
                } else {
                    log_access("Invalid RFID tag");
                }
            } else {
                log_access("RFID read failure");
            }
        }

        if (valid_tag && !button_pressed) {
            if (gpioRead(BUTTON_GPIO) == 0) {
                gpioDelay(DEBOUNCE_MS);
                if (gpioRead(BUTTON_GPIO) == 0) {
                    button_pressed = 1;
                    log_access("Button pressed");
                }
            }
        }

        if (valid_tag && button_pressed) {
            gpioWrite(LOCK_GPIO_1, 0);
            gpioWrite(LOCK_GPIO_2, 0);
            gpioDelay(LOCK_TIME_MS);
            release_locks();
            log_access("Access granted");
            valid_tag = 0;
            button_pressed = 0;
        }

        gpioDelay(100);
    }

    close_resources();
    return 0;
}

