#define PWM_FREQUENCY_HZ 100
#define PULSES_PER_REVOLUTION 600
#define TARGET_RPM 60

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *ena, *in1, *in2;
    struct gpiod_line *a, *b;
    int32_t count;
    double last_error;
    double integral;
    double last_time;
    pthread_mutex_t count_mutex;
} Motor;

Motor motor1, motor2;
FILE *log_file;
bool running = true;

void stop_motors() {
    gpiod_line_set_value(motor1.ena, 0);
    gpiod_line_set_value(motor2.ena, 0);
}

void release_resources() {
    stop_motors();
    gpiod_line_release(motor1.ena);
    gpiod_line_release(motor1.in1);
    gpiod_line_release(motor1.in2);
    gpiod_line_release(motor1.a);
    gpiod_line_release(motor1.b);
    gpiod_chip_close(motor1.chip);

    gpiod_line_release(motor2.ena);
    gpiod_line_release(motor2.in3);
    gpiod_line_release(motor2.in4);
    gpiod_line_release(motor2.a);
    gpiod_line_release(motor2.b);
    gpiod_chip_close(motor2.chip);

    if (log_file) {
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    running = false;
}

void *encoder_thread(void *arg) {
    Motor *motor = (Motor *)arg;
    struct gpiod_line_event event;
    int ret;

    while (running) {
        ret = gpiod_line_event_wait(motor->a, &event, -1);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for encoder event: %s\n", strerror(-ret));
            continue;
        }

        int32_t b_value = gpiod_line_get_value(motor->b);
        pthread_mutex_lock(&motor->count_mutex);
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            motor->count += (b_value == 1) ? 1 : -1;
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            motor->count += (b_value == 1) ? -1 : 1;
        }
        pthread_mutex_unlock(&motor->count_mutex);
    }

    return NULL;
}

void setup_motor(Motor *motor, int ena, int in1, int in2, int a, int b) {
    motor->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!motor->chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    motor->ena = gpiod_chip_get_line(motor->chip, ena);
    motor->in1 = gpiod_chip_get_line(motor->chip, in1);
    motor->in2 = gpiod_chip_get_line(motor->chip, in2);
    motor->a = gpiod_chip_get_line(motor->chip, a);
    motor->b = gpiod_chip_get_line(motor->chip, b);

    if (!motor->ena || !motor->in1 || !motor->in2 || !motor->a || !motor->b) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(motor->chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(motor->ena, "motor_ena", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    gpiod_line_request_output(motor->in1, "motor_in1", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    gpiod_line_request_output(motor->in2, "motor_in2", GPIOD_LINE_REQUEST_DIRECTIONS_OUTPUT);
    gpiod_line_request_input(motor->a, "motor_a", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);
    gpiod_line_request_input(motor->b, "motor_b", GPIOD_LINE_REQUEST_DIRECTIONS_INPUT);

    gpiod_line_event_request_both_edges(motor->a, "encoder_event", NULL);

    pthread_mutex_init(&motor->count_mutex, NULL);
