            pthread_mutex_unlock(&motor1.count_mutex);

            pthread_mutex_lock(&motor2.count_mutex);
            double count2 = motor2.count;
            motor2.count = 0;
            pthread_mutex_unlock(&motor2.count_mutex);

            double rpm1 = count1 / (PULSES_PER_REVOLUTION * dt) * 60.0;
