            double derivative1 = (error1 - motor1.last_error) / elapsed_time;
            double derivative2 = (error2 - motor2.last_error) / elapsed_time;

            double output1 = KP * error1 + KI * motor1.integral + KD * derivative1;
            double output2 = KP * error2 + KI * motor2.integral + KD * derivative2;

            output1 = fmax(fmin(output1, 1.0), -1.0);
            output2 = fmax(fmin(output2, 1.0), -1.0);

