#define RELAY_PIN 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A

#define TOUCH_THRESHOLD_REG 0x10
#define RELEASE_THRESHOLD_REG 0x0A
#define FILTER_CHARGE_REG 0x20
#define ELE_CURRENT_REG 0x01
#define ELE_CFG_REG 0x05
#define TOU_THRESH 0x01
#define REL_THRESH 0x01
#define FILTER_CHARGE 0x9A
#define ELE_CURRENT 0x0E
#define ELE_EN 0x02

#define TOUCH_STATUS_REG 0x00
#define NO_TOUCH_STATUS_REG 0x01

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int setup_mpr121() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (i2cOpen(I2C_BUS, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return -1;
    }

    // Enter stop mode
    if (i2cWriteReg8(I2C_BUS, MPR121_ADDR, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to enter stop mode\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return -1;
    }

    // Set touch and release thresholds
    if (i2cWriteReg8(I2C_BUS, MPR121_ADDR, TOUCH_THRESHOLD_REG, TOU_THRESH) < 0 ||
        i2cWriteReg8(I2C_BUS, MPR121_ADDR, RELEASE_THRESHOLD_REG, REL_THRESH) < 0) {
        fprintf(stderr, "Failed to set touch/release thresholds\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return -1;
    }

    // Configure filter/charge time and electrode current
    if (i2cWriteReg8(I2C_BUS, MPR121_ADDR, FILTER_CHARGE_REG, FILTER_CHARGE) < 0 ||
        i2cWriteReg8(I2C_BUS, MPR121_ADDR, ELE_CURRENT_REG, ELE_CURRENT) < 0) {
        fprintf(stderr, "Failed to configure filter/charge time and electrode current\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteReg8(I2C_BUS, MPR121_ADDR, ELE_CFG_REG, ELE_EN) < 0) {
        fprintf(stderr, "Failed to enable electrodes\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return -1;
    }

    // Enter run mode
    if (i2cWriteReg8(I2C_BUS, MPR121_ADDR, 0x00, 0x8F) < 0) {
        fprintf(stderr, "Failed to enter run mode\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return -1;
    }

    // Wait for stabilization
    usleep(100000);

    return 0;
}

int main() {
    if (setup_mpr121() < 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(RELAY_PIN, 0);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        uint8_t touch_status = 0;
        uint8_t no_touch_status = 0;

        if (i2cReadReg8(I2C_BUS, MPR121_ADDR, TOUCH_STATUS_REG, &touch_status) < 0 ||
            i2cReadReg8(I2C_BUS, MPR121_ADDR, NO_TOUCH_STATUS_REG, &no_touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            break;
        }

        if (touch_status > 0) {
            gpioToggle(RELAY_PIN);
            printf("Relay toggled. Touch status: 0x%02X\n", touch_status);
        }

        usleep(100000);
    }

    gpioWrite(RELAY_PIN, 0);
    i2cClose(I2C_BUS);
    gpioTerminate();

    return EXIT_SUCCESS;
}

