#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DURATION 50
#define MAX_DURATION 200
#define PWM_RANGE 256

volatile sig_atomic_t shutdown_flag = 0;

void handle_sigint(int sig) {
    shutdown_flag = 1;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0 || gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup() {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    gpioTerminate();
}

void generate_and_play_pattern() {
    int steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
    for (int i = 0; i < steps; i++) {
        int duty_cycle1 = rand() % PWM_RANGE;
        int duty_cycle2 = rand() % PWM_RANGE;
        int duration = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;

        gpioPWM(MOTOR1_PIN, duty_cycle1);
        gpioPWM(MOTOR2_PIN, duty_cycle2);

        gpioDelay(duration * 1000); // Convert ms to microseconds

        if (shutdown_flag) {
            break;
        }
    }
}

int main() {
    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    srand(time(NULL));

    while (!shutdown_flag) {
        generate_and_play_pattern();
    }

    cleanup();
    return EXIT_SUCCESS;
}

