    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        if (check_rain_sensor()) {
            log_event("Rain detected.");
            close_window();
            sleep(CHECK_INTERVAL);
        } else {
            sleep(CHECK_INTERVAL);
        }
    }

    close_window();
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

