#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define DT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100 // grams
#define SOLENOID_DURATION 5000 // milliseconds
#define READ_TIMEOUT 1000 // milliseconds

volatile sig_atomic_t keep_running = 1;

void handle_signal(int signal) {
    keep_running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (gpioSetMode(DT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(SCK_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set SCK low\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

int read_hx711() {
    unsigned long count = 0;
    int loop_cnt = 0;
    int timeout = READ_TIMEOUT;

    // Wait for the data pin to go low
    while (gpioRead(DT_PIN) == 1) {
        if (timeout-- == 0) {
            fprintf(stderr, "HX711 timeout waiting for data pin to go low\n");
            return -1;
        }
        usleep(100);
    }

    // Read 24 bits of data
    for (loop_cnt = 0; loop_cnt < 24; loop_cnt++) {
        gpioWrite(SCK_PIN, 1);
        usleep(1);
        count = count << 1;
        if (gpioRead(DT_PIN) == 1) {
            count++;
        }
        gpioWrite(SCK_PIN, 0);
        usleep(1);
    }

    // Read the 25th bit (gain)
    gpioWrite(SCK_PIN, 1);
    usleep(1);
    count = count << 1;
    if (gpioRead(DT_PIN) == 1) {
        count++;
    }
    gpioWrite(SCK_PIN, 0);
    usleep(100);

    // Pulse the clock 128 times to reset the HX711
    for (loop_cnt = 0; loop_cnt < 128; loop_cnt++) {
        gpioWrite(SCK_PIN, 1);
        usleep(1);
        gpioWrite(SCK_PIN, 0);
        usleep(1);
    }

    // Convert to a signed 24-bit value
    if (count & 0x800000) {
        count |= ~0xFFFFFF;
    }

    return count;
}

void log_event(const char *event) {
    FILE *file = fopen("stock_events.txt", "a");
    if (!file) {
        fprintf(stderr, "Failed to open stock_events.txt for writing\n");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    if (fprintf(file, "[%s] %s\n", timestamp, event) < 0) {
        fprintf(stderr, "Failed to write to stock_events.txt\n");
    }

    fclose(file);
}

int main() {
    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        int weight = read_hx711();
        if (weight < 0) {
            fprintf(stderr, "Error reading HX711\n");
            continue;
        }

        // Convert raw value to grams (calibration needed)
        int grams = weight / 1000; // Example conversion, adjust as needed

        if (grams < WEIGHT_THRESHOLD) {
            if (gpioWrite(SOLENOID_PIN, 1) < 0) {
                fprintf(stderr, "Failed to activate solenoid\n");
            } else {
                log_event("Solenoid activated");
                usleep(SOLENOID_DURATION * 1000);
                if (gpioWrite(SOLENOID_PIN, 0) < 0) {
                    fprintf(stderr, "Failed to deactivate solenoid\n");
                }
            }
        }

        usleep(1000000); // Sleep for 1 second
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

