#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define HX711_DOUT 4
#define HX711_SCK 17
#define SOLENOID_LOCK 27
#define KNOWN_WEIGHT_KG 1.0
#define THRESHOLD_WEIGHT_KG 5.0
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG "security.log"

static int calibration_factor = 0;
static int running = 1;

void handle_sigint(int sig) {
    running = 0;
    gpioWrite(SOLENOID_LOCK, 0);
    printf("SIGINT received, unlocking solenoid and exiting...\n");
}

void read_calibration_factor() {
    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (file) {
        if (fscanf(file, "%d", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file.\n");
            calibration_factor = 0;
        }
        fclose(file);
    } else {
        fprintf(stderr, "Calibration file not found, using default factor 0.\n");
    }
}

void write_calibration_factor(int factor) {
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (file) {
        fprintf(file, "%d\n", factor);
        fclose(file);
    } else {
        fprintf(stderr, "Error writing calibration factor to file.\n");
    }
}

int read_hx711() {
    int count = 0;
    int value = 0;
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetPullUpDown(HX711_DOUT, PI_PUD_UP);

    // Wait for the data line to go low
    while (gpioRead(HX711_DOUT) == 1) {
        usleep(1);
        if (count++ > 100000) { // Timeout after 100 ms
            fprintf(stderr, "HX711 communication timeout.\n");
            return 0;
        }
    }

    // Read 24 bits
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        usleep(1);
        value = (value << 1) | gpioRead(HX711_DOUT);
        gpioWrite(HX711_SCK, 0);
        usleep(1);
    }

    // Read the 25th bit (gain)
    gpioWrite(HX711_SCK, 1);
    usleep(1);
    value = (value << 1) | gpioRead(HX711_DOUT);
    gpioWrite(HX711_SCK, 0);
    usleep(1);

    // 24-bit two's complement
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

void calibrate() {
    printf("Place the known weight (%.1f kg) on the scale and press Enter...\n", KNOWN_WEIGHT_KG);
    getchar();

    int raw_value = read_hx711();
    if (raw_value == 0) {
        fprintf(stderr, "Failed to read raw value for calibration.\n");
        exit(EXIT_FAILURE);
    }

    calibration_factor = raw_value / (int)(KNOWN_WEIGHT_KG * 1000);
    write_calibration_factor(calibration_factor);
