    FILE *file = fopen(SECURITY_LOG, "a");
    if (file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(file, "[%s] Weight exceeded threshold: %.2f kg\n", timestamp, weight);
        fclose(file);
    } else {
        fprintf(stderr, "Error writing to security log.\n");
    }
}

