    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    gpioSetMode(SOLENOID_LOCK, PI_OUTPUT);
    gpioWrite(SOLENOID_LOCK, 0);

