#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20

static volatile int keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *relay_line;
static FILE *log_file;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_event(const char *event) {
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file);
    }
}

int main() {
    struct gpiod_line_request reqs[2];
    int ret;

    // Open chip
    chip = gpiod_chip_open_by_name("bcm2835-gpio");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request sensor line as input
    memset(&reqs, 0, sizeof(reqs));
    reqs[0].line = sensor_line;
    reqs[0].flags = GPIOD_LINE_REQUEST_INPUT;
    reqs[0].consumer = "IR Sensor Monitor";
    ret = gpiod_line_request_bulk(chip, reqs, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request sensor line: %s\n", strerror(-ret));
        gpiod_line_release(relay_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request relay line as output
    reqs[1].line = relay_line;
    reqs[1].flags = GPIOD_LINE_REQUEST_OUTPUT;
    reqs[1].consumer = "Relay Toggle";
    reqs[1].default_value = 0; // Start with relay OFF
    ret = gpiod_line_request_bulk(chip, reqs + 1, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request relay line: %s\n", strerror(-ret));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("relay_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(relay_line);
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_relay_state = 0;
    int sensor_value;

    while (keep_running) {
        // Read sensor value
        sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value: %s\n", strerror(-sensor_value));
            break;
        }

        // Check for obstacle
        if (sensor_value == 0) { // Active-low
            // Toggle relay
            last_relay_state = !last_relay_state;
            ret = gpiod_line_set_value(relay_line, last_relay_state);
            if (ret < 0) {
                fprintf(stderr, "Failed to set relay value: %s\n", strerror(-ret));
                break;
            }

            // Log event
            const char *state_str = last_relay_state ? "ON" : "OFF";
            log_event(state_str);
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup
    if (log_file) {
        fclose(log_file);
    }
    gpiod_line_release(relay_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

