    gpioWrite(MOTOR_LEFT_IN1, 0);
    gpioWrite(MOTOR_LEFT_IN2, 0);
    gpioWrite(MOTOR_RIGHT_IN1, 0);
    gpioWrite(MOTOR_RIGHT_IN2, 0);

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

