#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define BH1750_ADDRESS 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define I2C_BUS 1

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld %s\n", ts.tv_sec, ts.tv_nsec, message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to set relay state\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (keep_running) {
        int fd = i2cOpen(I2C_BUS, BH1750_ADDRESS);
        if (fd < 0) {
            log_message("I2C bus error");
            sleep(1);
            continue;
        }

        if (i2cWriteReg8(fd, 0x20, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
            log_message("Failed to set BH1750 mode");
            i2cClose(fd);
            sleep(1);
            continue;
        }

        usleep(180000); // 180 ms delay

        uint8_t data[2];
        if (i2cReadReg8s(fd, 0x20, data, 2) < 0) {
            log_message("Failed to read from BH1750");
            i2cClose(fd);
            sleep(1);
            continue;
        }

        i2cClose(fd);

        uint16_t lux = (data[0] << 8) | data[1];
        lux /= 1.2;

        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Lux: %d", lux);
        log_message(log_buffer);

        int relay_state = gpioRead(RELAY_GPIO);
        if (lux < LUX_THRESHOLD && relay_state == 0) {
            if (gpioWrite(RELAY_GPIO, 1) < 0) {
                log_message("Failed to activate relay");
            } else {
                log_message("Relay activated");
            }
        } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
            if (gpioWrite(RELAY_GPIO, 0) < 0) {
                log_message("Failed to deactivate relay");
            } else {
                log_message("Relay deactivated");
            }
        }
    }

    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    return 0;
}

