#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_DELAY 100 // milliseconds
#define LOCK_PULSE_WIDTH 1000 // microseconds
#define UNLOCK_PULSE_WIDTH 2000 // microseconds
#define MIN_PULSE_WIDTH 500 // microseconds
#define MAX_PULSE_WIDTH 2500 // microseconds

static int pi;
static int servo_handle;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    pi = gpioInitialise();

    if (gpioSetMode(pi, SERVO_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(pi, LOCK_BUTTON_PIN, PI_INPUT) < 0 ||
        gpioSetMode(pi, UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate(pi);
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(pi, LOCK_BUTTON_PIN, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(pi, UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down resistors\n");
        gpioTerminate(pi);
        exit(EXIT_FAILURE);
    }

    servo_handle = gpioServoCreate(pi, SERVO_PIN, 50); // 50 Hz frequency
    if (servo_handle < 0) {
        fprintf(stderr, "Failed to create servo handle\n");
        gpioTerminate(pi);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (servo_handle >= 0) {
        gpioServoDestroy(pi, servo_handle);
    }
    gpioTerminate(pi);
}

void set_servo_position(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }
    gpioServoPulseWidthMicros(pi, servo_handle, pulse_width);
}

void debounce_and_handle_button(int button_pin, int target_pulse_width) {
    if (gpioRead(pi, button_pin) == 0) {
        usleep(DEBOUNCE_DELAY * 1000); // Debounce delay
        if (gpioRead(pi, button_pin) == 0) { // Check again after debounce
            set_servo_position(target_pulse_width);
            printf("Servo moved to %d microseconds\n", target_pulse_width);
        }
    }
}

int main() {
    setup_gpio();

    signal(SIGINT, handle_sigint);

    printf("Press Ctrl+C to exit\n");

    while (keep_running) {
        debounce_and_handle_button(LOCK_BUTTON_PIN, LOCK_PULSE_WIDTH);
        debounce_and_handle_button(UNLOCK_BUTTON_PIN, UNLOCK_PULSE_WIDTH);
        usleep(10000); // Small delay to prevent busy-waiting
    }

    cleanup();
    printf("Exiting program\n");
    return 0;
}

