#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define POLL_INTERVAL_NS 10000000 // 10 ms in nanoseconds
#define ALARM_DURATION_MS 1000 // 1 second

volatile sig_atomic_t running = 1;

void handle_signal(int signum) {
    running = 0;
}

void setup_gpio(gpiod_chip *chip, int pin, int line_flags, gpiod_line **line) {
    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        fprintf(stderr, "Failed to get line %d\n", pin);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request(*line, "sound_sensor", line_flags) < 0) {
        fprintf(stderr, "Failed to request line %d\n", pin);
        gpiod_line_release(*line);
        exit(EXIT_FAILURE);
    }
}

void sound_sensor_mode(gpiod_chip *chip, gpiod_line *sensor_line, gpiod_line *led_line) {
    struct gpiod_line_event event;
    int rc;
    void *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZMQ context\n");
        exit(EXIT_FAILURE);
    }

    void *publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "Failed to create ZMQ publisher socket\n");
        zmq_ctx_destroy(context);
        exit(EXIT_FAILURE);
    }

    rc = zmq_bind(publisher, "tcp://*:5555");
    if (rc != 0) {
        fprintf(stderr, "Failed to bind ZMQ publisher socket: %s\n", zmq_strerror(rc));
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        exit(EXIT_FAILURE);
    }

    while (running) {
        rc = gpiod_line_event_wait(sensor_line, &event, POLL_INTERVAL_NS);
        if (rc < 0) {
            fprintf(stderr, "Failed to wait for line event\n");
            break;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            zmq_msg_t message;
            zmq_msg_init_size(&message, 1);
            zmq_msg_topic(&message, "SOUND_ALERTS");
            zmq_msg_send(&message, publisher, 0);
            zmq_msg_close(&message);
        }
    }

    zmq_close(publisher);
    zmq_ctx_destroy(context);
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
}

void alarm_node_mode(gpiod_chip *chip, gpiod_line *led_line) {
    void *context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZMQ context\n");
        exit(EXIT_FAILURE);
    }

    void *subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "Failed to create ZMQ subscriber socket\n");
        zmq_ctx_destroy(context);
        exit(EXIT_FAILURE);
    }

    zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, "SOUND_ALERTS", 12);

    int rc = zmq_connect(subscriber, "tcp://localhost:5555");
    if (rc != 0) {
        fprintf(stderr, "Failed to connect ZMQ subscriber socket: %s\n", zmq_strerror(rc));
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        exit(EXIT_FAILURE);
    }

    while (running) {
        zmq_msg_t message;
        zmq_msg_init(&message);
        zmq_msg_recv(&message, subscriber, 0);
        gpiod_line_set_value(led_line, 1);
        usleep(ALARM_DURATION_MS * 1000);
        gpiod_line_set_value(led_line, 0);
        zmq_msg_close(&message);
    }

    zmq_close(subscriber);
    zmq_ctx_destroy(context);
    gpiod_line_release(led_line);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "Modes: sound_sensor, alarm_node\n");
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpiod_line *sensor_line = NULL;
    gpiod_line *led_line = NULL;

    setup_gpio(chip, SOUND_SENSOR_PIN, GPIOD_LINE_REQUEST_INPUT, &sensor_line);
    setup_gpio(chip, ALARM_LED_PIN, GPIOD_LINE_REQUEST_OUTPUT, &led_line);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (strcmp(mode, "sound_sensor") == 0) {
        sound_sensor_mode(chip, sensor_line, led_line);
    } else if (strcmp(mode, "alarm_node") == 0) {
        alarm_node_mode(chip, led_line);
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

