static int g_mqtt_session;
static int g_mqtt_message;

static void signal_handler(int sig) {
    g_stop = 1;
}

static void log_to_syslog(const char *message) {
    openlog("IR_Decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

static void mqtt_publish(const char *payload) {
    MQTTMessage message = MQTTMessage_initializer;
    message.payload = (void *)payload;
    message.payloadlen = strlen(payload);
    message.qos = 1;
    message.retained = 0;

    MQTTPublish(g_mqtt_client, MQTT_TOPIC, &message);
}

static void decode_nec(const unsigned long *pulses, int npulses, char *address, char *command) {
    if (npulses < 68) return; // Minimum NEC frame size

    int i;
    unsigned long mark, space;
    int bit_count = 0;
    unsigned long data = 0;

    for (i = 0; i < npulses; i += 2) {
        mark = pulses[i];
        space = pulses[i + 1];

        if (mark >= 4500 && mark <= 5500 && space >= 1600 && space <= 1800) {
            // Header detected
            for (i += 2; i < npulses; i += 2) {
                mark = pulses[i];
                space = pulses[i + 1];

                if (mark >= 500 && mark <= 600) {
                    if (space >= 1600 && space <= 1800) {
                        // Logic 1
                        data = (data << 1) | 1;
                    } else if (space >= 500 && space <= 600) {
                        // Logic 0
                        data = (data << 1) | 0;
                    } else {
                        break;
                    }
                    bit_count++;
                } else {
                    break;
                }
            }

            if (bit_count == 32) {
                // Extract address and command
                unsigned long address_data = data >> 16;
                unsigned long command_data = data & 0xFFFF;

                // Validate checksum
                unsigned long checksum = (address_data ^ command_data) & 0xFF;
                if (checksum == (data >> 24)) {
                    snprintf(address, 9, "%08lX", address_data);
                    snprintf(command, 5, "%04lX", command_data);
                    return;
                }
            }
        }
    }
}

static void alert_callback(int gpio, unsigned level, uint32_t tick, void *userdata) {
    static unsigned long pulses[PULSE_BUFFER_SIZE];
    static int npulses = 0;
    static unsigned long last_tick = 0;

    unsigned long tick_diff = pigpio_get_current_tick() - last_tick;
    last_tick = pigpio_get_current_tick();

    if (level == 0) {
        if (npulses < PULSE_BUFFER_SIZE) {
            pulses[npulses++] = tick_diff;
        }
    } else {
        if (npulses > 0) {
            pulses[npulses++] = tick_diff;
            char address[9];
            char command[5];
            decode_nec(pulses, npulses, address, command);
            if (address[0] != '\0' && command[0] != '\0') {
                char log_message[50];
                snprintf(log_message, sizeof(log_message), "Address: %s, Command: %s", address, command);
                log_to_syslog(log_message);

                char json_message[100];
                snprintf(json_message, sizeof(json_message), "{\"address\": \"%s\", \"command\": \"%s\"}", address, command);
                mqtt_publish(json_message);
            }
            npulses = 0;
        }
    }
}

