    MQTTClient_setCallbacks(g_mqtt_client, NULL, NULL, NULL, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    MQTTClient_connect(g_mqtt_client, &conn_opts, &g_mqtt_context);
}

