                    close(i2c_fds[i]);
                    i2c_fds[i] = -1;
                    snprintf(message + strlen(message), BUFFER_SIZE - strlen(message), "%d,%.1f;", i + 1, lux_values[i]);
                }
            } else {
                snprintf(message + strlen(message), BUFFER_SIZE - strlen(message), "%d,%.1f;", i + 1, lux_values[i]);
            }
        }

        send_udp_packet(udp_sock, &multicast_addr, message);
        sleep(1);
    }

    close(udp_sock);
    for (i = 0; i < 4; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }

    return 0;
}

