#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define MAX_RETRIES 3
#define RETRY_DELAY 100000 // 100 ms in microseconds

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    keep_running = 0;
}

int open_i2c_device(const char *device, int address) {
    int file;
    if ((file = open(device, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }
    if (ioctl(file, I2C_SLAVE, address) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return -1;
    }
    return file;
}

int read_flow_data(int file, uint16_t *flow) {
    uint8_t buffer[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        if (write(file, buffer, 0) < 0) {
            if (errno == EIO) {
                retries++;
                usleep(RETRY_DELAY);
                continue;
            } else {
                perror("I2C write failed");
                return -1;
            }
        }

        result = read(file, buffer, 2);
        if (result == 2) {
            *flow = (buffer[0] << 8) | buffer[1];
            *flow &= 0x3FFF; // Mask to 14 bits
            return 0;
        } else if (errno == EIO) {
            retries++;
            usleep(RETRY_DELAY);
        } else {
            perror("I2C read failed");
            return -1;
        }
    }

    return -1;
}

double convert_to_slpm(uint16_t raw) {
    return (raw - 3277) * 0.1;
}

void log_flow_rate(double flow_rate) {
    FILE *log_file = fopen("airflow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    fprintf(log_file, "%s: %.2f SLPM\n", timestamp, flow_rate);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_file = open_i2c_device(I2C_DEVICE, I2C_ADDRESS);
    if (i2c_file < 0) {
        return EXIT_FAILURE;
    }

    while (keep_running) {
        uint16_t raw_flow;
        if (read_flow_data(i2c_file, &raw_flow) == 0) {
            double flow_rate = convert_to_slpm(raw_flow);
            log_flow_rate(flow_rate);
        } else {
            fprintf(stderr, "Failed to read flow data\n");
        }
        sleep(1);
    }

    close(i2c_file);
    return EXIT_SUCCESS;
}

