#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SENSOR_ADDR 0x39
#define WHO_AM_I_REG 0x24
#define ENABLE_REG 0x80
#define CFG6_REG 0xAF
#define SP_EN_BIT (1 << 7)
#define PON_BIT (1 << 7)
#define NUM_CHANNELS 10
#define SLEEP_INTERVAL 5

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int initialize_sensor(int fd) {
    uint8_t who_am_i;
    if (i2c_read(fd, WHO_AM_I_REG, &who_am_i) != 0 || who_am_i != 0x19) {
        fprintf(stderr, "Sensor not found or WHO_AM_I mismatch\n");
        return -1;
    }

    if (i2c_write(fd, ENABLE_REG, PON_BIT) != 0) {
        return -1;
    }

    if (i2c_write(fd, CFG6_REG, SP_EN_BIT) != 0) {
        return -1;
    }

    return 0;
}

int read_spectral_channels(int fd, uint16_t *channels) {
    uint8_t buffer[2];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (i2c_read(fd, 0x60 + i, buffer) != 0) {
            return -1;
        }
        channels[i] = (buffer[0] << 8) | buffer[1];
    }
    return 0;
}

double compute_lux(uint16_t *channels) {
    // Simplified lux approximation
    return (channels[0] + channels[1] + channels[2] + channels[3] + channels[4] + channels[5] + channels[6] + channels[7] + channels[8] + channels[9]) / 10.0;
}

