#define SENSOR_REGISTER 0x28
#define MAX_RETRIES 3
#define BACKOFF_MS 10

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

void log_error(const char *message) {
    FILE *error_log = fopen("seismic_error.log", "a");
    if (error_log) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline
        fprintf(error_log, "[%s] %s\n", timestamp, message);
        fclose(error_log);
    }
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, reg) < 0) {
            log_error("Failed to set I2C slave address");
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            log_error("Failed to write register address");
            retries++;
            usleep(BACKOFF_MS * 1000);
            continue;
        }

        if (read(fd, buf, len) != len) {
            log_error("Failed to read data from I2C device");
            retries++;
            usleep(BACKOFF_MS * 1000);
            continue;
        }

        return 0;
    }

    log_error("I2C read failed after retries");
    return -1;
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char *filename = DEFAULT_FILENAME;
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 16);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a I2C_ADDRESS] [-i INTERVAL] [-f FILENAME]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    FILE *csv_file = fopen(filename, "w");
    if (!csv_file) {
        log_error("Failed to open CSV file");
        close(fd);
        exit(EXIT_FAILURE);
    }
    fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");

    uint8_t data[6];
    while (keep_running) {
        if (i2c_read(fd, i2c_address, data, 6) == 0) {
            int16_t x_raw = (int16_t)(data[1] | (data[0] << 8));
            int16_t y_raw = (int16_t)(data[3] | (data[2] << 8));
            int16_t z_raw = (int16_t)(data[5] | (data[4] << 8));

            double x_g = x_raw * 0.000244;
            double y_g = y_raw * 0.000244;
            double z_g = z_raw * 0.000244;

            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

            fprintf(csv_file, "%s,%f,%f,%f\n", timestamp, x_g, y_g, z_g);
            fflush(csv_file);
        } else {
            log_error("Failed to read from sensor");
        }

        sleep(interval);
    }

    fclose(csv_file);
    close(fd);
    return 0;
}

