#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x23
#define POWER_ON 0x01
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_fd = -1;

void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_fd != -1) {
        close(udp_fd);
    }
    exit(0);
}

int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

int i2c_read_word_data(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int setup_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }

    if (i2c_write_byte_data(i2c_fd, POWER_ON, 0x00) < 0 ||
        i2c_write_byte_data(i2c_fd, CONTINUOUS_HIGH_RES_MODE, 0x10) < 0) {
        return -1;
    }

    return 0;
}

int setup_udp() {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }

    if (setsockopt(udp_fd, IPPROTO_IP, IP_MULTICAST_TTL, &TTL, sizeof(TTL)) < 0) {
        perror("Failed to set multicast TTL");
        close(udp_fd);
        return -1;
    }

    return 0;
}

void send_lux(float lux) {
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%f", lux);
    if (sendto(udp_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to send UDP packet");
    }
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (setup_i2c() < 0 || setup_udp() < 0) {
        cleanup(0);
    }

    while (1) {
        uint16_t raw_value;
        if (i2c_read_word_data(i2c_fd, 0x20, &raw_value) < 0) {
            fprintf(stderr, "Error reading from BH1750, retrying...\n");
            sleep(1);
            continue;
        }

        float lux = raw_value / 1.2;
        send_lux(lux);

        sleep(1);
    }

    return 0;
}

