#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <termios.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define INTER_BYTE_TIMEOUT_USEC 500000
#define BUFFER_SIZE 256

volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int configure_uart(int fd) {
    struct termios options;
    if (tcgetattr(fd, &options) < 0) {
        perror("tcgetattr");
        return -1;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = INTER_BYTE_TIMEOUT_USEC / 100;

    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

void log_detection(const char *timestamp_str, double range) {
    time_t rawtime = atol(timestamp_str);
    struct tm *timeinfo = localtime(&rawtime);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
}

int main() {
    int uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (configure_uart(uart_fd) < 0) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    char buffer[BUFFER_SIZE] = {0};
    char *line = NULL;
    size_t len = 0;
    ssize_t bytes_read;

    while (keep_running) {
        fd_set read_fds;
        struct timeval timeout;
        int retval;

        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        timeout.tv_sec = TIMEOUT_SEC;
        timeout.tv_usec = 0;

        retval = select(uart_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (retval == -1) {
            perror("select");
            break;
        } else if (retval) {
            bytes_read = read(uart_fd, buffer + strlen(buffer), sizeof(buffer) - strlen(buffer) - 1);
            if (bytes_read < 0) {
                if (errno != EAGAIN && errno != EWOULDBLOCK) {
                    perror("read");
                    break;
                }
            } else if (bytes_read == 0) {
                // EOF
                break;
            } else {
                buffer[bytes_read + strlen(buffer)] = '\0';
                char *newline = strchr(buffer, '\n');
                if (newline) {
                    *newline = '\0';
                    line = strdup(buffer);
                    if (!line) {
                        perror("strdup");
                        break;
                    }
                    newline++;
                    memmove(buffer, newline, strlen(newline) + 1);
                    char *range_str = strrchr(line, ',');
                    if (range_str) {
                        *range_str++ = '\0';
                        double range = atof(range_str);
                        log_detection(line, range);
                    }
                    free(line);
                    line = NULL;
                }
            }
        }
    }

    if (line) {
        free(line);
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

