#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_LEFT 4
#define GPIO_MIDDLE 17
#define GPIO_RIGHT 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

static int pi = -1;
static int serial_fd = -1;

void cleanup(int signum) {
    if (pi >= 0) {
        gpioTerminate(pi);
    }
    if (serial_fd >= 0) {
        close(serial_fd);
    }
    exit(0);
}

void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int setup_serial() {
    serial_fd = open(SERIAL_PORT, O_WRONLY | O_NOCTTY | O_NDELAY);
    if (serial_fd < 0) {
        perror("Failed to open serial port");
        return -1;
    }

    struct termios options;
    if (tcgetattr(serial_fd, &options) != 0) {
        perror("Failed to get serial port attributes");
        close(serial_fd);
        return -1;
    }

    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CRTSCTS;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;

    if (tcsetattr(serial_fd, TCSANOW, &options) != 0) {
        perror("Failed to set serial port attributes");
        close(serial_fd);
        return -1;
    }

    return 0;
}

int main() {
    setup_signal_handlers();

    pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (setup_serial() < 0) {
        cleanup(0);
        return 1;
    }

    if (gpioSetMode(pi, GPIO_LEFT, PI_INPUT) < 0 ||
        gpioSetMode(pi, GPIO_MIDDLE, PI_INPUT) < 0 ||
        gpioSetMode(pi, GPIO_RIGHT, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        cleanup(0);
        return 1;
    }

    if (gpioSetPullUpDown(pi, GPIO_LEFT, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(pi, GPIO_MIDDLE, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(pi, GPIO_RIGHT, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down\n");
        cleanup(0);
        return 1;
    }

    while (1) {
        int left = gpioRead(pi, GPIO_LEFT);
        int middle = gpioRead(pi, GPIO_MIDDLE);
        int right = gpioRead(pi, GPIO_RIGHT);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Failed to read GPIO\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("[%s] Left: %d, Middle: %d, Right: %d\n", time_str, left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            const char *msg = "EMERGENCY STOP!\n";
            if (write(serial_fd, msg, strlen(msg)) < 0) {
                perror("Failed to write to serial port");
            }
        }

        usleep(100000); // 100 ms
    }

    cleanup(0);
    return 0;
}

